-- ── Inferno ─────────────────────────────────────

UPDATE cantos SET title_uk = 'ПІСНЯ ПЕРША(1) Ліс. - Пагорб. - Три звірі. - Віргілій'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 1
    AND p.name = 'Inferno';

UPDATE terzinas SET text_uk = 'На півшляху свого земного світу
Я трапив у похмурий ліс густий,
Бо стежку втратив, млою оповиту.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'О, де візьму снаги розповісти
Про ліс листатий цей, суворий, дикий,
Бо жах від згадки почина рости!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Над смерть страшну гіркіший він, великий, -
Але за благо те, що там знайшов,
Повім про все, що в пам''ять взяв навіки.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Недобре тямлю, як постав цей схов,
Бо сонність так оволоділа мною,
Що з певної дороги я зійшов.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Я опинивсь під пагорба стіною,
Яким кінчався неширокий діл,
Де острах ліг на серце пеленою.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Я вгору глянув і побачив схил,
Вже убраний у сонячне проміння,
Що надає людині свіжих сил.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Тоді помалу уляглось тремтіння,
Що не давало спокою мені
Всю ніч, коли блукав між страховиння.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Як той, хто у задишці голосній
На сушу вийшов, піною укритий,
І озирає вири навісні, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Так і мій дух, не скінчивши летіти,
Зирнув назад і стежку оглядав,
Яка не дозволя нікому жити.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Тут я собі спочити трохи дав
І вирушив на гору незнайому,
А за опору нижчу ногу мав.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'І от, коли вже йшов я по підйому,
Збіг леопард, моторний та верткий,
І шерсть рябіла плямами на ньому.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Моїх очей він не злякавсь, дерзкий,
І, заступивши шлях, став на сторожі,
І я подавсь униз, у діл низький.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'А йшли хвилини ранішні, пригожі,
І сонце сходило з тим почтом зір,
Що з ним спахнули, як Любові Божій.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Схотілося у рух оздобить шир.
І дух надія звабила рожева,
Що скоро зникне цей плямистий звір.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Пора буяла навкруги квітнева,
Та я не вчув нічого, тільки ляк
Од вигляду уже близького лева.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'І так, здалось, на мене йшов хижак,
Наїжившись, страшенно зголоднівши,
Що рух повітря вмить, здалось, закляк.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Ще вийшла люта й зла вовчиця вивши, -
її неутоленна худорба
Примушує людей конать збіднівши.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'В очах її така була злоба,
Таке палало полум''я гаряче,
Що з страху шлях згубив я до горба.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'І наче той, хто дивиться найпаче,
Куди б скарби багаті примостить,
А, їх утративши, - в розпуці плаче,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Такий був я, бо твар мене щомить,
Встріч ідучи, помалу відсувала
Туди, де сяйво сонця не звучить.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Коли ж моя нога на діл ставала,
Явився хтось, у кого зір потух,
Мовчанка ж довга голос відібрала.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'В безлюдді я його побачив рух.
«Врятуй! - була мольба моя єдина, -
Байдуже, чи людина ти, чи дух!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Він мовив: «Не людина; був людина;
В Ломбардії мій батько оселивеь,
У Мантуї - моя там батьківщина.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Во время Юлія я народивсь,
Хоч пізно; жив я в Августовім Римі,
Коли ще лжебогам народ моливсь.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Я був поет, пісні складав любимі,
Як славний син Анхізів з Трої втік,
А Іліон упав в огні та димі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Та чом вертаєш і в журбі поник?
Чого не йдеш на горб, де корениться
Солодке джерело чудесних рік?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = '«Чи не Віргілій ти, чи не криниця
Широкоплинних мовних вод ясних? -
Спитав я й став, щоб в шані поклониться, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'О світло й честь усіх співців земних,
Ти зваж на захват мій, на шанування
Твоїх безсмертних творів видатних.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Ти вчитель мій, моє уґрунтування,
У тебе я знайшов на все життя
Той гарний стиль, що дав мені визнання.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Ти бачиш твар, що втік од неї я?
Рятуй мене ти, мудрецю славетний,
Бо в серці й жилах кров тремтить моя».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = '«Хай буде інший шлях тобі прикметний, -
Він одповів на жалісні слова, -
Щоб ти мерщій покинув діл цей шпетний.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Повз твар, яка, голодна, завива,
Не прослизне і найспритніший дока:
Хто мимо йде, усіх вона вбива.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Лиха вона з природи та жорстока;
Наївшись, голоднішою стає
Й ненатлого не насищає ока.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Із звірами відгулює своє
Без міри; та надія на Хорта є,
Що він цю твар таки, нарешті, вб''є.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Про нього скажуть: скарбів не ковтає,
В любові, мудрості й чесноті зріс.
І ґрунт між Фельтро й Фельтро доглядає.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Він за Італію зведе свій спис, -
Заради ж неї дівчина Камілла
І Евріал умерли, й Турн, і Ніс.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'І як би не тікала твар немила,
Він в Пекло зажене її, на дно,
Звідкіль її жадоба приманила,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'А звідсіля, - надумав я одно, -
Я поведу тебе, де залягають
Місця, які я взнав уже давно.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Почуєш ти, як в розпачі благають
Там духи з зойком та з ламанням рук,
Повторну смерть на себе накликають.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Побачиш тих, хто між вогненних мук
Таємно тішиться у сподіванні
Колись піднестись до блаженних лук.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'А схочеш в висі злинути останні, -
Душі, достойнішій за мене, здам
До ніжних рук тебе при розставанні.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Бо той, хто звіку владарює там,
Мене, що бився у ворожій раті,
Й тих, хто зі мною, не пуска й до брам.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'А в тронній владаря світів палаті
Усе пристойне пишному кошу,
Щасливий той, хто буде там на святі!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'І я йому: «Поете, я прошу,
Ім''ям Христа, якого ти не відав,
Все зло й все гірше хай тут полишу,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Ти ж покажи усе, про що повідав:
Хай браму бачу я з Петром святим
І тих, хто в муках та скорботі знидів».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'І рушив він, а я - слідом за ним.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 46;

UPDATE cantos SET title_uk = 'ПІСНЯ ДРУГА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 2
    AND p.name = 'Inferno';

UPDATE terzinas SET text_uk = 'День одійшов; з натомленої спини
Всього живого тягарі земні
Тьма поскидала; тільки я, єдиний,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Все готувавсь до мужньої борні
З трудною стежкою з нестерпним жалем;
Та вірна пам''ять сил додасть мені.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'О музи, хай ваш хист сіяє палом,
О думко, що я бачив, запиши
І передай навік людським скрижалям.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'І я: «Поете, спершу ти ріши,
Якщо ти хочеш скрізь мене проводить,
Чи доблесть є на те в моїй душі?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Співав ти: батько Сільвіїв зіходить
Ще тлінний та минущий в світ тривкий,
Зберігши чуйність, що в живому бродить.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Коли ж противник всяких зол палкий
Був добрий з ним, передбачавши славу
Його діянь, і хто він, і який,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'То мудрий відзнача його по праву:
Обранець неба вишнього добра,
Рим породив він та його державу,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'А той же й та (це істина стара)
Засновані, щоб стать святим престолом
Наступникам апостола Петра.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Ця путь, розцвіченим твоїм глаголом
Прославлена, причиною в віках
Була його звитязі й папським столам.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Сосуд обрання теж у цих полях
Пізніше був, щоб дать підпору вірі,
Яка спасіння відкриває шлях.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'А я чого піду? Хто пустить в мирі?
Ніякий не Еней, не Павел я,
На цю я честь не варт ні в якій мірі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Коли ж спуститись знаджує земля,
То чи не здасться спуск мій божевіллям, -
Для мудреця ясніша мисль моя».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Мов той, хто раптом виниклим зусиллям
Занедбує намічені діла
Й прощається з готовим вже справиллям,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Вчинив і я: де схил чорнила мла,
У думці справа та пішла вся прахом,
Що з запалом розпочалась була.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = '«Я бачу у словах, повитих жахом, -
Сказала тінь, вся - благородний чар, -
Що ти в душі пройнявсь побожним страхом.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Він обсипа людину, мов той жар,
Примушуючи подвигу зректися,
Як мур уявлений спиняє твар.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Щоб міг від остраху ти відмогтися,
Скажу, чом став твоїм я ватажком,
Щоб знав, коли в мені жалі знялися.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Був з тими я, хто між добром і злом,
Як пані кликнула щонайгарніша,
І їй скоривсь я серцем і умом.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'І от до мене над зорю ясніша
Звернула очі й голос чарівний;
Лиш в ангелів розмова лагідніша:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = '«О мантуанська чемна душе, чий
На цілу землю розголос лунає
Й лунатиме, аж поки світ живий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Мій друг, що дружби з долею не має,
На прикрому безлюдному горбі
Дорогу втратив і в страху вмирає.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Боюсь, щоб не накоїв зла собі,
Щоб з поміччю, бува, не опізнитись, -
За нього, чула, й небо у журбі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Іди, щоб там найшвидше опинитись
І мудрим словом стань його втішать;
Мені з турбот допоможи звільнитись.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Я - Беатріче, я кажу рушать,
Прийшла я з місць, куди вернутись хочу,
Любов мені звеліла це сказать.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Я піднесу тобі хвалу пророчу,
Як стану перед Господом святим».
Замовкла, й мову я почав урочу:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = '«О пані благосна, єдина, з ким
Наш людський рід всі перевищив твори,
Які під небом зібрані низьким!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Так уподобав я наказ твій скорий,
Що, все здійснивши б, думав, що не встиг, -
І зайвими були б його повтори.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Але скажи, це хто тобі поміг
У глиб землі без остраху пускатись,
Звідкіль усяк тікав би скільки міг».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = '«Щоб міг за словом довго не шукатись, -
Сказала, - стисло відповім одне,
Чом не боюся я сюди спускатись.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Того боятись треба, головне,
Що позбавля когось життя й спокою, -
Все ж інше анікому не страшне.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Ласкавий Бог створив мене такою,
Що ваша скорб повз мене промина,
Що я - поза пожежею яркою.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Та в небі благородна є жона;
Того жалівши, хто підпав блуканням,
Вмолила Вишнього Суддю вона,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Звернулась до Лючії із благанням,
Сказавши: «На людину ту малу
Ти зглянься й огорни її сіянням».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Знайшла мене Лючія, ворог злу,
Де ми сиділи з древньою Рахіллю,
Й сказала: «Справжню Богові хвалу'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Знось, Беатріче, і зарадь зусиллю
Того, хто любить так, що став на згин,
Піднявшись вище над людською цвіллю!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Чи ти не чуєш, як там стогне він?
Чи ти не бачиш, як зо смертю б''ється
Між хвиль, грізніших од морських пучин?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Ніхто на світі палко так не рветься
До радості і не тікає бід,
Як я, зачувши, як те слово ллється.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Прийшла звідтіль, де сяє небозвід
Я, пісні ввірившись твоїй урочій,
Яка вславля тебе й слухацький рід».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Сказавши так, звела на мене очі,
Де сльози струменіли в чистоті,
І я стежки знайшов якнайкоротші.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Прибув до тебе на прохання ті
І врятував од звіра, що з''явився
Тобі на цій великій висоті.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Та що тобі? Чого, чого спинився?
Чого на серці підлий страх тяжкий?
Чого в тобі сміливий дух смутився?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'І це тоді, коли святі жінки
У небі втрьох клопочуться про тебе,
Я ж блага обіцяю дар такий?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Мов квіт, в нічнім морозі, як в погребі,
Побитий, похиляє вниз чоло
Й знов оживає у ранковім небі,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Так я відчув, що стомлення спливло,
І вигукнув із серцем посмутнілим,
Мов той, до кого звільнення прийшло:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = '«О преблага, з якою став я смілим,
І ґречний ти, що зразу ж поспішив
І підійшов до мене з словом милим,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Ти так мені бажання прищепив
Рушати краєм тим жахним, немирним,
Що до своїх вернувсь я перших слів.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Іди ж, пойнятий захватом надмірним,
Ти - проводир, ти - пан, учитель - ти».
Сказав я й слідом за поетом мирним'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'Ступив на шлях лісистий і крутий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 48;

UPDATE cantos SET title_uk = 'ПІСНЯ ТРЕТЯ Брама Пекла. - Нікчемні. - Ахерон. - Човен Харона'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 3
    AND p.name = 'Inferno';

UPDATE terzinas SET text_uk = '«Крізь мене йдуть до міста мук найтяжчих,
Крізь мене йдуть до мучень і заков,
Крізь мене йдуть між поколінь пропащих.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Суд правий вів творця моїх будов:
Звели мене Могуття, що все родить,
Найвища Мудрість і Першолюбов.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Лиш після мене світ став брами зводить.
Ніщо не вічне, я ж на всі віки.
Лишайте сподівання всі, хто входить».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Із чорних літер напис я такий
Побачив на вершку хмурної брами
Й сказав: «Учителю, о жах який!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'І він, немов господар над думками:
«Лишатись легкодухість має тут,
І має вмерти дрож перед страхами.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Як обіцяв я, ми прийшли в той кут,
Де скорбні тіні можеш ти уздріти,
Що розуму збулись блаженних пут».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Він руку дав мені, і я зогрітий
Був усміхом спокійного лиця, -
Й повів у глиб, у таїну повитий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Такі зітхання й лемент без кінця
Почулись у беззорянім склепінні,
Що струмом сліз облився раптом я.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Усі наріччя, мови старовинні,
Репетувань і ремствувань слова
У плесках рук, у вигуках, хрипінні, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Зливались в гамір, що завжди трива
У цьому місці, крутячись всечасно,
Немов пісок, що вихор порива.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Мені тоді зробилося так жасно,
Що мовив: «Волю ти мою вволи,
Скажи, хто мучиться отак злощасно?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'І він: «На животіння це прийшли
Ті, що зірок, мізерні, не хапали,
Жили собі без гани, без хвали.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'А поряд - ангели, що з висі впали
Ті, недостойні, і не вороги,
Й не слуги Божі, лиш за себе дбали,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Щоб вигляд не темнився дорогий,
їх з неба гнано, пекло ж браму стисло,
Щоб гріх не вихваляв свої борги».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'І я: «Учителю, що там нависло
Й над нами закрутило круговерть?»
Він одповів: «Про це скажу я стисло:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Вони вже не надіються на смерть
І так ненавидять роки пропалі,
Що чорні заздрощі їх повнять вщерть.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Ніхто за них не згадує в печалі,
І Ласка, й Суд їх зневажають так,
Що й ти не говори, поглянь і - далі!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Я, зиркнувши, побачив: в небі знак
Летів, кружляючи, і зупиниться,
Як видалось мені, не міг ніяк.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'За ним така неслася плетениця
Померлих душ, що я й не уявляв,
Як стільки встигло смерті причаститься.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'По тому, як вже декого впізнав,
Побачив я того з нероб неплідних,
Хто зрікся, страхопуд, великих справ.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Я зразу ж зрозумів, що бачу бідних
Перед собою неярких нікчем,
І Богу, й ворогам його огидних.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Вони, з яких ніхто не жив живцем,
Тут прудко бігли, всі в укусах, голі,
Над ними ж - оси й ґедзі тьмою тем.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Поривши лиця, кров стікала долі,
Усуміш із слізьми на ґрунт масний,
Де жовті черви кублились поволі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Поглянув далі, й натовп голосний
Побачив я край буйного потоку
Й спитав: «Учителю, ти поясни,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Щоб знав я, чом вони із цього боку
На той всі прагнуть перейти мерщій,
Як бачу, хоч у тьмі й не видно оку».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'І він мені: «Одвіт почуєш мій,
Коли зупинимо свої ми кроки
На Ахероновій косі журній».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Стараючись не завдавать мороки
І волю дати боячись словам,
Я мовчки йшов на край ріки широкий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'І човен ми побачили, а там
Почварний дід, роззявивши пащеку,
Горлав: «Ой горе, злобні душі, вам!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Вже годі мріять про зорю далеку,
Я тут, з човном, щоб вас перевезти
У вічний морок, в холоднечу, в спеку!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'А ти, живий, од мертвих геть коти
Назад, де скоро вже розквітне травень! -
Та, бачивши, що я не хочу йти,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Додав таке: - Ти краще іншу гавань
І легший човен зразу обирай;
Моє судно важке тобі для плавань».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'І вождь йому: «Хароне, не займай!
Так хочуть там, де все зробити можуть
Чого захочуть. Так що не чіпай».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'І перестав тоді мене тривожить
Кудлай-човняр з мертвотного багна,
Що міг з очей зірниці сяйні множить.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'І квола зграя голих душ, смутна,
Почувши заклик той гучний і строгий,
Зі скреготом зубів, як навісна,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Взялась клясти - і Бога, й рід убогий,
І давнє покоління, й молоде,
І час родин, і матерів пологи.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Та, плачучи, встелила вся, хто де,
Проклятий берег зливою з хмарини, -
Він всіх, хто Бога не боїться, жде.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Харон, злий дух з очима - як жарини,
Розпалюючи погляд, купчив гурт:
Всіх гнав, веслом загайним міряв спини.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Як лист злітає восени до бурт
За першим другий, поки на галуззі
Останній не загляне в самий нурт, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Адамове так плем''я в шумній тузі
Одне за одним збилось у човні,
Мов птаство, скупчене в сильці, у крузі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Поки пливли по чорній струмині,
Хапаючись зійти на той бік темний,
На цьому знову з''юрмились квапні.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = '«Мій сину, - проказав учитель чемний, -
З усіх країн, хто в Божім гніві вмер,
Збираються на берег цей підземний,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Щоб поспішать заріччям до печер, -
їх так острожить правосуддя Боже,
Що страх стає бажанням відтепер,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'А добра тут душа пройти не може,
І що в Харона грізний був привіт,
То сам збагни, з чим слово його схоже».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Він закінчив, і враз похмурий світ
Так задрижав, що навіть перед економ
Мене од страху кидатиме в піт.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'В плачливім краї знявся вихор гоном,
Пустельний діл скорботи спалахнув
В моєму серці відсвітом червоним,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'І впав я, наче той, хто вмить заснув.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 46;

UPDATE cantos SET title_uk = 'ПІСНЯ ЧЕТВЕРТА Коло перше (Лімб). - Нехрещені немовлята і доброчесні нехристияни'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 4
    AND p.name = 'Inferno';

UPDATE terzinas SET text_uk = 'Мій раптом перервався сон глибокий,
Бо грім оглушливий я враз почув
І встав, немов ударений під боки,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'І все спочилим оком озирнув,
На ноги звівшись, подививсь уважно,
Щоб добре зрозуміти, де я був.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Стояв на стежці я, що неосяжно
Збігала вниз, в те урвище сумне,
Де лемент мук відгримував протяжно.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Таке в густім тумані неясне
Було воно, що зір мій недолугий
Не міг сягнуть крізь марево жахне.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = '«Тепер ми зійдемо в сліпі округи, -
Сказав поет і на обличчі зблід, -
Я буду перший, а ти будеш другий».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'І я, уздрівши сполотнілий вид,
Сказав: «Чи зважусь, коли й ти стерявся,
Ти ж завжди захищав мене од бід!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'І він: «Злощасних репет увігнався
Ізнизу так, що вкрив лице бліде
Тим жалем, що тобі він жахом здався.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Але ходім, бо довгий шлях не жде».
Так він сказав та й уступив зі мною
У перше коло, що круг прірви йде.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Тут, стежачи за пітьмою німою,
Я не почув ні скарг, ні нарікань, -
Самі зітхання коливали млою:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'їх збуджувала туга без страждань
У стовпищі, в якім не розрізняєш
Дітей, жінок, мужів усяких звань.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'І добрий вчитель мій: «Ти не питаєш,
Це що за духи, на яких глядиш?
То знай, ще поки далі не ступаєш,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Що це не грішних душ хисткий комиш,
А ті, хто без хрещальної поради
Не знали, що спасає найпевніш.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'їм християнські не лились відради,
Було чуже їм Божество само, -
Я увіходжу теж до їх громади.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Це незнання - єдине нам гальмо,
Й ми тим караємось за цю невдачу,
Що без надій жаданням живемо».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'І жаль узяв, що в Лімбі тут побачу
Я тих, кому пошану всім здаю
За видатні діла й величну вдачу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = '«Скажи, учителю, скажи, вождю, -
Почав я, щоб зміцнитися у вірі,
Яка являє для брехні суддю. -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Невже тут по заслузі чи офірі
Ніхто блаженства не досяг цілком?»
І він на ці слова, і темні й щирі,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Відмовив: «Бувши тут ще новаком,
Я бачив, як зійшов сюди властитель,
Звитяжця коронований вінком.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'За ним звідсіль пішли: всіх прародитель,
Його син Авель, благочесний Ной,
Мойсей, законодавець і служитель,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Давид і Авраам, що жив давно,
Ізраїль з батьком і сини численні,
Рахіль, дорожча над усе майно,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Й багато ще - і стали всі блаженні.
Узнай одне ти - душі всі людські
До того часу не були спасенні».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'У згадках про події неблизькі
Ми не лишали прокладати в лісі,
Кажу, у лісі душ, стежки вузькі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Та спогади недовго ці велися
Між нами ще, як смуги світляні
У здолану півкулю тьми влилися.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'За кілька кроків видний став мені
Освітлений зелений простір луки,
Де сяйвом сяли люди видатні.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = '«О шано й честь мистецтва та науки,
Скажи, хто ці, що доля їх ясна
Й відділені вони в окремі злуки?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'І він мені: «їх слава голосна,
З якою ти ще на землі зіткнувся,
Така, що й в Бога шана їм значна».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'І голос в той же час мені почувся:
«Вшануємо ж великого співця,
Бо зниклий дух його до нас вернувся!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'І по слідах великого сліпця
Нас три величні тіні йшли стрічати,
Нерадісні і несумні з лиця.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'І добрий мій учитель став казати:
«Он глянь: мечем оперезавши стан,
Іде, мов з пишним почтом, цар багатий, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'То сам Гомер, усім поетам пан,
А другий - то творець сатир Горацій,
А то - Овідій і за ним - Лукан.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Ішов я з ними вряд в натхненній праці
І вряд у славі йду - таж чуєш сам
Той спів хвали, мов князеві в палаці».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Так я уздрів блискучу школу там
Вождя поетів, що, могутньокрилий,
Летів орлом назустріч небесам.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Вони про себе щось поговорили
І привітання мовили свої,
І посміхнувся мій учитель милий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Усі тримались, як близькі мої,
І, розуміючи високу шану,
Я шостим став у велетнів сім''ї.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Отак ішли до світлого ми стану
Й поважно мову про таке вели,
Про що розповідать пізніше стану.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Під благородний замок ми прийшли,
Який сім раз оточували стіни,
Й джерельні води навкруги текли.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Долаючи, мов суходіл, струмини,
Дістались двору ми крізь сім воріт
І вздріли свіжу зелень луговини,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'В очах у мешканців горів привіт,
У постатях ласкава сяла милість,
А в тихій мові - лагідності світ,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Зійшли ми вкупі на горбка похилість
В такому світлі, що змогли вочу
Оглянуть мовчазну дібров журливість.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Великі, до яких в думках лечу,
Вщасливили мене своїм собором,
Що й досі ще від захвату тремчу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Я вздрів Електру в натовпі прозорім,
І Гектора, й Енея розрізнив,
І Цезаря в броні, з шулічим зором.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Каміллу і Пентесілею вздрів
По другий бік та ще царя Латина,
Який з Лавінією там сидів.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Вздрів Брута я й дружину Коллатіна,
Корнелью, Марцію та Юлью -всіх.
А осторонь - самого Саладіна.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'І, перевівши зір очей своїх,
Побачив я, що вчитель всіх, хто знає,
Сидить в сім''ї філософів значних.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Всяк дивиться, всяк шану виявляє.
З ним обіч був Сократ, а там Платон,
І Діоген своє тут місце має.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Тур Демокріт, що ввів случай в закон,
Фалес, ким славилась бібліотека,
І з Емпедоклом Геракліт, Зенон.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Вздрів якостей досліджувача грека
Діоскоріда, - тут же був Орфей,
Ще й Туллій, Лівій, мораліст Сенека,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'І геометр Евклід, і Птолемей,
І Гіппократ з Галеном, Авіценна,
І Аверроес, цей тлумач ідей.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'Тяглася їх гірлянда незліченна,
Та хай про це хтось інший розповість,
Бо тема й так у мене широченна.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 49;

UPDATE terzinas SET text_uk = 'І двох співців позбавилося шість,
Бо враз мене вожай мій знаменитий
Од мирних лук, де всіх розважив гість,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 50;

UPDATE terzinas SET text_uk = 'Туди повів, де нічому світити'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 51;

UPDATE cantos SET title_uk = 'ПІСНЯ П''ЯТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 5
    AND p.name = 'Inferno';

UPDATE terzinas SET text_uk = 'І тут зійшов до другого я кола,
За перше меншого, та від розпук
Кричали душі голосніш довкола.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Й страхітного Міноса вчув я гук;
Який при вході судить справедливо,
Хвостом указуючи розмір мук.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Кажу, коли якась душа лякливо
Розповіла про всі свої діла,
То цей знавець гріхів, тонкий на диво,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'їй місце визначає в царстві зла,
Хвоста скрутивши стількома витками,
В котре по черзі коло засила.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Тиск перед ним і днями, і ночами;
Душа тут кожна свій проходить суд:
Сказала, вчула та й пішла до ями.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = '«О ти, хто в наш занурюється бруд, -
Гукнув Мінос, коли на мене глянув,
На мить лишивши безконечний труд, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Дивись, куди ввійшов і з ким ти станув,
А про широкий вхід і не гадай!»
І вождь до нього: «Чом так гучно грянув?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Не з власного жадання йде в ваш край:
Так хочуть там, де все зробити можуть
Чого захочуть, так що не чіпай».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'І ось такий, що й камінь міг стривожить,
Зачувся лемент, і зневіра йме,
Чи зойки відчаю луна не множить?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Туди прийшрв, де світло геть німе,
І знявся рик, як в буряному морі,
Коли на ньому дужий вітер дме.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Пекельні вихори, рвучкі та скорі,
Засуджених волочать, тягнуть, б''ють
Згори і знизу, й ті в сльозах та в горі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'І душі, летячи у каламуть,
Ридають, виють, сповнюючись хіттю,
Самого Бога в небесах клянуть:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Я взнав, що підпадає тут страхіттю,
Жахливій бурі цій той люд яркий,
Який скорився лиха розмаїттю.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'І як на крилах носяться шпаки
В холодну пору, збившися у зграї,
Так духів злих пролинув рій швидкий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Звідсіль, звідтіль, вверх, вниз, як в водограї,
І без надій, що прийде тиші мить
Або змаліють муки їх безкраї.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Як журавлиний ключ із зойком мчить,
Коли на південь відлітає птиця,
Так я, передбачавши ремства нить,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Уздрів, як тіней гурт в бурханні мчиться,
І запитав: «Учителю, яким
Жінкам так грізно чорний вітер мститься?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = '«Найперша з тих, що виглядом своїм
Тебе цікавить, - він мені промовив, -
Була царицею над світом всім;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Щоб одібрати ґрунт у марнословів,
їй підказала похіть навісна
Розпусту скриту вивести зі сховів, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Семіраміда, Нінова жона
І спадкоємиця його зрадлива;
Султан тепер там, де жила вона.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'А це - кохання жертва нещаслива,
Яка збезчестила Сіхея прах;
А далі - Клеопатра похітлива».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Я вздрів Єлену, за яку в боях
Лягли війська, Ахілла міць велику,
Яка з кохання згинула в віках,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Паріса вздрів, Трістана й ще без ліку
Тих нещасливих, що Амор жене,
Як за життя їх гнав на згубу дику.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Коли мій вождь назвав число значне
Мужів і дам - весь почет іменитий,
Я засмутився, жаль пройняв мене,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'І я сказав: «Співцю, поговорити
Хотів би я із тінями двома,
Що вихор їх жене несамовитий».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'І він: «Побачиш, як зрідіє тьма
Й вони наблизяться: ім''ям любові
Благай, і пара підлетить сама».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Коли до нас їх вир підніс раптовий,
Подав я голос: «Привиди журби,
Як Інший зволить, станьмо до розмови».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Як в полум''ї жадоби голуби
У рідні гнізда між зелені крони
Летять на крилах спільної судьби, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Вони удвох з оточення Дідони
Перенеслись у пітьмі коловій, -
І стали біля нас без заборони.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = '«О ти, що ходиш по землі живий
І надійшов сюди, у сморід чорний,
До нас, що світ забарвили в крові.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Якби нам другом цар був непоборний,
Вблагали б ласку ми тобі послать,
Щоб ти щасливим був у висі горній.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'То слухай, споминай, що є згадать,
І поки буря десь там забарилась,
Ми будем слухати і розмовлять.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Жила я там же, де й на світ з''явилась,
Над морем тим, що в нього По втіка,
Котра супутниць тьмою збагатилась.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Кохання, що шляхетних обпіка,
Його зманило молодичим станом,
Який сточила тут печаль гірка.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Кохання, що кохать дає й коханим,
Мене взяло, вогнем наливши вщерть,
Що став моїм він, як ти бачиш, паном.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Кохання нас вело в злощасну смерть.
Каїна жде того, хто кров''ю вмився», -
І вже їх ворушила вітраверть.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Ці душі слухавши, я похилився
І в болісну заглибився печаль;
Поет спитав нарешті: «Чом спинився?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'І я на це почав: «О лютий жаль!
Ці ніжні мрії, ці солодкі чари
їх завели в таку скорботну даль!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'А там звернувся до цієї пари
Й почав: «Франческо, від твоїх страждань
У серці чую болісні удари.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Але скажи: під час палких зітхань
Як вчило вас чаруюче кохання
Спізнати мить жагучих поривань?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Й вона: «Немає більшого страждання,
Як згадувати любий щастя час
В біду; твій вождь здає в тім справоздання.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Коли ж ти прагнеш знать, який у нас
Початок був коханню, збудься спраги, -
Я плакать буду й мовить водночас.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Якось ми вдвох читали для розваги,
Як Ланчелота взяв кохання пал,
І самоти не брали до уваги.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'І часто, мов під дією дзеркал,
Нам під очима лиця пік рум''янець.
Але нас подолав миттєвий шал:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Ми прочитали, як тремтів коханець,
Бо вперше в губи цілував самі, -
І цей от, мій незмінний співвигнанець,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Мені вуста торкнув, з жаги німий, -
Твір і співця за Галеотто мавши,
Вже того дня більш не читали ми».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Так дух розповідав цей, споминавши,
А той ридав; і руки я простер
У даль за ними, від жалю вмиравши,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'І впав, неначе той, хто нагло вмер.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 48;

UPDATE cantos SET title_uk = 'ПІСНЯ ШОСТА Коло третє. - Цербер. - Черевоугодники. - Чвакало'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 6
    AND p.name = 'Inferno';

UPDATE terzinas SET text_uk = 'Вернулась тяма, що на час лишила,
Коли жалів я свояків отих,
Чия печаль так дуже засмутила,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Й нові я муки й мучених нових
Побачив всюди, де б не озирався,
Де б не лишав мій крок слідів своїх.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Я в третім колі: дощ не припинявся,
Холодний, вічний, проклятий, важкий;
Він по землі одноманітно слався.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Градини, іній, снігові грудки, ,
Мішаючись із мороком постійним,
Смердили під ногами ґрунт в''язкий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'І Цербер, звір із вищиром потрійним,
На три собачі пащі валував
На люд, поглинутий болотом гнійним.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Багряні очі, шерсть, масна від страв,
Грубезне пузо, лапи - кігті наче -
Він гриз, і дер, і дряпав, і кусав.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Промоклі тіні вили по-собачи,
Й чи той чи цей ховаючи з боків,
Крутились дзиґами, та без удачі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Хробак здоровий, Цербер нас зустрів,
Роззявив пащі враз, ошкірив зуби
І весь од люті сильно затремтів.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'І руку простягнув вожай мій любий,
Землі взяв жменю та як кидоне
В голодні пащі наїдок той грубий!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Мов пес, коли йому шматок заткне
Голодну пащу й зів, з брехання спухлий,
Замовкне раптом, поки не ковтне, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Так Цербер увірвав, одразу вщухлий,
Свій рев, який так голосно гуде,
Що душі тут усі були б поглухли.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Йдучи по тінях, по яких іде
Дощ нескінченно, ставили ми ноги
В порожняву у вигляді людей.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Вони підводитись не мали змоги,
І лиш один схопивсь аж підстрибнув,
Коли побачив нас серед дороги.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = '«О ти, хто сміло в Пекло це ступнув, -
Він проказав, - мабуть, мене впізнаєш,
Бо ти уже, коли я вибув, був».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'І я йому: «Такий ти вигляд маєш
Унаслідок тривалого ярма,
Що вже навряд тепер тебе вгадаєш.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Повідай же - бо тут ти недарма, -
Який ти гріх вчинив, що кар за нього
Є сила важчих, гірших же нема?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'І він: «У місті, заздрому до всього,
Ти народився, - тож я твій земляк,
Бо й я родивсь там для життя масного.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Обжерливістю відзначавсь я так,
Що Чвакалом дражнили всі знайомі, -
А тут я мокну під дощем, бідак.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'І довелося не мені самому
Однакових тут скуштувать силець
За гріх однаковий». Сказав по тому'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Я: «Чвакало, так скрушно для сердець
Бринить твій жаль і викликає сльози;
Та, може, знаєш ти, який кінець'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'У нашім місті матимуть погрози,
І що веде співгромадян до чвар,
І де зростають праведності лози?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'І він мені: «Після тривалих свар
Рясна проллється кров лісовиками,
А партію противну жде удар.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'На третій рік повернуться до брами
Вигнанці й переможницькі війська,
Й підлесник прийде нинішній з військами.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Притисне здоланих п''ята важка
Тих, що надовго містом завладають,
А цим лишаться сльози і тоска.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Два праведники марно промовляють:
Жадоба, скупість, заздрість до єства -
Од іскор тих в людей серця палають».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Так закінчив печальні він слова,
І я йому: «Іще прошу, мені ти
Відкрий усе, що темрява хова.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Тегг''яйо, Фаріната знаменитий,
Ще Рустікуччі Якопо й ще хтось, -
От як Арріго й Моска іменитий, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Скажи мені, де місце їм знайшлось?
Дізнатись хочу про судьбу найкращих -
Іти їм в Рай, чи в Пекло довелось?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'І він: «У норах ще чорніших, важчих
За гірший гріх каратись треба їм,
Побачиш їх внизу у муках тяжчих.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Як знову підеш світом ти живим,
Прошу, згадай мене хоч ненароком,
А більш я не скажу й не відповім».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'І ще раз скошеним од болю оком
На мене глянув і під шум струмин
Згубився в натовпі сліпців широкім.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Вожай сказав: «Уже не встане він,
Аж поки на сурму громовокрилу
Не явиться нещадний властелин.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Усяк повернеться в свою могилу,
Одіне плоть колишнього буття
Й почує вироку незрушну силу».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Ми тихо йшли, немов між куп сміття,
Між тіней, кинутих під дощ похмурий,
І про грядуще мовили життя.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Сказав я: «Вчителю, чи їм тортури
Побільшить вирок правий судії,
Чи проясніє їхній вид понурий?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'І він: «Науки пригадай свої:
Відомо, що чим ближча досконалість
В душі, тим більші рай чи скорб її.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'До риси досконалості й на малість
Не підійти їм після їхніх діл,
А все ще сподіваються на жалість».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Так в бесіді пішли ми третім з кіл,
Про зміст її не стану я казати,
І вийшли зрештою на дальший схил.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'І тут зустрів нас Плутос, недруг клятий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 39;

UPDATE cantos SET title_uk = 'ПІСНЯ СЬОМА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 7
    AND p.name = 'Inferno';

UPDATE terzinas SET text_uk = '«Папе Сатан, папе Сатан алеппе!» -
Завів так Плутос голосом хрипким,
І мій мудрець, що знав усе в цім склепі,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Мене розрадив: «Хоч би й надто злим
Був звір, а все ж не втрима на запорі
Від тебе переходу колом цим».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'А далі товстогубій злій потворі
Промовив він: «Проклятий вовче, цить!
Бо задихнешся, як смертельно хворі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Не без причин в безодню він стремить:
Так хочуть там, де військо Михаїла
Взялось пиху насильницьку зломить».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'І як під бурю падають вітрила,
Коли зламалась щогла на кормі,
Так хижа твар звалилася безсила.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'І далі ми пішли по цій тюрмі,
В четверте коло, до провалля ближче,
Де зло всесвітнє скублилось у тьмі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'О правосуддя Боже! Хто б міг вище
Накупчити страждань, ніж я уздрів!
І чом душа стає гріхам за грище!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Як хвиля, кинувши Харібди зів,
Біжить назад і інші б''є з розгону, -
Так люд не шкодував тут кулаків.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Я бачив люд з найбільшого загону,
Примушених з усіх боків штовхать
Грудьми й всім тілом кляту перепону.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Тут люто пхала одна одну рать
І вантажі носила з ревним криком:
«Чого їх кидати?», «Чого збирать?» -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Так рухались похмурим колом диким,
І кожен тяг у протилежний бік
З гучним тим самим безсоромним кликом.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'А, на серединний прийшовши стик,
Вертали знову битися жахливо,
І я, не в силі здержати язик,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Сказав: «Учителю, з''ясуй це диво:
Чи часом не тонзурники всі ті,
Із лисинками, що від нас наліво?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'І він: «В своєму першому житті
Усі вони були на розум косі
Й не знали міри в їжі і в питті,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Тож по-собачому хрипкоголосі,
Вертають, вивергаючи лайки,
Всередину із крайніх точок осі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'В тих, в кого на тонзуру маківки
Поголені - у пап, у кардиналів, -
Найбільш скарбів заховано в мішки».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'І я: «В цій, вчителю, картині жалів
Я добре розпізнати мав би тих,
Кого порок іще недавно вжалив».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'І він: «Ти марних не чекай утіх:
Гидке життя спотворює собою
До невпізнанності обличчя їх.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Вони на суд останній прийдуть з бою:
Той стисне кулаки й проклін пошле,
Цей голою заблиска головою.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Бо ті, хто зле збирав, хто тратив зле, -
Приречені на чвари проклятущі,
І всяке їм картання - замале.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Ти бачиш, сину, як скороминущі
Дари Фортуни чинять людям зло,
На бійки спонукаючи найдужчі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Все злото, що під місяцем було
Чи є, душі хоча б одній-єдиній
Спокою ні на хвилю б не дало.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = '«Учителю, - спитав я, - благостині!
Яку Фортуну ти згадав мені,
І як із рук її все благо лине?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Озвався він: «О витвори дурні!
Яке ж бо вас невідання вразило!
Думки тобі відкрию неясні.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Той, хто ширяє в світі мислю сміло,
Небесні сфери сотворив і їм
Дав рушіїв, щоб все навкруг світило.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Усюди світлом ширячись сяйним,
А серед людства діло це - наснага
Тій, хто владає таланом земним,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Щоб всі передавав минущі блага
Народ народові, сім''ї - сім''я,
Бо меншає в людей з літами спрага.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Той кориться, цей силою сія
За присудом тієї, що з ділами
Весь час таїться, як в траві змія.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'І, високо літаючи над нами,
Вона провидить, судить і вершить
Нарівні з іншими всіма богами.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'У ній ніщо на місці не стоїть
І зміни одна одну обганяють,
Нове-бо виникає кожну мить.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'І от її усі лиш розпинають,
Замість палку складати дяку їй,
І заповзято й дружно проклинають.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Вона ж в незмінній радості благій
Співає з ангелами нам із далі
І крутить кулю в благості своїй.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Проте спустімось на ще більші жалі, -
Заходять вже зірки, які стреміли вверх,
Коли я рушив; поспішімо ж далі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Пройшли ми колом тим на самий верх,
Звідкіль стікав ручай, зникавши в рові,
В якому промінець останній мерк'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'В воді, скоріше чорній, ніж багровій.
І ми зійшли в провалину саму,
Ідучи вслід похмурому струмкові.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Збігаючи в ненависну пітьму,
Спливала річка, наче під ворота,
Під те багно, що Стікс ім''я йому.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Я, придивившись, що то за сквернота,
Побачив тіней голих гурт тісний,
Занурений в драговину болота.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Не лиш руками билися вони,
А й головою, і грудьми, й ногами,
А хто й зубами гризся, навісний.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Мій добрий вчитель: «Сину, перед нами
Це душі тих, кого вразила лють,
А ще до того знай: під струминами'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Багато душ у смороді гниють,
Окіл бентежать зойками гучними
Й колишуть, як ти бачиш, каламуть».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Стогнали в твані тонучі: «Були ми
У траурі на сонячній землі,
Нам душу сповивали чорні дими,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Й терзаємось у смороді, в гниллі».
Так виливали, кумкаючи, муку,
Інак не в силі висловить жалі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Відмірявши значну дугу по луку,
Між річкою й болотом серед мли,
На тих дивившись, хто ковтав багнюку,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Високої ми вежі досягли.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 44;

UPDATE cantos SET title_uk = 'ПІСНЯ ВОСЬМА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 8
    AND p.name = 'Inferno';

UPDATE terzinas SET text_uk = 'Я, далі ведучи, скажу, що, пішки
Ще вежі не діставшись, на вінці
Ми зори зупинили біля вишки,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Де вздріли два спахнулі промінці
Й на відповідь ще й третій розгорівся
У ледь очам приступній далі цій.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Й від мене в море всяких знань полився
Потік розпитувань: «Це хто? Кому
Той пломінь відповів? Як він з''явився?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'І вождь: «Якби ти крізь імлу німу
Міг бачити, то б стрівсь очима з жданим,
Невидним ще у випарів диму».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'І як проноситься над стиглим ланом
Легка стріла з дзвінкої тятиви,
Так утлий човен, мовби ураганом,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Нестримно мчав на берег неживий,
А в ньому іздаля човняр жахливий
Кричав: «Нарешті, грішнику новий!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = '«Ні, Флегію, ні, Флегію гнівливий, -
Сказав мій пан, - з тобою будем ми,
Лиш поки цей здолаєм бруд вадливий».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Як хто розчарувань зазнавши тьми,
Почне стогнати й голосить при цьому,
Так зойки Флегій видихнув сами.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Вождь опинився в човнику легкому,
Подавши знак мені іти за ним;
Вагу в човні лиш я складав вагому.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Ми посідали, і шляхом мутним
Побіг наш човен, глибший слід лишивши,
Ніж поки був він із гребцем самим.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Ми рухались, по мертвій річці пливши,
Як перед мною встав хтось у багні
Й спитав: «Хто ти, що йдеш тут, не доживши?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'І я: «Іду, бо вільно йти мені,
А ти хто? Ти збудив ніяк не жалі».
І він: «Я з тих, що плачуть тут сумні».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'І я: «Бодай ти у плачу й печалі,
Проклятий образе, віками гнив!
Тебе впізнав я, хоч ти весь у калі».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Тоді він борт обіруч ухопив,
Та вчитель відіпхнув його, до діла
Сказавши: «Геть іди, до інших псів!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'А там притис мене тісніш до тіла
Й, цілуючи, сказав: «Блаженна та,
О гнівний душе, що тебе родила!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Живим владала ним пиха пуста,
Ніхто добром не згадує за нього,
А тінь його тримають болота.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'А скільки ще царів та панства того,
Що тут залізуть свиньми у багно
І не залишать спогаду малого!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'І я: «Учителю, прошу одно:
Нехай човняр продовжить веслування,
Поки гордій не піде геть на дно!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'І він мені: «Єдина мить чекання!
Ще човен наш не стане на приплав,
Як буде здійснено твоє бажання».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'І я побачив, як того обпав
Великий гурт, до люду не подібний,
І Богу вдячні я слова послав.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Усі горлали: «Ось Філіппо Срібний!»
А той, скажений флорентійця дух,
Рвав бік собі і в люті був несхибний.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'На тому зник з очей і гамір вщух.
Та вчулося виття, по тьмі розлите,
І знову я напружив зір і слух.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Мій добрий вчитель мовив: «Слізьми вмите
Це місто, де страждає люд без меж;
Воно, прокляте, має назву Діте!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'І я: «Учителю, мечетей, веж,
Будинків пломеніють ясні стекла,
Пойняте все загравами пожеж».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'А він: «Огонь, де йде борня запекла,
Дає свій одсвіт у найдальший схов,
Це взнаєш, нижнього досягши Пекла».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Нарешті човен у рови зайшов,
Які оточували землю туги;
Був, як з заліза, мур навкруг будов.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Але ще довго човен креслив дуги,
Аж поки не гукнув човняр: «Тепер
Мерщій виходьте, це ваш берег другий!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Було при брамі кількасот химер,
Колись рясним дощем упалих з неба,
Вони гукали: «Хто з вас ще не вмер,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'А йде нахабно й сміло до Ереба!»
Зробив їм знак мій вчитель видатний,
Що потай побалакати їм треба,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'І, хижу вдачу стримавши, вони
Сказали: «Йди, цього ж лиши в пащеках
Страхів, як він не боягуз дурний,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'То хай вертається стежок далеких
Собі шукати, ти ж лишайся тут,
Ти, що водив його по небезпеках».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Читачу, уяви, яких отрут
Я скуштував, страшну зачувши мову,
І захотів побачить рідний кут!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'І я: «О вождю, подавав чудову
Мені ти допомогу раз із сім,
Видимі ж біди виникали знову!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Не кидай же мене під містом цим!
Коли мені йти глибше - річ не вільна,
То краще вже додому повернім!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Та вождь, що путь була з ним досі спільна:
«Не бійсь, не відберуть в нас навмання
Доріг, які дала нам влада чільна.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Тут жди мене, і хай охороня
Тебе Надія; в цій імлі мертвотній
Тебе ніколи не залишу я».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Пішов мій добрий батько, я ж, самотній,
Запав у нерішучість претяжку
Між «так» і «ні» в борні безповоротній.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Ловив його я мову нешвидку,
Вони ж раптово, ніби ненароком,
Всі поспішили за стіну міську'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Й замкнули браму перед самим оком
Учителя мого, і він один
До мене повернув повільним кроком.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Потупившись, ішов понурий він,
Весь час гадавши про відмову строгу:
«Хто не пустив мене до скорбних стін?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Сказав мені: «Я не досяг порогу,
Та не турбуйсь, здолаю їх війська,
Готові довгу витримать облогу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Це не нова зухвалість їх така:
їх взнали верхні брами всемогучі,
Що й досі залишились без замка.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Вгорі ти прочитав слова мертвучі,
Але уже крізь місто те страшне
Йде без супутніх колами по кручі'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Той, хто нам брами всюди відімкне».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 44;

UPDATE cantos SET title_uk = 'ПІСНЯ ДЕВ''ЯТА Біля воріт Діте. - Фурії. - Посол з неба. - Коло шосте. - Єретики'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 9
    AND p.name = 'Inferno';

UPDATE terzinas SET text_uk = 'Той колір, що я вкрився ним од страху,
Коли побачив, як верта вожай,
Відбивсь йому в лиці відтінком жаху.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Спинивсь поет, запавши у відчай,
І став вдивлятись марно, хоч і ревно,
Крізь непрозору млу в туманний край.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = '«Проте ми подолати мусим певно, -
Почав він, - а як ні... Підмога де?..
О, якби він з''явився тут напевно?..»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Я добре бачив, що у нього йде
Уривано за одним словом друге,
Зв''язку ж немає поміж них ніде.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'І сповнився боязні я і туги,
Вбачаючи у мові тій сліди
Уявної душевної недуги.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = '«Чи сходив хто до щілини сюди,
Для цього перше кинувши кружало,
Де кара - безнадійність назавжди?» -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Так я спитав і мовив він: «Бувало,
Що хтось сюди проходив не без діл
Тим шляхом, що я ним пройшов чимало.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'От і мене у цей послала діл
Зла Еріхто; її відьомська школа
Вертати вміла духів до їх тіл;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Коли моя душа лишилась гола,
Вона вдягла ізнов у плоть мене,
Щоб тінь вернуть з Іудиного кола.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Найнижче місце те найбільш сумне
Й найдальше від небес, що всім керують.
Тож знаю шлях я, - хай твій ляк мине.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Ці болота, що всюди тут панують,
Смердять навколо міста злих жалів,
Де вороги загибель нам готують...»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Забув я, що він далі говорив,
Бо надто вражений я став страшилом,
Коли на вежі вогняній уздрів'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Пекельних фурій, що звились над схилом
Утрьох, жахливі, геть усі в крові,
Хизуючись своїм жіночим тілом.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Зелені гідри - шати їх живі,
Замість волосся ж в них клубки зміїні
Сичали в кожної на голові.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'І він, служниць пізнавши господині
Над царством вічного плачу гірким:
«Поглянь, - сказав, - на лютих цих еріній.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Це - Алекто із голосом гучним,
А поруч - Тісіфона, образ жаху,
Мегера ж - зліва». І скінчив на цім.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Ті ж груди дряпали собі, з розмаху
Руками били й так ревли з-за стін,
Що до поета я припав зі страху.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = '«Медуза де? Хай скам''яніє він, -
Вони горлали, дивлячись додолу, -
На ньому мста Тезеєвих провин!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = '«Ти відверни й сховай лице під полу:
Побачивши страшний Горгони лик,
Забудеш путь по сонячному колу», -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Сказав і повернув мене убік
Учитель та притис іще й руками
Мої долоні до моїх повік.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'О люди із здоровими думками!
Помисліть-но, яка наука вам
Під цими дивовижними рядками!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Тим часом ріс у напрямі до брам
Разючий гуркіт у бурхливій хвилі,
Надаючи стрясання берегам.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Так вихори шаліють знавіснілі,
Коли повітря б''ють дві течії,
У прямуванні різні, рівні в силі, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Гілля ламають, гатять ручаї,
Нестримно мчать, женуть людей, худобу,
Не розбиравши, де стада чиї.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'І вождь, звільнивши зір мені: «Ти спробуй
Звернути ока нерв спочилий свій
На древню піну й пари люту злобу».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Мов жаби, як зачують раптом змій,
Закумкають, аж затуляєш уші,
І всі під воду кинуться мерщій, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Так, бачив я, численні грішні душі
Від Одного тікали в твань грузьку,
А Той ступав по Стіксу, як по суші.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'А щоб запону одслонять важку,
В задусі зводилась його лівиця,
Мов піднімала річ якусь тяжку.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Я взнав посла небес, що мав явиться,
Звернувсь до вчителя, і він мовчком
Дав знак мені в шанобі поклониться.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Ах, як гнівився цей борець із злом,
Що ображало в ньому досконалість!
Він браму розчинив тонким жезлом.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = '«О вивержена з неба клята малість! -
Гукнув він, ставши на жахний поріг, -
Звідкіль така обурлива зухвалість?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Чом опиратись тим, хто переміг?
Скорітесь волі, що в мету влучає
І збільшує для вас тягар вериг?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Ви знаєте, чим доля відомщає?
У Цербера у вашого з оков
Намулені місця всяк добачає!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Нечистим шляхом він назад пішов,
На нас не кинувши свій погляд милий,
Мов той, хто, ринувши у мислей схов,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Не бачив тих, що поруч з ним ходили.
Дало нам сил це сяйво серед мли,
Й відважно ми поріг переступили.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Без опору до міста ми зайшли,
І палко я бажав про тих дізнатись,
Що у фортеці замкнені були.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Зайшовши, став я миттю оглядатись
І вмить побачив діл скорботи й зла,
Де мало все од лементу здригатись.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Як в Арлі, де ріка тече мала,
Як в Полі над Карнаро, де в затоці
Італія замок собі знайшла,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Гробниці горбляться на кожнім кроці, -
Тут ними всіяно весь ґрунт пустий;
Та гірш було, що з усієї моці'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Між ними звився полумінь густий.
Жара пашіла скрізь така велика,
Якої й звиклим не перенести.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'На трунах зсунуті були всі віка,
Й зітхання чулися з-під них жаскі,
Мов із грудей розтятих чоловіка.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'І я: «Учителю, це хто такі,
Що, змушені до скорбної постави,
Лиш зойки дикі видавать важкі?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'І він: «Це лжеучень усяких глави
З їх послідовниками. Тут, в огні,
Злічити їх не вистачить уяви.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Із схожим схоже тут в одній труні
У полум''ї, то більш, то менш похмурім».
Він шлях праворуч показав мені,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'І ми пішли між полем мук і муром.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 45;

UPDATE cantos SET title_uk = 'ПІСНЯ ДЕСЯТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 10
    AND p.name = 'Inferno';

UPDATE terzinas SET text_uk = 'І от іде стежиною вузькою
Між мурами товстими й полем мук
Учитель мій, і я за ним ступою.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = '«О вишній уме, що до гірших лук
Ведеш мене, - почав я, - як владика,
Ти спрагу вдовольни із власних рук!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Чи можна тих, чия вина велика,
Побачити? Нехай би підвелись -
Немає ж варти, і розкриті віка».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'І він: «...Вони закриються колись,
Як з Йосафату вернуть опочилим
Тіла, в які свого часу вляглись.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Це кладовище віддане могилам
Для Епікура та його рідні,
Які вбивають душу з вмерлим тілом,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Але небавом при одній труні
Задовольниться й це твоє жадання
І друге, що ховаєш в таїні».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'І я: «Мій добрий вождю, запитання
Я пильно бережу в душі своїй,
Щоб виконать твої заповідання».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = '«О ти, що йдеш по місту цім живий
Уродженцю Тоскани, будь же ґречний,
Прошу тебе, зі мною мить постій.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Твоя вимова - доказ безперечний,
Що ти із благородної землі,
Якій я, може, був занебезпечний».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Так гримнув голос у гробничій млі, .
І з страхом до вождя я пригорнувся,
Немов до нені злякані малі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'А вождь мені: «Чого це ти вжахнувся?
Ти бачиш Фарінату, що піднявсь
По крижі в домовині й не схитнувся».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'І пильно в нього зором я втуплявсь,
А він, чоло здіймаючи та груди,
Здавалось, Пекло згорда роздивлявсь.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Вожай до нього між могильні груди
Штовхнув мене, уміло ведучи,
Й сказав: «Хай мова в тебе ясна буде».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Коли ж наблизився я, ідучи,
На мене скоса він поглянув знизу
Та й попитав зневажливо: «Ти чий?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'І я, щоб догодить його капризу,
Нічого не втаївши, все повів,
І він неначе в млу вгорнувся сизу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'А далі вимовив: «Твоїх дідів
Вважав я з партією ворогами
І двічі на вигнання засудив».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = '«Та привела до рідної їх брами, -
Я відказав, - і перша, й друга путь, -
Цього ж зробить не вміли ваші з вами».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'І тут, в труні, приховуючи лють,
Звелась ще друга голова по шию -
Навколішки підвівся дух, мабуть.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Дух озирнувсь, плекавши, певно, мрію
Побачить поруч мене ще когось,
Але, даремну втративши надію,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'В сльозах сказав: «Коли уму вдалось
Тебе звести у цю сліпу в''язницю,
Де син мій? Не з тобою він чогось».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'І я: «Не сам іду крізь цю темницю:
Керує мною той, що поряд жде,
З ким Гвідо ваш не міг заприязниться».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Сумні слова й лице його бліде
Були для мене ясні й зрозумілі,
І я в відмові не схибнув ніде.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'І з зойком підхопивсь він у могилі:
«Ти що? «Не міг!» Отож його нема?
І світло дня не тішить очі милі?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Й, побачивши, що ждати вже дарма,
Бо з відповіддю я спізнивсь моєю,
Впав навзнак, і його покрила тьма.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'А гордівник, що мовою своєю
Мене затримав, не змінивсь в лиці
І далі вів перервану рацею:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = '«Не вміють вас мої долать бійці,
І це мене жахливіше терзає,
Ніж язики вогню в могилі цій.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Та п''ятдесят разів не запалає
Прекрасна владарка держав нічних, -
Й цього невміння взнаєш зло безкрає.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Та хай ти вернеш до країв земних! -
Скажи, чом цей народ такий жорстокий
В своїх законах до людей моїх?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'І я йому: «Багряні ті потоки,
Що нам при Арбії несли загин,
Нерідко згадує наш храм високий».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Чолом поникнувши й зітхнувши, він:
«Не сам я був, - сказав, - як до навали
Приєднувався я не без причин.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Але був сам, коли усі жадали
Фйоренці і руїни, й всяких бід.
Сам проти всіх був, непохитний, сталий».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = '«Ах, угамувався врешті ваш би рід! -
Я побажав. - Зніміть же пута з мови,
Під їх вагою я неначе зблід.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Як я гадаю, зір у вас готовий
Побачить, що з собою час несе,
Сучасність же огорнута в покрови».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = '«Як ті, хто кепсько бачить, зрим ми все, -
Сказав він, - що віддалене від ока:
Всевишній вождь дає нам світло се.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Коли ж близьке воно, то зависока
Нам ця завада; без вістей од вас
Ріка знання про світ в нас неглибока.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Отож ти розумієш, що запас
Всіх наших знань загибель жде єдина,
Коли замкнеться хід в майбутній час».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'І каючись, мов то моя провина,
Відмовив я: «Скажіть тому, хто впав,
Щоб не оплакував живого сина.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Не відповів я через безліч справ,
В мою бо душу сумнів труту крапав,
Що з неї розум ледве врятував».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'І мій учитель тут мене поквапив,
І поспішив я духа розпитать,
Хто з ним іще у ці гроби потрапив.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'І він: «Душ з тисячу - чимала рать;
Є Федеріко Другий, а крім нього -
Ще Кардинал; не варт і рахувать».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Він щез, і до поета я старого
Вернувсь у хвилюванні - мова ця
Передвіщала безліч зла нового.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Він вирушив, і я - в сліди співця.
Йдучи він запитав: «Про що турботи?»
І я йому відкрився до кінця.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = '«Запам''ятай все мовлене навпроти
Твоєї долі, - наказав мудрець.
Звів палець, - та дізнайся ось про що ти:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Лиш ставши перед любим для сердець
Промінням зір, що бачать все правдиво,
Життя свого ти взнаєш реченець».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Сказавши це, він повернув наліво,
Й пішли ми до середини, де був
Крутий обрив, що біг згори стрімливо,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'А звідти сморід нестерпучий тхнув.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 46;

UPDATE cantos SET title_uk = 'ПІСНЯ ОДИНАДЦЯТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 11
    AND p.name = 'Inferno';

UPDATE terzinas SET text_uk = 'Ми пругом вужчим перейшли й тіснішим,
Який складався з диких валунів,
Спинившись над проваллям ще жахнішим.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Від смороду, який весь час валив
З безодні чорної невпинним плином,
З нас кожен заховатися волів'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'За віко гробу з написом нетлінним:
«Це папи Анастасія тюрма,
Що впав у єресь слідом за Фотіном».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = '«Іти нам вниз можливості нема,
Аж поки нюх не звикне до гидоти,
А там для нас вже буде все дарма», -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Так вчитель мій, і я на те: «А доти
Щось роз''ясни мені, щоб час не йшов
Намарне». Й він: «Та я не проти.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Мій сину, між скелястих цих основ, -
Почав він мову, - містяться три кола,
Що вужчають, біжучи стрімголов.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Юрба проклята повнить їх довкола, -
Скажу, щоб далі ти лиш додивлявсь,
Яка покара вдачу їх зборола.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Злий вчинок приводом неправді ставсь,
Огидний небу; той несправедливий,
Хто до насильства та оман вдававсь.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Самим лиш людям злий обман властивий
І тим бридкіший Богу, тож для них
У нижчих колах мук добір жахливий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'У першім - тьма насильників лихих;
Трьом смугам віддане воно суміжним,
Троїстий-бо природою цей гріх:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Чинити Богові, собі чи ближнім
Насильство можуть, їм та їх речам,
Як взнаєш, стежачи за думки стрижнем.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Насильній смерті й ранам ближній сам
Підпасти може, а маєтки в нього -
Руйнації, пожежам, грабежам.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Отож розбійник, ласий до чужого,
Людиновбивця і брудний палій -
Всі в першій смузі покарання злого.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Собі й маєткам лиха заподій
І в другу смугу муки йди терпіти,
Карайся у провині там своїй'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Із тим, хто жити не схотів на світі,
Добро гайнує, програш покрива
І плаче там, де слід було б радіти.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'А ці насильства - кривда Божества:
Його відкинення, хула кричуща,
Зневага до природи і єства.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Тому-то смуга познача найвужча
Тавром своїм Каорсу і Содом
І всіх, кому мерзенна сила суща.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Обман, що честь гидує ним, як злом,
Можливий і до тих, хто йме нам віру,
Й до тих, які не вірять нам цілком.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'А ще є способи вбивати щиру
Любов природну, вдавшись до мерзот.
Тож в другім колі мучать совість хиру'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Святош, що наживалися стокрот
З підробок та шахрайства, симонії,
Хабарництва та інших ще підлот.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Любов обманом нищать лиходії
Й ту, що природній додає добро
І зроджує довірливі надії.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Найменше з кіл є в той же час ядро
Для всесвіту й престол для пана Діте,
Там зрадників шматується нутро».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'І я: «Учителю, твоє розвите
Пояснення висвітлює мені
Цю прірву і населення в ній скрите.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Але скажи: ті, хто вищить в багні,
Хто в вихрі мчить, хто мерзне в зливі з тучі,
Хто лається у марній метушні, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Чом обминули місто це палюче
Раз Божий гнів над ними розітнувсь?
І чом караються так нестерпуче?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'І він мені: «Чого це так схибнувсь
Твій, - мовив, - розум, може, понеслися
Кудись думки й на інше він звернувсь?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Згадай-но краще, з пам''яттю зберися,
Що в «Етиці» твоїй було в рядку
Про три образливі для неба риси:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Нездержливість, злобливість та ярку
Тваринність? Ще нездержливість на кару
Заслужує порівняно легку.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Розглянь-но істину цю, повну чару,
І пригадай, - це саме призвело
Ті грішні душі до важкого вдару, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Збагнеш, чом віковічне їх житло
Не тут і чом на кару без докорів
їх Боже правосуддя прирекло».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = '«О сонце, лікарю коротких зорів,
Ти словом так вщасливлюєш мене,
Що всю науку радо б я оспорив,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Назад вернись, хай вузол розітне, -
Сказав я, - мисль твоя, чому насподі
Карається лихварство навісне?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = '«У філософському, - він мовив, - зводі
Одне із місць пояснення дає,
Що основним початком у природі'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Премудрість і мистецтво Божі є;
Коли ж ти іншим віддасись наукам,
Розгорнеш вчення «Фізики» своє,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'То взнаєш, що природним всім спонукам
Мистецтво, ніби учень, вслід іде, -
Отож воно є наче Божим внуком.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Ти маєш знати, що Мойсей веде
У книзі «Битія», що Бог не всує
їм двом довірив людство молоде.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'А в лихваря щось інше за мету є,
Йде манівцями, крізь чагар та хмиз,
Мистецтвом і природою гордує.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Та час вже лаштуватись нам униз,
Пливуть до обрію небесні Риби,
Наблизився до Кавру сяйний Віз'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'І видно шлях, що йде в камінні глиби».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 39;

UPDATE cantos SET title_uk = 'ПІСНЯ ДВАНАДЦЯТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 12
    AND p.name = 'Inferno';

UPDATE terzinas SET text_uk = 'Місця, де йшли ми з горем та печаллю,
Були такі похмурі та страшні,
Аж зір від них ми відвернули з жалю.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'На Тренто схожі ці місця сумні,
Де берег Адіче колись порвали
Чи труси, чи пересуви земні.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Від самого шпиля сповзли завали
В рівнину, і немає стежки вниз
Тому, хто вийде на високі скали, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Такий був спуск до царства муки й сліз.
Вгорі ж, де ледве можна розміститься,
Розлігся звір і всього себе гриз,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Неначе той, хто до нестями злиться,
Ненатлий звір, який знеславив Кріт;
Від лжекорови він лиш міг вродиться.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Мудрець йому: «Гадаєш, знов привіт
Тобі прислали скорені Афіни,
А вождь їх смерть приносить до воріт?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Та геть, тварюко! Цей не взяв єдиний
Мотка в твоєї мудрої сестри,
А йде, щоб бачить ваших мук картини!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Як бик, упавши в час кривавий гри
Від вдалого удару, не крутився,
А здригував ногами до пори, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Отак від люті й Мінотавр звалився.
Вожай гукнув мені: «Униз біжім,
Аж поки він ще не переказився».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'І схилом поспішили ми крутим,
А камінь сипався, немов нестямки,
З-під ніг моїх під тягарем новим.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Замисливсь я, й сказав він: «На уламки
Милуєшся ти величезних гір,
Де я лишив це чудище без тямки?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Як того разу бачив їх мій зір
І страх вони породжували в мене,
То їх не руйнував ще владний вир.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Та перед тим, як в огненій геєні
Той походжав, хто вивів багатьох
Із тих, що вили, в Діте полонені,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Одразу трусонувся хмурий льох,
І я подумав, що з жари здригнувся
Усесвіт і зчинивсь переполох,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Що, мабуть, світ на хаос обернувся:
У ту хвилину цей важкий стрімчак
Із місця давнього свого й схитнувся.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Але зверни свій зір на діл: отак
Вирує у крові потік вогненний
Насильникам, що жерли неборак.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'О жадібність сліпа, о гнів страшенний,
Що нас веде в короткому житті
І вік в крові терзає нескінченний!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Я бачив рів: краї його круті
Суціль усю долину оточили», -
Про це повів учитель мій в путі,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Навкруг центаври бігали щосили
Й ті самі луки на боках у них,
Що й на землі в мисливстві їм служили.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'З''явились ми, і стук копит утих,
А троє ухопили стріли в руки
І до тятив приклали їх тугих.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Один гукнув здаля: «Які це муки
Чекають вас, що ви згори йдете?
Кажіть, не руштесь, бо ми спустим луки!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Мій вчитель мовив: «Відповідь на те
Дамо Хіронові, ти ж - неотеса,
Й тобі на лихо запал твій росте. -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Торкнув мене й додав: - Ти бачиш Несса,
Який красуню Деяніру звів
І загубив, убитий, Геркулеса.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Середній, що одне плече підвів, -
Великий то Хірон, пестун Ахілла,
А третій - Фол, якого знищив гнів.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Вздовж рову біга їх велика сила,
Стріляючи усіх, хто виплива
Над рівень, що їм доля ухвалила».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Ми підійшли, привітні шлем слова...
Кошлатою зарослий бородою,
Кінцем стріли Хірон ледь розсува'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Вусища над великою губою
Та до своїх: «Глядіть-но, камінець
Він ідучи ворушить під собою!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Такого не вчинив би жоден мрець».
Торкнув його мій вождь у груди голі,
Де з чоловіком злився жеребець,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'І мовив: «Він живий. З святої волі
Показую йому цей темний діл -
Це неминучість, а не примха долі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Та, що мені дала новий уділ,
Співати перервала «Алілуйя».
Він не харциз, я ж дух без грішних діл.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Та ради цнот, що ради них терплю я
Цей дикий шлях, багнище це руде,
Нам дай когось ти із своїх, молю я,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Щоб указав він місце нам тверде
Та й переніс своїм хребтом широким.
Бо він не дух, повітрям він не йде».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Хірон праворуч повернувся боком
І мовив Нессові: «Ти - провідник,
А стріне хтось, обороняйся скоком».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Повів він берегом одної з рік,
Де вир кипів клекочучої крові
І звідки чувся відчайдушний крик.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Я бачив тут занурених по брови.
І мовив Несе: «Тут кожен з них - тиран,
Ковтать майно і кров чужу готовий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Тут ті, хто злочином сквернив свій стан.
Тут Александр і Діонісій лютий,
Сицилії жорстокосердий пан.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Той, з чорним чубом, пишний та надутий,
То Адзоліно, а білявий цей -
Обіццо д''Есте, вмерлий без покути:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Нешлюбний син послав у край смертей».
Звернувсь до вчителя я, й той промовив:
«Тут перший він, я другий, я з гостей».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'А там центавр нам стежку приготовив
До тих, хто аж по шию увійшов
В найгарячіший із пекучих сховів.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'На когось показав: «Він проколов
Те серце у пречистій Божій длані,
Що на далекій Темзі точить кров».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Я бачив далі в річці полум''яній
Чи голови, чи тіні до пупка,
І деякі були мені ще й знані.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Все більш і більш мілішала ріка
І покривала вже самі лиш ноги.
І перейшли ми на той бік струмка.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = '«В малій частині нашої дороги
Все вищав рівень кров''яного дна, -
Сказав центавр, - тож ясно, схил пологий'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Вниз піде річкою, поки вона
Не зіллється із тим потоком саме,
Де для тиранів кара є одна.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Киплять на муки віддані судами -
Аттіла, найстрашніший бич землі,
І Секст, і Пірр; спливаючи сльозами,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Ридають у вируючій імлі
Ріньєр Корнето і Ріньєр да Пацці,
Що на шляхах точили війні злі».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'І він помчав назад, до служби й праці.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 47;

UPDATE cantos SET title_uk = 'ПІСНЯ ТРИНАДЦЯТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 13
    AND p.name = 'Inferno';

UPDATE terzinas SET text_uk = 'Не перебравсь центавр ще через річку,
Як ми потрапили у ліс такий,
Що годі в нім шукати стежки стрічку.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Не свіжість крон - сухих прутів пучки,
Не рівне віття - стовбур вузлуватий,
Не плід рясний - отруйні шпичаки.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Не мешкає там дикий звір кошлатий,
Що радо кублиться в таких місцях,
Як до Корнето з Чечіни ліс клятий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Там гнізда гарпій в тінявих кущах,
З Строфад прогнали гарпії троянців,
Навіявши на них пророцтвом жах.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'В них крила, лик дівочий без рум''янців,
Великі, вкриті пір''ям животи, -
Весь вигляд їх, немов у тих поганців.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'І добрий вчитель: «Будем звідси йти
У другій смузі по трудній стежині, -
Звернувсь до мене, - де пробудеш ти,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Поки опинишся в страшній пустині.
Тож треба, щоб ти добре роздививсь
І довіряв мені, як і донині».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Я чув, як лемент навкруги зчинивсь.
Але ж ніщо ніде не появлялось,
І, здивувавшись з того, я спинивсь.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Мені здалось, що вчителю здавалось,
Немов мені здається, що це крик
У стовпищі, яке в лісу ховалось.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'І він мені сказав: «Придерж язик!
Ти краще кущ візьми і без принуки
Зламай галузку й подивись на сік».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Тоді простяг я перед себе руки,
І відломилась гілочка якась, -
Кущ заволав: «Чом завдаєш ти муки?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'І темна кров із зламу полилась,
А кущ той знову: «Що це за розбої?
Звідкіль така жорстокість узялась?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Були ми люди, нині в сухостої,
А ти явив би більшу доброту
І більший жаль і до змії простої».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Мов зламану зелену гілку ту
Охоплює вогонь з одного краю,
А другий плаче, мокрий, як в сльоту,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Та суміш мови й темного ручаю
Ішла із гілки, я й її впустив,
Мов той, хто повен жаху та відчаю.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = '«Щоб вірив він, що вздрить одне із див, -
Сказав мій вчитель, - душе потерпілий.
Я в вірші про це диво говорив.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Звестись на тебе руки б не посміли;
Та неймовірним був мені той збіг,
Його підбив на вчинок я немилий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Скажи йому, ким був ти, щоб він міг
Розмаяти твоєї слави стяги,
Як знову стане на земний поріг».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'І кущ: «Ця мова будить пломінь спраги,
Що тут не скажеш сам собі «мовчи».
Отож я попрошу у вас уваги.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Я той, хто мав обидва ті ключі
До серця Федеріго, й їх обачно
Всував і висував, не дзвенячи.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Його довіру я сприймав подячно
Й почесну службу завжди ніс як слід,
Сон і життя віддавши їй нелячно.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Блудниця-заздрість, що заради бід
До Цезаря в чертоги зачастила,
Мор для народів, для палаців стид,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Серця всіх проти мене підпалила,
Й підпалені підпал моїй судьбі
Вчинили в Августа, й судьба згоріла.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Душа моя, полишена в ганьбі,
Надумалась ганьбу помстити тлінням, -
Всім правий, я неправим став собі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Але клянусь новим своїм корінням,
Я й раз не зрадив за багато літ
Державця з праведним його правлінням.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Хай той із вас, хто прийде знов у світ,
Поверне врешті честь мені здорову,
Бо заздрощів її притиснув гніт».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Мить почекавши: «Він закінчив мову, -
Сказав мені поет. - Часу не гай,
Як хочеш щось довідатися знову».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'До нього я тоді: «Ти попитай
Предмет, мені корисний і цікавий,
А я без сил, бо жалю повен вкрай».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Тож мовив він: «Обіт твердий і правий
Дасть мій супутник, щирий і незлий,
А ти, закутий душе, будь ласкавий'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Сказати, як душа йде в ці вузли?
Як можеш, ще скажи, чи ваші груди
Від цих кайданів звільняться коли?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Тут стовбур глибоко дихнув, і всюди
Почулося гудіння немале:
«Моя вам відповідь коротка буде.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Коли душа лиха й ведеться зле
Із тілом, кинувши його свавільно,
Мінос її у сьоме коло шле.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Упавши в ліс, не озирає пильно,
Щоб розшукати місце їй своє, -
Ляга у ґрунт зерниною повільно,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Там пагоном і деревом стає,
І гарпії годуються від крони,
Ран завдають, а в рані отвір є.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Як всі ми знайдем наші оболони,
Але їх не надіне жоден з нас:
Чого зреклись - не вернемо в день оний.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Ми принесем їх в ліс, що листя стряс,
Щоб тіло висіло на шпичакові
Душі бридкої безконечний час».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Ще слухать стовбура були готові,
Бо він зростав не на такі ліси,
Коли волання вчулися раптові, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Скидалось на собачі голоси,
І це мисливця б сповіщати мало,
Що недалеко вепр і гончі пси.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'І от - повз нас ізліва двоє мчало
Оголених, подряпаних, прудких
Й без ліку гілля на бігу ламало.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = '«О смерть, прийди, прийди!» - так перший з них,
А другий не відстати намагався
Й кричав: «Такий у тебе, Лано, спіх,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Який під Топпо зовсім не являвся!»
Та, більш не в силі видати хоч звук,
Захекавшись, він під кущем сховався.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'За ним гурти голодних чорних сук,
Наповнюючи ліс, прожогом бігли,
Немов хортиць хтось випустив із рук.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'За мить вони накинутися встигли,
Й розшматували геть того, хто впав,
І розхапали труп ще не остиглий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Мене за руку мій вожай узяв
І вивів до куща, який, нізащо
Скалічений, в сльозах, в крові казав:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = '«О Джакомо да Сант-Андреа! Нащо
Було ховатись в гущині моїй?
Чи винен я, що жив ти, як ледащо?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Наблизившись до нього, вчитель мій
Сказав: «Ким був ти, що перехопились
Слова скорботні у крові густій?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'І він до нас: «О душі, що спустились
Поглянути на зганьблений мій ріст,
Коли гілки від мене відділились, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'Згребіть на мій злощасний корінь лист!
Я з того міста, де прийшов Хреститель
Замість того войовника, чий хист'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'Невтомно потрясає нам обитель.
Якби побіля Арнського моста ,
Ще не лишався давній покровитель,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 49;

UPDATE terzinas SET text_uk = 'То в місті відбудови висота
Із того, що лишив Аттіла, з праху
Так не звелась би, як тепер зроста.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 50;

UPDATE terzinas SET text_uk = 'Я ж рідний дім обрав собі за плаху».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 51;

UPDATE cantos SET title_uk = 'ПІСНЯ ЧОТИРНАДЦЯТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 14
    AND p.name = 'Inferno';

UPDATE terzinas SET text_uk = 'Любов до рідного звеліла краю
Весь лист обірваний зібрать як слід
І повернуть безсилому з одчаю.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Дійшли до місця ми, де перехід
Був з другої у третю смугу й лютий
Явився праведного суду вид.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Щоб читачу виразніше збагнути,
Скажу, що прибули ми в ті краї,
Де на рівнині й квіту не добути.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Навколо праліс оточив її,
Навкруг же нього йшли рови канальні;
І зупинили кроки ми свої.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Блищали там жаркі піски безжальні,
Такі ж, як і були, у млі століть,
Як вів Катон війська в похід свій дальній.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'О Божа мста, як мусить той тремтіть,
Хто прочитає про твої удари,
Що я на власні очі мав уздріть!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Великі бачив голих душ отари,
Всі плакали за вчиненим в житті,
Своєї кожен зазнававши кари;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Горілиць на піску лежали ті,
А ті навпочіпки ген посідали,
Або тинялись і самі, й в гурті.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Найбільше тих було, що вкруг никали.
А тих найменше, хто в стражданнях ліг,
Але їх зойки голосно лунали.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'А на піски, я скільки бачить міг,
Повільно йшов дощем вогонь лапатий,
Немов без вітру по нагір''ях сніг.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Як Александр, уздрівши, що солдати
В індійській спеці гинуть під вогнем,
Що, впавши з неба, не спішив згасати, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Звелів за кожним стежить пластівцем,
Де б він не ліг, топтать його ногою,
Бо пломінь гасне легше одинцем.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Підпалений небесною золою,
Мов з іскри трут, спалахував пісок,
Подвоюючи муки ще й жарою.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Не спочиваючи, тривав танок
Злощасних рук, які пекучі плями
Скидали із розжарених кісток.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Почав я: «Вчителю, ти перед нами
Все змив, крім тиску демонів, який
Нас допустити не хотів до брами,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Це хто лежить, великий, громіздкий,
Незрушно, блискають лиш очі вперті,
Мов нехтує вогненні язики?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'І той помітив, що слова одверті
Про нього я вождеві говорю,
Й гукнув: «Який в житті, такий я в смерті!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'І хай Юпітер, знову повторю,
Замучить коваля хоч до загину, -
Хай блискавку його востаннє зрю! -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Нехай утомить в праці без упину
Усіх в жерлі у Етни вогнянім
Під гук: «Рятуй, рятуй, Вулкане-сину!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Як у бою під Флегрою труднім;
Хай б''є мене він з усієї сили, -
Та не здола його звитяжний грім!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Тоді вожай мій, повний гніву й сили, -
Цих слів я в нього не передбачав:
«О Капанею, гонор твій немилий'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Не вмер, тож карі тяжчій ти підпав,
Із мук ні одна не переважає
Тієї, що твій сказ тобі послав. -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'І, втишивши обурення безкрає,
До мене: - Він в числі сімох царів
Брав Фіви, зневажав і зневажає'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Він Бога і прощення не просив,
Тримаючи себе весь час свободним;
У грудях в нього лиш пиха і гнів.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Ну що ж, рушаймо знов, один за одним,
Не йди лиш по гарячому піску,
А обминай-но лісом прохолодним».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'На річку мовчки вийшли ми близьку,
Що з лісу винесла червону воду, -
Цю барву досі згадую жаску, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Як Булікаме витікає з броду
Туди, де воду грішниці беруть,
Так на пісок несла ця річка воду,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Собі в камінні прокладавши путь.
І я помислив, а чи не сюдою
Удвох нам треба далі йти, мабуть.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = '«З усього, що ми бачили з тобою
Відколи перейшли той вхід, куди
Усім пройти приречено судьбою,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Такої погляд твій не знав води,
Щоб викликала сильне здивування;
Вона вгашає всі вогню сліди», -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Так вождь свої закінчив міркування,
І я просив, нехай не відмовля
В поживі, раз моє збудив бажання.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = '«У морі спорожніла є земля, -
Почав він, - що спрадавна Крітом звали,
Коли ще світ наш був як немовля.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Там є гора, яку в віках вславляли
Струмки й діброви; їда - назва їй:
Тепер її потроху занедбали.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Там Реї син у схованці своїй
Безпечно спав, і мати його крики
Глушила в галасливості бучній.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'У тій горі стоїть старик великий,
Що від Дам''яти спину відверта,
Як в дзеркалі, у Римі бачить лики.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'А голова вся щирозолота.
І щиросрібні в нього руки й плечі,
А з міді все - до низу живота.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'І дві ноги суціль - залізні речі,
Крім глиняної правої ступні,
Яка важкі трима кістки старечі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Крім золота, на часточки дрібні
Потріскане все тіло, і холоне
Сльоза із щілин на печернім дні'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'І в Ахероні, Стіксі й Флегетоні
Тече цим долом, де мерцям тюрма;
Скидаючи ті струмені червоні'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'В провалля, звідки виходу нема,
Утворюючи став, що звуть Коцітом.
Ти вздриш його, тож мовити дарма».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'І я йому: «У разі нашим світом
Ще протікає цей страшний потік,
Чому лиш тут для ока став одкритим?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'І він: «Ця вирва - наче лійка рік.
Крута, як бачиш, кам''яниста, гола;
Йдучи по ній униз у лівий бік,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Всього іще не обійшли ми кола,
Й яких новин нам не пошле Плутон,
Від здивування ти не зморщуй чола».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'І знов я: «Вчителю, де Флегетон,
Де Лета? Проминаєш це мовчанням,
А той тече, ти кажеш, з слізних лон?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'І він: «Обом я радий запитанням,
Та відповіддю на одне із них
Звучить тут струм червоним клекотанням.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Побачиш Лету, та не в ямах цих,
А там, куди приходять обмиватись,
Коли зника спокутуваний гріх. -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'І ще сказав: - Пора нам відправлятись
Туди, де буде найзручніше нам,
Де ноги в нас не будуть обпікатись,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'Бо гасить пара всякий вогник там».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 48;

UPDATE cantos SET title_uk = 'ПІСНЯ П''ЯТНАДЦЯТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 15
    AND p.name = 'Inferno';

UPDATE terzinas SET text_uk = 'По березі пішли ми кам''яному,
Й туман густий на річку всюди ліг,
І від огню вода ховалась в ньому.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Як межи Бруджею й Гвідзантом ріг
Фламандці обвели високим валом,
Щоб поміж ними й морем став поріг,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'А Падуя від Бренти з її шалом
Люд захища й трудів його плоди,
Як в К''ярентані стане жар чималим, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Так само й тут, хоч камінь і твердий,
Поставив майстер мури неширокі,
Щоб захистити сушу від води.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Від лісу в даль ступали наші кроки,
Що вже крізь випари з усіх калюж
Його не бачили б і гостроокі, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Коли зустрілось нам чимало душ,
І межи них почулись різні толки,
І стали всі вони у нас чимдуж'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Вдивлятись, мов у кам''яні осколки
На стежці в промені молодика,
Мов дід-кравець шукає вушко в голки, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Так оглядала нас юрма бридка;
Аж раптом хтось мене смикнув за полу
І вигукнув: «О, дивина яка!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Коли торкнувся він мого подолу,
До нього враз я голову нагнув
І, розглядаючи фігуру кволу,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Не так пізнав, а серцем я збагнув
Лице, скоричнявіле від скорботи,
Й «Чи ви не сер Брунетто?» - я гукнув.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'І він: «О сину мій, чи ти не проти,
Щоб міг Брунетто сер Латіні з мить
Пройти з тобою рухові навпроти?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'І я відмовив: «Це й мені кортить.
А хочете, тохядемо із вами
На хвильку, як супутник мій звелить».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = '«О сину, - він сказав, - з цієї ями
На мить хто стане, стане той навік,
Щоб вік пектись безжальними вогнями.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Отож ідіть вперед, піду я вбік.
А радісні хвилини як пролинуть,
До тих вернусь, хто йти в огні привик».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Я не наважувався берег кинуть,
Але чолом схилявся до плеча,
Мов той, хто має гостя в шані стрінуть.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'І він почав: «Чи доля, чи случай
Веде сюди тебе, іще живого?
І хто це путь для тебе визнача?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = '«Там, нагорі, в цвіту життя ясного, -
Я мовив, - я в долині заблукав,
Як ще не вийшов строк життя мойого,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'А вчора вранці з неї відступав,
І цей вернув мене й повів стезею,
Яку він добре, як я бачу, знав».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'І він: «За провідною йди зорею,
Й дороги в гавань слави приведуть,
Як стежив я за долею твоєю,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Якби не мав так рано я заснуть,
То, бачачи небес таке сприяння,
Я прагнув би тобі полегшить путь.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Але народ, відомий з хизування,
Що з Ф''єзоле зійшов колись, малий,
І грубих звичаїв зберіг владання,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Тобі він за добро помститься, злий, -
І вірно це: на дикій горобині
Іще ніколи смокви не росли.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Сліпим у світі дражнять ще донині
Цей люд пихатий, заздрісний, скупий;
Самий зв''язок з ним чинить зло людині.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Прославить доля так твої стопи,
Що кожна з партій вишкерить голодну
Пащеку, щоб на них ти жав снопи.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Тварюки ф''єзольські хай одна одну
Жеруть, а вирослу на їх гною
Хай не чіпають квітку благородну,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'В якій воскресло у чергу свою
Святе насіння древніх римлян саду,
Що звиродніло нині від огню».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = '«Якби небесного хазяїн граду
Мене почув, - сказав я, - то весь час
Очолювали б ви людську громаду.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Та й досі в думці ще печалить нас
Ваш гарний образ, добрий, без огуди,
Коли ще за життя ви раз у раз'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Навчали, як увічнюються люди,
І поки житиму, до вас моя
Подяка у піснях бриніти буде.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Слова, що чув од вас про майбуття,
В душі я запишу, щоб проясніли
У Знаючої з уст, як стрінусь я.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'А зараз хочу я, щоб зрозуміли,
Що совісті моєї чистий дух
Скорився фатуму, хай він немилий,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Не вперше ніжить це мій грубий слух,
Хай колесо Фортуна обертає,
Як селянин сапу, легку як пух».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Знов серце вчитель тут явив безкрає.
Й сказав, підвівши зір очей ясних:
«Найкраще чує той, хто пам''ятає».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Ми далі йшли у бесідах значних
І я, йдучи, Брунетто став питати,
Чи є ще хто з осіб тут видатних.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'І він: «Та варто б декого згадати,
А всіх - ми тільки зіб''ємось в числі,
Та і часу на це в нас малувато.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Тож знай: тонзурники всі немалі,
Вони й письменні вельми, й вельми славні
Були в гріхах тих самих на землі'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'І Прісціап в юрбі цій непоправній,
Й Франческо, син Аккосо, в ряд ступив;
Увагу й гиді приділив би давній,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Отій, яку смиренний раб рабів
З-над Арно вигнав геть на Баккільйоне,
А Бог там з нею швидко покінчив.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Ще б називав їх, полум''я ж червоне
Строк покладає і путі й розмов,
І свіжий вихор на піску холоне.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Я тіням цим назустріч би не йшов.
Прошу, щоб ти про «Скарб» поклопотався,
Бо в нім моє життя й моя любов».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Він повернув назад і так помчався, -
Як той в Вероні, що на бій стає,
Щоб плащ зелений взяти, і здавався'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Тим, хто домчить, - не тим, хто відстає.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 42;

UPDATE cantos SET title_uk = 'ПІСНЯ ШІСТНАДЦЯТА Коло сьоме. - Третій пояс (продовження)'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 16
    AND p.name = 'Inferno';

UPDATE terzinas SET text_uk = 'Як вийшли ми із вожаєм над доли,
Долинув раптом водоспаду гук,
Немов над квітами дзижчали бджоли.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Коли три тіні вибігли з-над лук
Від хмари тіней, що їх дощ огнисто
Зливав потоком ненастанних мук,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'І на бігу волали голосисто:
«Спинися, бо твій одяг видає,
Що наше ти лишив порочне місто!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'О, скільки опіків в думках встає,
Що кожному ятрили свіжу рану!
Від згадки й досі боляче стає.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Учений мій послухав річ неждану
І враз до мене: «Трохи підождім, -
Сказав, - як хочеш їм віддати шану.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Були б не під вогнем ми дощовім,
У цих місцевостях звичайнім завше
Спішити б личило тобі, не їм».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Ми зупинилися, і, нас догнавши,
Ізнову тіні затягли свій спів,
Навколо нас всі троє закружлявши.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Як той борець, що тіло умастив,
І, для удару час обравши вдалий,
Вивча суперника з усіх боків, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Так у кружінні душі обертали
До мене лиця, так що ноги їх
Із головами різний напрям мали.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'І «Якщо бідність цих ґрунтів сипких
Примусить гордувати прохачами, -
Почав хтось, - як і вигляд лиць смутних,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Та все ж спинись, розкрийся перед нами,
Скажи відверто, хто ти і чому
По Пеклу в нас живими йдеш ногами?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Той, хто бреде попереду крізь тьму
Без одягу й не дасть він струпам ради, -
Значніший був, ніж бачиш по ньому.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Онук він чеснотливої Гвальдради,
Ім''я мав Гвідо Гверра, - і щокрок
Мечем і розумом всім ніс відради.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'А той, що ледь ступає на пісок, -
Тегг''яйо Альдобранді, уславляти
Повинен світ це ймення до зірок,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'І я, що з ними на хресті розп''ятий,
Був Рустікуччі Якопо; в гріхах
Найбільше винен шлюб мій тричі клятий».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Якби не риск згоріти в пломінцях,
Обняв би тіні я, - мій друг учений
Зрадів би, мабуть, - взяв же гору жах'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Над наміром зійти в пісок палений
Із нашого твердого укриття
Під огневій клекочучий, скажений.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'І я почав: «Не гордість - співчуття
До вас у цій вогненній хуртовині
Та ще скорботу міг почути я,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Коли мій пан, уздрівши вас в пустині,
Сказав слова, з яких я осягнув,
Що юрми йдуть таких, які ви нині.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Я з вашої землі; іще малим я був,
А поважані ймення ваші в душу
З пошаною й любов''ю я замкнув.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Лишу я тут пекельну жовч і рушу
По яблуко солодке, молоде
Од вожая: у глиб зійти ще мушу».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = '«Хай тіло довго ще твоє веде
Душа, - відмовив опіками вкритий, -
Хай світла слава перед тебе йде!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Але, скажи, чи дозволенно жити
Ще в нашім місті лицарства взірцям.
Чи мусять, вигнані, комусь служити?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Гульєльм Борсьєре, що ступає там,
Повідав дещо, бо звідтіль недавно,
Й не раді ми були земним вістям».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = '«Нові людці, збагачені безславно,
В пиху та розкіш у тобі вдались,
Флоренціє, й скорбиш ти безугавно!» -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Так я гукнув, чоло піднявши ввись,
І три душі перезирнулись пильно,
Мов ті, які на істині зійшлись.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = '«Коли ти можеш легко так і сильно, -
Відмовили вони, - розповідать,
Щасливий ти, що промовляєш вільно.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Як з місць жаху, де нам віки страждать,
Піднімешся на зоряні дороги
І зможеш «Я там був» усім сказать,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Скажи, щоб знали нас хати й чертоги».
Вони побігли втрьох, за тінню тінь,
І крилами здались мені їх ноги.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Скоріш, ніж вимовляється «амінь»,
Ті душі щезли в огнянім покрові.
Мій вчитель рушив знов у далечінь.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Я йшов за ним, коли почув раптові
Десь близько клекотання й шум струмин,
Що Перешкодою були розмові.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Мов річка та, що має шлях один
Від Монте-Везо в напрямі до сходу
По лівому нагір''ю Апеннін'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = '(Звуть Аквакета ту в верхів''ях воду),
А далі по хребту між скелі мчить,
Втрача в Форлі ім''я, та не природу,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Й під мурами монастиря шумить
В Сан-Бенедетто, спуск там до долини,
Де тисяча б могла принаймні жить.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Так вийшли ми з вождем до верховини,
Де грім такий над вирами гримить,
Що ледь я не оглух від громовини.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Вірьовкою свій стан я встиг обвить
Від леопарда, хитрого звірюки,
Мав боронитись і його скрутить.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Вірьовку з себе зняв я без принуки,
Коли вожай зробити це звелів,
її змотавши, дав йому у руки.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Він взяв її, на правий бік ступив
Й один кінець в провалля кинув темне
Якмога далі від його країв.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = '«А що, як звідти раптом щось таємне, -
Сказав я нишком, - може стрибонуть?
Не певний вчитель, мабуть, недаремне».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Яким обачним слід при тому буть,
Чий зір не з вчинків лиш покров зриває,
Але й з думок, які до них ведуть!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Сказав мені він: «Те вже випливає,
Чого я жду й про що думки твої
І що твій погляд в пітьмі розрізняє».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'На істину, подібну до брехні,
З зав''язаними дивляться ротами,
Звичайно, щоб не бути у вині,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'А я мовчать не в силі, і рядками
Комедії цієї під кінець
Я, читачі, клянуся перед вами,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Що бачив сам, як з пітьми, мов плавець,
Щось підіймалось нелюдського штибу,
Страшне й для найхоробріших сердець,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Мов той вертав, хто, розігнавши рибу.
Й до каменистого дістався дна,
Звільнивши якір із морського глибу,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Працюючи ногами, вирина.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 46;

UPDATE cantos SET title_uk = 'ПІСНЯ СІМНАДЦЯТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 17
    AND p.name = 'Inferno';

UPDATE terzinas SET text_uk = '«Цей гострохвостий звір, що з нами поряд,
Руйнує мур в фортеці кам''яній,
По цілім світі йде від нього сморід!» -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Таке промовив вождь учений мій
І знак подав, що ждать потвору буде
На стежці забрукованій твердій.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'І це гидотне втілення облуди
Лице наблизило кінець кінцем,
Не витягши хвоста, сховавши груди.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Було його лице людським лицем:
М''який блаженний усміх, щоки чисті, -
А тулуб вився, як в змії, кільцем,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Дві лапи волохаті й пазуристі;
Обидва ж боки, спина з животом
Від смужок та кружечків - геть плямисті,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Куди там туркові з шовків жмутком,
Не витчуть килимів таких татари,
Арахна знов програла б з полотном.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Як пристають до берега байдари -
Півсудна у воді, пів - на землі,
Як там, де у неситих німців свари,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Бобер, присівши, ладить пастки злі, -
Так лютий звір з іменням Геріона
З''явився враз на кам''яному тлі,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'А хвіст був - мов розчахнута колона,
Й стояли сторч отруйні два кінці,
Неначебто жало у скорпіона.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Сказав вожай мій: «Маєм, як ловці,
Від нашої дороги відхилитись
До чудиська, що сіло на луці».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Поквапились праворуч ми спуститись
І кроків з десять стежкою пройшли,
Стараючись піском не обпалитись.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Коли до звіра близько вже були,
Побачив тіні я, що в спогляданні
Сиділи коло прірви серед мли.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Тоді учитель: «Кладучи в вивчанні
Край дослідам» ти подолай свій страх, -
Сказав, - і розберись у їх стражданні.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Веди розмову там в скупих словах,
А я домовлюсь, як би над цим долом
Нас переніс він на своїх плечах».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Так вирушив палючим сьомим колом
Я сам-один, без друга, боязкий,
Поміж народом, мученим і голим.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'У них в очах світився біль різкий,
Чи тут, чи там, віддавшись небезпеці,
То пломінь відсували, то піски.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Так само роблять пси в нестерпній спеці
Ротами й лапами, коли кусать
Почнуть їх блохи, мухи а чи ґедзі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Я в лиця намірявся заглядать,
Та лютий пломінь падав без упину,
І я не міг нікого упізнать.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'І кожен з них на шиї мав торбину
На колір певну й певний знак на ній,
Які були за втіху всім єдину.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'І в одного на довгім гамані
Я вздрів лазур небесного ефіру,
Що лева мала обриси ясні.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'А інший, що являв покуту щиру,
На капшуку, червоному, як кров,
Мав гусака, білішого від сиру.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'І той, якому вишив білий шов
Знак на калитці з синьою свинею,
Спитав мене: «А ти чого прийшов?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Живий, то б і живою йшов землею,
Тут сяде Вітальяно, мій сусід,
Персоною гріховною своєю.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Це - флорентійці, з Падуї ж мій рід.
Мені рвуть вуха, а собі утроби,
Волаючи: «Сюди б вельможу слід,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Що на торбині змалював три дзьоби!»
Скривив тут рота й висунув язик,
Неначе бик, не тямлячись від злоби.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'І я, щоб не розгнівавсь провідник,
Мій рятувальник серед звірів хижих,
Від тих мордованих скоріше зник.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Знайшов я вожая уже на крижах
Тварюки, що смирила дику лють.
І він мені: «Сил наберися свіжих,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Бо тут по сходах тільки так ідуть.
Сідай ти спереду, а я позаду,
Щоб гострий хвіст не міг тебе торкнуть».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Мов той, що над собою тратить владу
В припадку лихоманки при грозі,
У всякім затінку вбачає ваду, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Таким я став од слів цих, та в сльозі
Дав страм мені позбутися відчаю,
Як добрий пан несмілому слузі,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Я виліз звірю на плече по краю
Й хотів сказать, та вимовить не зміг,
Лише два слова: «Обійми, благаю!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'А той, хто вмів у злигоднях доріг
Мене втішать, як я лиш сів, негайно
Мене вхопивши, вдержатись поміг,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'І мовив: «Геріоне, вирушай-но,
Але обачно й повагом лети,
Нова-бо ноша важить незвичайно».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Мов човен, що готується пливти,
Назад-назад він подавався звідти,
Коли ж відчув, що вільно можна йти,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Відразу повернув свій хвіст розвитий
І, випроставши, мов вугор, кістяк,
Став, лапами махаючи, летіти.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Ніколи в світі не лякались так
Ні Фаетон, що віжки Божі кинув,
Лишивши в небі полум''яний знак,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Ані Ікар злощасний, що загинув,
Наважившись добратися до зір,
Хоч батько і гукав: «Куди полинув?!» -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Як я, коли побачив скрізь мій зір
Лиш порожнечу і помітив з лиха,
Що обмежовує її лиш звір.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'А він спускався вниз так стиха-стиха,
І рух, і напрям зміг я зрозуміть,
Бо чув, як сильно вітер знизу диха.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Тепер дізнавсь, що справа гримотить
Ген водоспад і сіє водним пилом;
Не встиг я трохи голову схилить,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Як, переляканий новим страшилом,
Побачив попереду блиск огнів.
І, тремтячи, зіщулився всім тілом.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'І вздрів я те, чого раніш не зрів:
Як ми кружляєм крізь великі болі,
Що насувалися з усіх боків.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Мов сокіл, що летить уже поволі,
Утомлений, не бачачи пташок,
Під зойк сокільника: «Немає долі!» -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Із піднебесних поверта стежок,
Де він даремно сто разів крутився,
Й сіда, від всіх подалі, на лужок, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Так Геріон до прірви дна спустився,
Під самий-самий бескид сторчовий,
І, ледь від наших він осіб звільнився,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Зник, як стріла зникає з тятиви.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 46;

UPDATE cantos SET title_uk = 'ПІСНЯ ВІСІМНАДЦЯТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 18
    AND p.name = 'Inferno';

UPDATE terzinas SET text_uk = 'Є в Пеклі місце, зване Лихосхови,
Залізних тонів муром кам''яним
Оточене; таке ж воно й з основи.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'А посередині, у долі тім,
Глибока та широка є криниця, -
Про неї я пізніше розповім.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'У тому поясі, який тісниться
Поміж криницею й підніжжям скель,
Аж десять більших виїмів гніздиться.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Як силами навколишніх земель
Круг міста риють більші й більші ями
На оборону мурів та осель, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Вид у ровів і тут такий же самий,
Як і по наших замках та містах:
Висять мости для ходу над ровами.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Так і по схилах тут, і по ровах
Із гострих скель проходи утворились,
Що до криниці свій проклали шлях.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Ми й стали тут, як скинуті лишились
Зі спини Геріона, і пішов
Поет наліво звідти, де спинились.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Йдучи, я вправо зрів новий захов,
Нових мучителів, нові страждання,
Які наповнювали перший схов.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Там чулось голих грішників ридання;
Багато з них назустріч нам ішло,
А інші - швидше нашого ступання.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Так римляни роздвоїли жерло
Моста на час святого ювілею,
Щоб тісняви між піших не було,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Й прочани струминою однією
До замку й до Петра туди текли
І другою вертали течією.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'І тут, і там - я з хмурої скали
Спостерігав, як не один рогатий
Шмагав нещадно ззаду тих, що йшли.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Ах, перший же удар мастив так п''яти
Нещасним, що не важились вони
Ні другого, ні третього чекати.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Із тіней хтось наблизивсь до стіни,
І тут же я почав у думці ритись:
«Чи не здибавсь мені вже цей сумний».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Я зупинивсь, щоб краще роздивитись,
І мій вожай ласкавий дуже був,
Мені дозволив трохи відступитись,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Батожений цей голову нагнув,
Ховаючись, та прогадав, похмурий,
Бо я сказав: «І що ти цим здобув?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Ні, не змінив своєї ти натури,
Венедіко Каччанеміко; гріх
Який привів тебе на ці тортури?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'І тінь мені: «У підземеллях цих
Ти нагадав мені старі оселі
Й людей, моєму серцю дорогих.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Я той, хто раду дав Гізолабеллі
Повірить в те, що обіцяв маркіз.
То все брехня про зганьблені постелі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'З болонців не один я впав униз, -
Тут стільки наших загнано в закути,
Що чуєм ми силенну силу слів,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Які й од Савенни до Рено чути.
Якби цьому взнать докази схотів,
То скупість серця прагни не забути».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'І чорт його тут батогом огрів,
Гукнувши: «Годі, бандуре огидний,
Вперед! На продаж тут немає дів!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Я озирнувсь, де був учитель гідний,
І ми невдовзі з ним дійшли туди,
Де висувавсь уступ гребеневидний.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Ми легко піднялися до гряди
І рушили по ній у праву руку,
Лишаючи цю яму назавжди.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Коли звелись на мостову ми злуку,
Над шляхом, що був страдникам сумним,
Вожай сказав: «Постій і глянь на муку,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Яка тяжить над грішним людом цим,
Ти ще не бачив, що це тут за люди,
Бо йшов із ними в напрямі однім».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Під арку глянувши між скельні груди,
Відразу я помітив одного,
Що наче зневажав тягар осуди.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'І вождь сказав без розпиту мого:
«Іде великий приклад страстотерпцям:
Ані сльози в очах сухих його.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Мов рицар виступає перед герцем!
Це той Ясон, що золоте руно
Узяв у колхів розумом і серцем.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Він перш до Лемносу привів судно -
А там порізали всі гнівноокі
Жінки чоловіків не так давно.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Пустивши в хід дари й слова високі,
Він звів там Ізіфілу чарівну,
Якою сестри зведені жорстокі,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Й лишив її вагітну й самітну.
Тож мука ця за гріх той знаменитий,
Ще й помста за Медею навісну.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Із ним ідуть всі інші дурисвіти.
Та досить роздивлятись перший діл
І тих, кого припало тут зустріти».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Туди ми вийшли вже, де другий схил
Перетинався стежкою вузькою,
Де на мосту лежав прадавній пил.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Тут чулись дужі пирхи над юрбою,
Що повнила собою другий рів
Й себе вдаряла власною рукою.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'На вінцях же смердючий глей осів
Од випарів, що знизу йшли, зісподу,
І для очей нестерпні, й для носів!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Тут дно було тьмянисте, як в негоду,
Й, щоб яму всю належно озирнуть,
Мостом зійти ми мали по проходу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Тих місць ми досягли, куди, мабуть,
Гній звезенб з усіх відхідків світу,
І грішники в тім смороді гниють.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'І тінь побачив я суціль облиту,
Немов хто гряззю голову обдав,
Й не знать, чи має маківку він бриту.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Гукнув мені він: «Може, ти гадав
Побачити в мені найбільш брудного?»
І я йому: «Як вірно я вгадав,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Тебе колись я бачив, та сухого
Алесьйо ж бо Інтермінеллі ти,
Тож і дивлюсь: караєшся ти строго».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Й себе він по макітрі ну товкти:
«В усьому винні ті слова лестиві,
Що мій язик не втомлювавсь плести».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Сказав вожай мій: «Очі неслізливі
Вниз опусти й знайди в юрмі тісній,
Яка так терпить кари справедливі,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Бридку задрипу в сморіднім багні,
Що дряпає собі лице руками
І то підскоче, то впаде у гній.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Таїс-блудниця то з її речами.
Як мовив гість: «Чи я годжусь тобі?»
Вона: «Ти чудо між чоловіками!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Та досить бачили ми в цій юрбі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 46;

UPDATE cantos SET title_uk = 'ПІСНЯ ДЕВ''ЯТНАДЦЯТА Коло восьме. - Третій схов. - Святокупці'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 19
    AND p.name = 'Inferno';

UPDATE terzinas SET text_uk = 'О волхве Сімоне, о жадні учні,
Господнє сотворіння пресвяте,
З добром заручене, ви, зла підручні.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'За злото й срібло всім продаєте.
Вже треба, щоб про вас сурма дзвеніла,
Ви ж в третім схові кару несете.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Під нами далі вже була могила,
Коли ми вийшли на крутий місток,
І яма нам своє нутро явила.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'О вишня мудросте, значний твій крок
У небі, на землі, у Пеклі злому!
В твоїм-бо правосудді всім урок!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'На стінах бачив я й на дні вузькому
Багровий камінь, круглий, весь в дірках,
Які були однакові в усьому.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Не ширшими здались в моїх очах
За ті хрестильні в любім Сан-Джованні,
Де кум держить малятко на руках.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Колись таку плиту при рятуванні
Втопаючого я розбив одну,
І ось - печатка на моїм зізнанні.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'У вусті ходу в товщу кам''яну
У кожнім ноги грішника стриміли,
А тіло все суціль зайшло в стіну.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'І кісточки яскраво пломеніли.
Так сильно корчилися пари ніг,
Що й вірьовки втримать не мали б сили.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Як не спалахує все жирне вмиг,
А полум''я лиш на поверхні дише,
Так тут вогонь од п''яток далі біг.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = '«Скажи, учителю, хто це сильніше
За інших корчиться від лютих мук, -
Спитав я, - й полум''я там червоніше?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'І він: «Як хочеш, не спускавши з рук,
Я пронесу тебе крутим цим схилом,
І сам почуєш його мови звук».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'І я: «Тобі благе й мені є милим.
Ти знаєш те, що хочу я сказать.
Ти пан, і я твоїм корюся силам».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Тоді ми вийшли на четверту гать
І повернули вліво, вниз до ями,
Де зяють діри й полум''ям горять.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'І добрий вчитель стис мене руками
І відпустив, як стали - не раніш -
Ми там, де грішник той сукав ногами.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = '«Хто б ти не був, що вниз чолом стирчиш, -
Почав я, - наче кіл, що хтось вбиває,
Печальний душе, скорб свою утіш».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Схиливсь я, мов чернець, що сповідає
Убивцю, той же, вчувши смерті гніт,
її за всяку ціну віддаляє.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'А він гукнув: «Невже покинув світ,
Невже покинув світ той Боніфацій?
Чи список наш збрехав на кілька літ?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Ти, може, утомився від труднацій
З багатствами, що викрав ради них
Красуню й нею торг ведеш в палаці?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Я наче той був, чий язик затих,
До нього бо звернулись незвичайно,
Він розгубився й був ні в сих ні в тих.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Віргілій мовив: «Ти відповідай-но:
Та я не той, не той, кого ти ждав!»
І раду цю я виконав негайно.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Тоді цей дух ногами замахав,
А там почав так жалісно зітхати
Й казать: «Навіщо ж ти мене чіпав?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Коли ти так хотів про мене взнати,
Що не злякали прірви кам''яні,
То знай, що я вдягав розкішні шати,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Що ведмедиха - мати є мені,
Що сам я піклувавсь про ведмежаток,
Копив добро - тепер я в гамані.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Під головою в мене тут - з десяток
Таких, хто симонією грішив,
Кому каміння не пече вже п''яток.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Давно б поверхню цю я залишив,
Коли б з''явився той, кого з тобою
Я сплутав, як уперш заговорив.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Та довше я стою сторч головою,
Пожежу чуючи в ногах лиху,
Аніж йому призначено судьбою.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Бо після нього весь в гидкім гріху
Від заходу йде пастир без закону, -
Той всіх обгонить на своїм шляху.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Новітньому подібний Іасону,
Описаному в Маккавеїв, він
Французького підтримку знайде трону».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Не знаю, може, злий був мій учин,
Слова ж на відповідь були готові:
«Якого скарбу ждав, скажи, взамін'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Господь наш, як святому дав Петрові
Свої ключі? Наказ він мовив свій:
«Іди за мною!» - та й по цьому слові.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Петру та іншим не платив Матвій
Ні злотом, ні сріблом, як обережно
Посів він місце по душі кривій.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Тож стій отут, бо скараний належно
З чужим добром грабованим стирчи,
Як з ним на Карла бадьоривсь безмежно.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Якби не так я шанував ключі,
Поважані для всіх людей путящих,
Гаптовані у тебе на парчі,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'То я б удавсь до виразів ще тяжчих,
Бо кривдить землю всю ваш хижий хист,
Підносить гірших, в грязь ввергає кращих.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Вас, пастирі, вже знав євангеліст
В тій, що на водах возсіда, байдужа,
Лиш блудствує з царями з різних міст.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'А в ній, семиголовій, сила дужа
На десять рогів сяяла свята
Аж поки шлюбного любила мужа.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Тепер в вас віра срібна й золота;
Відміна та в вас од ідоловіра,
Що в нього Бог один, а в вас - до ста...'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'О Константине, тож не купіль щира,
А дар твій папі зло вчинив тяжке,
Що до багатства в них пропала міра».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'І поки я співав йому таке,
Від сорому чи люті в хриплім реві,
Ногами виробляв він щось бридке.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Гадаю, що сподобавсь вожаєві,
Бо слухав він моїх уважно слів:
Були вони правдиві і життєві.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'І тут руками він мене обвив,
До серця пригорнув, поніс угору
По тій дорозі, що й сюди привів.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Проніс мене крізь путь круту, сувору
Аж на високий арковий карниз,
Де вид у п''ятий схов одкрився зору.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'І там мене, де спуск ішов униз,
Він бережно поставив на скелину,
Що неприступною була й для кіз,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Звідкіль побачив я нову долину.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 45;

UPDATE cantos SET title_uk = 'ПІСНЯ ДВАДЦЯТА Коло восьме. - Четвертий схов. - Віщуни'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 20
    AND p.name = 'Inferno';

UPDATE terzinas SET text_uk = 'Нові покари я в тім самім ритмі
Оспівую в двадцятій пісні цій
Канцони першої - про втоплих в пітьмі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Вже на круті схиливсь я камінці,
Щоб роздивитись дно глибоке долу,
Зволожене у слізнім озерці.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Й багато душ побачив, що по колу
Ходили, сльози мовчазні ллючи;
Так ходять в нас в процесіях спрокволу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Я ще одне помітив, що, йдучи,
Вони тримають дивно підборіддя;
В них не на місці й шия на плечі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Це з скрученими лицями поріддя
Лише назад примушене ходить,
Незмильне втративши очей повіддя.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Параліч може хворому скрутить
Потворно так на шиї м''язи й жили,
Що я не міг такого й уявить.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Хай Бог дає тобі, читачу, сили
Ума в цім місці зосередить міць.
А я не міг, щоб очі не сльозили,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Як вздрів спотворених тьму-тьмущу лиць.
Та й їхніх сліз потік неутолимий
В них не по грудях біг, а між сідниць.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Притьма залився я й собі рясними,
На камінь спершись, і такі слова
Сказав вожай: «Невже ти теж із ними?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Бо жаль до винних губить тут права:
Хто може буть злочинніший за того,
Хто винним перед Богом співчува?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Зведи чоло і очі на отого,
Під ким розсілась на очах фівян
Земля на крик: «Куди ти мчиш, для чого,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Амфіараю? Чом покинув стан?»
Та колісницю гнав він без упину,
Поки Мінос не взяв його у бран.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Дивись, він груди обернув на спину
За дерзкість, що хотів вперед все знать.
Тепер назад він знає путь єдину.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Ще зриш Тіресія, - він зрадив стать.
Із чоловіка жінкою зробився
І всю істоту мусив був мінять,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Аж поки знов з гадючим шлюбом стрівся,
Києм приборкав в гадах крові бунт
І в чоловіче пір''я знов одівся.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'За черевом його іде Арунт,
Що в горах Луні, де на дні кар''єру
Каррарець вбогий обробляє ґрунт,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Житлом обрав із мармуру печеру,
Де міг побачить небо у зірках
І в далині морській струнку галеру.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'А ця, в якої голова в кісках,
Хова від тебе невидимі груди,
А тіло все в шерстистих волосках, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Ця звалась Манто, що блукала всюди
Й моя сподобалась їй сторона.
Отож про неї й повість в мене буде.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Побачивши, що зовсім самітна,
Вітчизну ж Вакха рабство осідає,
Світ за очі пішла собі вона.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'В Італії прекрасній, в Альпах сяє
Те озеро, де йде до Маньї путь.
Це озеро ім''я Бенако має.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Джерела, що їх з тисячу, мабуть,
Від Валькамоніки до Гарди, гони
Пеннінські вмивши, в озеро течуть.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Всередині, де сходяться кордони,
Благословляти пастирі б могли
Народ із Трента, Брешії й Верони.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Де береги у низині лягли,
Бергамці не зруйнують чи брешійці
Пескьєри гарні та міцні вали.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'А надмір рідини, якого в шийці
Не вміщує Бенако, випада
І витіка, мов через вінця в лійці.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Текти почавши з озера, вода
Більш не Бенако, а вже Мінчо зветься
Аж до Говерно, де у По впада.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Одразу ж річка до рівнини ллється,
Там ширшає/стає на взір ставка,
А влітку сохне й смородом береться.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Сюди ішовши, дівчина жорстка
Серед боліт вподобала місцину,
Хоча рослинність там була й рідка.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Звела вона тут з слугами хатину
І віддалась чаклунству й ворожбі,
Аж поки не поклали в домовину.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Сусідні люди збилися й собі
На тому, що його, немов намисто,
Твань оточила, дикому горбі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Щоб згадувану в бесідах врочисто
Засновницю ніхто з них не забув,
Нове назвали Мантуєю місто.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Притулок мій залюднений вже був,
Аж поки легковірність Касалоді
Безчесний Пінамонте обманув.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Кажу на те, щоб, чуючи в народі
Щось інше про походження землі
Моєї, знав ти - це брехня, та й годі».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'І я: «Ти, вчителю, слова незлі
Промовив щиро на мою повагу,
Що іншу річ вподібню я золі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Але скажи: на всю оцю ватагу
Чи не уздриш хоч одного, який
Мою до себе привернув увагу?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Тоді мені він мовив: «Той, з щоки
Якого борода по темній спині
Спадає, в дні, як в Греції-таки'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'В колисці місце лиш було хлопчині,
Авгуром був, з Калхантом кораблі
Послав з Авліди по морській пучині.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Це Евріпіл, діла його незлі
Співа моя трагедія висока, -
її ж уривки знаєш чималі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'А ця от далі тінь кощавобока -
То Мікаеле Скотто; він митцем
Був у магічному дурінні ока.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Он Гвідо там з Азденте, з тим шевцем,
Який за дратвою, за копилами
Заходиться запізненим плачем.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Зриш грішниць, що, простившися з голками,
До чарів узялись через каприз,
Щоб чаклувать над зіллям та ляльками.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Але ходімо, бо сяйнув униз
Й, межі обох півкуль торкнувши зовні,
Склав Каїн за Севільєю свій хмиз.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Тієї ночі місяць був у повні.
Згадай лишень, що промені ясні
Вели тебе крізь чагарі безмовні».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Так, ідучи, він говорив мені.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 44;

UPDATE cantos SET title_uk = 'ПІСНЯ ДВАДЦЯТЬ ПЕРША'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 21
    AND p.name = 'Inferno';

UPDATE terzinas SET text_uk = 'Так ми з моста на міст, багато вівши
Чужих моїй Комедії розмов,
Пройшли, щоб, зором глибочінь розкривши,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Ще на один поглянуть Лихосхов
В нових покарах і новій печалі;
Занадто чорним я його знайшов.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Як у Венеції, де в арсеналі
Взимі в''язка смола кипить, буя,
Щоб засмолити судна на причалі,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Що там стоять; і дехто обробля
Готове вже судно, а дехто маже
Борти мандрованого корабля,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Хто робить весла, хто канати в''яже,
Той ремонтує ніс, а той корму,
Хто ж на бізань, фок-мачту ладить тяжі, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Тут не вогню, а вишньому уму
Завдячувала рідина кипінням,
Сочившись звідусіль у чорну тьму.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Смолу я бачив з булькотанням пінним,
І верх її шумливий то здіймавсь,
То опадав з бурхливим клекотінням.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Розглянуть я все пильно силкувавсь,
Та вождь, говорячи: «Дивись, дивись-но!», -
Відтяг мене відтіль, де я лишавсь.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Оглянувсь я, мов той, хто ненавмисно
Тікаючи від ворога учвал,
Все озирається зі страхом, звісно,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Оглянувся на шум страшних навал, -
І враз побачив - мчав на нас огидний
Диявол чорний по бескеттях скал.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Ах, та який же був він страховидний!
Невже такі бридкі всі хвостачі,
Як він, ширококрилий, прудкохідний!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'На гострому високому плечі
Бридкого грішника держав і дряпав
На п''ятці шкуру в нього, несучи.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Гукнув з моста: «Гей, хто там з Лихолапів!
От старшина святої Зіти вам, -
Топіть його, а я назад почапав'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'У землю, де лише Бонтуро сам
Хабарничать нізащо не візьметься,
І з «ні» вам «так» за гроші зроблять там».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Жбурнув його, як завжди тут ведеться,
Й погнав назад; пес, пущений з ланця,
За злодієм так швидко не женеться.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'А той пірнув і вирнув, та плавця
Чорти настигли, й кожен дав по тичці,
Із криком: «Ні Святого в вас Лиця,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Ані купань нема, як в Серкйо-річці!
Щоб не зазнав ти наших пазурів,
Сиди собі в смолі, як фрукт на дичці!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Та й підчепили сотнею гаків,
Приказуючи: «Ти не будь докучним,
Чи стань одним з таємних шахраїв».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Так кухарі велять своїм підручним
Втопляти м''ясо гаком в казані,
Щоб не спливало й залишалось тучним.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'І добрий вчитель мій сказав мені:
«Щоб не побачив хтось тебе одразу,
Сховайся за уступи кам''яні'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Й не бійся, чуючи мені образу,
Бо від цієї чортівні я діл
Таких наслухався того ще разу».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'А далі перейшов він мосту схил
І, шостого уздрівши схову ложе,
Нових набратись мусив мужніх сил.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'З такою лютістю і так вороже
Не нападають пси на жебрака,
Що всюди жебрає, де тільки може,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Як біси вистрибнули з-під містка
Та й кинулись на нього із гаками,
Але він гримнув: «Геть, юрмо дерзка!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Хай вислухає той мене між вами,
Кому ясний моєї мови зміст,
А там, як зможете, тягніть до ями!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Гукнули всі: «Хай вийде Лихохвіст!»
І вийшов він, лишивши решту-ззаду,
Й спитав: «Який тебе періщить хлист?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = '«Чи, Лихохвосте, здумав ти до ладу,
Невже б то зваживсь, - вчитель мій сказав, -
Сюди прийти я, знавши вашу зваду?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Я з волі Божої сюди попав.
Отож не заважай, бо небо хоче,
Щоб іншому я шлях цей показав».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Пиха чортяча зникла неохоче.
Він розгубився, упустив свій гак
І мовив іншим: «Шкода, він проскоче».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Тут вождь мені: «О ти, що певно так
Сховався за уступ, з кутка зручного
Виходь, і хай тебе покине ляк».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'І я підвівся і підбіг до нього,
Й чорти мене обстали у злобі,
І я боявсь їх зрадництва лихого.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Так, бачив я, тремтіли у журбі
Подолані, виходячи з Капрони,
В ворожій бачачи себе юрбі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Припав я до вождя для оборони
Й в мерзотні пики утопив свій зір:
Добра не обіцяв їх зір червоний.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Гаки спустили й: «От завив би звір, -
Між себе мовили, - гучноголосо!»
Й відповідали: «То й гати до дір!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Але на них поглянув гнівно й косо
Той чорт, що говорив з вождем моїм,
І вигукнув: «Облиш, облиш, Нечосо!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'А там сказав до нас: «Невільно цим
Уступом вам іти, бо арку шосту
Зруйновано не знати як і ким.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Щоб іншу путь вам відшукати просту,
Зайдіть в печери ближчої жерло,
Там вихід є ще до одного мосту.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Учора без п''яти годин було
Дванадцять сотень шістдесят шість років,
Як землетрусом міст той геть знесло.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Я шлю моїх оглянуть з усіх боків
І стан речей узнати в тім краю, -
Ви з ними йдіть; це захист ваших кроків.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Десятку, Бородо, збереш свою, -
Він став лічить: - Ти підеш, Злий Собако,
Й ти, Бахуре, й ти Росотопчію,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Й ти, Никлокриле, й ти, Старий Кусако,
Й ти, Ікло Вепряче, й ти, Труто-Змій,
Й ти, Неотесо, й ти, Дурний Чортяко.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'По стежці смоляній ідіть самі,
А ті хай обминуть моста остачу
Й до переходу йдуть собі в пітьмі».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = '«Ой леле, вчителю мій, що я бачу!
Ти шлях цей знаєш, сам зі мною йди, -
Промовив я, - вони ж несуть невдачу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Коли ти обережний, як завжди,
То чом не бачиш, зле вони клопочуть
І поглядами зичуть нам біди?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'А він: «Не бійся, хай собі скрегочуть, -
Це проти тих, засуджених навік,
Що із смоли тут виринати хочуть».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'І вирушили всі на лівий бік,
Але з них кожен перед Бородою
Поміж зубами висунув язик,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'А той їм з заду прогримів трубою.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 47;

UPDATE cantos SET title_uk = 'ПІСНЯ ДВАДЦЯТЬ ДРУГА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 22
    AND p.name = 'Inferno';

UPDATE terzinas SET text_uk = 'Я бачив вершників, які до бою
Ладналися з пихою в рівний стрій,
Але назад тікали із ганьбою;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Я бачив, ворог нищив навісний
Вас, аретинці; бачив я колони
Солдатів; бачив рицарський двобій'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Під барабан, сурму, а чи під дзвони,
А чи на знак з високих башт фортець,
Місцевий або видний крізь кордони, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Але ніде не бачив я, щоб грець
Обрав на свій сигнал просту волинку
Для всіх - чи піший то, чи верхівець.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Ми із чортами вийшли на стежинку
(Ну ж і компанія!), та зриш людей
Побожних в церкві, а п''яниць - у шинку.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Мій зір цікавився смолою, де
Хотів я бачить всі куточки схову
І всіх, хто шляхом вічних мук іде.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Немов дельфін, що хвилю вздрів, готову
Судно нещасне в вирах потопить,
Вистрибує з-під водного покрову, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Так, прагнучи нестерпність мук зменшить,
Якийсь із грішників червону спину
Являв очам на блискавичну мить.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'І наче жаби під жарку годину,
Лишаючи все тіло в глибині,
Самі лиш писки висувають з плину, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Так скрізь чинили грішники сумні,
Але, щоб не зіткнутись з Бородою,
Ховались у киплячій гущині.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Я бачив - серце й досі рве журбою, -
Як забаривсь один і не пірнув
(Бува, лишиться й жаба над водою),'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'А тут Старий Кусака саме був -
Вчепився в кудли, зліплені страшенно,
І, як ту видру, сильно смиконув.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'їх імена узнав я достеменно,
Бо чув безперестанно кличі їх,
Коли вони звертались поіменно.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = '«Гей, Неотесо, пазурів кривих
Дай гостроту йому покуштувати!» -
Почулись голоси кількох із них.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'І я: «Учителю, кортить спитати,
Хто із смоли киплячої там звівсь,
Як причепивсь до нього чорт рогатий?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Мій вождь звернувся: «Звідки ти з''явивсь,
Коли?» - І дав той відповідь нам скору:
«В Наваррськім королівстві я родивсь,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'І мати віддала служить до двору.
А батько мій був майстром темних справ,
Згубив себе й майна велику гору.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Своїм я в короля Тебальдо став
І, надто захопившись хабарами,
У цей окріп нарешті я попав».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Тут ікло Вепряче йому зубами,
Які не сором мати й кабанам,
Відчути дав, які від бивнів шрами.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Попалась миша в лапи злим котам!
Та Борода, йому спочинок давши,
Промовив: «Кинь, йому ще я задам! -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Тоді звернувсь до вчителя, сказавши:
- Як хочеш щось дізнатись, то спитай,
Поки не розшматований назавше».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'І вождь: «Скажи, серед тутешніх зграй
Чи не трапляються якісь латинці
В смолі?» І той: «Ще мить тому, бодай,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'З сусідом їхнім був я наодинці.
Куди приємніш бути із панком,
Ніж з тим, хто шле удари навздогінці».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Тут Бахур: «Годі ляпать язиком!» -
Сказав, і гак у руку, як острогу,
Уп''яв, і видер з м''ясива шматком.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'А Трута-Змій наміривсь теж у ногу
Встромити гак, але очей грозу
На нього звів десятник дуже строгу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Коли ущухло трохи все внизу,
Мій вождь спитав того, чия несита
На рану скорб лила гірку сльозу:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = '«А хто була ця тінь, смолою вкрита,
Коли весь інший залишив ти люд?»
Він одповів нам: «То був брат Гоміта,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Той, що з Галлури. Зла і лжі сосуд, -
Над ворогами владарю свойому
Він учинив занадто легкий суд:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Усіх за гроші відпустив додому,
Як сам казав. Він був не рядовим,
А був царем у царстві тім брудному.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'А логодорець Мікель Дзанке з ним
Веде розмову. Часто і охоче
Говорить кожен про сардінський дім...'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Ой, гляньте, як зубами він скрегоче!
Я дечого б чимало розповів,
Але боюсь, що гаком полоскоче!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Помітивши, що раптом підступив
Дурний Чортяка злий, начальник лютий
Промовив: «Птах лихий, вгамуй порив!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = '«Покличу, якщо хочете почути, -
Так зляканий став мову знов вести, -
Тосканців та ломбардців з ями смути.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'А лихолапам краще відійти,
Щоб не лякали злістю нас своєю.
А я, не сходячи із висоти,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Сімох покличу стежкою цією
Прийти, як свисну, як це робим ми,
Зринаючи з смоли дихнуть над нею».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Звів Злий Собака писок із слиньми,
Хитнувши головою, мовив: «Балуй,
Хитруне, та не памороч уми!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'А той, бо спритність мав таки чималу,
Сказав: «Вам добре з Хитруном таким,
Що віддає своїх вам на поталу!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Тут Никлокрил, перечачи усім,
Гукнув йому: «Як пустишся навтіки,
Чи з бігом не зрівняюсь я твоїм?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Як над смолою крил розмах великий
Розкину, то і видно буде нам,
Чи встоїш проти нашої ти кліки».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Читачу, подивуйся чудесам:
Всі стали очі обертать поволі,
І перший, хто не довіряв словам.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Цього Наваррцеві було доволі,
Напружив ноги та й стрибнув собі,
Урятувавшись від лихої долі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Усі аж скаженіли у злобі,
Й найгірше той, хто більшого дав маху.
Він кинувся, гукнувши: «Я ж тобі!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Але дарма: бо крил гінких до страху
Не прирівняти: цей шугнув на дно,
А той в повітрі уподібнивсь птаху.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Навчилось каченя не так давно,
Як сокіл надлетить - мале у воду!
І той у гніві, що втекло воно.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Розлючений Росотопчій нагоду
Не проминув, щоб дати бій усім,
І полетів над ямою наброду.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Не стрівся він з хабарником метким,
Тож бойовисько розпочав гаряче
На цей раз із товаришем своїм.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'А цей, лихий, як яструб той неначе,
Теж в нього пазурі встромив зо зла,
Та й впали разом в озеро кипляче.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'Жара в смолі їх миттю розняла,
Та повернутися не мали сили,
Бо обліпила крила їм смола.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'І Борода, як інші, посмутнілий
Звелів, щоб четверо в парній імлі
На той бік прірви помагать летіли.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 49;

UPDATE terzinas SET text_uk = 'І тут, і там всі сіли на землі
Й гаки простерли вгрузлим у мерзоті,
Що вже спеклись в розтопленій смолі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 50;

UPDATE terzinas SET text_uk = 'І ми їх залишили у турботі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 51;

UPDATE cantos SET title_uk = 'ПІСНЯ ДВАДЦЯТЬ ТРЕТЯ Коло восьме. - П''ятий схов (закінчення). - Шостий схов. - Лицеміри'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 23
    AND p.name = 'Inferno';

UPDATE terzinas SET text_uk = 'Самотнім, мовчки йти нам без супутніх,
Один за одним надійшла пора,
Як в міноритів прийнято покутніх.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Мені згадалась байка прастара,
Подібна тим подіям проречистим:
Езоп в ній вивів жабу та щура.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'В «цю мить» і «зараз» схожість та ж за змістом,
Що в бійці тій і в баєчних рядках,
Коли поглянуть оком променистим.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'А що думки по других йдуть думках,
То народилась з тої мислі друга,
І ось чому подвоївся мій страх.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Я думав так: «Лиш через нас наруга
Спіткала так їх і жорстоко, й зло,
Тож їх гризе і гіркота, і туга,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Що зло коли б їх дужче припекло,
Його б на нас зігнали і негайно:
Як зайцю з хортом, так би й нам було».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Волосся диба стало незвичайно,
Коли назад я раптом озирнувсь,
І так сказав: «Учителю, сховай-но'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Себе й мене, щоб кожен з нас позбувсь
Тих Лихолапів: не одну їх тушу
Уже я бачу, гнівом всяк надувсь».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'І він: «Твоє лице не швидше мушу
Сприймать, хоч був би я й свинцевим склом,
Аніж твою пойняту страхом душу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Думки одним в нас в''яжуться вузлом;
Мої з твоїми легко поєднати,
Тож до ухвали звів я їх притьмом;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Якщо доволі правий схил покатий,
То в дальший схов потрапимо за мить
І вороги не зможуть нас догнати».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Не встиг свою він мову закінчить,
Як я побачив - на простертих крилах
Рій демонів до нас чимдуж летить.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Мій вождь схопив мене (він був ще в силах!),
Як мати, що прокинулась в диму,
У стінах, від пожежі спломенілих,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Хапає сина та й біжить у тьму,
Турбуючись ним дужче, ніж собою,
Накинувши сорочку лиш саму.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Умить рвонувсь він до крутого звою,
Що обертавсь на косогір стрімкий
І замикав наступний схов стіною.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Не швидше наповняє лотоки
Перед млиновим колесом струмина
І з розмаху б''ють в лопаті струмки, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Ніж ковзала учителева спина,
І він мене до серця пригорнув,
Не як товариша, як свого сина.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'І лиш ногами землю він торкнув,
Як вискочили на скалу з розгону
Дияволи, та страх уже минув:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Бо вишній Промисл, давши в охорону
їм цю лише єдину - п''яту - з ям,
Наклав на вихід з неї заборону.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Блискучі тіні посувались там
Повільно, заливаючись сльозами,
Знесилені тяжким якимсь чуттям.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'На кожній плащ із довгими кінцями,
Каптур на очі низько насувавсь, -
Отак в Колоньї вчинено з ченцями:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Плащ зверху золотом сяйним вкривавсь,
Але тяжким, свинцевим був зісподу,
Що Фрідріхів - солом''яним здававсь.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'О вічний одяг для цього народу!
Пішли ми - вліво, як черга журна,
Вслухаючись у зойки й плач наброду.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Під тягарем, за одною одна
Йшли тіні, і супутника нового
Хода щокрок давала забарна.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Тож я вождеві: «Пошукай, на кого
З людей, ділами чи ім''ям значних,
Слід глянути, поки йде спуск полого».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Впізнав тосканську мову хтось із них
І вигукнув: «Чом женете в дорогу
Ви, що хапаєтесь між тіней цих?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Можливо, дам тобі я допомогу».
І озирнувся й мовив вождь: «Зістав
Ступні разом із ним і йдіть у ногу».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Спинивсь, побачив двох, чий вид являв,
Що допомога в них для нас готова,
Але вантаж і шлях їм заважав.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Наблизившись до нас, вони без слова
Оглянули від ніг до голови,
Й така почулась поміж ними мова:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = '«Як видно з рухів горла, цей живий,
Коли ж померлі, чом же їм, гордливим,
Як всім, не скручено плащами вий? -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Й до мене: - О тосканцю, нещасливим
Нам, лицемірам, запит серце стис:
«Хто ти такий?» - дай відповідь тужливим».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'І я до них: «Я народився й зріс
Над любим Арно, у великім місті,
Те саме тіло я й сюди приніс.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Хто ж ви такі, що муки пломенисті,
У вас, я бачу, по щоках струмлять?
Чому на вас ці тягарі злотисті?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Один відмовив: «Так ваги гримлять
У жовтій та свинцевій оболонці,
Що терези від гир тяжких скриплять.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Ми з ним брати-веселуни, болонці,
Я - Каталано, Лодерінго - він;
Закликані як миру охоронці'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'До тебе в землю; слід, щоб був один,
А ми удвох служили так завзято,
Що Гардінго не видно з-під руїн.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Почав я: «О братове, вас узято...»
Й замовк, побачивши, що в три коли
Людину долі до землі прип''ято.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Мене помітив, зойки вмить зросли
Крізь довге бородище чорно-синє.
Брат Каталано вчув той крик хули'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'І мовив: «Цей, чий стогін знизу лине,
Упевнив фарисеїв сонм сліпий,
Що краще хай один за всіх загине...'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Лежить він, голий, впоперек тропи
І терпить болі під важким ходінням
Від натискання кожної стопи.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Карався й тесть тим способом незмінним,
І радники, що слухались їх слів
І стали для євреїв злим насінням».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Я бачив, як того, хто так терпів,
Із здивуванням розглядав Віргілій,
Розп''ятого, який довічно скнів.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'А там звернув слова до брата милі:
«Скажи, як добре ставлення твоє,
Чи вихід є якийсь на правім схилі,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Щоб швидше на бажання йти своє
І чорних ангелів нам не просити
Знести туди, де міст який не є?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Сказав: «Скоріш, ніж можна уявити.
Тут є стіна великої гряди,
Що ям перетинає ряд розбитий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Стіна ж та обвалилась, і туди
Ви можете піднятись по руїні,
Що вкрила схили й дно після біди».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Постояв вождь і по малій хвилині
Мені сказав: «Молов казки дурні
Той чорт, що гаком грішних бив по спині».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'І брат: «В Болоньї лічено мені
Гріхи диявола, їх цілу зливу ,
Наведено. Він - кат, отець брехні».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'З обличчям, перекошеним од гніву,
Ходою вождь широкою пішов;
І, кинувши юрбу, сумну й тужливу,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 49;

UPDATE terzinas SET text_uk = 'Ступив я в слід вождевих підошов.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 50;

UPDATE cantos SET title_uk = 'ПІСНЯ ДВАДЦЯТЬ ЧЕТВЕРТА Коло восьме. - Сьомий схов. - Злодії'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 24
    AND p.name = 'Inferno';

UPDATE terzinas SET text_uk = 'Пори тієї в молодому році,
Коли під Водолієм Сонце йде
І ночі дням здають частину моці,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Коли полотна паморозь кладе,
Мов білий брат її, в поля просторі,
Та довго їм не влежати ніде, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'У селянина ж порожньо в коморі,
То він іде й глядить, і бачить лан
Весь білий, і об поли б''є у горі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Й вертається, в сумний запавши стан,
Але отямившися від удару,
Виходить знов і крізь надій туман'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Він бачить: світ змінився, мов од чару,
І радісно береться знов до справ -
Попастися жене свою отару.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Так вчитель мій страху мені нагнав,
Як на виду побачив я морщини,
Та він бальзаму рані серця дав.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Уже ми вийшли на моста руїни,
Й звернув до мене вождь лице ясне,
Що перше в нього бачив край долини.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Він, озирнувши груддя кам''яне,
І, начебто порадившись з собою,
Розкрив обійми і обняв мене.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Мов хто не скінчив з справою одною,
А дальшу взяв уже до голови,
Так він, мене піднісши над стіною'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Уступу, намічав уступ новий,
Казавши: «Став на цей ти камінь ногу,
Та перше спробуй, може, він кривий?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Ніхто в плащі цю б не пройшов дорогу,
Бо ледве й ми повзли на брили з брил,
Він - легко, я ж спирався на підмогу,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Якби із цього боку шлях на схил
Не був коротший тих, що їх долають,
Як вождь - не знаю, я ж - позбувся б сил.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Але тому, що Лихосхови мають
Покатість до криничного жерла,
Виходить, що вони стіну здіймають,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Щоб не однакова увись була.
Там врешті ми спинились, де кремнистий
Стрімчак повис, як ламана скала.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Став подих в мене кволий та нечистий,
Поки спромігся я шпиля дістать,
І мусив стомлений на камінь сісти.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = '«Тепер не час тобі ледарювать, -
Сказав учитель; - слави ні перина,
Ні подушка не в силі дарувать.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Коли бере безславних домовина,
Вони такий же залишають слід,
Як дим в повітрі чи на хвилях піна.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Зведися ж: втому подолати слід
В душі, яка здолає зло природи, ,
Як плоть важка не призведе до бід.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Ми маємо зійти на довші сходи;
Не досить нам лишити ці місця,
Якщо зі мною певно дійдеш згоди».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'І звівсь я, вдаючи, ніби моя
Бадьорість більша, ніж була на ділі,
Й сказав: «Рушай, бо сповнивсь моці я!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Ми вирушили по ще менш похилій
Урвистій скелі, по якій іти
Було ще важче, ніж на першій брилі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Я розмовляв, щоб очі одвести,
Аж з ями голос раптом стало чути,
Та слів ніяк не міг я осягти.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'То дивно, що не в силах був збагнути,
Бо ж на мосту стояв, якраз над ним.
А голос був розгніваний і лютий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'І я нагнувся, та очам живим
Крізь пітьму не пройти до дна жахного,
І я: «Учителю мій, перейдім'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'На другий бік, спустімся з мосту цього,
Бо хоч я звідси й чую - слух ступів,
Хоч і дивлюсь - не бачу ж я нічого.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'У відповідь він мовив: «Я б хотів
Сказать, що хочеш чути: що високу
Слід просьбу вдовольнять без зайвих слів».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Зійшли із мосту ми із того боку,
Що поряд з восьмим сховом по стіні;
Цей схов явив картину нам широку:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'І я побачив кублища страшні
Огидних змій; од негоді цієї
Ще й досі кров холоне у мені.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Не слав же, Лівіє, землі своєї,
Де крім амфесібен є тьма потвор:
Келідри, ченкри, якули, фареї.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Ні стільки гиді, ні подібний мор
Не стрінуться ні там, де ефіопи,
Ні там, де хвиль червоних чути хор.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Торуючи собі між гадів тропи,
Крутились голі тіні без надій
Знайти чи схови, чи геліотропи.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'На грудях в них хвости й голівки змій
Сплітались, тиснучи із болем спину
І руки в''яжучи вузлом на ній.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Найближчому до нас в одну хвилину
Туди, де шия з пліч в живих стирчить,
Змія, вкусивши, упустила слину.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Скоріш, ніж О чи /хто начертить,
Спахнув він і згорів, весь обернувшись
На попіл за якусь коротку мить.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'І тільки він розсипавсь, розметнувшись,
Прийшов цей попіл сам з собою в стик,
Ув образі колишньому зімкнувшись.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Учені знають часу певний лік,
Що Фенікс хоч вмира, та кров в нім свіжа,
Коли надходить п''ятисотий рік.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Лиш сльози ладанні - у нього їжа
Та ще амом, не зерно, не трава,
А нард і мирра - в нього смертна хижа.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Мов той, хто падає і охлява,
Коли його на землю біс жбурляє,
Чи закупорюється голова,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Коли ж підводиться, все оглядає,
Тяжким припадком зламаний цілком,
Дивується і, дивлячись, зітхає, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Так грішник встав над попелу горбком.
О, Божий суд суворий надто з нами,
Раз безліч мук вділяє багатьом!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Мій вождь спитав, хто він і звідки саме;
І той: «Недавно я з Тоскани зміг
Потрапить до цієї злої ями,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Звіряче, не по-людськи я поліг.
Так, мулом справді був: Я Ванні Фуччі -
Звір, і Пістойя - гідний мій барліг».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'І я вождю: «Нехай про дні він луччі
Розкаже нам, за віщо кари ці;
Я знав його лихим в благополуччі».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Перш грішник не вважав, що тут співці,
Але, на мене звівши очі вперті,
Від сорому змінився на лиці'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Й сказав: «Що ти страждання зриш відверті, -
Це найлихіше у моїй судьбі
І навіть гірше від самої смерті.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Відмовити не можу я тобі,
Сюди-бо я попав як тать із татів, -
Взяв посуд з ризниці я, далебі,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'А іншого в крадіжці звинуватив.
Та щоб цьому не дуже був ти рад,
Якщо на вихід ти надій не втратив,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'Ти слух свій прихили для дальших рад:
В Пістойї спершу влада «чорних» згине,
Та свій Флоренція поновить лад.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'Марс пари з долу Магрського підкине
У тучі, як вмістилища покар,
І буря разом з громом всюди рине;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 49;

UPDATE terzinas SET text_uk = 'Почнеться бій з подертим клоччям хмар,
Яке втече по Піхтовому полю, -
Там «білих» остаточний жде удар.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 50;

UPDATE terzinas SET text_uk = 'Кажу це, щоб тобі завдати болю».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 51;

UPDATE cantos SET title_uk = 'ПІСНЯ ДВАДЦЯТЬ П''ЯТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 25
    AND p.name = 'Inferno';

UPDATE terzinas SET text_uk = 'Наприкінці розмови святокрадець,
Підвівши руки, дулі поробив
І крикнув: «Боже, ось тобі мій вкладець!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Від того часу змій я полюбив:
Одна ті чорні заглушила звуки,
Мов кажучи: «А не кажи цих слів!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'А друга, оповивши йому руки,
Зв''язала у тугому їх вузлі,
Й не розірвать ніяк цієї злуки.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Пістойє, о Пістойє! Чом в золі
Ти не зникаєш у вогненних бурях,
Твоє закореніло сім''я в злі!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'У жодному з пекельних кіл похмурих
Ще не траплявсь мені такий блюзнір,
Ні навіть той, хто впав на фінських мурах.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'І той побіг, немов лавина з гір;
Я вздрів центавра - з пащі била піна
І він кричав: «А де він? Де цей звір?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Є, мабуть, у Мареммі половина
Тих змій, що збились там, де був конем,
До місць, де починалася людина.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Над тім''ям же нависши тягарем,
На плечах ширився, немов собака,
Дракон; із ніздрів дихав він огнем.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Учитель мій сказав: «Ти бачиш Кака,
Який колись під самий Авентін
Розлив озера крові, розбишака.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Давно не ходить із братами він,
Бо видурив собі в них на додаток
Велике стадо з тучних луговин.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Не довго так збирав собі достаток:
Дав Геркулес йому сто раз дубця,
Хоч перший же вмертвив його десяток!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Центавр завіз у даль свого їздця,
Й три духи підійшли під час розмови,
їх не помітили б ні вождь, ні я,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Якби вони не вигукнули: «Хто ви?»
Тоді з нас кожен мову перервав,
їх пильно роздивлятись був готовий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'З них на землі нікого я не знав,
Та голос до знайомства спричинився,
Бо раптом хтось чиєсь ім''я назвав,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Промовивши: «А Чанфа де подівся?»
І носа пальцем я собі торкнув,
Щоб вождь з увагою з тим духом вівся.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Не диво, коли ти це все почув
І віру ймеш, читачу, неохоче:
Я теж не вірю, хоч і сам там був.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'І поки я втупляв свої в них очі,
Враз виповз шестиногий змій гидкий
Та на одного з них як не підскоче!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'В середні лапи він забрав боки,
Передніми перехопивши кисті,
А там обидві укусив щоки'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'І задніми він стегна стис нечисті,
Між обома протнув свого хвоста,
І вгору звівсь по спині всій костистій.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Так плющ до стовбура не прироста,
Не глушить так, як ця гидка тварюка
Притиснулась до людського хребта.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Злились, як віск, людина і гадюка,
І постає в очах в нас не загин -
Забарвлених інакше тіл сполука.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Так барви зазнають в багатті змін,
Поки огонь не встиг папір пожерти, -
Уже не білий, ще й не чорний він.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'А інші два, пізнавши образ стертий,
Волали: «Як, Аньєле, ти змінивсь!
Поглянь, - не два і не один тепер ти!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'На місці двох єдиний лик з''явивсь,
Бо й голови зімкнулися в єдину,
І вид новий од давнього різнивсь.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Руками лапи стали в ту хвилину,
Й не розпізнаєте, хоч як б''єтесь,
Живіт, литки, і стегна, й груди, й спину.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Колишній вигляд зник, розвіявсь десь,
І образ «Два й ніхто», що небезпеку
В собі ховав, змінився геть увесь.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Мов ящірка, що в нестерпучу спеку
Десь блимне блискавкою серед дня,
Перебігавши стежку недалеку.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Так, звідкись вистрибнувши, змієня
На одного й останніх двох насіло,
Все чорно-синє, наче перченя,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Вп''ялось в те місце, котре нам служило
Найпершим живлення провідником,
А потім впало вниз до ніг безсило.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Укушений аж остовпів притьмом,
Стояв, дививсь на змійку, позіхавши,
Як вражений недугою чи сном.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'У змійку - він, та - в нього зір втуплявши,
Обоє дим пускали всім на страх,
Він - з рани, змійка з пащі виділявши.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Тож хай мовчить Лукан у тих місцях,
Де в нього зник Сабелл і з ним Нассідій,
Хай слуха, про який повім я жах.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Про Кадма й Аретузу хай Овідій
Мовчить, що на ручай та на змію
їх обернув, - не з мене буть завиді, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Бо дві істоти у однім строю
Він не міняв, у нього два сосуди
Взаємно не міняли суть свою.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Тут безперервно зміни йшли усюди:
З хвоста в гадюки вила рознялись,
Той ноги звів, піднявши їх по груди.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Голінки й стегна щільно так злились,
Що вже ніхто не міг би й пригадати,
Чи щілина й була між них колись.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Хвіст набирав все більш тієї втрати,
Що той зазнав, а шкірний в них покров -
В змії м''який, а в мужа став лускатий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Я бачив - лікоть у пахву ввійшов
І довші лапи у змії робились,
В людини ж руки йшли у глибший схов.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Дві задні лапи у змії скрутились
І вкупі стали членом потайним,
В нещасного ж дві лапи утворились.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Вкривав обох їх кольором новим
І переносив пасмами волосся
З одної голови на другу дим.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Одне з них впало, друге підвелося,
Та їх в''язав близьких очей огонь
В якім міняння пик розпочалося.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Той, хто стояв, розтяг лице до скронь,
І з зайвих решток речовин прилежних
Два вуха стало в розмірі долонь.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Що ж не сповзло назад з причин, залежних
Від обсягу, те збилось в носа гак
Та ще у губи розмірів належних.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Той, хто лежав, свій писок витяг так,
Що вуха вмить зайшли в покров лиснючий -
Подібне робить з ріжками слимак.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Язик, в людини цільний, балакучий,
Розпався навпіл, а жало, як є,
Стяглося, й зник раптово дим тягучий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Душа, що втратила лице своє,
З сичанням голосним повзе тропою,
А той, заговоривши, вслід плює.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Він, повернувшись спиною новою,
До іншого: «Хай Бозо, як і я,
Поповзає стезею коловою!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'Так бачив я між сьомого сміття,
Що змінювалось все й мінилось гидко,
Й списав, можливо, щось не до пуття.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'Хоч стомленим очам не дуже видко,
Й мій дух бентежився, в свої круги
Не так ті двоє тіней зникли швидко,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 49;

UPDATE terzinas SET text_uk = 'Щоб не впізнав я Пуччо Шкутильги, -
Із трьох лиш він був при своїм суціллі
І не позбувся виду чи ноги.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 50;

UPDATE terzinas SET text_uk = 'А другий - той, за ким скорблять в Гавіллі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 51;

UPDATE cantos SET title_uk = 'ПІСНЯ ДВАДЦЯТЬ ШОСТА Коло восьме. - Восьмий схов. - Лукаві порадники'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 26
    AND p.name = 'Inferno';

UPDATE terzinas SET text_uk = 'Радій, Фйоренцо, ти така велика,
Що на землі й на морі б''єш крилом,
Та йде і в Пеклі слава стоязика!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Увагу поміж злодіїв п''ятьом
Віддав я вродженням твоїм, якими
Ти б не пишалась; криюсь я стидом.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Коли у сні годинами нічними,
Насниш ти правду, взнаєш, що за змін
Ждуть жителі у Прато й інші з ними.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Раз має статись щось (хоч би й загин!),
То хай би якнайшвидше мав він статись!
Бо тим він тяжчий, чим пізніший він.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Ми рушили; як мусили спускатись
На дно уступами, - по них тепер
Удвох з вождем ми мали видиратись.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'І тут, між тріщин, каменів печер
Ми здерлись на стежину самітную, -
Нога не йшла, щоб лікоть не підпер.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Засумував тоді й тепер сумую,
Вернувши мислю бачених в юрбі,
І серце якомога я гальмую,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Щоб керівник був у його судьбі,
Й коли опорою зоря жива є
Чи ліпший хтось, - не заздрю я собі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Мов селянин, який відпочиває,
В той час, як скрить лице своє пора
Тому, хто світ промінням осяває,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Як муха місце дасть для комара, -
Він бачить в світляках весь глиб долини,
Де лан оре і виноград збира, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'В стількох вогнях тієї ж вздрів хвилини
Я восьмий схов, як, бувши на мосту,
Побачив скрізь під ним страшні глибини.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Мов той, за кого учинили мсту
Ведмеді, бачив, як візок з Іллею
Вогненні коні мчали в висоту,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Саме лиш сяйво, ясністю своєю
Подібне на хмаринку неясну,
Десь високо вгорі понад землею, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Так бачив я, вогонь снував по дну;
Хоч душі в нім горіть не перестануть,
Не викривав із них він ні одну.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Я став на верх моста, щоб краще глянуть,
Й якби я не затримавсь на краю,
То легко міг би в тій безодні кануть.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'І вождь, цікавість бачивши мою,
Сказав: «У цих вогнях є душі, й кожна
Зодягнена у пагубу свою».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = '«Учителю, - промовив я, - тотожна
Ця думка з баченим; передусім ''
Скажи лишень мені, коли це можна,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Який то пломінь із вершком двійним
Неначе ворожнечу ллє злостиву,
Мов Етеокл горить із братом в нім».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Він мовив: «Кару тут несуть правдиву
Улісс і Діомед; їх ремесло
До мсти веде їх, як вело до гніву.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'В палаючий вогонь їх принесло
Сильце з конем, що відчинило браму,
Звідкіль шляхетне римське сім''я йшло;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Де''щамія, що в сльозах від страму
Ахілла, мертва, кличе в млі жадань;
Та ще Палладій, викрадений з храму».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = '«Якщо говорить це двійко палань,
Прошу, - сказав я, - вчителю, і знову
Прошу, і тисяч варте це прохань,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Не дай мені почуть твою відмову
Тут зачекать рогатий пломінь цей,
На волю згляньсь, уклін зробить готову».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'І він: «Оздоблює твоє лице
Достойна просьба, і її я вволю;
Не розмикай лиш губ своїх кільце.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Я сам казатиму; турботи й волю
Твої я знаю, ти ж для греків цих,
Мабуть, незбагнутих поділиш долю».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Обравши мить і місце, вождь до тих,
Що саме сходили на схил пологий,
Звернув промову в виразах таких:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = '«О ви, одягнуті в огненні тоги!
Якщо вас гідний став я, поки жив,
Якщо вас гідний став я, скільки змоги,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Як я вести почав високий спів,
Не рухайтесь, і хтось хай скаже, чому
Та як загинув, як життя скінчив».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Гойднувшись, вищий ріг в огні старому
Став видавати гуркіт чималий,
Неначе грім у вихрі вітряному.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'І, розхитавши свій вершок малий,
Немов крило для підіймання й лету,
Заговорив і так сказав: «Коли'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Я від Цірцеї, що мене в Гаєту
На цілий рік замкнула, відійшов
(Енея назва не пірнула в Лету),'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Ні почуття до сина, ні любов
До батька, ні палкий вогонь сердечний,
Який до Пенелопи не холов, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Не похитнули потяг небезпечний
Душі моєї - бачить в світ вікно,
Людську чесноту і порок конечний.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Я спорядив одне тоді судно
І в море вийшов із товаришами,
Які були зі мною заодно.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Проплив між обома я берегами
Іспанії й Марокко, сардів край,
Й між іншими в тім морі островами.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Уже в нас над чолом сріблився гай,
Коли у місце ми зайшли вузьке те,
Де Геркулес, щоб позначити край'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Шляхам, стовпи поставив для прикмети,
Й пішов Севільї справа сад живий,
А зліва одійшли будови Сети.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = '«О браття, - мовив я, - пройшли вже ви
Крізь сотні тисяч лих на захід дальній!
Недовгий строк потратьте життьовий,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Що вам лишився, на відповідальні
Ще дальші подорожі в світ сумний,
Щоб вслід за сонцем, землі зріть печальні.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Тож пригадайте, ви чиї сини,
Бо ви народжені не животіти,
А знання й честь нести у світ ясний».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Недовга ця промова знаменитий
В моїх супутниках лишила слід,
І вже не знав я, як їх зупинити.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Кормою повернули ми на схід,
Зробили на шалений лет в просторі
Із весел крила й брали вліво хід.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Під іншим полюсом я всі вже зорі
Зрів уночі, а наші на очах
Зникали мало не цілком у морі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Уп''яте сяяла на небесах
І гасла місячна стезя широка,
Відколи вийшли ми на смілий шлях,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Як несподівано гора висока
Замріла невиразно нам здаля,
Що вищою з усіх здалась для ока.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Зраділи ми, але нова земля
Зустріла негостинно, вітровінням
Ударивши у снасті корабля.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Кружило тричі нас води крутінням,
Вчетверте ж піднялась корма увись,
Униз же ніс пішов чиїмсь велінням -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'І хвилі понад нами знов злились».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 48;

UPDATE cantos SET title_uk = 'ПІСНЯ ДВАДЦЯТЬ СЬОМА Коло восьме. - Восьмий схов (закінчення)'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 27
    AND p.name = 'Inferno';

UPDATE terzinas SET text_uk = 'Засяяв пломінь рівно, мов планета,
Помчав у далину і там заглух
Із дозволу привітного поета.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Коли наш зір принадив інший дух
Неясним звуком, що із нього рвався
І долинав до наших чуйних вух.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Як сицилійський бик, чий рев вчувався
На зойк того - і так тому і слід, -
Хто пильно збудувать його старався,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Ревів стогнанням жертв його обид,
Хоч, бувши зроблений увесь із міді,
Здавалось, од страждань та болів, блід, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Так, замкнені в палаючім боліді,
Говірку позичаючи в огні,
Слова з''являлись у туманнім виді,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Та зрештою собі шляхи ясні
На вістрі язика знайшли в проході,
І ринули розбірні й голосні, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Й почули ми: «О ти, хто в нашім роді
Ломбардськім щойно чітко говорив,
Сказавши: «Йди лишень, із мене годі», -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Я б, може, пізно просьбу повторив,
Не пожалій спинитись на хвилину,
Як не жалію я, хоч би й згорів.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Як зараз впав ти в цю сліпу країну, -
Вгорі ж зосталась люба сторона
Латинська, що я втратив за провину, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Скажи, чи мир в Романьї, чи війна?
Од гір, де Тібр почавсь, до стін урбінця
Лежить моя вітчизна чарівна».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Я ще уваги повен був по вінця,
Коли мій вождь із доторком легким
Сказав: «Промов йому, вшануй латинця».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'І тут я волю дав словам таким
Без затримок тривалих чи обманів:
«О душе, скована вогнем палким!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Твоя Романья вся в серцях тиранів
Без воєн неспроможна й дня прожить,
А нині меч нікого там не зранив.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Равенна, як раніш, така ж лежить,
У ній орел Поленти загніздився,
І Черв''я під крилом його дрижить.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'А край, що зрештою оборонився,
Де ліг француз кладовищем сумним,
В зелених лапах нині опинився.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'А пес Веруккйо з песиком своїм,
Які Монтанью вбили так мізерно,
Скриплять зубами над шматком смачним.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Міста ж біля Ламоне та Сантерно
Під юним левом білого герба,
Що зазіхає на добро пажерно.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Той край, де Савйо ллється з-під горба,
Лежить собі між долом та горою,
Немов між волею й ярмом раба.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Але прошу тебе переді мною
Відвертим бути, як я щойно був,
Щоб не забувсь ти пам''яттю людською».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Вогонь, мугикнувши, ізнов хитнув
Своїм колючим вістрям, і, не знаю,
Як саме сталось, зрештою загув:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = '«Якби я вірив, що відповідаю
Тому, хто знов побачить білий світ,
То мій вогонь би не тремтів без краю.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Та ми терпіти будем вічний гніт,
Тож віддаватись нічого химерам, -
Не боячись ганьби, я дам одвіт.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Я воїном був, потім кордильєром,
Повіривши у мотуз рятівний,
І віру цю святим сповило б флером.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Якби мене наш пастир головний
Не спокусив - хай злом йому помститься! -
Я розповім, як стався гріх страшний.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'В житті, відколи зміг на світ з''явиться,
З дарунком нені з м''яса та кісток,
На вдачу був не лев я, а лисиця.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Таємних я доріг знав кожний крок
І так прехитру лаштував я пастку,
Що край землі здригався од чуток.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Коли побачив я останню частку
Своїм літам, то надійшла пора
Згорнуть вітрила і прибрать оснастку.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Утіхам давнім всім поклав я край
І дурня я прогнав, якого клеїв, -
Ах, я нещасний! - і вже бачив рай,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Та ватажок новітніх фарисеїв,
Що воював в місцях, де Латеран,
Не проти сарацинів чи євреїв;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Він ворогами мав лиш християн,
Які не здобували Акри сміло
Й не гендлювали в землях бусурман.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Зневажив він свій сан, святе все діло,
В мені ж - непоказний, сумирний чин
І мотуз, той, що геть ослабив тіло,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'І як Сільвестра хворий Константин
З Сиратті кликав гоїти проказу,
Мене намірився закликать він'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'У нього люту вгамувать відразу.
1 знітивсь я, не знавши, що робить:
Він нетверезим видався одразу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'А він казав: «Душі гризото, цить!
Я розгрішу тебе; хай ум багатий
Порадить Пенестріну як згубить.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Рай можу замикати й розмикати,
Ключі я маю для ції мети, -
їх не хотів мій попередник знати».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Не міг до мене доказ не дійти,
Не втримав слів у власній обороні,
Й сказав: «Раз, отче, зняв із мене ти'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Мій гріх, то удержись в такім законі:
Багато обіцяй, а менш роби, -
Й восторжествуєш на високім троні».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Франціск по мене злинув на гроби,
Та чорний херувим промовив руба:
«Облиш, бо він іде в мої раби!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Мені душа була у нього люба,
Відколи раду він лукаву дав!» -
І зараз же вхопив мене за чуба.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Він не розкаявсь, прощеним не став;
А каючись грішить - дільце мерзенне,
Є суперечність в цьому стані справ».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Ой лихо! Чудисько оте скажене
Мене за чуб схопило й додало:
«А ти й не бачив, що за логік з мене»? -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'І до Міноса вкинуло, й чоло
Насупив той, хвостом крутнув по спині
Аж вісім раз, його куснувши зло,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Й сказав: «Вогонь - покара цій провині».
Тому я тут в скорботі й муці йду,
В огонь одягнений, як бачиш, нині».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'І пломінь в дальшу муку та біду
Посунув, змовкнувши, червонотілий,
Хитавши ріг свій гострий на ходу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'А я і вождь - ми разом поспішили
Звестись на кам''яної арки шар
Над ямою, де муками платили'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Ті, хто на чварах наживав тягар.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 46;

UPDATE cantos SET title_uk = 'ПІСНЯ ДВАДЦЯТЬ ВОСЬМА Коло восьме. - Дев ''ятий схов. - Призвідники розбрату'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 28
    AND p.name = 'Inferno';

UPDATE terzinas SET text_uk = 'Хто, навіть вільними від рим словами,
Повісти міг би, скільки крові й ран
Побачив я на дні нової ями?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Тут мова лиш заводить нас в обман:
Бо наш словник ще дуже невеликий
І розум завузький збагнуть цей стан.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Якби звелись усі мерці й каліки,
Хто кров у благодатному крак>
Пулійському пролив під зойки й крики'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Від рук троян; хто в довгому бою
Перснями заплатив данину волі,
Як чесний Лівій в книгу вніс свою;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Ті, хто відчув непереносні болі,
Що їх завдав дерзкий Роберт Гвіскард,
І ті, чиї кістки гниють поволі'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Під Чеперано, де без алебард
Пулійці зрадили, й, не вдівши лати,
При Тальякоццо їх здолав Алард;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Коли б на одну купу поскладати
Всі кукси й шрами, - їх стократ затьмить
Той надто моторошний схов дев''ятий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Побачив я того поміж страхіть,
У кого, мов у діжки не до вжитку,
Був розруб з губ до місця, чим смердіть.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Кишки звисали аж по саму литку,
Йшли нутрощі до темного мішка,
Де в кал надходить все, що є в спожитку.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'На мене звівши очі хижака,
Розкрив свої він груди до скелета
Й сказав: «Дивись, розрубина яка!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Дивися на каліцтво Магомета!
А спереду йде стогнучи Алі, -
Спотворене лице - його прикмета.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Усі, хто тут несе в собі жалі,
Є сівачами розбрату й розколу
І йдуть, порубані, в жахливій млі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'А ззаду чорт рубає всіх посполу,
Бо грішники гуртом повз нього йдуть,
Шматує лезом він усіх спрокволу,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Коли вертається скорботна путь.
У нас, допоки дійдемо до нього,
То всі ушкодження і заживуть.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'А ти хто, що по краю кам''яного
Йдеш гребеня, ти, може, відтягти
Гадаєш строк покарання страшного?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = '«Не вмер він ще, і не гріхи стягти, -
Сказав мій вождь, - його повергли в сушу, -
Бажання все самому осягти.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Умерлий, я його проводить мушу
Крізь Пекло, з кола в коло всіх принук, -
Це так, як те, що бачу твою душу».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Спинив їх з сотню тої мови звук.
Всі, роздивляючись мене єдино,
Від подиву забули гіркість мук.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = '«Під ясним сонцем братові Дольчіно,
Щоб не зарано впав на наш поріг,
Перекажи таке, жива людино:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = '«Готуй припаси, бо глибокий сніг
Новарцю стане за підмогу, й з нею
Боротись довго ти б уже не зміг». -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Підвівши ногу трохи над землею,
Промовив Магомет такі слова,
Ступнув та й рушив стежкою своєю.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Той, в кого з одним вухом голова
Була обкарнана на повну силу,
Відтятий ніс і зрізана брова,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Спинивсь, бо мову вчув для себе милу,
Як всі, у здивуванні похиливсь,
Розкрив горлянку, з крові потемнілу,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Й сказав: «Ти не за гріх сюди зваливсь,
Я в тій землі, де знають всі латину,
Стрічав тебе, якщо не помиливсь.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Ти П''єра пригадай да Медічіну,
Коли повернешся у чарівну
Поміж Верчеллі й Маркабо долину,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Ти попередь у Фано сивину
Мессера Гвідо з Анджолелло в парі, -
Бо прозираєм істину одну, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Що скинуть їх за борт в мішку по сварі
Біля Каттоліки на дно руде
При зрадному тиранові-почварі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Між Кіпром та Майоркою ніде
Не здибувавсь Нептун з таким пороком,
Хоч вільно там пірат судно веде.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Цей зрадник, що одним лиш бачить оком
І править в землях, що їх мій сусід
Повік минав би якнайшвидшим кроком,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'До себе звабить їх, мов для бесід,
Але вітрам фокарським необорим
Вже їм було б молитися не слід».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'І я йому: «Щоб світом я просторим
Розніс про тебе звістку між людьми,
Скажи: хто це з таким печальним зором?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Тоді він щелепи розняв самі
Сусіду, що ішов сумний, в мовчанні,
І вигукнув: «А він тепер німий!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Це ж він згасив у Цезаря в вигнанні
Весь сумнів, бо кого, мовляв, жде трон,
Той гаятись не мусить у ваганні.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Ой як стогнав, коли його закон
Позбавив язика, як плакав з туги
Колись швидкий на мову Куріон!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Пліч-о-пліч рештки рук підносив другий
У темряві, поміж калічних зграй,
З лицем, аж почорнілим од напруги,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Вигукуючи: «Моску ще згадай,
Який сказав: «Раз почали - скінчімо!»
І тим приніс біду в Тосканський край».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'А я додав: «А в дім твій - смерть, всім зримо!»
Й, примноживши страждання, видав виск
Та й знову з криками подався мимо.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'А я, вдивившись в дивовижний тиск,
Таке побачив, що розповідати
Без свідків я б не взяв на себе риск,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Коли б не людська совість: цей вожатий
До мене руку із щитом простер,
Щоб чистого душею захищати.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Побачив я й мов бачу дотепер,
Як стежку тіло безголове стеле
У стаді покалічених химер.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'І голову несе воно, дебеле,
В простягнутій руці, немов ліхтар,
І стогне болісно вона: «Ой, леле!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Він сам собі світив, немов пожар,
І був один у двох і двоє в однім,
А як - це знає лиш правічний цар.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Він зупинився під мостом безводним
І руку простягнув свою увись,
Щоб зблизитись до нас лицем холодним'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'І мовити: «На мене подивись,
Між мертвих дишеш, як живе все диха,
Ти згляньсь на тих, що в муці тут злились.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Коли ж з мого ім''я всім буде втіха,
То знай, що я Бертран де Борн, який
Призвів малого короля до лиха.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Я сина з батьком ятрив на сварки, -
Незгірш Ахітофел Авессалома
З Давидом збурював на бій гіркий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Нарешті мозок мій скувала втома,
Бо він був зрубаний мечем з хребта
Й для нього решта тіла незнайома,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'Така була мені покара й мста».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 48;

UPDATE cantos SET title_uk = 'ПІСНЯ ДВАДЦЯТЬ ДЕВ''ЯТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 29
    AND p.name = 'Inferno';

UPDATE terzinas SET text_uk = 'Великий натовп цей і ці терзання
До того обпоїли зір мені,
Що підступали із грудей ридання.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Віргілій же: «Що бачив ти на дні?
Чому ти роздивлятися готовий
Ці тіні покалічені, страшні?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Тебе ж не притягали інші схови,
І там же ти не зупинивсь ніде.
На двадцять дві аж милі ці закови.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'А місяць вже під наші ноги йде,
Лишивши обмаль часу нам на жалі,
Багато ще небаченого жде».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = '«Якби ти знав, - я мовив у печалі, -
На що я зором націляв своїм,
Ти сам би не велів мені йти далі».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Але він рушив, я пішов за ним,
Розмову слухавши, на зміст багату,
А там додав: «У цім дуплі бруднім,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Де зір мій прагнув одшукати втрату,
Напевно, і мій родич зотліва, -
Він платить за гріхи велику плату».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Тоді сказав учитель: «Постривай,
І думка хай твоя над цим не б''ється,
Бо он його майнула голова;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Я бачив все, як він між тіней в''ється,
Гукає щось, погрожує тобі,
І чув, що Джері він дель Белло зветься.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'А ти не помічав його в юрбі
Й, цікавлячись лиш владарем Отфору,
Не подививсь на родича в клятьбі».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = '«О вождю мій, він смерть мав наглу й скору,
Яку не відомстили, - мовив я, -
Ті, що несуть ганьби тяжкої гору,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Не змила кров йому гидка сім''я,
Тому ми і зустрілися чужими, -
Тож співчува йому душа моя».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Наблизились з розмовами такими
До скелі ми, і схов новий цей нам,
Коли б світліш було, до дна б став зримий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Коли зійшли ми над останню з ям
Тих Лихосховів, і юрма безруха
Одкрилася здивованим очам, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Розлігся лемент не одного духа,
Мов зойки караних з ста тисяч диб,
Тож затулив собі міцніш я вуха.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Такі знялися б стогони, коли б
У серпні всі лікарні в Вальдік''яні,
В Мареммі, на Сардинії у глиб'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Занурити у звалище на твані.
Такий нестерпний дух сюди проник,
Мов гній зібрався в непромитій рані.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Ми підвелися на останній стик
Довгастої скали, звернувши вліво,
І погляд мій, що до імли вже звик,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Пройшов до дна, де Богу незрадливо
Слугує Справедливість, бо велить
Фальшівникам каратися жахливо.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Не знаю, чи було сумніше зріть
В Егіні, як людей, тварин до миші
Лихе повітря, сповнене страхіть'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Заразних, вбило все, що тільки дише,
І винищило всіх, хто був живий,
Та знову людство, як поет нам пише,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Пішло уже від сім''я мурашви, -
Ніж бачити у цій жахній долині
Стражданнями заповнені рови.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Хто на живіт упав, а хто на спині
Лежав сусідовій, ті ж, мов козли,
Угору видирались по стежині.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Ми крок за кроком мовчазні ішли,
Дивуючися дивом стрічним трупам,
Що свого тіла звести не могли.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Побачив двох, що підпиравсь, як слупом,
Сусідом кожен, сидячи, цілком
Від пальців ніг до тім''я вкритий струпом.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Не бачив я, щоб працював скреблом
Бистріш слуга, як пан не терпить ждати,
Чи сторож, змінюючись перед сном,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Ніж кожен шкіру дер собі, затятий,
Та розривав сверблячі пухирі,
Щоб хоч на мить полегшення дістати,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'І так шкребли по скровленій корі,
Як з коропа луску зчищають вміло
Або з ляща на чорному дворі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = '«О ти, що дряпаєш і рвеш злютіло, -
Почав мій вождь до одного із них, -
Мов кліщами, руками власне тіло,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Скажи, латинців чи нема яких
Між вами, хай же ти не поламаєш
Повіки нігтів для трудів таких!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = '«Латинці ми, яких ти розглядаєш, -
Обидва, - відповів він із плачем, -
Ти ж будеш хто, що пильно так питаєш?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'І вождь мій мовив: «Ми разом ідем
Із ним, живим; я вийшов у дорогу,
Щоб Пекла показати весь об''єм».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Забувши про взаємну допомогу,
У мене кожен, тремтячи, вдививсь
Як і всі ті, що чути мали змогу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Мій добрий вчитель ближче нахиливсь,
Сказав: «Скажи їм, що в думках витає».
Я й розпочав, пораді підкоривсь:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = '«Хай вічно ваша пам''ять не зникає
У першім світі, де людський є плід,
Хай під сонцями багатьма сіяє!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Скажіть, звідкіль ви і який ваш рід,
А що в броні ви з лусочок-мерзенниць,
То вам цього стидатися не слід».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = '«Я був з Ареццо, і Альберо-сьєнець, -
Сказав один, - мене вогню віддав,
Та не за те сиджу в найглибшім з денець.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Я, правда, з ним якось пожартував:
«Літать я вмію летом небувалим», -
А він, глупак, до цих цікавий справ,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Хотів навчитись, та не став Дедалом.
І той, кому доводивсь як синок,
Звелів мене згубить вогненним палом.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Мінос же, що не робить помилок, -
А що в алхімії досяг я висі, -
В цей схов послав мене на вічний строк».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'І я сказав поетові: «Дивися,
Який пихатий сьєнський весь народ!
Французи - й ті не так би повелися!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'А другий прокажений гріховод
Таке тоді мені додав: «Крім Стрікки,
За скупість гідного всіх нагород;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Та й Нікколо, що сім''я вніс гвоздики
Найперший в ґрунт, а із садових див
Линули урожайні втішні ріки;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Ще й товариство, у яке вгатив
З Ашани Качча землі всі з садами,
Засліплений же розум загубив.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Щоб ти довідавсь врешті, хто це саме
Кепкує тут із сьєнців залюбки,
Хай очі в тебе ще добавлять тями'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Й впізнаєш ти Капоккйо тінь, який
Алхімією підробляв метали;
Пригадуєш, я змалку був такий'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'І в мавпуванні став мастак чималий».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 47;

UPDATE cantos SET title_uk = 'ПІСНЯ ТРИДЦЯТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 30
    AND p.name = 'Inferno';

UPDATE terzinas SET text_uk = 'В часи, коли Юнона відомщала
Семели гріх на Фівах, коли, страх
Із неба несучи, в доми їх мчала,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Цар Атамант із безумом в очах
Свою дружину вздрів з двома синками,
Яких вона тримала на руках,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Гукнув: «Даваймо зловимо сітками
Левицю з левенятами!» - і враз
Схопив маля залізними руками,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'І, здійснюючи владарки наказ,
Леарха взяв розчерепив об стіну;
Втопилась мати з другим воднораз.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Коли фортуна кинула в руїну
Троян, щоб не лишилось і знаку,
І царство й цар знайшли свою кончину.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Гекуба впала у журбу тяжку,
Коли уздріла вбиту Поліксену
І сина Полідора на піску.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Залишив розум матір полонену,
Й завалувала псицею вона,
Свою судьбу жаліючи шалену.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Проте, ні Фів, ні Трої лють жахна
Не людям лиш, а й звірам, що на волі,
Ніколи не була така страшна,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Як лють, що виявили тіні голі,
Які, кусавши, бігли навпростець,
Мов свині, коли хлів повалять долі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Одна Капоккйо уп''ялась в хребець
Зубами і під стогони великі
У дальній потягла його кінець.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'І аретинець: «Той це Джанні Скіккі, -
Промовив тремтячи, - що нас усіх
Лякають у ньому ці скоки дикі».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = '«О, - мовив я, - поки зубів своїх
Він не встромив у тебе, то повинна
Піти в нас мова про шаленця гріх».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'І він мені: «Душа це старовинна
Тієї Мірри, що її стряса
До батька досі ще любов злочинна.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Щоб согрішити з ним, оця краса
Себе так підробила в скромній шаті,
Як той, хто там далеко десь куса».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'А той під Бодо підробивсь Донаті,
Кохавшись в пані табунів самій,
В його ж і заповіт писав кімнаті.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Коли скажених двоє цих у тьмі
Забігли десь, зустрічні та попутні
До себе привернули погляд мій.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Одного бачив: мав би форму лютні,
Коли б відрізать все від паху вниз,
Де почались роздвоєння відчутні.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'З водянки, від якої він не ліз,
Не те що не ходив, живіт роздуто
Ще вище лиць, набряклих геть від сліз.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Так рот йому роздерла спрага люта,
Що ця губа, здавалось, вверх летить,
А та лягла на підборіддя круто.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = '«О ви, що всюди можете ходить,
І тут, як по землі, йдете так само, -
Промовив нам він, - згляньтесь, поглядіть'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Як мучиться тут майстер ваш Адамо!
Був на землі бенкет суцільний, пир,
А тут діймає спрага - дика прямо!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Струмки, які від Казентінських гір
Біжать зеленими лугами в Арно
Й каналом розрізають вогкий шир,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Ввижаються весь час мені - й не марно,
Бо сушить їхній блиск ще більш мене,
Хоч виглядаю я і так почварно.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Суворий суд, що з кривди не схитне,
Для мене визначив щабель карання,
І часто дух мій візьме та й зітхне.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Я там, в Ромені, брав на підробляння
Монети із Хрестителем ясні,
І тілу мить в огні була остання.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Якби побачив душі я сумні
Тих Гвідо, Алессандро та їх брата, -
Й фонтана Бранди не шкода мені!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Тут одного десь тінь блукає, клята,
Як вірить тим скаженим бігунам, -
Та що я вдію, бо нога - як втята!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Якби то легкість повернуть ногам,
Щоб крок ступить в сто літ я був би в силі,
Уже давно я мандрував би там,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Шукаючи його в огидній гнилі,
Хай обводу всього, навкруг бери,
Миль з одинадцять, впоперек - з півмилі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Це ж через них попав я до діри -
Примушували карбувать флорини,
Що мали домішок каратів з три».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'І я: «А хто ці двоє? В чім їх вини?
Як взимку змочена рука, димлять,
Праворуч там, людина до людини».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = '«Такими їх застав, коли з проклять, -
Сказав він, - прірва ця мене вхопила.
Ніколи брехень їм вже не казать.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'От ця шахрайка Йосифа губила,
А грек, шахрай Сінон згубив троян;
Пропасниця ж смердюча все убила».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'І той вже вскочив у злоби туман
І в гніві, з маху, скільки стало сили,
У пузо бахнув, як у барабан.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'А майстер той Адамо, роздобрілий,
Його в одвіт у пику затопив,
Бо мав кулак не надто обважнілий,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Приказуючи: «Хоч не з ряду бив,
Бо рухатись мені не дуже зручно,
А все ж удар не надто ослабів».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'А той відмовив: «Трапивши невлучно
У пломінь, ти не квапив ніг прудких,
Коли монету карбував поштучно».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Товстун же: «Правда йде зі слів твоїх,
А чи слова ти правди говорив ці,
Коли за правду мав троянець їх?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = '«Брехав я в слові, ну, а ти в карбівці, -
Сказав Сінон, - тож ти життя й знання
Віддав, щоб жить на чортовій верхівці».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = '«Клятвопорушнику, згадай коня, -
Відмовив черевань, - і тим карайся,
Світ пам''ята тебе до цього дня».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = '«А ти від спраги лютої старайся, -
Промовив грек, - налить живіт бурди
І черевом, як плотом, прикривайся!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Тоді-монетник: «В тебе, як завжди,
Мерзоти повен рот, на гидь багатий,
Бо спрагу чую й дмуся од води,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Ти ж весь в жару, горить язик проклятий,
І дзеркало, в яке дививсь Нарцис,
Ти б без запрошення почав лизати».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Що інтерес до спору в мене ріс,
Учитель мовив: «Що тобі в цім диві?
Ще трохи - й я цього б не переніс».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Коли сказав мені він так у гніві,
Я озирнувсь, і стид мене пойняв;
Ще й досі у душі він соромливій.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Мов той, хто лихом снив, як сон змагав,
І, щоб те снилось лиш, він мріяв спавши,
Бо переплутував з уявним яв, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Таке ж і я чинив, благання славши
Від серця, щбб мені пробачив він,
І, що я прощений уже, не знавши.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = '«І менший сором більшу із провин, -
Сказав мій вождь, - спокутує звичайно,
Й тобі журитися нема причин.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'І пам''ятай, що стану я негайно
З тобою, в разі доля допуска,
Подібні свари слухать непотайно.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 49;

UPDATE terzinas SET text_uk = 'Воліть їх слухать - воля то низька».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 50;

UPDATE cantos SET title_uk = 'ПІСНЯ ТРИДЦЯТЬ ПЕРША'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 31
    AND p.name = 'Inferno';

UPDATE terzinas SET text_uk = 'Язик той, що завдав мені страждання,
Від чого сором в мене ріс і ріс,
Одразу ж вгамував мої вагання.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Так я чував, - був у Ахілла спис
Від його батька, що у час той самий
І рани завдавав, і ліки ніс.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Залишили ми ті злощасні ями,
Обходячи по краю без доріг,
І не обмінювалися словами.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Похмурий день на відпочинок ліг,
Я бачив кепсько, мов крізь сутінь ночі.
Раптово я почув - звучав десь ріг;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Він заглушив би грім, що з хмар гуркоче
Між блискавок та дощових гірлянд, -
І спрямував туди свої я очі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Коли під натиском невірних банд
Великий Карл втрачав братів по зброї,
Так моторошно не сурмив Орланд.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Звернувши зір в бік музики різкої
Й побачивши немов громаддя веж,
Я: «Вождю, тінь фортеці то якої?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'І він мені: «Уяву не бентеж,
То далина тебе ввела в оману,
Ти ж хочеш бачити і в пітьмі теж.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'От станем ближче, вийде все з туману,
І сумніви розвіються умить.
Отож тебе я й підганяти стану. -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Почав, за руки взявши, говорить: -
Щоб знову в прикрий не упав обман ти
Й даремно не лякався тих страхіть,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Тож знай, що то не вежі, а гіганти
До пупа видимі навкруг жерла.
Ми підійшли уже. Тепер поглянь ти».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Як, поки хмарна розтає імла,
Наш зір у темряві ще неглибокій
Те розрізня, де досі муть була,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Так ми пішли по стежці неширокій,
Спускаючись у ще хмурніший край,
І меншав мій обман, і ріс неспокій,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Бо, мов у вежах вся стіна стара
В Монтереджоне, як ведеш очима, -
Криничний так обстали грізно край'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Ті вежі, половина тіла зрима
Жахних гігантів, що донині їм
Грозить Юпітер, в час, коли він грима.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Угадував я під лицем страшним
І плечі, й груди, й живота частину,
І руки понад краєм кам''яним.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Природа, створюючи без упину
Істоти різні, права все ж, свята,
Катів не давши Марсові в дружину.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'А, творячи слона або кита,
Не кається, вдоволена собою,
І в цьому видна мудра простота.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Коли ж до сили разом із злобою
Буває додається й ум тямкий, -
Людина позбавляється спокою.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Був грубий в нього й довгий вид такий,
Як шишка близ Петра святого в Римі;
Належних розмірів були й кістки.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'До лоба в половині тіла зримій
Один на одному б не дотяглись
Три фризи, велетні ці незборимі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Від стегон тридцять п''ядей би вляглись
До місця - так прикидував кришталь мій, -
Де щільно застібки в плащі зійшлись.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = '«Рафель маї амек ізабі альмі!» -
Оглушно заревів страшенний рот,
Не назвичаєний в ніжнішій псалмі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'І вождь до нього: «Душе нечеснот,
За ріг берися, ним ти краще скажеш,
Як мучить злість чи інша із гризот.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Обмацай шию і на ній пов''яжеш
Дебелий ремінь, душе туману,
Тоді і ріг на ньому ти підважиш. -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'До мене ж: - Це Немврод. Свою вину
Він зна. Через діла його нікчемні
Ми маєм в світі мову не одну.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Та годі з нас: розмови з ним даремні,
Бо як йому нікого не збагнуть,
Так і його слова для інших темні».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Ми подались ліворуч в дальшу путь
Й побачили за постріл арбалета
Гіганта, що його долала лють.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Хто дужчий поборов цього атлета,
Не знаю, - знов, щоб не чинив наруг,
Рука та - на живіт, ця - вздовж скелета,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'І велетенське тіло все навкруг,
У нього відбираючи свободу,
Аж п''ять разів обвив тяжкий ланцюг.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = '«Гордій вважав, що ствердить зверхність роду,
Як на Юпітера він зазіхне, -
Сказав мій вождь, - от має й нагороду.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Це Ефіальт - він витворяв страшне,
Коли богам гігант був страховитий,
А нині й пальцем не поворухне!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'І я йому: «Хотів би я уздріти,
Який він, той незмірний Бріарей,
Якби дозволив це мені зробити».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Він відповів: «Тут близько є Антей,
Він вільно розмовляє, без кайданів,
І послугу він зробить для гостей.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'А той, кого ти хочеш бачить, станув
Десь далі, скутий теж, щоб не крутивсь,
І гарний був, та гнів його споганив».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Ніколи ще підмурок не трусивсь
І не здригалась вежа, страхом скута,
Як в злобі Ефіальт заворушивсь.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Злякавсь я, що вже смерть підходить люта, -
Бо страх, насправді, то смертельна річ, -
Якби міцні я не помітив пута.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'І далі стежкою пішли ми встріч :
Антею - певно, той був на льодині;
Він ліктів з п''ять од стегон мав до пліч.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = '«О ти, хто в ощасливленій долині,
Де слави Сціпіон зажив навік
Вслід втеклій Ганнібаловій дружині,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Кричати з тисячами левів звик
І змушуєш у те пойняти віру:
Коли б ти на війну проти владик'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Повів братів, то перемогу щиру
Сини землі дістали б, - нас знеси
В глибини, де Коціт замерз надміру.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'А Тітія й Тіфона не проси;
Супутний мій дарунок знаменитий
Несе собі, нагнись, та не вкуси,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Твою він славу хоче відновити,
Бо ще живий і ласкою небес
Щасливо на землі гадає жити», -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Сказав мій вчитель; мов слухняний пес
Той взяв його в простягнуті долоні,
Що міцність їх спізнав сам Геркулес.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Віргілій, вчувши зручність в їх полоні,
Сказав мені: «Підходь, я обійму».
І з ним в однім ми опинились лоні.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Як Гарізенда видасться тому,
Хто йде внизу, нахиленою грізно
Й от-от впаде на голову йому, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Мені здававсь Антей таким приблизно, -
І пожалів: не той я шлях обрав,
А рятуватися було запізно.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'Та він поставив нас на мерзлий став, -
Люцифера з Іудою пекельна
Терзала холоднеча там, - і встав,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'І випроставсь, як щогла корабельна.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 49;

UPDATE cantos SET title_uk = 'ПІСНЯ ТРИДЦЯТЬ ДРУГА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 32
    AND p.name = 'Inferno';

UPDATE terzinas SET text_uk = 'Якби мій вірш був жорсткий та суворий,
Щоб міг відповідать безодні тій,
Де починаються всі скелі й гори,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Я б вилив сік своїх думок і мрій
Якнайповніше, а без цього статку
Підношу полохливо голос свій,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Бо значно важча справа - без остатку
Дна світового дати малюнки,
Аніж дитячий белькіт: «мамко», «татку».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Поможуть віршу хай святі жінки,
Як Амфіону будувати Фіви,
Щоб він уславив бачене, дзвінкий!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'О створений на лихо роде хтивий,
Думки про тебе в нас такі сумні!
Вже вівці кращі, аніж ти, бунтливий!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Коли ми опинилися на дні
В гіганта під ногами, я негайно
Став оглядати мури обвідні.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Зачулось враз: «Уважніше ступай-но,
Не йди по головах братам в біді,
Бо й так вони страждають надзвичайно!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Оглянувшись, побачив я тоді,
Що під ногами озеро, дзеркалам
Подібне, але зовсім не воді.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Узимку під таким товстим вкривалом
Не спить Дунай поміж австрійських рік,
Чи Танаїс ген за холодним валом;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Коли б то величезний Тамберник
На озеро це впав, чи П''єтрапана, -
Крізь лід би жоден камінь не проник.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Як жаба висуває, мов із жбана,
З води свій писок кумкать в пору спек,
Коли селянка снить жнивами зрана,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Так мертві тіні в лід, немов у глек,
До ліній стиду на лиці ховались,
Зубами повторявши стук лелек,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Обличчями найнижче всі схилялись;
Про холод - ротом, а в чуттях тяжких -
Про болі серця - зором признавались.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Спустивши очі, біля ніг своїх
Побачив я дві тіні зледенілі,
Що й кучми переплутались у них.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = '«Скажіть ви, стиснуті в єдиній брилі, -
Сказав я, - хто ви?» Не звелись самі,
Лиш вбік зирнули, скільки чулись в силі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'І тут їх очі налились слізьми;
І сльози бралися відразу льодом
Від холоднечі вічної зими.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Вони були подібні двом колодам,
Які скобами збиті ще міцніш,
Аніж цапи б сплелись в борні над бродом.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'А інший, прихиливши вид щільніш,
Який з морозу без ушей зостався,
Сказав: «Чом в нас, як в дзеркало, глядиш?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Щоб ти докладно про обох дізнався, -
Діл, де біжить Бізента, в їх роду
І від Альберто, батька їх, дістався.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Вони й одноутробні, на біду,
Нікого ти не знайдеш у Каїні,
Хто більше б заслужив тремтіть в льоду:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Ні той, кому пробив - йому і тіні -
Огруддя списом доблесний Артур,
Ані Фокачча, ані той в глибині,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Хто заступа нам стежку до тортур
І називався Сассоль Маскероні, -
Його в Тоскані знає кожен мур.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'І, щоб не бути в розпитів полоні,
Дізнайсь, що Камічоп де Пацці я
Й мені Карлін потрібен в обороні».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Я тисячі тих бачив, хто з лиця
Був синій, як собака, й зріть не можу
Відтоді крижаного озерця.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Чим більше наближалися ми к ложу,
Куди стремить усяка річ важка,
Тим я від страху був у більшім дрожу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Чи випадковість, чи судьба така, -
Йдучи повз діл, весь од голів строкатий,
Торкнувся враз я одного виска.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'І дух з плачем гукнув: «Чого штовхати?
Коли ти не з''явився відомстить
За Монтаперті, то чого топтати?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'І я: «Мій вчителю, дозволь просить,
Постій, мою послухай просьбу щиру,
Ми потім надолужим кожну мить».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Мій вождь погодивсь, я ж сказав блюзніру,
Який брехав гидкіш за всіх собак:
«Хто ти, що поспіль всіх ганьбиш над міру?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = '«А сам ти хто, - промовив він, - що так
На лиця ти ідеш по Антенорі, ,
Немов живий ступає на стрімчак?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = '«А я живий і є, не будеш в горі,
Мабуть, коли, - одвіт мій був такий, -
Уславлю я тебе в земнім просторі».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'І він: «Якраз я хочу навпаки, -
Йди геть звідсіль; кінчай цю мову кляту;
Не місце тут розводить балачки».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Схопив я за потилицю кошлату
Й сказав: «Мені своє ім''я назвеш,
Бо обскубу я голову патлату».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'А той: «За те, що ти мене скубеш,
Я не скажу, хто я, хай і каліччя,
Хай тисячу разів мене клянеш».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Я намотав собі на передпліччя
І висмикнув волосся жмут товстий,
А він із гавкотом ховав обличчя.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Коли гукнув хтось: «Бокко, з чого ти?
Хіба не досить щелепами гримать,
А ти ще й гавкаєш? Під три чорти!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Я мовив: «Можеш язика притримать,
Запроданцю! Вернусь - і все повім,
І від ганьби ім''я тобі не вимить!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = '«Іди, - він мовив, - всім брехать живим,
Не обминай лиш згадкою живою
Цього із язиком його швидким.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Він плаче за французькою грошвою,
«Мені там, - скажеш, - стрівся Двера злий,
Де всі корою вкриті льодовою».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Про інших зайде мова ще коли, -
Он Джанні Сольданьєр, он Беккерія,
Якому рідні комір розсікли.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Тут всі - від Ганелона-лиходія
До того, хто болонцям ключ одніс,
Як пойняла Фаєнцу сонна мрія».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Пішли ми, й враз вождю я руку стис,
Уздріли двох, вморожених в крижину, -
З них верхній капшуком на нижнім звис'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'І, як вмирущий з голоду в хлібину,
Несамовито вгризся в місце, де
Із черепа заходить мозок в спину.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'І не лютіш, помщаючись, Тідей
Пив Меналіппа кров зі скронь гарячу,
Ніж цей впивавсь у вмістище ідей.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = '«О ти, що виявляєш лють звірячу,
Гризучи голову в страшній грозьбі,
Скажи мені, - сказав я, - хай побачу,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Чи справедливий ти в своїй злобі.
Хто ти, скажи, й якій ти мстиш мерзоті, -
І в світі дещо я зроблю тобі,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Поки не всохне мій язик у роті».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 47;

UPDATE cantos SET title_uk = 'ПІСНЯ ТРИДЦЯТЬ ТРЕТЯ'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 33
    AND p.name = 'Inferno';

UPDATE terzinas SET text_uk = 'Піднявши рота від страшної страви
Й волоссям жертви з губ утерши кров,
Цей грішник припинив бенкет кривавий'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'І так почав: «Мене ти хочеш знов
Вернуть у розпач, що пече незгасно
Від думки лиш самої - не розмов.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Коли ж на зрадника, якого сласно
Гризу, впаде це сім''я відкриттям, -
Мовлять я й плакать ладен одночасно.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Не знаю, хто ти є і як відтам
Попав сюди, а що твоє коліно
З Флоренції - з вимови чую сам.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Тож знай, що я був графом Уголіно,
Архієпископом Рудж''єрі - цей;
Ворожість нас тут в''яже воєдино.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Як він мене брехливістю рацей,
Яким так вірив я, призвів до смерті, -
Усі наслухалися цих вістей.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Але ніхто в щоденній коловерті
Не знав, яка була та смерть страшна.
Про ницість слухай-но слова одверті.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'В вузеньку шпарочку, замість вікна,
У вежі, що Голодною зоветься
Та багатьох ув''язнює вона,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Я бачив, місяць безліч раз дереться,
Коли злий сон душі порушив стан, -
Повівши, що зазнать нам доведеться.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Приснився цей мені владар і пан,
Він вовка гнав з вовчатами на гору,
Що Лукку затуляє від пізан.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Спустили і хортів, порвавши швору, -
Усі Гваланді, та й Сісмонді всі
Й Ланфранкі мчали в цю жахливу пору,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Та й знищили в безжальності усій
З малими й батька, що звивався диба;
В крові ходили, наче по росі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Я підхопивсь, і стисла горя глиба,
Бо плакали вві сні мої малі,
Також ув''язнені, й просили хліба.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Жорстокий ти, коли свої жалі
Словами кількома лише обмежив,
Не плакав, - та чи й плачеш взагалі?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Попрокидалися, і кожен стежив,
Коли тюремник принесе обід,
Але той сон усім серця бентежив.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Аж раптом чую, забивають вхід
Страшної вежі; мовчки подивився
Я на синів і скрив розпуки слід.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Відчув, що в камінь я перетворився,
Вони ж стогнали; Ансельмуччо мій
Спитав: «Чого ти, батьку, засмутився?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Та я не плакав. У журбі німій
Просидів день і ніч, поки прекрасне
Зійшло світило у красі своїй.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Блідий світанок, що сяйне і згасне,
В сумну пробравсь темницю, і я вздрів
В них чотирьох своє обличчя власне, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Собі я руки в розпачі вкусив.
Гадавши, що я голод за всіх важче
Терплю, вони, підвівшись із кутів,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Сказали: «З''їж нас, батьку. Це найкраще,
Коли ти відбереш життя у нас.
Нехай воно іде на щось путяще».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Щоб не смутить їх, мій відчай пригас.
Ще день і ще без їжі, без вологи.
Чом не розверзлась нам земля в той час!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'А на четвертий день мій Гаддо ноги
Мої до себе пригорнув щільніш
І простогнав: «Дай, батьку, допомоги!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'І він помер, і, як мене ти зриш,
Я зрів їх смерть, - а був же кожний мол од!
Смерть в п''ятий, шостий день - і не пізніш.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Осліплий, мацав я камінний холод,
Звав кожного, - і кожний був мертвяк,
Аж поки горе переміг злий голод».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Замовкнувши, накинувсь неборак
На вбогий череп знову й ну глодати
Зубами гострими, як у собак.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'О Пізо, ти ганьбиш весь край багатий,
Де наше «si» так солодко бринить!
Сусіди не спішать тебе карати,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'То хай Капрайя і Горгона вмить,
Немов дві греблі, встануть в гирлі Арно,
Щоб весь твій люд у хвилях потопить!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Хоча граф Уголіно вмер немарне,
Бо, зрадивши тебе, він замки здав,
Але дітей морити - це ж почварно!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Покайсь, мала фіванко, і прослав
Малечу - Угуччоне та Брігату
Та ще тих двох, що в пісні я назвав.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Ми вже в долину сходили покату,
На грішних іншого уже зразка
І навзнак перекинутих багату.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Сам плач їх плакати не допуска,
І біль, що набігає їм на очі,
Назад верта, і мука знов тяжка,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Як витекти сльоза з очей захоче,
Ледь на студене вийде прикриття,
То забралом криштальним заклубоче.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Хоч в холоді згубив я всі чуття
І вже ніяких форм, ні барв, ні літер
Не міг би, мабуть, розрізнити я,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Мені здалось, що почуваю вітер,
Тому я: «Вчителю, це б звідки йшло?
Бо тут же пари й слід хтось ніби витер».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'І він: «Пожди, хоч би там що було,
Вже скоро твої очі з прямотою
З''ясують цього вітру джерело».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'А хтось із скутих холодом і тьмою
Гукнув: «Хіба ви, душі, злі такі,
Що вас послали до низького звою!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Ви тягарі зніміть з очей важкі,
І погляд знов нехай сльозою присне,
Поки не вернуть холоди бридкі».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'І мовив я: «Тобі зроблю корисне,
Скажи ж, хто ти, і хай тягар вериг
Із криги, як збрешу, мене притисне».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'І він сказав: «Я брат той Альберіг,
Що злі плоди в саду ростив, упертий,
Й ужинок має фініків - не фіг».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = '«О! - з подивом гукнув я. - То вже вмер ти?»
І він: «Та не обходить це мене,
Чи дано тілу час життя чи смерті!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Одне лиш діло тут нам і ясне,
Що душі падають до Толомеї
Раніш, як нитку Атропос утне.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Щоб ти охочіш з ямини моєї
Знімав цю непрозору пелену,
Знай, що душа як зрадить, то до неї'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Як і зі мною стало, в мить одну
У тіло входить біс в лихій погрозі,
Душа ж викочується в глибину,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'В криницю, не спинившись на порозі.
Тут не вважають мертвим і того,
Можливо, хто заклякнув на морозі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Коли з землі ти, мусиш знать його:
Це Бранка д''Ор''я; хто із нас не знає
Цього сусіду з давнини свого!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = '«Боюсь, - сказав я, - правди тут немає:
Цей Бранка д''Ор''я зовсім ще не вмер.
Він їсть, і п''є, і спить, і вбрання має».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'І він: «До Ляхолапових озер
Туди, нагору, ще тоді не вийшов
Мікеле Дзанка, де сидить тепер.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'З близьким я родичем місця полишив,
Де віддавались радощам стільком,
І вже надіями себе не тішив.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 49;

UPDATE terzinas SET text_uk = 'Тепер мерщій звільняй мій зір цілком!»
Йому ж орбіти я не зчистив очні:
З ним найшляхетніш - стати селюком.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 50;

UPDATE terzinas SET text_uk = 'О генуезці, розуми порочні,
Чого ще на собі вас держить світ?
Чому не пожирає вас, збиточні?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 51;

UPDATE terzinas SET text_uk = 'Я з тим, хто сто пройшов решіт і сит
В Романьї, бачив одного, в якого
Душа давно вморожена в Коціт,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 52;

UPDATE terzinas SET text_uk = 'А тіло на землі вдає живого.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 53;

UPDATE cantos SET title_uk = 'ПІСНЯ ТРИДЦЯТЬ ЧЕТВЕРТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 34
    AND p.name = 'Inferno';

UPDATE terzinas SET text_uk = '«Трядут хоругви к нам владики Ada»
Все ближче; подивись лишень на знак, -
Сказав учитель, - де його громада».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'І як, коли б у хмарах день побляк
Чи відійшов би з нашої півкулі,
Ледь бачимо здаля верткий вітряк, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Побачив я будову в свисті й гулі
Й сховавсь од вітру за вождя в імлі,
Немов у найнадійнішій притулі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Люд грішний в неймовірному числі -
Аж лячно в римах це віддать словами, -
В льоду стирчав соломинками в склі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Хто лежачи, хто випроставшись прямо,
А хто сторчком, ногами догори,
Або упершись в маківку п''ятами.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Коли без слів прийшли ми до гори,
Учитель, показать мені схотівши
Того, хто гарним був у час старий,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Ступив набік, мене вперед пустивши,
«Ось Діте, - мовив він, - і ось той рів,
Де ти подужчаєш, все оглядівши».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Як раптом захолов я й остовпів,
Читачу, не питай: я весь стенувся,
Розповісти - не вистачило б слів.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Не чувсь я мертвим, та й живим не чувся.
Збагнеш ти й сам, що я переживав,
Коли й життя, і смерті враз позбувся.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Володар найсумнішої з держав
Був до середини грудей в крижині.
Гігантові я б скорше дорівняв,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Аніж гігант руці його єдиній;
Тепер вже можеш сам ти справу здать,
Який він весь, умерзлий у льодині.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Якщо він на Творцеву благодать
Звести смів погляд, повний люті й крові.
То скільки зла від нього треба ждать!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Я з подиву позбувся навіть м©ви,
Побачивши на ньому три лиця!
Той вид, що спереду, - увесь багровий,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Два інші йшли від шийного кільця
З обох боків і, пересікши міру,
Сягали десь під кучмою кінця.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'З них правий вид мав барву жовто-сіру.
Коли ж пройти до водоспадів Ніл,
Побачиш лівого обличчя шкіру.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Над кожним височіла пара крил,
Таких же самих розмірів потрібних.
Я в морі не здибав таких вітрил'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Безперих, на кажанячі подібних.
Махаючи весь час на цілий світ,
Вітрів він троє створював осібних,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Що обвівали без кінця Коціт.
І річка аж до дна вся прохолола:
Сльозами сходив він на шість ланит,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'А кожна з пащ, мов терниця, молола
По грішнику, - щоразу об коли
Душа стражденна тіпалася гола.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Передній ще жахливіші були
Такі тертя під скреготи зубовні,
Що дерли шкіри кусень чималий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = '«Той, угорі, що терпить кару вповні, -
Сказав мій вождь, - то Юда Іскарйот,
В зубах он голова, а решта - зовні.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'А в тих обличчя видно без турбот:
У чорній пащі ти он бачиш Брута, -
Він корчиться увесь, та зціпив рот.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'А в Кассія статура краще скута.
Та сутеніє вже; в дорогу час.
Вся хлань тобою бачена і чута».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Звелів тримать за шию, як за пас,
А сам, обравши місце й мить належні,
Щоб груди помах крил розкрив для нас,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Вчепився в шерсть почварі, обережні
Зробивши рухи, і притик в притик
Ввійшов крізь шпару у льоди сумежні.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Коли ж туди продерлись ми, де бік
Поволі обертається на ногу,
Він головою аж до п''ят приник'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'І, наче відчуваючи тривогу,
Поповз по шерсті знову серед тьми,
Знайшовши, мабуть, правильну дорогу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = '«До мене ближче припади грудьми, -
Дихнув мій вождь, як той, що утомився, -
Лиш так врятуємось із прірви ми».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'В розколину камінну простромився,
На край мені він сісти допоміг,
Туди ж таки і сам перемістився.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Звів очі вгору я, де зріти міг
Люцифера таким, яким зрів досі, -
Але стриміло знизу двоє ніг.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Усі думки мої різноголосі
Хай той збагне, кому і невтямки,
Яку пройшов я зараз точку осі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = '«Зведись, - сказав учитель, - шлях тяжкий
Поперед нами й довга ще дорога,
А сонце вийшло на свої стежки».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Вкруг нас не сяла пишнота чертога,
Це скорше був якийсь природний льох,
Де струмувала напівтьма волога.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = '«Перш як залишим цю безодню вдвох,
Учителю, - сказав я, - на прощання
Розвій мій сумнів у словах кількох:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Де лід? А він? Чом терпить покарання
Він головою сторч? А сонце де,
Що вечір вмить змінився на світання?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'І він: «Ти уявляв, що вождь веде
В те місце, звідки вдався до походу
На гробака, який у глиб іде?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Ти там і був, поки спускавсь до споду,
Але там оберт я зробив крутий
Куди всі тягарі стримлять ізроду.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Півкуля ж, де віднині будеш ти,
Зворотна тій, що знала небезпеки,
Коли на ній загинув той святий,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Що був од всякого гріха далекий.
А місце, де стопи твої сп''ялись
На це кружало, - спідній бік Джудекки.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Світає тут, - там зорі зайнялись.
З чиєї ж вовни нам була драбина,
Той все стирчить і досі, як колись.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Його ввібрала ця от половина,
Й земля, яка навколо тут цвіла,
Злякавшись, що її ковтне пучина,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'До нашої півкулі утекла,
Підскочивши горою на тій рисці,
Де він ввіткнувсь в порожняву жерла.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Є недалеко Вельзевула місце
Ледь чутне та незриме й потайне,
І там, внизу, дзюркоче, як в криничці,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Струмочок, продовбавши кам''яне
Русло, похоже на тропу зміїну,
І це для нас є місце висхідне».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Мій вождь і я зійшли на цю стежину,
Щоб вийти з того Пекла до життя,
І дуже довго без перепочину'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Угору йшли, він - першим, другим - я,
Аж поки не уздрів я в шпару скелі
Усю красу небесного буття.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Ми вийшли й зір звели на зорні стелі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 34
    AND p.name = 'Inferno'
    AND terzinas.terzina_number = 47;


-- ── Purgatorio ─────────────────────────────────────

UPDATE cantos SET title_uk = 'ПІСНЯ ПЕРША Вступ. - Чотири зірки. - Катон'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 1
    AND p.name = 'Purgatorio';

UPDATE terzinas SET text_uk = 'Для вод спокійних паруси віднині
Суденце мого духа наставля,
Плавбу лишивши по страшній пучині.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Співатиму про друге царство я, -
Там душі очищаються, небесне
Блаженство прозираючи здаля.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Нехай же знов поезія воскресне,
Бо ваш я, чисті музи, на віки!
Хай створить Калліопа тло чудесне,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Вторуючи тим голосом, який
Відняв колись в Сорок злощасних віру,
Що злочин їм відпуститься важкий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Солодкий колір східного сапфіру,
Зливаючись під першим небом цим
З прозорістю надхмарного ефіру,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Всю радість повернув очам моїм,
Як попрощавсь я з берегом конання,
Для серця і очей моїх страшним.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Ясна планета, що несе кохання,
Всміхатися примушувала схід,
Сховавши Риб у променях світання.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Направо глянув я, звернувши вид
На інший полюс, на тих зір чотири,
З яких втішався наших предків рід.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Вогням тим раде все в небеснім ширі,
Ти ж, їх не бачачи, ллєш ріки сліз,
О вдово Півноче, гіркі та щирі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Коли ж я очі перевів униз,
На інший знову полюс, на місцину,
Де з неба зникнув пломенистий Віз, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Побачив поруч я стару людину,
Що гідна шани вищої була,
Ніж та, яка сповняє душу сину.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Сивінь блищала в кучерях чола
І в бороді, яка по грудях, дбало
На сторони роздвоєна, лягла.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Так сяйво чотирьох світил спадало
Згори на нього, що здалось мені,
Неначе сонце перед ним палало.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = '«Хто ви, що тут, по хмурій струмині,
Тікаєте із вічної темниці? -
Спитав він, брови суплячи грізні. -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Хто вас провів? Хто пломенем зірниці
Ту нескінченну чорну ніч роздер,
Що тьмарить дно пекельної в''язниці?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Невже закон поламано тепер?
Чи небо передумало й пустило
Вас, непрощенні, до моїх печер?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Вожай на мене глянув, зрозуміло
Словами, рухом, поглядом вказав
Спустити зір, схилитися несміло'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'І вимовив: «Не я того бажав, -
Зійшла жона небесна доручити,
Щоб я його в дорозі проводжав.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Коли ж ти хочеш в пам''яті лишити
Подробиці, то вимов слово лиш, -
І радий я в цьому тобі служити.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Свій вечір ще побачить він пізніш,
Та був ладен від безуму страшного
Побачити його якнайскоріш.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Я, присланий, як вже сказав, до нього,
Щоб вивести із нетрів злих облуд,
Обрав єдину, хоч тяжку, дорогу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Я показав йому весь грішний люд,
А зараз покажу покутних духів,
Де нагляд за очищенням - твій труд.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Та більше не згадаєм наших рухів;
Небесна сила помагала нам,
Щоб він тебе побачив і послухав.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Тож привітай його із прибуттям -
Йому свободи дано теж бажати
Й заради неї жертвувать життям.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Ти смерть за зло також не міг вважати,
Бо в Утіці сам вік свій вкоротив,
А в судний день одягнеш пишні шати.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Законів нам ніхто ж бо не змінив:
Він ще живий, мене ж Мінос не знає,
Бо звідти я, де чисті очі стрів'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Твоєї Марції, яку єднає
З тобою мрія, душе пресвятий.
її любов за нас хай промовляє!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Твоїх сім царств дозволь же нам пройти,
І я подяку їй складу охоче,
Якщо згадать себе дозволиш ти».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = '«Так Марція мої втішала очі, -
Він відказав, - що, бувши на землі,
Робив я все, чого вона захоче.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Тепер течуть між нами хвилі злі,
Вона пішла навік з душі моєї,
Коли закон знайшов мене в імлі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Та вас веде із милості своєї
Жона небесна - й слова не кажи,
Бо досить лиш послатися на неї.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Тож до призначеної йдіть межі,
Та перше змий йому з обличчя плями
І комишем його підпережи.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Недобре-бо із млистими очами
Являтись в рай, у місце пресвяте,
До першого поміж воротарями.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Он острівець; в болото вбоге те
Невтомні води б''ють у піні білій;
У мулі тільки сам комиш росте.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Ніякий стовбур прорости не в силі
На тих низьких багнистих берегах,
Бо неспроможний підкорятись хвилі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Вертайтеся не по своїх слідах, -
Он перший промінь сонця появився.
Він вкаже вам на гору вірний шлях».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'І з тим він зник. Я зараз же підвівся,
Не кажучи ні слова, підійшов
До вожая й на нього подивився.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'А він почав: «Ходімо без розмов
Назад, мій сину. Бачиш на світанні,
Як далі вниз пішла рівнина знов».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Зірниця гнала сутінки туманні,
І в далині, куди вони пливли,
Замерехтіло море в трепетанні.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Ми навпростець долиною пішли,
Мов ті, що манівцями десь блукали,
Аж поки врешті стежки не знайшли.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Коли ж ми по рівнині мандрували,
Де промінь йа росу уже сяйнув,
А в затінку ще краплі не зникали, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Учитель мудрий мій траву торкнув,
Зволожив руки у небесні соки,
А я, коли його думки збагнув,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Заплакані йому підставив щоки,
Й живу він барву поновив на них,
Яку зігнав у пеклі страх жорстокий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Ми вийшли до пустельних вод смутних,
Що не носили на собі ні разу
Нікого, хто б вернувся до живих.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Підперезав мене він там з наказу.
О чудо! Він смикнув одну з рослин, -
І виросла нова така ж одразу'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Там само, звідки першу вирвав він.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 46;

UPDATE cantos SET title_uk = 'ПІСНЯ ДРУГА Передчистилище. - Ангел-стерничий. - Каселла'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 2
    AND p.name = 'Purgatorio';

UPDATE terzinas SET text_uk = 'Торкнуло сонце обрій знизу в місці,
Меридіан якого перетне
Сіонську гору у найвищій рисці.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'І ніч, яка свій віз весь час жене,
Спливла із Гангу, терези тримавши,
Що кине їх, як меншать день почне.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'І бачив я: мінилось все, як завше,
Аврора стала старіти за мить,
На жовтизну рум''янець помінявши.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'А ми не знали, на яку ступить,
Мов той, залюблений у мандруванні,
Хто в думці йде, а тілом ще стоїть.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Та раптом, як у досвітки туманні
Червоний Марс на схід верстає шлях,
Так в мене перед зором на світанні -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Хай би ще раз це блиснуло в очах! -
Таке з''явилось бистре сяйво біле,
Що наздогнать його не годен птах.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'І поки я звертав лице похиле
До вчителя, небачене зросло,
Пояскравішало незрозуміле.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'А там з боків щось біле піднесло,
Не знати що, а з того потім знову
Униз потроху біле щось зійшло.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Учитель додивлявсь, урвавши мову.
Та повело воно крилом ясним,
І він, вгадавши яву загадкову,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Гукнув: «Стань на коліна перед ним!
Твори молитву! Це ж бо ангел Божий, -
Тут місце тільки слугам неземним.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Поглянь, вітрилам і веслу ворожий,
Човна веде на крилах він своїх,
По цій гладіні, на земну несхожій.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Поглянь, у небо простягає їх
І віковічне пір''я в них іскриться,
Не тлінні волоски істот людських».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Чим ближче підпливала сяйна птиця,
Тим яскравіше вид її блищав,
Аж очі не здолали вже дивиться,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Й я опустив їх. Ангел наближав
До берега такий легенький човен,
Котрий по хвилях сліду не лишав.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Було там душ із сотню; сяйва повен,
В човні стояв божественний вожай,
І спів навкруг летів, блажен, стомовен:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = '«В ісходе Ізраїлеве...» - весь край
Псалма святого співами сповнявся;
І закінчили, як велить звичай.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Благословенням хресним попрощався
Стерничий з ними, бо зійшли з човна,
І легко, як приплив, назад помчався.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Уздрівши, що навколо глушина,
Скрізь обдивлялись душі якомога,
Мов той, кому відкрилась новина.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Далеко вгору повела дорога
Ще юний день, і сонячна стріла
З півнеба вже прогнала Козерога,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Коли чоло юрма їх піднесла
Й спиталася: «Чи ви б нам не вказали
Стежини, щоб на гору привела?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Віргілій мовив: «Якщо ви вважали,
Що ми тут знаєм стежку, - то дарма.
Ми, як і ви, сюди примандрували'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Тому й години, мабуть, ще нема.
Та ми дістались стежкою такою,
Що зійдемо на шпиль цей жартома».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Помітивши уважною юрбою
Із подиху мого, що я не мрець,
Поблідли душі з дива й неспокою.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Як тисне люд, коли прудкий гонець,
З оливкою в руці, гука важливі
Новини і для вух, і для сердець, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Круг мене душі юрмились щасливі,
Забувши, що не вмили ще облич
І ще не стали чисті і вродливі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Душа якась побачила увіч
І так мені зраділа, без облуди,
Що я їй мимохіть ступнув навстріч.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'О тіні, можуть вас лиш бачить люди!
Я тричі прагнув обійнять її -
Й щоразу бив себе самого в груди.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Чи з дива риси витягайсь мої,
Але вона всміхнулась, одійшовши,
Коли ж прискорив кроки я свої,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Звеліла стати, поглядом вколовши, -
І я впізнав її та попросив
Порозмовлять зі мною трохи довше.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Відповіла: «Як я тебе любив
Живий, то й тут з тобою радо стрівся, -
Постіймо. Як досяг ти цих країв?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = '«Та, мій Каселла, тут я появився
На час лише, поки дійду мети, -
Я мовив, - ти ж, померши, де барився?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'І він: «Не скривдив лик мене святий
Що нас вивозять звідтіля, де болі,
Хоч відмовлявсь не раз мене везти.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Він справедливій підлягає волі, -
Три місяці бере лиш тих у путь,
Хто хоче в мирі одійти з юдолі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Нарешті біля моря, де течуть
Тібрійські води, в гирла каламутні,
Його прихильність зміг і я відчуть.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'До берега, де ждуть його попутні,
Що шлях їм не лежить на Ахерон,
Керує нині крила він могутні».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'А я: «Коли не відібрав закон
У тебе пам''ять з виконанням вмілим
Любовних заспокійливих канцон, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Прошу, мені мотивом, серцю милим,
Ясного спокою у душу влий,
Вона тремтить, що тут укупі з тілом».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = '«Любов, що думці промовля моїй», -
Він заспівав так ніжно, що я слухав,
І ніжність слух навік скоряла мій.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'У вчителя мого, у мене й духів -
В усіх захоплені були серця,
Закриті для душевних інших рухів.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Ми тихо йшли і слухали співця,
Але старий урвав ходу нескору,
Гукнувши: «Чи таке вам до лиця?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Не гайтесь лаштуватися на гору!
Щоб швидше Бог, безпам''ятні раби,
Проник до вас, зніміть із себе кору!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Немов на зерно й кукіль голуби
Мовчущим табунцем собі злітають
Без звичної пихатої хвальби,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Та розлітаються, все покидають,
Коли б їх настрахать хто-небудь зміг,
Бо важчі їх турботи обсідають, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Отак і душі враз, не зчувши ніг,
На берег кинулись, забувши й співи,
Мов той, хто заблудився без доріг.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'І наш був крок також не менш квапливий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 45;

UPDATE cantos SET title_uk = 'ПІСНЯ ТРЕТЯ'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 3
    AND p.name = 'Purgatorio';

UPDATE terzinas SET text_uk = 'Коли переполох, для душ нежданий,
По всій рівнині розпорошив тих,
Що йшли на шпиль, для розуму жаданий,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Я притуливсь до друга днів моїх -
Без нього що робив би я з судьбою?
І як би вийшов з мандрувань тяжких? -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'І вчув, що він обурений собою,
Святе сумління - як найтонший слух!
Вина й мала стає йому тяжкою.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Коли ж нарешті він притишив рух,
Поважність звичну повернувши крокам,
То мій розгублений спочатку дух'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Згадав мету, що втратив ненароком,
І от я очі звів на дивогляд -
Він в небо муром зводився широким.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Проміння, червоніючи позад,
Переді мною зникло на стежинці,
Як перед найгустішою з завад.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'І, боячись лишитись наодинці,
Я озирнувсь, - аж по землі крутій
Лежала лиш переді мною тінь ця.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Мій захисник сказав: «Кинь, сину мій!
Чого це обдивлятись закортіло?
Чи я не тут? Чи не вожай я твій?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Де нині вечір, мир знайшло там тіло,
Що відкидало тінь мою хоч де
Й не в Бріндізі - в Неаполі спочило,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'І от від мене тінь вже не впаде.
Хай вигляд хмар тебе сильніш вражає:
На промінь промінь тіні не кладе.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'І хоч небесна сила полишає
У тілі біль і студінь навісну,
Та саме як - розкрити не бажає.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Закрито й іншу людям таїну -
Збагнуть її лиш дурня вабить мрія! -
Як три особи містять суть одну.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Тому й лишайся, людський роде, з quia!
Якби ти міг здійснить свої ждання,
То понести не мусила б Марія.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Ти бачив тих, що ждали навмання,
Але натомість, волею Закона,
Засуджені на вічне незнання.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Кажу про Арістотеля, Платона
І багатьох ще». Тиша залягла,
Й чоло поникле вкрила дум запона.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Нарешті стежка до гори звела.
Перемогти ці урвища могучі
Нога найдужча, певне б, не змогла.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'З Турбії стежка в Лерічі по кручі
Здалася б і широка, і пряма
Проти цієї кам''яної кучі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = '«Шукать дороги тут, либонь, дарма, -
Учитель вимовив, - яка б до стелі
Тих довела, у кого крил нема».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'І от коли він в думи невеселі
Заглибився, понуривши чоло,
Я ж озирався навкруги на скелі, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Побачив я ізліва, як ішло
До нас багато духів так повільно,
Що руху вздріти око не змогло.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Я мовив: «Вчителю, поглянь-но пильно -
Он рада йде; то може б, ти спитав,
Коли стежок не знаєш безпомильно».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Поет зирнув і лагідніш сказав:
«Ходім до них, бо їхні кроки важчі.
Ти, сину, сумніви свої зостав».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Були вони далеко: мовив краще -
Коли ми кроків з тисячу пройшли,
Лишалась відстань, як кидок із пращі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Та ось вони спинились край скали,
Мов ті, що стали раптом у ваганні
І зовсім розгубилися були.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = '«О ви, померлі в добрім сподіванні! -
Віргілій вигукнув. - Хай мир благий,
Яким усі ви марите в єднанні,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'На гору шлях підкаже до снаги,
Бо зволікання гірше, ніж удари,
Для тих, що час їм надто дорогий».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Як перша із овець іде з кошари,
Позаду ж всі - за одною одна
Із простої й сумирної отари,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Те саме й інші роблять, що вона, -
На спини лізли б, якби та спинялась,
Хоч їм причина зовсім не ясна, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Так перша з душ до нас тут приєдналась -
Печаткою чесноти на чолі
Вона й серед щасливців одрізнялась, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Та глянувши, що сонця до землі
Моя особа зовсім не пустила
І тінь лягла праворуч по скалі,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Вона спинилась, потім одступила,
І кожна з тих, що натовпом густим
Позаду йшли, те ж і собі зробила.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = '«Без вашого питання відповім,
Що тіло це людське - живого роду,
Тому-то й рвуться промені на нім.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Ви не дивуйте на його свободу,
Бо дозвіл він дістав на небесах
І хоче подолати перешкоду», -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Сказав поет, і у таких словах
Всі духи радили: «Ходімо з нами», -
J з радістю показували шлях.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Один з них мовив: «Як ідеш з мерцями,
Мені увагу приділи живу, -
Чи не стрічав мене поміж бійцями?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Оглянув постать я, мені нову:
Він був русявий, гарний і рухливий,
Та шрам надвоє розтинав брову.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Не розпізнав я, хто цей дух вродливий;
Той мовив: «Глянь-но! - Показав перед,
Де в грудях зяяв розруб страхітливий,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'І посміхнувсь, додавши: - Я Манфред,
Констанци рідний внук, імператриці.
Прошу, як вирвешся із цих тенет,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'У доні будь, в сім''ї, де міг родиться
Блиск Арагону і Сицилій блиск,
І правді всій допоможи розкриться.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Як збив мене з коня ворожий тиск,
Я вдавсь до того, хто крізь рани бачив
Мого життя уже пригаслий приск,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'В сльозах благав, щоб він мене пробачив,
Бо вельми щедрі руки в Доброти
Для тих, хто шлях свій каяттям позначив.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Якби козенцький пастир зміг не йти
Виконувати Климента веління,
А глянув би в Господній лик святий, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'При Беневенто й досі жерло б тління
Побіля мосту прах моїх кісток
Під вартою важенного каміння.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'А так їх мочить дощ, вкрива пісок
Над Верде, за кордоном, і зотліють
Із тягарем обернених свічок.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Але не сильно так прокляття діють,
Щоб вічна не вернулася любов,
Аж поки в нас надії зеленіють.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Хто без відпущення з життя пішов,
Хоч і розкаявся в хвилину смерті,
Зайти не може під святий покров'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Аж тридцять строків, поки був упертий
В провинах протягом десятиліть,
Як присуду молитвою не стерти.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'Тепер добрав ти сам, як звеселить
Констанцу розповідь твоя про мене, -
Де стрів мене й за що їй слід молить.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'Молитва там - розправить тут рамена».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 49;

UPDATE cantos SET title_uk = 'ПІСНЯ ЧЕТВЕРТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 4
    AND p.name = 'Purgatorio';

UPDATE terzinas SET text_uk = 'Коли з душевних сил котрась, буває,
Чи в радощі чи в смуток порина
І тільки цим уся душа палає, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'То іншим не спалахує вона
(Не можна, отже, вигадки пробачить,
Що душі наші полумінь єдна).'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Тож як зачується чи замаячить
Таке, що душу жаром обгорта,
То як збігає час, вона й не бачить.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Лиш роздивлятись може сила та,
З цієї ж душу полум''я спостигло;
І та мов скута, ця ж у вись зліта.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Єство моє про це дізнатись встигло,
Коли з Манфредом мову ми вели,
Бо сонце непомітно перебігло'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'На п''ятдесят вже градусів, коли
Дістались ми туди, де тіні зграйно
Гукнули: «Шлях шукали ви й знайшли!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Як достигають грона, то негайно
Скрізь виноградар терном затуля
Лазівки, не такі вузькі звичайно,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Як та, що нею лізти до шпиля
Ми почали з учителем поволі,
Як душ не стало чути іздаля.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Простують люди до Сан-Лео, Нолі
І пішки до Бісмантови ідуть,
Але звестись на бескиди ці голі'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Було можливим лиш для крил, мабуть,
Високої мети, - ще й надихали
Слова поета, вказуючи путь.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Вузьким проваллям рушили ми в скали,
Де камінь в небеса свій верх простер,
І ми собі руками помагали.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Коли ж здолали ми крутий бар''єр
І вийшли на вузеньку полонину,
Спитав я вчителя: «Куди тепер?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Він одповів: «Мене на верховину
Ти супроводь, не пожалівши сил,
А там я вожая тобі зустріну».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Але стрімкий був велетенський схил,
Який величніш за пряму здіймався,
Що нею ріжеться квадрант навпіл.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'І я почав, бо віддих затинався:
«Лишаєш, батьку, ти мені сліди,
Пильнуй, щоб я їх повсякчас тримався»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = '«Синочку, хоч на камінь той зійди», -
Він вимовив, вказавши над собою
Серед урвистих скель облом гряди.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Од слів його я сповнився снагою,
Поповз за ним по кручених стежках
І, зрештою, на камінь став ногою.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'І сіли так ми, щоб у нас в очах
На схід була дорога страхітлива, -
Приємно глянуть на відбутий шлях.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Спочатку вниз дививсь я, та вразлива
Увага йшла до сонця, бо зливавсь
На нас ранковий промінь десь ізліва.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Поет примітив, як я дивувавсь,
Що в сяйнім повозі їздець крилатий
Між нами й Аквілоном просувавсь,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'І пояснив мені: «Якби Близнята
Були близ дзеркала, що ясно так
Повинне на всі сторони палати, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Ми бачили б, що світлий зодіак,
Коли не хибить путь його безмежна,
Підходить під Возів небесний знак.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Збагнеш, від чого справа ця залежна,
Дізнавшися, що мають і Сіон,
І ця гора, йому супротилежна,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Єдиний обрій за твердий закон,
Півсфери ж дві, і що стезя надхмарна,
Де коні гнав бездольний Фаетон,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Отут, по цьому схилу, незабарна,
А там іде по тому, навпаки, -
І мисль твоя тоді не буде марна».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = '«Звичайно, - відповів я, - зір швидкий
Ніколи ще не був такий у мене,
Як нині, хоч мій розум затяжкий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Незміряних кружінь кільце вогненне,
Що вчені звуть екватором його,
Лежить, між нами й сонцем полонене,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Як я добрав з пояснення твого,
Звідсіль на північ, хоч його ж євреї
На південь мають від шпиля свого.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Та не зневаж цікавості моєї:
Чи довго йтиме стежка ця важка,
Що важко навіть глянути на неї?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'А він мені: «Гора оця така,
Що ти спочатку тільки йти не в силі,
А вище - стане там хода легка.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Отож, коли для тебе стануть милі
І любі над усе стежки оті,
Мов плавний рух човна по тихій хвилі;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Коли ти дійдеш до кінця путі, -
Там тільки й зможеш на спочинок сісти,
Оглянеш сам усі місця святі».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Не встиг поет сказать цієї вісті,
Хтось поруч вимовив: «Аби знаття,
Що ти раніш не перестанеш лізти».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Обидва роздивились до пуття
Й побачили ізліва каменюку,
Що не помітив ні поет, ні я.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Ми підійшли. Там сіло на прилуку,
У холодок багато душ нудних,
Що в лінощах зневажили спонуку.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Одна, найслабша, мабуть, із слабких,
Собі руками обхопила ноги
Й поклала мляво голову на них.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = '«О пане мій, - я мовив, - глянь на цього,
Бо він - таки справжнісінький лежух,
Мов ліньки за сестер рідніші в нього».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Насилу повернув обличчя дух
І, ледве зиркнувши від стегон вище,
Сказав: «То й лізь, коли такий ти зух!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Його впізнав я і, хоч гнувся нижче
Й від втоми важко дихати було,
До нього приступив. Коли ж я ближче'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Спинився, трохи він підвів чоло
Й спитав: «То втямив ти, чом сонце Воза
З-за лівого твого плеча тягло?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Його рвучкі слова й незграбність пози
Були такі, що мимохіть всміхнувсь
І мовив я: «Не по тобі ллю сльози,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Бельаква, та скажи, чом тут приткнувсь?
Чи, на своїх ждучи, об камінь сперся,
Чи до колишніх звичок повернувсь?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'А він: «Чого б я, брате, вгору дерся, -
Мене б прогнав Господній птах від брам,
Бо слід гріхів і досі ще не стерся.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Мене й лишило небо цим місцям
На цілий строк мого земного віку,
Який лінивсь віддать я молитвам.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Бо слово має тут користь велику,
Як з серця йде, що взнало благодать.
А нам усім - лиш нидіти без ліку».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Поет рішив, що годі зволікать,
І вимовив: «Іди, піднісши око, -
На полудні не може сонце ждать,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Бо піч уже ступає на Марокко».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 47;

UPDATE cantos SET title_uk = 'ПІСНЯ П''ЯТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 5
    AND p.name = 'Purgatorio';

UPDATE terzinas SET text_uk = 'За вожаєм пішов, не поспішавши,
Й смиренно не підводив голови,
Коли, на мене пальцем показавши,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'З юрби позаду хтось гукнув: «Диви,
Крізь другого не йде проміння з дива,
І він собі ступає, як живий!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Я озирнувсь і вгледів, як щаслива
Цікаво роздивляється юрма
Мене, мене і темну пляму зліва.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = '«Чого хвилюється твій дух дарма,
Чому баритись? - вчитель мій промовив. -
Таж діла до їх слів тобі нема!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'За мною йди, і хто б не марнословив,
Будь наче горда вежа кам''яна,
Що не схитне її ніякий повів.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'У кого думка думку обмина,
Не скоро той зустрінеться з метою,
Штовхають-бо гадки одну одна».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Що міг сказать я, крім «Іду з тобою!»?
І у рум''янцях зашарівсь густих -
Змиває часом краска гріх собою.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'А душі далі йшли, їх крок не тих,
І линуло молитви стоголосся,
«Помилуй мя», журливе, стих у стих.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Як глянули, що світлу довелося
З моїм зіткнутись тілом, - спів ущух,
І «О!» хрипке і довге протяглося.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'І начебто гінці, за духом дух,
До нас підбігло двоє й попросило:
«Назвіть себе та ублажіть нам слух».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Учитель їм: «Перекажіть ви сміло
Отим, хто розпитатись вас послав,
Що в нього справді з м''яса й крові тіло.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Коли їм стежку тінню він урвав,
Хай, взнавши істину, його вшанують,
Щоб він для них колись в пригоді став».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Так прудко води в горах не шумують,
І промені, які несуть нам суш,
У серпні хмар так швидко не руйнують,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Як кинулись гінці назад, між душ,
Аби до нас всім роєм приєднатись,
Неначе вершники, що мчать чимдуж.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = '«Це люд, приречений весь час тинятись,
Біжить благать тебе, - сказав поет, -
Ти слухай їх, але не смій спинятись».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = '«О душе, йдеш ти до щасливих мет
З тим самим тілом, даним ще ізроду...
Та не стреми так свій неспинний лет!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Кого впізнаєш з нас, щоб мать нагоду
Про нього на землі розповісти?
Чого спішиш? Чому не зменшиш ходу?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Нам довелось тягар гріхів нести
Аж до хвилини смерті не своєї,
Коли осяяв пломінь нас святий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Розкаяні і прощені, до неї
Ми в мирі з Богом тихо підійшли
У сяйнім блиску світлої киреї».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'А я: «Не ті в вас риси, що були,
І я нікого розпізнать не можу,
Та, духи, що для святості жили,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Кажіть - я все зроблю во славу Божу,
Во ім''я миру, що мене веде,
Коли із світу в світ я переходжу».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Сказав один: «Тут клятв ніхто не жде,
Тобі, як всі, й без клятви довіряю,
Аби ти не знесилився ніде.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'До тебе мову перший я звертаю,
Прошу: як завітаєш у краї,
Що близ Романьї й Кардового краю,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'То в Фано просьби принеси свої,
Щоб ревно там за мене хтось молився,
Тяжкі гріхи змиваючи мої.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Я звідти родом, ранами ж покрився
І втратив кров, яка дає життя,
В онуків Антенора, бо змилився,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Шукавши в них безпечного буття;
На мене ж д''Есте був лихий без міри,
Несправедливий більш, ніж думав я.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Якби тоді поїхав я до Міри,
То серед інших, може б, досі жив, -
Мене ж в Ор''яко наздогнали звірі,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Побіг в болото я, між комишів,
І там упав, бо в мулі грузли ноги,
І річку крові власної уздрів».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'І другий дух сказав: «Коли дороги
Ти пройдеш всі, куди умом сягнув,
То удостой мене жалю й помоги.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Я з роду славних Монтефельтро був,
Бонконте - я, і ні Джованна мила,
Ніхто не дбав, щоб спини тут не гнув».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Спитав я: «А яка ж вина вчинила
Так в Кампальдіно чи біда яка,
Що зникла назавжди твоя могила?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = '«О, там же, в Казентіно, до струмка, -
Дух відповів, - що з назвою Арк''яно
Від Апеннін, з-під Ермо, витіка,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'У день страшний загибелі, нерано,
З пробитим горлом ледве я дійшов,
Червонячи весь шлях свій кров''ю з рани;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'І язиком, зважнілим для розмов,
«Маріє», - встиг шепнуть, як ти вже знаєш,
Лишаючи тілесний свій покров.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Живим скажи усе, що знати маєш.
Господній ангел взяв мене, й грозу
Зчинив той, з Пекла: «Гей, чого займаєш!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Коли вже за одну його сльозу
Тому, з небес, віддасть нетлінне кара,
То тлінному візок я підвезу!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Відомо, як у висі гусне пара,
А з неї в небі остигає мла,
І далі вже пливе блакиттю хмара.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'До злої волі, що шукає зла,
Додавши глузду, зняв він дим із вітром,
Бо звіку здатність ця в нього була,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'І ввечері погнав наказом хитрим
Од Пратоманьйо аж до Апеннін
Хмарину й струсонув густим повітрям,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Що обернув ураз на воду він, -
І залило притьмом яри без ліку,
Бо грунт не міг увесь ввібрати плин.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Зусюди повінь цю несло велику,
Що завжди в русло головне зверта,
Й не стримати було навалу дику.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'І труп мій кинула бистрінь крута
З Арк''яно в хвилі Арно по зливанню,
На грудях розриваючи хреста,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Що з рук я склав у мить страшну, останню.
Мій труп тягло між заростей рясних,
Аж поки мулом засмоктало й тванню».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = '«Коли ти вернешся з блукань трудних
І кожна пригадається подія, -
Сказала тихо третя після них, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'То не забудь, прошу, й мене: я - Пія.
Знайшла я в Сьєні світ, в Мареммі - тьму.
Це знає той, кого манила мрія,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Я ж подала для персня перст йому».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 46;

UPDATE cantos SET title_uk = 'ПІСНЯ ШОСТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 6
    AND p.name = 'Purgatorio';

UPDATE terzinas SET text_uk = 'Коли кінчиться партія у «цари»,
Той, хто програвсь, од люті аж пашить,
Повторюючи всі костей удари,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'За другим же юрба канюк спішить, -
Той зайде перед ним, смикне той ззаду,
А той ще - збоку ближче забіжить.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'А він іде, всіх слухаючи зряду,
Щось даючи, аби прохач відстав,
І тим рятується, на їх досаду.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Отак і я обличчя повертав
У натовпі густому на всі боки
Й звільнився врешті, всім-бо обіцяв.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Там аретинець був, що скін жорстокий
Сталь Гіно Такко завдала йому,
І той, хто впав при втечі до протоки.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Там зводив руки на мольбу німу
Новелло Федеріго й той пізанець,
Чий батько добрість виявив саму.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Граф Орсо теж був, як і смерті бранець,
Що заздрість принесла сердезі край,
Хоч, мовив, був не за гріхи вигнанець.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Кажу про П''єра де ла Брочча. Хай
Брабантська донна дбає що є сили,
А то опиниться між гірших зграй!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Скінчивши з тінями, які молили,
Щоб інші помолилися за них,
Аби найшвидше в рай вони ступили,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Почав я: «Десь-то у рядках своїх
Ти кажеш, світе мій, що не поможе
Молитва проти вироків святих.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Всі ж молять тут про милосердя Боже...
Невже надії їх - лише мана?
Чи я не так тебе тлумачу, може?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'А він мені: «І мисль моя ясна,
І їх не зрадять їхні сподівання,
Коли продумати усе до дна.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Бо не змаліє суду владування,
Як вмить вогонь любові зробить те,
Що робить довге тут перебування.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Коли ж писав я слово це просте,
Ще не могла молитва гріх обмити,
Для неї ще чужим було святе.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Високий сумнів слід твій пригнітити,
Зажди, чи та не ствердить це тобі,
Хто буде істині й уму світити.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Не знаю я, чи втямив ти собі,
Що мовлю про щасливу Беатріче,
Яка тебе чекає на горбі».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'А я: «Мій проводирю, йдімо швидче,
Я вже не стомлююся, як колись,
І тінь гори поквапитися кличе».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Він одповів: «Ми день іти взялись,
Щоб путь скінчити вечором затишним,
Але думки ці наші не збулись,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'І поки станеш на шпилі горішнім,
Той верне, хто за гору там іде,
І полум''ям тебе засліпить пишним.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Он глянь - душа сидить і нас не жде,
А поглядає навкруги байдуже, -
Хай скаже, найкоротша стежка де».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Наблизилися ми. Ломбардська душе,
Яка була велична й горда ти,
Яка поважна і шляхетна дуже!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Вона без слів давала нам пройти,
Лиш погляд кидала на нас вогнистий,
Мов лев на відпочинку, з висоти.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'І підійшов Віргілій променистий,
І запитав її про зручний шлях.
Вона ж не побажала відповісти,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Та поцікавилась, в яких краях
І як жили ми. Ледь вожай промовив:
«Я мантуанець...» - раптом у думках'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Схопився дух, як вітру ніжний повів:
«Ти з Мантуї! Там і моє село,
Сорделло я!» - І обіймав, здоровив...'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Рабо Італіє! Скорбот житло,
Судно без стерника під хуртовину!
Не владарка земель - блудниць кубло!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Зачувши про кохану батьківщину,
Тінь благородна миттю підвелась
До співвітчизника, як личить сину.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'А в тебе колотнеча здійнялась
Між городянами над всяку міру,
І вкруг стіна за ровом зіп''ялась.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Поглянь по берегах морського ширу,
Злощасна, і на себе зір зведи, -
Чи є куток, який радів би миру?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Юстініан узду був назавжди
Надів тобі, в сідлі ж нема нікого, -
Тож сором став би менший без вузди.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'А ви, святоші, кесаря нового
Та посадили б до його сідла,
Якби ви Бога слухали живого.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Та кінь здичавів з неслухнянства й зла
Бо від острог тоді став одвикати,
Як ваша цю вузду рука взяла.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Ти ж, німцю Альберте, волів тікати,
Бо кінь не хоче в збруї йти твоїй,
А ти ж в сідло повинен був сідати.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Бодай Суддя правдивий присуд свій
На кров твою з зірок небесних кинув
Такий, щоб ужахнувсь наступник твій!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Ти з батьком рідним, що на тебе вплинув,
Затягнуті в зажерливості твань,
Дали, щоб сад імперії загинув.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Ти на Монтеккі й Капулетті глянь,
Мональді й Філіпескі, безтурботний,
Яких знегод зазнали та страждань.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Жорстокий, глянь на згин безповоротний
Твоєї знаті під ярмом страшним,
На Сантафйор сплюндрований, скорботний.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Ти глянь на плачучу столицю - Рим,
Почуй вдовину голосьбу даремну:
«О кесарю, чом ти не став моїм?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Ти глянь на земляків любов взаємну, -
І якщо й слід чуттів у тебе щез,
Хоч здумай про свою неславу темну!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Скажи, Юпітере, ти ж бог чудес,
Що дав себе за людство розіпнути, -
Чи поглядаєш ти сюди з небес,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Чи, може, десь готуєшся звернути
З глибин своїх думок таке на нас,
Чого ми й не спроможемось збагнути?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Міста Італії тривалий час
Тиранів повні, й пнеться на Марцелла
Селюк як ватажок прихильних мас.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Флоренціє моя! Ти будь весела,
Тебе це слово не торкнеться ввік, -
Твій мудрий люд міста дивує й села!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Багато хто у серці правду звик
Ховать, щоб лук не натягати в русі, -
Твій люд для правди розв''язав язик.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Багато хто себе посад спокусі
Не дасть зманить. Твій люд - не те, повір:
Його не кличуть - сам кричить: «Беруся!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Є в тебе гроші, є розважність, мир -
Отож лишайсь вдоволена собою!
Коли це правда - не страшний докір.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Афіни й Спарта вславлені судьбою
За їх державність справіку були, -
Та не угнатись древнім за тобою!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'Достойна ти найвищої хвали,
Бо заклади, що в жовтні встановляла,
Півлистопада б ледве прожили.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'Чи полічити, скільки ти міняла
Законів, звичаїв, монет, округ,
Скількох у громадянстві поновляла?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 49;

UPDATE terzinas SET text_uk = 'Коли при пам''яті, поглянь навкруг, -
Побачиш, що нагадуєш ти жінку,
Яка в перинах мучиться з недуг,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 50;

UPDATE terzinas SET text_uk = 'Метаючись без сну і відпочинку.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 51;

UPDATE cantos SET title_uk = 'ПІСНЯ СЬОМА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 7
    AND p.name = 'Purgatorio';

UPDATE terzinas SET text_uk = 'Нас три й чотири рази привітавши,
Бо дуже він кохався в земляках,
Сорделло відступив, «Хто ви?» спитавши.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = '«До того ще, як по горі цій шлях
Достойним душам показав Спаситель,
Вже поховав Октавіан мій прах.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Віргілій я; згубив святу обитель
Лише тому, що віри я не знав.
Оце мій гріх», - так відповів учитель.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Мов той, хто зором дивну річ спіймав
І, щоб знайти до правди шлях коротший,
«Це так» і «ні, не так» в думках міняв, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Закляк Сорделло; враз, спустивши очі,
До ніг Віргілієвих він схиливсь
І обійняв, як старшого молодший:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = '«О сяєво латинян! Це ж відкривсь
Тобі весь глиб, властивий нашій мові!
О вічна славо місць, де я родивсь!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Я вдячний за хвилини ці чудові!
Коли тебе почути гідний я,
Скажи, ти в Пеклі був? В якому рові?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = '«У царстві мук дорога йшла моя, -
Той відповів, - по колах всіх до краю,
Де цнота нас вела не навмання.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Я не за дію - за недію маю
Не бачить сонця, що з його світань
Втішавсь ти, я ж про них лиш нині знаю.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Внизу місцина є, не від страждань,
Лише від мли смутна, немов заклята,
Не лютих зойків повна, а зітхань.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Зі мною там - безвинні немовлята,
Що зубом смерті вкушені були,
Адамова ж вина ще з них не знята.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Зі мною там всі ті, що не змогли
Іти трьома священними шляхами,
А іншими чеснотами жили.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Коли ти можеш, то піди із нами,
Щоб найскоріш ми опинились там,
Де у Чистилище є певні брами».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Він одказав: «Нема ніяких брам,
Та вештаюсь я вільно по окрузі
І стежку покажу, як хочеш, вам.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Але вже сонце на вечірнім прузі,
На гору ж потемки не можна йти,
То поміркуймо про ночівлю, друзі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Тут легко гурт значних осіб знайти, -
Коли ти згоден, ми б до них присіли,
Не без утіхи з ними стрівся б ти».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = '«Як? - відповідь була. - То б не пустили
Вночі охочих вийти на шпилі,
А то у них забракло б, може, сили?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Провів Сорделло пальцем по землі,
Сказавши: «Не здолати й риски кроком,
Коли вона сховається в імлі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Відступиш перед мороком глибоким,
Бо волю він у тебе відбира
І робить безпорадним та безоким.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Тебе до себе звабить моря гра,
І цілу ніч в блуканнях ти змарнуєш,
Аж поки прийде ранішня пора».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'І вчитель мовив: «То ходімо, чуєш,
Туди, де зможем провести ми час
З приємністю, як ти нам пропонуєш».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Уже ми рушили, коли нараз
Помітив я між кручами щілину, -
Такі трапляються у горах в нас.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = '«Ми підемо, - сказала тінь, - в долину,
У скелі вибиту без людських сил,
І пождемо світання там годину».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'З височини, де ми стояли, в діл,
Звиваючись, тропа вела нас доти,
Аж поки зник і вирівнявся схил.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Червець, білила, жар іскристо-злотий,
Індійського ебену блиск живий,
Гра зламів, як смарагда розколоти, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Усе те проти квітів і трави,
Якими тут вкривались пишні луки,
Не піднесло пихато б голови.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Природа-бо не тільки барви й звуки
Тут кидала, а й пахощі лила,
Чудовні творячи незнані злуки.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Співаючи «Владичиці хвала»,
Присіли на квітках і травах тіні,
Яких од нас ховала ще скала.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = '«Аж поки сонце не зайшло в глибіні,
Не сходьте вниз до вінценосців тих, -
Так мантуанець мовив на камінні. -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Вам рухи й лиця тіней визначних
Із місця краще роздивитись цього,
Ніж стали б ви в долині серед них.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Той, хто сидить найвище і до всього
Байдужий, бо ніщо не веселить,
І хто не мовить слова ні до кого, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Рудольф то імператор, що зцілить
Італії мав змогу тіло хворе,
Яке тепер ніхто не оживить.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'А цей, чий вид йому гамує горе,
У землях панував, де б''є струмок,
Що йде з Молдави в Ельбу, з Ельби в море, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Це Оттокар, який ще з пелюшок
Був кращий, ніж ледащо з бородою,
Розпутний Венцеслав, його синок.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Кирпань, який, збентежений судьбою,
Щось каже духу з добрістю в лиці,
Вмираючи, лілеї вкрив ганьбою.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Погляньте на скорботні душі ці:
Та в груди б''є себе, а та - дивіться -
З долоні робить подушку щоці.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Бо ж їхній син і зять, як моровиця,
Французьку землю знищує притьмом, -
їм є чого від горя й мук хилиться.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'А той, що видається моцаком
І вкупі з носачем виводить фразу,
Оперезався гонорів паском.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Коли б затримався при владі зразу
Юнак, який чоло за ним здійма,
Перелилась би доблесть з вази в вазу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'А інших згадувать синів дарма:
Хай Федеріго й Джакомо на тронах,
Найкращого ж із спадку в них нема.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Нечасто бачиш у потомних гронах
Чесноти предків волею того,
Хто їх дає на просьби по законах.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Співає поруч носача цього
Ще й Педро, славою навік покритий,
Бо знали Пулья і Прованс його.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Рослину має сім''я проростити, -
Щастить Констанці проти всіх дружин,
А надто Беатріче й Маргеріти.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Найтихший владар сів собі один,
Хоч щастя в пагонах у нього вище:
Англійський Генріх то, Йоаннів син.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'А той, що очі звів, стоїть найнижче, -
Маркіз Гульєльмо; мста за нього й лють
Мечем Алессандрії в бойовищі'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Кров з Монферрато й Канавезе ллють».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 46;

UPDATE cantos SET title_uk = 'ПІСНЯ ВОСЬМА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 8
    AND p.name = 'Purgatorio';

UPDATE terzinas SET text_uk = 'Була година, що наводить тугу
На моряків, м''якшить-бо серце їм
За вигуком «бувай!» смутному другу,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Коли новий любові пілігрим
Десь чує, як оплакують каплиці
Вмирущий день подзвінням жалібним.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Я кинув слухати і став дивиться:
Поважний дух, піднявшись, щоб була
Його помітна тінь юрбі столицій,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Склав руки; звівши до свого чола,
На схід поглянув, мов сказав до Бога:
«Байдужий я до блага і до зла!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Й злетіло «Світе тихий...» з уст у нього
Так гаряче, побожно й ніжно так,
Що в млості я забув себе самого.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'І душі підхопили, мов на знак,
Побожну пісню, ніжну та гарячу,
І очі піднесли, як і співак.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Скеруй свій зір на істину, читачу!
Спрозоріла запона, як скляна,
І стало видно правди зміст і вдачу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Побачив я, як ця юрба значна,
Немов з небес чекавши благодаті,
Дивилась вгору, скромна, мовчазна.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Побачив ще, як стали наближати
Два ангели і кожен мав клинок,
Блискучий, та затуплений, щербатий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Зелений, наче молодий листок,
Убір в зелених крилах променився
І легко з вітром бавивсь між гілок.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Один із них над нами зупинився,
А другий на той бік перелетів,
І натовп душ між ними опинився.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Я б любував з білявих їх голів,
Та зір мій відібрала їх корона,
Він втратив силу від сліпучих див.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = '«Вони - посли Маріїного лона, -
Сказав Сорделло, - повзає тут змій,
Вони ж - тверда від нього оборона».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Я озирнувсь - такий був острах мій, -
І в вожая сховався під габою,
Знайшовши в згортках захист певний свій.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Сорделло ж мовив: «Стріньмося з юрбою
Цих знатних тіней, що, мені здалось,
Охоче б побалакали з тобою».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Три кроки лиш пройти нам довелось,
Аж тут, немов чекав мене зустріти,
Уважно додивлявсь до мене хтось.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Не встиг ще небосхил так потемніти,
Щоб те в очах його й моїх запнув,
Що відстанню раніш було закрите.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Ступнув він ближче, ближче й я ступнув, -
Суддя шляхетний Ніно! Як приємно,
Що ти до злих залічений не був!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Він, привітавшися сердечно й чемно,
Спитав мене: «Під гору цю коли
Водою ти дістався нетаємно?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = '«О, - мовив я, - стежки по горю йшли.
Нехай би, в першому житті відбуті,
Вони б в наступнім радість принесли».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'І лиш мої слова були почуті,
Як одсахнулися й Сорделло, й він,
Немовби подивом великим скуті.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Звернувся до Віргілія один,
А другий до сусіди: «Встань, Куррадо,
І подивися на Господній чин!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Мені ж він мовив: «Вдячності заради,
Що винен ти тому, хто приховав
Путі свої й блукає без поради, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Мою Джованну, я прошу, настав
На молитви? хай слізьми щоки вмиє,
Бо в небо завжди чистих плач злітав.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Навряд чи мати в неї з горя мліє,
А то б свій білий зберегла покров, -
Колись вона за цім ще пожаліє!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Ось доказ, як горить в жінках любов,
Коли згаса її підпора гідна,
А зір і дотик не розпалять знов.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'А на труні міланцева єхидна,
Не півник наш, галлурський, родовий, -
Для неї це окраса надто бідна».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Він мовив, на обличчі огневий
Світився відблиск чесної любові, -
Хоч не сліпучий він, та віковий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'А я, вдивившись в небеса чудові,
Все дивувався нешвидким зіркам,
Що сунули по коловій основі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Вожай спитав: «Що, синку, бачиш там?»
І я йому: «Там три побачив зірки,
Що освітили полюс, наче храм».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'І він: «Вони зійшли замість четвірки,
Яку за обрій час тепер заніс,
А ти уранці споглядав так зірко».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Сорделло тут його в обіймах стис,
«Ось ворог наш!» - гукнувши любій тіні,
Він пальцем показав кудись униз.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Там, в не захищеній нічим частині
Байраку, сунула гадюка зла,
Той, може, змій, що смерть приніс людині.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Ця клята стрічка по траві повзла,
Облизуючись, спину вигинала,
Немов тварина митись почала.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Не бачив я й не розповім, як гнала
Сторожа ангельська на небосхил, -
Я бачив тільки, що вона примчала.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Під подувом її зелених крил
Утік той змій, і стежкою своєю
Вернули вартові небесних сил.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'А дух, до нас підкликаний суддею,
Весь час, як споглядала бій земля,
Знайомився із постаттю моєю.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = '«Хай пломінь, що веде тебе здаля,
На свічі стопить віск твоєї волі,
Щоб до емальового йти шпиля! -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Почав цей дух. - А як в моїм околі?
Я в Вальдімагрі паном хизувавсь
На всі навкруг місця широкополі,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Коррадо Маласпіна прозивавсь,
Не старший з тим ім''ям, того ж я дому.
Тут очищаюсь, бо в рідні кохавсь».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = '«О, - мовив я, - у вас я в краї тому
Не був, але чи хтось в Європі є,
Хто б не чував про землю ту відому?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Про вас чужинець навіть дізнає,
Бо чутка скрізь, незмильна, як присяга,
Хвалу князям, хвалу й землі дає.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Клянусь - хай знайдеться дійти відвага! -
Що внуки гідно зберігають честь,
Яку вам добули грошва та шпага.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'У них, з природи й звички, вартість єсть,
І хай лихий глава весь світ спокусить,
Та їх не зманить на стежки нашесть».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'І він: «Іди, й семи разів не мусить
Лягати сонце в постіль ту ж таки,
Яку Баран з зірних копит не струсить, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Для наших вух приємні ці гадки
У голові твоїй прип''ято буде
Цвяхами, кращими за всі чутки,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Як вирок долі чинності не збуде».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 47;

UPDATE cantos SET title_uk = 'ПІСНЯ ДЕВ''ЯТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 9
    AND p.name = 'Purgatorio';

UPDATE terzinas SET text_uk = 'По обрію, мов із морського лона,
Біліючи на східному шпилі,
Зійшла кохана ветхого Тіфона.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Гра самоцвітів на її чолі
Холодної тварини вид створила,
В якої хвіст, як вістря у стрілі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Там ніч два кроки вгору вже зробила,
Де п''ять вели розмови кругові,
І мусила на третім скласти крила,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Коли знемігсь я, мов усі живі,
Бо врешті надійшла хвилина рання,
І задрімав, схилившись на траві.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'В годину, недалеку до світання,
Коли сумує ластівка в піснях,
На згадку, мабуть, першого страждання;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Коли наш розум робить вільний змах,
Земні турботи кинувши, зринає
В божественних перепочити снах, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Мені приснилось, що орел ширяє
На дужих крилах в пір''ї золотім
І, цілячись на землю, небо крає.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Приснилося, що був я в місці тім,
Де Ганімед своїх покинув рідних,
Занесений у понадхмарний дім.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Гадав я: «В небесах, для себе гідних,
Орел шукає цілі для погонь,
Не полюбляючи низин огидних».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Приснилось, що на нашу оболонь
Він блискавкою впав мене забрати
І злинути в негаснучий огонь.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'А там приснилось, стали ми палати, -
Уявний пломінь був такий страшний.
Що зміг моє сновиддя перервати.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Так, певно, затремтів Ахілл грізний,
Побачивши навколо край далекий.
Коли вві сні попав до чужини,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Бо мати мріяла, щоб небезпеки
Син, схований на Скіросі, уник,
Але ж і там знайшли героя греки, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Як я здригнувсь, і сон мій геть утік,
І зблідли в мене щоки, як в людини,
В якої холод враз торкнувся щік.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Зі мною був лиш провідник єдиний,
Внизу десь бігли хвилі голубі.
І сонце небом зо дві йшло години.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = '«Не бійся і не піддавайсь журбі, -
Учитель мовив, - ми якраз де треба,
І сміливості дух плекай в собі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Чистилище перед очима в тебе,
Поглянь - оце навкруг його стіна,
А там он, у проломі, вхід до неба.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'На моріжку, де зелень запашна,
Уранці, як тебе лишила дія
І ти заснув, з''явилася жона'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Прекрасна й дивна. «Я Лючія, -
Сказала, - взяти велено мені
Того, над ким панує сонна мрія».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Сорделло й інші тіні визначні
Зостались, а тебе вона забрала
На руки й вийшла, я ж - услід ясній.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Сюди принісши, тут тебе поклала,
Вказавши гарними очима вхід,
І водночас із сном твоїм пропала».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Мов той, хто, збувшись сумнівів та бід,
Міняє страх на впевненість і спокій,
Коли йому відкрився правди слід, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Так я змінився в радості глибокій.
Вожай, уздрівши це, пішов вперед,
Пішов і я з ним по горі високій.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Читачу, бачиш, як підніс я лет,
Тож не дивуйся на мистецтво вище.
З яким про свій писатиму предмет.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'На місце в мурі вийшли ми найнижче,
Де в ньому був, здавалося, пролом,
І вздрів стіну я, підійшовши ближче,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Із замкненим воротами жерлом,
Три східці різнобарвні й мовчазного
Воротаря з осяяним чолом.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Не зводив я очей з лиця ясного,
Яке таким світилося вогнем,
Що я не стерпів погляду жахного.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Сидів він із оголеним мечем,
Що так іскрився відблисками сталі,
Аж я не міг до нього стать лицем.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = '«Відповідайте і не руште далі, -
Він мовив, - хто вас вів? Що треба вам?
Глядіть, щоб не взяли вас часом жалі».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = '«Жона небесна так сказала нам, -
Учитель вимовив, - негайно звідци
Ідіть туди сміливо - брама там».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = '«Нехай жона ця стане вам в провідці, -
Так благородний брамник одповів, -
Відважно ви зійдіть на наші східці».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Ми підійшли. Я східець перший вздрів,
Лискучий, сяйний, біломармуровий,
Що лик мій як у дзеркалі відбив.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'А другий з них був почорно-багровий,
І камінь - грубий, висохлий як є,
Потрісканий до самої основи.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Найвищим, на уявлення моє,
Був третій з них, порфіровий, яскравий,
Мов кров, що з вени раненої ллє.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'На нього вісник праведної слави
Поставив ноги, сівши на поріг, -
Алмазним здавсь поріг той величавий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Вожай мені здолати допоміг
Благої волі східці, дав пораду:
«З благаннями впади йому до ніг».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Я, вдаривши у груди тричі зряду,
Схилившися до ніг, прохання склав,
Віддаючись цілком йому під владу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Сьома «глаголями» чоло списав
Мені вістрям меча він і: «Ці плями
Подбай в дорозі стерти!» - проказав.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'З-під одягу свого, такого ж саме
На колір, як суха земля й зола,
Він вийняв руку із двома ключами:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Один був з злота, другий - із срібла.
В щілину білий вклав, а потім жовтий, -
Й на мене хвиля щастя наплила.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = '«Коли б із двох лиш одного знайшов ти
Або в ключах цих вийшла б ґандж яка, -
Сказав він, - то у браму б не-зайшов ти.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Один дорожчий, другий для замка
Потрібніший і вимагає вміння,
Бо саме він пружину відмика.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Іще я маю від Петра веління,
Щоб краще я відкрив, аніж замкнув,
Як хтось мені до ніг складе моління».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Тур браму він всередину штовхнув,
Сказавши: «Йдіть; нема-бо стежки в висях
Тому лиш, хто б свій зір назад звернув».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'І кожна стулка брами об завісах
З металу, що співає, мов сурма,
Повільно обернулася на списах.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Тарпейська брама не гула сама
Отак, коли із нападом зухвалим
Забрала чесного Метелла тьма.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Та я почув із громом небувалим,
Що голос чийсь молитву десь веде:
«Тебе, - лунало ніжно, - Бога хвалим».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'Проте було, як і інакше де,
Як і у нас частенько може бути,
Коли із хором враз орган гуде:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'Слова то чути добре, то не чути.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 49;

UPDATE cantos SET title_uk = 'ПІСНЯ ДЕСЯТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 10
    AND p.name = 'Purgatorio';

UPDATE terzinas SET text_uk = 'Коли ми стали по той бік порогу,
Який моторна хитрість обмина,
Воліючи покручену дорогу,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Замкнулась знову брама голосна, -
Це я почув. Якби я озирнувся,
Чим виправдалась би моя вина?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Ми йшли вузьким шляхом, що простягнувся
В глухій розпадині туди й сюди,
Як в морі вал - набіг і вбік війнувся.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = '«Нам тут потрібні вмілість і труди, -
Почав вожай, - не вийти б ненароком
Звідтіль і звідси на свої ж сліди».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'І ми таким повільним надто кроком
Посунули, що на спочин зайшов
Щербатий місяць шляхом одиноким,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Аж поки ми із кам''яних заков
Не вийшли на вершок стрімкої скелі,
Там, де гора униз пішла ізнов.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Я - стомлений, обидва - невеселі,
Непевні, досягли ми площини,
Відлюднішої, ніж тропа в пустелі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Дорога йшла стрілою вздовж стіни,
Між прірвою й скалою край обриву
Й три людські зрости мала ширини.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Уступ тягнувсь направо і наліво,
І, скільки вистачало сил в очах,
Не видно змін було у нім, на диво.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Нога на цей ще не ступила шлях,
Коли побачив я перед собою
Широкі обводи по стрімчаках,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Всі біломармурові, із різьбою,
Що проти них не тільки Поліклет,
Сама природа вкрилася б ганьбою.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'От ангел, щойно мов скінчивши лет,
Приносить вість, виплакувану звіку,
Про мир на всій землі, мету всіх мет,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'З майстерністю на всю стіну велику
Зображений в величній красоті,
Не схожий на подобу без''язику,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Мов «Радуйся!», клянусь, казав він тій,
Що обертає, благосна, ключами,
Які любов хоронять в чистоті.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'А вид її, осяяний словами,
Що «Се раба господня», виглядав,
Неначе образ, литий за взірцями.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = '«Для іншого увагу теж зостав», -
Сказав моєї керівник надії,
Що близько серця в нього я стояв.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'І тут помітив я позад Марії,
Між образів, як вирослих з землі,
І обіч з тим, хто вів мене до мрії,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Іще картину, врізану в скалі.
Я обійшов Віргілія і вп''явся
У постаті на мармуровім тлі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Ковчег, страшний для того, хто хапався
За діло не своє, тягли бики,
І віз під ним неначебто хитався.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Сім хорів створювали співаки,
І в мене сперечалось око з вухом:
Таки є звуки! Ні, нема-таки!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'У зору спірка йшла також із нюхом
Про дим з кадильниць - витвір різьбаря, -
Чи пахне він, чи ні кадильним духом?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Перед ковчегом, сяйним, як зоря,
Ішов танцюючи псалмист побожний,
Що вищий був і менший за царя.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'А на палаці - бачить міг би кожний -
Мелхола сумно поглядала вниз,
Як і належить пані цій вельможній.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Пішов я від Мелхоли й переніс
На інші образи свою увагу,
Вони ж біліли на увесь карниз.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Змальовано тут славу і повагу
Монарха, що чеснот його талан
Григорія подвигнув на звитягу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Великий імператор цей - Траян.
Вдова, ридавши, за вузду спиняла
Коня в найліпшого з нехристиян.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Навкруг у корогвах з орлом стояла
Кіннота, і нечутна іздаля
Десь військова сурма похід співала.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Сердешна жінка наче примовля:
«Скарай убивць мого, владарю, сина.
Хай і мене поглине з ним земля!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Він каже: «Кари не втече провина,
Як вернемо». Вона: «Ти б хоч зирнув,
А то ще набіжить лиха година,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Й не вернеш ти». А він: «Я б не вернув, -
Наступник зробить». А вона: «Що в тому,
Як викона хтось те, що ти забув?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'А він: «Веде обов''язок додому,
Бо справедливість дужча од війни,
І жалість заступає путь відому».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Для кого не існує новини,
Той тут створив для всіх видиму мову,
Нову для нас, бо ми - землі сини.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'І поки милувавсь я знову й знову
На образи покори, любі тим,
Хто знає руку різьбаря чудову, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = '«Багато духів кроком нешвидким, -
Шепнув поет, - з мого підходять боку, -
Угору ми за ними вслід ходім».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'На все нове пожадливому оку
Слова ці стільки додали снаги,
Що вмить на стежку глянув я широку.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Хотів би я, читачу дорогий,
Щоб ти не знітивсь, звірившися чуду,
Як саме Бог велить платить борги,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'І в формі мук побачив би полуду,
Бо суть настане після всіх страждань,
Які скінчаться в день Страшного суду.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Почав я: «Вчителю, там суне, глянь,
Щось неподобне зовсім, незбагненне,
І сповнивсь я непевності й вагань».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'І він мені: «Моє хоч око вчене,
Та їх придавлює такий тягар,
Що помилився погляд навіть в мене.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Ти краще придивися до примар,
Що йдуть під брилами уздовж дороги, -
То й зможеш уявити ступінь кар».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Пихатий християнський роде вбогий,
В сліпих думках у тебе голова:
Ногам ти віриш, хоч задкують ноги.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Хіба не бачиш ти, що ми черва,
Що з нас метелик ангельський виходить
І мчить туди, де істина жива?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Чом півнем розум твій себе поводить?
Не знаєш ти, що ми - комахи, глей,
Де розвій лиш невивершений бродить?..'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Коли як слупи статуї людей
Стоять, і кожна стелю підпирає,
Притиснувши коліна до грудей,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'То вигляд їх несправжніх мук звертає
На справжні муки глядачів чуйних;
Я також співчуття звернув безкрає'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'На більш чи менш зігнутих духів тих,
Яких згинали більші й менші брили,
Й здавалося, найбільш терплячий з них'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Немов зітхав: «Немає більше сили!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 47;

UPDATE cantos SET title_uk = 'ПІСНЯ ОДИНАДЦЯТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 11
    AND p.name = 'Purgatorio';

UPDATE terzinas SET text_uk = '«Наш Отче, ти, який живеш на небі
Не через те, що замкнений у нім,
А люблячи істот, близьких до Тебе!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Іменню й силі будуть хай Твоїм
Од всіх створінь хвала і слава щирі,
Подяка й захват духом всесвятйм!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Твоє до нас хай прийде царство в мирі,
Інакше відшукати вірну путь
Не може розум у всесвітнім ширі!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Як волю в жертву в небесах здають
Всі ангели, співаючи «Осанна!»,
Хай на землі тим шляхом люди йдуть!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Хай нині нам спаде щоденна манна,
Без неї-бо пустельний світ страшний
І відстає квапливість ненастанна!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Як ми вини даруєм, хоч вони
Страждань нам завдають, так, благодійний,
Нам цнот не зважуй, а даруй вини!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Чеснотам нашим захисте надійний,
Удари відвертай, подай снаги,
Бо спокушає ворог нас постійний.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Останнє просим, Боже дорогий,
Не нам, бо нам уже не допоможе,
А тим, що йдуть за нами, Всеблагий!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Отак, благавши милосердя Боже
За себе і за нас, вони несли
Каміння, на важке сновиддя схоже.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Під різним тягарем поволі йшли,
Утомлені, зажурені хилились,
Щоб змиті плями світу з них були.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Як треба, щоб ми тут за тих молились,
Хто в муках нас не забуває там,
Де корені од волі відділились!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Допомогти б їм, щоб збулися плям,
Якими світ забруднює людину,
І, чисті й вільні, віддались зіркам!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = '«О, хай вам швидше випростає спину
Той милосердий, що надасть вам крил
У небесах ширяти без упину!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Скажіть, як вийти нам хутчій на схил,
Що нас би вивів на жадані сходи,
І як найменше витратити сил,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Бо тіло це, Адамове з породи,
Якого не ввібрала ще земля,
Важкої, дуже втомної природи».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'І відповідь, неначе й не здаля,
Тому, за ким ішов я цими днями,
Нас досягла не знати звідкіля'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Й така була: «Ідіть направо з нами,
І тут очам відкриються місця,
Де можна йти немертвими ногами.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Якби не заважала брила ця,
Що нахиляє лоб мені пихатий
І змушує не піднімать лиця,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Я б глянув, хто, живий, себе назвати
Не хоче, і настійність би моя
Умовила за мене попрохати.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Значного був тосканця сином я,
Гульєльмо він Альдобрандеско звався, -
Ви, сподіваюсь, чули це ім''я.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'До того предками я хизувався
І видатними подвигами їх,
Що в серці навіть спогад не з''являвся'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Про спільну матір; зневажав я всіх,
Тому й помер, як сьєнець кожен знає,
А в Кампаньятіко - всі, до малих.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Омберто я; пишання це безкрає
Мене зоставило без голови,
І весь мій дім од нього лихо має.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Зніс брилу я на шлях цей коловий
І, поки Бог мої припинить муки,
Мерцем роблю, як не робив живий».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Понурившись, сумної мови звуки
Я вислухав; тут інший дух зирнув
На мене з-під своєї каменюки,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Побачив, упізнав мене, гукнув
І вгору очі, скуті як в залізі.
На превелику силу повернув.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = '«О, - мовив я, - невже ти Одерізі,
Агобйо слава й слава ремесла,
Як зве Париж, «освітлювання в книзі»?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Відмовив: «Слава, брате, вся пішла
Тепер до Франко, юного болонця,
Мені ж зосталась крихітка мала.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Колись же їй, приємнішій од сонця,
Я, мавши кожний натяк за лихий
На неї наклеп, був за оборонця.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Отут спокутується гріх пихи.
Я б тут не був, якби не вчув я Бога,
Ще змогу маючи робить гріхи.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'О марна славо з голосу людського!
Якщо нема глибоких корінців,
То незабаром всохне крона вбога.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Чув Чімабуе, що з усіх митців
Найкращий він, але з приходом Джотто
Загал суворіше його судив.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Цей Гвідо в мовному мистецтві - злото,
Як з тим зрівнять, а може, хтось з''явивсь,
Хто і тому, й цьому завдасть турботи.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Бо гомін світу - вітер лиш: він звивсь,
Хвилюючись і тут і там у гоні,
Й змінив ім''я, як в напрямі змінивсь.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'В чім слава через сотні літ по сконі?
У тім, що члени дряхлістю примне,
Чи в тім, що вмреш, казавши «папи», «моні»?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'А сотні років - щось таке ж дрібне
Супроти вічності, як рух бровою
Проти дороги в небо зоряне.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Цього, що ледве йде переді мною,
Колись-то знав народ в Тоскані всій, -
Тепер лиш Сьєна згадує порою'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Вождя, який здобув пошану їй,
Долаючи Флоренцію шалену, -
Там блуд лишився, де був гонор в ній.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'На барву слава - з травку одноденну,
І той за мить знебарвлює її,
Хто родить на землі її, зелену».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'І я: «Втишаються чуття мої
Од цього слова, а бундючність в''яне.
Але про кого ці слова твої?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = '«Це Провенцано, - він сказав, - Сальвані.
Тут за зухвальство він іде тепер,
Якому сьєнці всі були слухняні.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Пішов він з каменем, як тільки вмер.
Так борг платити випадає зухам,
Хто на землі занадто кирпу дер».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'А я: «Коли там, під горою, духам,
Які покинули земний покров,
Свій строк життя перед покутним рухом'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = '(Як час не зменшиться від молитов)
Потрібно зважувати власні вади, -
То як сюди так швидко він дійшов?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = '«Він, бувши, - той сказав, - на версі влади,
Пихи позбувся раптом і притьма
На площі став благать уклінно ради'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'За друга, що його взяла тюрма,
Нестерпно люта Кардова закова,
Тремтівши тілом перед усіма.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Я замовкаю. Знаю, - темна мова,
Та скоро вже дбанням співгородян
З''ясуєш значення цього ти слова.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'Цим вчинком він собі полегшив стан».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 48;

UPDATE cantos SET title_uk = 'ПІСНЯ ДВАНАДЦЯТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 12
    AND p.name = 'Purgatorio';

UPDATE terzinas SET text_uk = 'Неначе два бики в ярмі одному,
З обтяженою тінню ми були,
І вчитель мій не бачив зла у тому.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Коли ж гукнув: «Тепер вперед пішли,
Бо тут потрібно, щоб весло й вітрило
Не зупиняючись човна вели», -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'То зараз випростав своє я тіло,
Як слід робить, коли рушаєш ти,
А лихо ще думки твої обсіло.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Я, мріючи дістатися мети,
За любим вчителем пішов охоче,
І дуже легко стало так іти,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Коли він мовив: «Опусти-но очі,
Бо не завадить знати до пуття,
Дорогу тим, хто збочити не хоче».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'На згад про тих, хто зник без вороття,
В церквах лежать надгробком їх подоби,
Які були вони ще за життя,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Й доводять до плачу з журби й шаноби:
Нерідко колють спомини жалом
Чутливе серце, сповнене жалоби.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Отак і тут дорога вся цілком
Від муру аж до самої безодні
Була в малюнках пензлем і пером.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Впізнав я отого, хто благородні
Над всі створіння риси мав і, мить
Просяявши, в глибини впав холодні:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Впізнав я Бріарея, що лежить,
Жорстоко вдарений стрілою з неба,
Й морозом смертним все навкруг темнить;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Впізнав також Палладу, Марса й Феба,
Що прозирають, збройні ще, з отцем
В порубаних гігантах млу Ереба;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Впізнав Немврода, що з сумним лицем
Глядить на сеннаарців гордовитих
Під вежею з нескінченим вінцем;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Тебе, Ніобо, й жах в твоїх залитих
Слізьми очах впізнав я на шляху
Поміж семи й семи дітей забитих;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Тебе, Сауле, й смерть твою лиху
Од власного меча на тій вершині
Гелвуї, що навік лишив суху;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Тебе, дурна Арахно, в павутині,
Яку зіткала ти сама собі,
Уже півпавуком, в тужній одміні;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Тебе, о Ровоаме, в боротьбі
З підданцями: тікаєш в колісниці,
А стріли царські не страшні юрбі;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Ще образ був на бруку, мов на криці,
Як матері помстився Алкмеон
За всі її нові прикраси ниці:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Ще образ був, як в храмі, між колон,
Сеннахеріб, кривавлячи порфіру,
Синами вбитий, впав на власний трон;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Ще образ був, з яким тріумфом Кіру
Гукнула Тамірі звитяжно й зло:
«Жадав ти крові - тож хлебчи надміру!», -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Ще образ був, як врозтіч утекло
Все ассірійське військо по долинах,
Як Олоферна тіло полягло.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Впізнав я Трою в попелі й руїнах...
О Іліоне! Твій гіркий кінець
Зображено в страхаючих картинах.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Та хто ж пера та пензля був знавець,
Який фігури з тінню зладив строго
Й разюче для умів і для сердець?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Мрець вигляд мав мерця, живий - живого.
Ніхто б не міг у дійсність прозирнуть,
Як я, що зору не підвів свойого.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Тож діти Євині хай кирпу гнуть,
Хай задаються, замість поглядати,
Яка погана під ногами путь!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Ми гору обійшли вже набагато,
І сонце рухалось куди хутчій,
Ніж міг наш розум клопітний гадати,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Коли сказав мені учитель мій,
За ким я йшов: «Зведи-но погляд вище,
Залиш своїх думок печальний рій,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Дивися, он підходить ангел ближче,
Служниця ж шоста дня - уже її
Скінчився строк - іде все нижче й нижче.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Вдягни в пошану слів своїх рої,
Бо вкаже він короткий шлях нагору,
А день біжить і цей, як всі твої».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Я звик, що він мене усю цю пору
Постійно вчить не гаяти хвилин,
І зразу осягнув пораду скору.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'В убранні із сіяючих тканин
Наблизилась до нас істота біла,
Сліпучіша од всіх морських перлин.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Розкривши руки й розпростерши крила,
Сказала: «Йдіть, очищені серця,
Он сходини лежать - на брилі брила».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Як рідко має відгук мова ця!
О людство, ти ж споріднене лазурі,
Чом падаєш без сил од вітерця?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Тут ангел нас провів на сходи в мурі,
Змахнувши по чолу моїм крильми,
І мандри обіцяв нам непохмурі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Як в місті із відмінним ладом, ми
До храму, що панує над долами,
По Рубаконте з іншими людьми'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Підводилися зручними ходами
(Коли споруджені були вони,
Ні книг, ні мір не гидили ще плями), -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Так вирубані в товщині стіни
Тут сходини вели у друге коло,
Але цей хід занадто був тісний.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Пішли ми, й в серце захватом вкололо:
«Блаженні духом нищії» завів
Хтось раптом ніжним голосом зокола.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Ах, як цей шлях ні на один з шляхів
У Пеклі не скидався! Тут-то співи,
А там прокльони й стогони мерців.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Як рушили ми сходами терпливо,
Важкий внизу, в долині, кроку вдар
Враз незрівнянно легшим став, на диво.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Тож я: «Учителю, який тягар
Із мене знято, що пропали болі
І легко я дійшов би аж до хмар?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Він одказав: «Коли ще й ті глаголі,
Які лишились в тебе на чолі,
Хоч майже стерті, зникнуть всі поволі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Чим далі йти ми будем від землі,
Тим радісніш ногам і легше буде
Підводитися по крутій скалі».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'І я вчинив тоді, як чинять люди,
Аби дізнатись, що на голові,
Коли на це їм вказують зусюди:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Вони підносять руку, а то й дві,
Щоб замінити з поміччю такою
Звичайні очі, тут недійові.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Я звів правицю, повен неспокою,
Шістьох лиш літер на чолі торкнувсь
З накреслених безсмертною рукою.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Помітив це мій вождь і усміхнувсь.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 46;

UPDATE cantos SET title_uk = 'ПІСНЯ ТРИНАДЦЯТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 13
    AND p.name = 'Purgatorio';

UPDATE terzinas SET text_uk = 'Зійшли ми аж на верх камінних сходів,
Де вдруге вужчала височина
Що розгрішає всіх, хто б нею сходив.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'І тут карниз, дорога і стіна
Вилися, як і нижче, безкінцеві,
Але була в них менша довжина.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Художникові тут і сницареві
Роботи не було: каміння й брук
На колір видавалися свинцеві.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = '«Тут про пораду наш даремний гук, -
Сказав поет. - Стояти ж нам без діла -
Це завдавать собі лиш зайвих мук».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Приглянувшись до сяйного світила,
Узяв він віссю руху правий бік
І ліву обернув частину тіла.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = '«О ясне сонце, під яким я звик
Упевнено в дорогу вирушати,
Веди нас далі, як вело, - він рік. -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Ти, що світам даєш блискучі шати,
Хай з незліченних сяючих зірок
Нас твій лиш промінь має проводжати!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Ми рушили й пройшли в короткий строк
Із милю (на земну узявши міру),
Бо воля нам прискорювала крок,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Як вчули ми, що дух шугнув по ширу,
Та бачити його не довелось, -
Скликав на бенкет він любові й миру.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Ще, пролітаючи, промовив хтось
«Вина не імуть» голосом високим,
І вітром слово мимо понеслось.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Воно ще чулось в мороці безокім,
А вигуку «Орест - це я!» ушам
Було не втримати хоч ненароком.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Спитав я: «Батьку, що за голос там?»
Аж третій поруч пролунав поволі:
«Любіть того, хто зло вчиняє вам!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'І добрий вчитель: «В цім карають колі
Гріх заздрощів і душам завдає
Бич, плетений з любові, гострі болі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Вузда ж на грішників бряжчить своє,
І протягом покутної стежини
Подібних звуків, мабуть, сила є.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Та крізь повітря подивись на стіни
І ти побачиш, скільки тут сумних
Сидить, оперши о каміння спини».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Розкривши очі, я помітив їх,
Примушених до каменя тулиться,
В киреях, як на колір - кам''яних,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'І, підійшовши глянути на лиця,
Почув: «Маріє, помолись за нас!»,
«Михайле, Петре, всі святі, моліться!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Навряд чи хто знайшовся в наш би час,
В чиїх би грудях смуток не з''явився
Від тих, чий вигляд знов мене потряс,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Бо я, коли до них так придивився,
Що помічав їх кожний рух малий,
Відчув, як сум тяжкий крізь очі лився.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Здалось, в волосяницях всі були,
Підтримувані ближчого плечима,
І разом тиснулися до скали.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Так старцеві з незрячими очима
Під стінами розгрішних пожадань
Сліпий сусід чоло плечем підтрима,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Щоб не благанням і дощем ридань
Додати співчуття в серця високі,
А й жалюгідним виглядом страждань.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Як сонця не побачать сліпоокі,
Так небо глянуть не дало на світ
Цим тіням, лишеним у тьмі глибокій,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Бо вії в них в''язав залізний дріт,
Як шовк - в яструбеняти молодого,
Якому дику лють скоряє гніт.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Я бачив їх, не бачений, а з того
Занепокоївся, зніяковів,
І озирнувсь на вчителя свойого,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'А він таємним думам одповів
І, дозвіл давши мовити без страху,
Сказав: «Питай, але без зайвих слів».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Віргілій рухався тим боком шляху,
Де уповзала круча вниз крива
І зяяла безодня, повна жаху.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'По цей же бік здавалось, мов співа
Юрба страждаючих бездольних духів
І сльози бігли з-під жахного шва.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Звернувсь до них і: «Хто б мене послухав, -
Почав я, - з тих, хто сяєво здійма
Метою чистих всіх душевних рухів?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Хай найясніша благодать сама
Розвіє піну вашого сумління
Й очистить річку вашого ума!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Почути вас - моє палке стремління,
Чи тут латинські душі є, скажіть,
Щоб міг я вислухати їх веління?*'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = '«О брате, тут навічно всіх держить
Як жителів міських єдине місто,
До смерті ж хтось в Італії мав жить», -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Так голос десь озвався проречисто,
І я пішов на нього навпростець,
До тіней, що тримались, мов намисто.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Одна з них виявляла нетерпець...
Скажу на запитання: як же саме? -
Тяглась-бо підборіддям, як сліпець.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Сказав їй: «Душе, змалена сльозами,
Тобі, мабуть, хтось мову розріша, -
Хто ж ти і звідкіля, скажи словами».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = '«Була я сьєнка, - мовила душа, -
Між інших тут мене трима надія
Того діждатись, хто не поспіша.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Сама носила я ім''я Сапія,
Мене ж, Софії-мудрості на зло,
Про зло для ближніх тільки й гріла мрія.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Послухай, що мені колись було,
Й не думай, що про сказ тобі збрехала.
Як зморшки вкрили вже моє чоло,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Під Колле наша армія програла
І з бойовища у ганьбі втекла, -
Цього жадав їй Бог, а я благала.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Я радістю охоплена була
Найбільшою з усіх, коли навалу
Подужаних очима обвела,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Й, задерши в небо голову зухвалу,
Мов дрізд в одлигу: «Не боюсь тебе!» -
Гукнула Богу, збуджена до шалу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Хотіла потім врятувать себе,
Та боргом затулило б вхід чудесний
Розкаяній у небо голубе,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Коли б не П''ер Гребінник благочесний,
Який за мене сльози лив рясні
Й зродив надію на чертог небесний.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Але хто ти? Слова твої ясні,
Ти маєш очі широко розкриті
І дишеш мовлячи, здалось мені».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = '«У мене очі, - я сказав, - зашиті
Теж будуть, та недовго, согрішав
Із заздрощів не дуже я на світі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Не з тим я зовсім почуттям кружляв
Там, нижче, й розум мій, уяви повний,
Немовби камінь на мені лежав».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Сказала: «Хто ж твій провідник чудовний,
Що ти про поворот гадаєш свій?»
І я: «Оцей, хто тут стоїть, безмовний.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'Я теж, як всі, хто ще не вмер, живий.
І ти скажи прохання сокровенне,
Щоб я й для тебе крок зробив малий».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'Відповіла: «Це все нове й знаменне,
І ласка Божа на тобі сія,
Тож в молитвах не забувай про мене.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 49;

UPDATE terzinas SET text_uk = 'Всім найдорожчим заклинаю я:
Подбай, як знову підеш по Тоскані,
Щоб піднеслась між рідних честь моя,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 50;

UPDATE terzinas SET text_uk = 'їх знайдеш ти в пустоголових стані,
Де в Таламоне з порту вийшов глум,
Як з флотом на казковій річці Дьяні, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 51;

UPDATE terzinas SET text_uk = 'Бо в адміралах всякий легкодум».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 52;

UPDATE cantos SET title_uk = 'ПІСНЯ ЧОТИРНАДЦЯТА Друге коло. - Заздрісні. - Приклади покараних заздрощів'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 14
    AND p.name = 'Purgatorio';

UPDATE terzinas SET text_uk = '«Це хто повз нас іде, хоч ще навіки
Смерть не дала ширяти тут і там,
І розтуля, й склепляє він повіки?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = '«Не знаю, хто він, знаю, що не сам.
Ти ближче, так почни привітну мову,
Щоб не боявсь одповідати нам».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Так двоє тіней кинули по слову,
Одна одну старавшись підвести,
І підняли обличчя крізь закову.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Одна з них мовила: «О душе, ти
Прямуєш в небо, не лишивши тіла, -
Зроби ж нам втішну ласку, сповісти,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Звідкіль ідеш? І чим ти заслужила,
Що нагорода в тебе є така,
Яку дістати б кожна з душ хотіла?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'І я: «В Тоскані річка є вузька,
Що, свій початок взявши в Фальтероні,
Сто миль неутомимо протіка.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Там я з''явивсь у смертній оболоні,
А називать моє ім''я - дарма:
Його не досить знають ще сторонні».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = '«Як намір твій досяг мого ума,
То йдеться, зрозуміло всім, про Арно», -
Сказала тінь, що не була німа.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'І друга мовила: «Мабуть, не марно
Він зараз назву річки проминув?
Хіба про чудисько говорять гарно?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'І дух, який питання це почув,
Так одповів: «Не знаю: хай би скоро
Із річкою весь діл її загув!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Бо з витоку її із гір (Пелоро,
Одірвана від пасма висота,
Панує десь удалині просторо)'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'До вустя аж, що воду поверта
У море, звідки небозвід розвіяв,
А в річку знов вода зібралась та, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Цураються чеснот, неначе зміїв,
Чи то якесь нещастя в цих краях,
Чи інше щось-то плодить лиходіїв.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Ті, хто живе по клятих берегах,
Із власною природою не в ладі,
Мов паслись на Цірцеїних лугах.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Спочатку в порченім свинячім стаді,
Що гідне жолудів, не страв людських,
По вбогій річка ця тече леваді,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'А там стікає до дворняг лихих,
Гавкучих, та з негострими зубами,
І верне пику, зневажавши їх.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Чим далі, то скоріше мчить пісками
Зловісна, нещаслива річка ця
Серед собак, які стають вовками.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'І, визволившись раптом із кільця,
Біжить поміж шахраюватих лисів,
Що не бояться жодного сильця.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Я не замовкну, хоч той вуха звісив.
Хай пам''ята, що все це не байки,
Що справжній дух мої слова підвисив.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Я бачу, в гай край лютої ріки
Заходить твій племінник полювати,
А здобиччю йому стають вовки.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Та й ну живе їх м''ясо продавати
І різать їх, немов старих тварин, -
У них - життя, а честь - у себе брати.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'А гай стає з кривавих цих годин
Такий, що протягом тисячоріччя
Не зеленітиме ніколи він».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Мов той, хто, вражений сумною річчю,
Якийсь-то роблячи непевний рух,
Зміняє вираз радого обличчя, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Так і душа, напружуючи слух,
Вмить засмутилась, знітилась без сили,
Почувши, що промовив гнівний дух.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Слова цього й лице того збудили
До них мою увагу, я й спитавсь,
Як звуть їх і чого б вони хотіли.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'І дух, що з першим вигуком звертавсь,
Сказав мені: «Ти ждеш од мене звука,
Якого я від тебе не діждавсь.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Та Бог - твій захист і твоя зарука,
А благодать - як місяцевий лик;
Отож ти знай, що Гвідо я дель Дука.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Так пломінь заздрощів мене пропік,
Що як, бувало, бачу радість в кому,
Ти б в мене бачив зеленавість щік.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Я тут з того насіння й жну солому.
О людство! Чом кохаєшся ти в тім,
Коли йому завада - ось у цьомуі'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'А це - Ріньєр, якого знатний дім
Да Кальболі пригадує смиренно,
Бо не зрівнятись у чеснотах з ним'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Ані потомкам, що живуть шалено,
Ні всім, хто збудував собі житло
Між По й горою, й морем, аж до Рено.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Там всі ґрунти так зіпсувало зло
І стільки там отруйного коріння,
Що путнє щось уже б і не зросло.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Де добрий Ліцйо, Гвідо де Карпінья,
Манарді вчений, Траверсаро П''єр?
Перевелись романців покоління!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'В Болоньї замість Фабро хто тепер?
В Фаенці, перейнявши Фоско вдачу,
Хто б зріс в мізерії й величним вмер?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Тосканцю, не дивуй, що гірко плачу,
Як Гвідо згадую да Прата я,
А Уголіно д''Адзо де побачу?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Тіньйозо Федеріго де сім''я?
Споруди Анастаджі й Траверсарі
(Там спадщина чеснот їх, де й моя!)?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'А дами й рицарі! В якому чарі
Блискучих їх трудів і їх забав
Любов і чемність виступали в парі!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'О Бреттіноро'', чом ти не зникав,
Як вся твоя сім''я й ще дехто гідний,
Щоб ухилитись від злочинних справ?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Хвала Баньякавало - він безплідний.
А Кастрокаро - сором, Коньйо - теж,
їх замок стане всяким графам рідний.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'В Пагані знов родитимуть без меж.
Хоча їх Демон у труну з собою
Не візьме всю неславу їхніх веж.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'О Уголін де'' Фантолін! З тобою
Гаразд, бо вже нема чого гадать,
Що вкриє хтось твоє ім''я ганьбою.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Іди, тосканцю! Хочеться ридать,
А не казати про нащадків злого!
Такі думки лиш серце нам гнітять».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Ми знали, що шляхетні душі строго
Пильнують нас; вони були німі,
То значило, що ми знайшли дорогу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Нараз, коли ми рушили самі, -
Мов грім, що небо пронизав безкрає,
Розлігся голос у свинцевій тьмі:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = '«Хто стрінеться - мене забити має!»
І раптом щез, неначе грому вдар,
Що, хмару розпанахавши, зникає.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Ще слух наш не спочив од тих примар,
Як знов на всю загуркотало силу,
Неначе вдруге вдарило із хмар:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = '«Я -Аглавра, обернута на брилу!»
І крок назад ступив я, щоб зійтись
З поетом і вхопити руку милу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'Повітря заспокоїлося скрізь,
І він сказав: «Щоб людям не загинуть,
Міцні вудила їм би придались.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'Але ви кидаєтесь все поглинуть,
І вудка ворога вас тягне враз, -
Вузда й поради мудрі марно линуть.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 49;

UPDATE terzinas SET text_uk = 'На себе глянуть небо кличе вас,
Показуючи світ в красі блискучій,
А ви у землю дивитесь весь час, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 50;

UPDATE terzinas SET text_uk = 'За це вас і карає Всевидючий».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 51;

UPDATE cantos SET title_uk = 'ПІСНЯ П''ЯТНАДЦЯТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 15
    AND p.name = 'Purgatorio';

UPDATE terzinas SET text_uk = 'В ту мить, як третя скінчилась година
Й не відчинялось ще світань вікно
На сфері, жартівливій, мов дитина,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Як сонцю тут було, коли воно
До надвечір''я рухалося скоса,
А вдома північ залягла давно.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Проміння блиснуло нам просто в носа,
Тому що ми всю гору обійшли
Й світило нам на заході знялося.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Я, глянувши, що промені несли
Вогонь могутній тисячоязикий
І досі ще не бачені були,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Руками затулив собі повіки
І захисний зробив для зору вал,
І сяєво розбилося на бліки.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Як промінь, од води або дзеркал
Відбитий, скаче під небес склепіння,
Зберігши в цьому русі весь свій пал, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Цим і відмінний промінь від каміння,
В якого зовсім не високий скік,
Як нам посвідчує мистецтво й вміння, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'У мене вдарили за бліком блік,
І світло, хоч відбите, так засяло,
Що вмить я очі відвернув убік.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = '«Це що там, милий батьку, заблищало
Яскраво і нестерпно для очей, -
Спитав я, - й за хвилину більше стало?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = '«Засліплює тебе, як всіх людей,
Сім''я небесна, - відповів до мене, -
Вказать нам шлях і присланий оцей.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Ти скоро звикнеш бачити священне
Й блаженства з ним збиратимеш плоди,
Наскільки, звісно, це тобі здійсненне».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Ми ближче підійшли, і нам радий
Промовив ангел, чарівний на вроду:
«Тут ширше, ніж внизу, ідіть сюди!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Я вчув, коли ми рушили по ходу,
«Блаженні милостивії»; цей спів
Та й ще «Радій, звитяжцю» йшли зісподу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Підводячись з поетом, я схотів,
Аж поки досягнем щабля нового,
Послухати учителевих слів'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'І з запитанням підійшов до нього:
«Що дух з Романьї в думах мав своїх,
Казавши про заваду в цім для того?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'А він мені: «Його втягнув цей гріх
В запізно збагнену глибінь страждання,
І радить він уникнуть сліз гірких.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Вас із достатком зв''язують бажання -
Чим більше вас, тим менше припаде,
І з заздрощів народяться зітхання.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Коли ж любов до вишніх сфер веде
Угору ваше почуття безкрає,
То в ваше серце гіркота не йде, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Бо там чим більше кожен промовляє:
«Це спільне», - тим багатший він стає,
Тим більше милосердя в нім палає».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = '«Тепер потрібне слово знов твоє, -
Озвався я, - щоб обминуть облуду,
Бо сумнів серце сповнює моє.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Та як же так: бо шмат дрібніший буде,
Якщо ділить його на всю юрму,
Аніж коли б стояло менше люду».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'А він мені: «Даєш весь час уму
Вгрузати в щось, земних дрібничок повне,
І з світла завжди робиш ти пітьму.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Оте добро, безмежне й невимовне,
Яке в любов, у небеса стремить, -
Мов промінь, що на світло мчить чудовне.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Добра тим більшає, чим більш горить,
А милосердя ллється по потребі,
Отож чеснота виростає вмить.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Чим більше душ збирається у небі,
Тим більш любов єднає їх рої,
Що віддзеркалюють любов між себе.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Як неясні тобі слова мої,
То скоро Беатріче погамує
І ці, й всі інші запити твої.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Та поспішай, бо ще тебе плямує
П''ятірка літер, чистоти ж чола
Дійти сльоза покутна попильнує».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Хотів сказати я: «Тобі хвала...», -
Та вже на коло ми нове звелися,
І мова місце зорові дала.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'І тут мене мов підхопило в висі,
Й здалося, ніби я побачив храм,
Куди учені натовпом зійшлися.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'А жінка примовляла коло брам
По-материнськи ніжно: «Сину любий,
Чом стільки клопоту завдав ти нам?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Ми ж з батьком скрізь розшукували згуби,
Засмучені обоє». І пропав
Цей привид, як вона склепила губи.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Тоді в сльозах жіночий вид постав, -
Стає стражданням ця вода краплиста,
Коли її на очі гнів пригнав.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Казала жінка: «Як владар ти міста,
Що бились за його ім''я боги,
Бо квітне тут наука пломениста,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Скарай того, хто доні дорогій
Зухвало стан обняв, о Пісістрате!»
А чоловік, спокійний та благий,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'їй слово одказав ясне й крилате:
«Що ж візьмем для ненависті й злоби,
Якщо ми для любові хочем страти?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Я бачив шал нестямної юрби,
Як юнака вона каменувала
Під вигуки: «Добий його! Добий!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Він похиливсь під смертю, що поклала
Його на землю, а в його очах
Небесна брама ясно поставала.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Круг нього вирував убивства жах,
А він за вбивців у сльозах молився,
Звертавсь до Бога в болісних словах.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Коли від внутрішніх видінь звільнився
Й до зовнішньої дійсності вернувсь, -
Збагнув, що в мріях я не помилився.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'І проводир на мене озирнувсь,
Мов на розбудженого, й зауважив:
«То що тобі? Чого ти похитнувсь?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'З півмилі є, як ти раптово зважив
На щось стороннє й зразу шкутильгнув,
Немов себе вином чи сном обтяжив».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = '«О добрий батьку, ти б лишень почув
Що сталось, - мовив я, - мара побожна
Пробігла, поки я кульгавим був».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'А він: «Крізь сотню навіть масок можна
Побачити, мов крізь прозоре скло,
Твої думки, хай з них минуща кожна.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Не сховано від тебе це було,
Аби відкрив ти серце водам миру,
Що вилива предвічне джерело.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Не так питав тебе, як той, хто віру
В свій зір лиш має й квапиться спитать
В мерця, який упав на землю сіру.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Я ж запитав, щоб сил ногам надать.
Так треба спонукати бездіяльних,
Які марнують час чи просто сплять».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Ми тихо йшли до небокругів дальніх,
Віддаючись розмовам щирим тим,
У вечорових одблисках прощальних.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'Аж звідкілясь насунув раптом дим,
Хмариною, чорнішою від ночі,
Нас обгорнувши мороком густим.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'Цей дим заповнив нам легені й очі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 49;

UPDATE cantos SET title_uk = 'ПІСНЯ ШІСТНАДЦЯТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 16
    AND p.name = 'Purgatorio';

UPDATE terzinas SET text_uk = 'Тьма Пекла та беззоряної ночі,
Коли незміряної довжини
Хмарину чорну вихор мне й клубоче,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Не навела б тієї пелени
На зір мені, як дим цей непрозорий,
Такий жорстокий і такий жахний.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Вожай мій був на допомогу скорий,
А що не міг я розтулить повік,
То руку дав мені він для опори.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Немов сліпець, який держатись звик
Поводиря, чиє дбання щоденне
Від небезпек його рятує вік,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Я теж посунув крізь хмурне, шалене
Це димне місце за поводирем,
Що говорив: «Не відставай од мене».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Чув голоси я, молитви з плачем,
Щоб зглянувсь на покутних агнець Божий
І зняв гріхів обтяжливий ярем.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'І кожен вів мотив, на інші схожий,
А всі зливались в звуках чарівних,
Утворюючи ладний хор і гожий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = '«Учителю, то співи душ смутних?» -
Спитав я. Він.; «Ти вірно розмишляєш,
І вузол гніву - тут весь клопіт в них».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = '«То хто ж ти, що про нас так розмовляєш
І йдеш в диму між нашої юрми,
Мов час календами ще виміряєш?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Отак чийсь голос вимовив з пітьми.
Отож учитель проказав: «Озвися
Й спитай, чи зійдем нині вгору ми».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'І я: «Ти, що, очистившись, у висі
Творцеві принесеш прекрасний дух,
Зі мною йди, на чудеса дивися».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = '«Піду з тобою, поки вільний рух, -
Він одповів, - та в цім диму постилім
Потрібен нам не зір, а тільки слух».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'І я почав: «Нагору йду я з тілом,
Яке ще смерть не бралась розкладать,
І вже пройшов устріч пекельним силам.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'А що мене осяла благодать
І проводжати забажалось Богу
Стежками, що не дано всім топтать, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Не приховай, з чийого ти порогу,
Чого ж іще прошу від тебе я,
То це вказати нам з пітьми дорогу».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = '«Я був ломбардець, Марко на ім''я,
Любив чесноту, мудрості знайому.
Чи нині в них влуча стріла чия?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Хто обира наверх тропу відому?» -
Так мовивши, додав він: «Помолись
За мене, як дістанешся додому».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'І я: «Клянусь, якщо дійду колись,
Зробити це, та зараз дай пораду,
Бо знов у мене сумніви знялись,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Та ще й сильніші, на мою досаду,
Бо правда слів твоїх без боротьби
З недавно сприйнятим доходить ладу;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Чеснота зникла, повен світ ганьби,
Як сказане тобою те ж доводить.
Він дихати не може від злоби.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'А люд ніде пояснень не знаходить, -
Тож запитання не зневаж мого:
Чи то зірки, чи сам собі він шкодить?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Зітхання в нього стало зойком: «О!»
І він почав: «Ти мною не погребуй,
Та світ сліпий, і ти - дитя його.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Ви завжди все приписуєте небу,
Мовляв, зірки весь час і тут, і там
Всім рухають на власну лиш потребу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Тоді було б не дано зовсім вам
Свободи волі й вищої подяки
Діянням добрим, осуду - гріхам.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Зірки штовхають, не скажу - на всякий
Вас вчинок, а як навіть би й сказав,
То світло вирізня добра познаки.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Якби свободний вибір ваш повстав
Проти зірок уже в найпершім ділі,
То протягом життя б усе здолав.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Свободні, ви підлеглі вищій силі
Й природі кращій: вам вони дають
Думки, не зв''язані зірками в тілі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Тож світ звертають на неправу путь
Самі живі, у смертних вад в полоні.
Простеж, як докази до цього йдуть.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Не роджена душа лежить у лоні
Того, хто з нею, мов дівча ясне,
Все бавиться, тримаючи в долоні.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Душа простенька, тямлячи одне:
Як радісно було Творця їй бавить,
Вернути прагне щастя чарівне'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'І помиляється буває: славить
Мізерне щось, звеличує без меж,
Як нею вождь а чи вузда не править.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Потрібні, як вузда, закони; теж
Потрібні трони, звідки б додивлятись
У Місті правди до священних веж.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Закони є, та хто б за них мав братись?
Ніхто, бо чільний пастир хоч жує
І ремиґає, - він, проте, без ратиць.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Його ж отара верне на своє:
Як той же харч в вождя, що в неї зроду,
То іншого вона не визнає.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Отак призвів поганий напрям ходу
До того, що весь світ угруз в гріхах,
І винуватити не варт природу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'От Рим, що дав закони у віках,
Два сонця мав, по одному в окрузі,
Що світський осявали й Божий шлях.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Та перевищило одне в напрузі.
Меч воїнський і пастирське жезло,
Хоч зв''язані, але не стали друзі,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Стикаються безбоязно, та зло.
А що з насіння впізнають рослину,
Помисли, що із цього б нам зросло!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Де поять Адідже із По рівнину,
Колись жили там рицарства взірці,
А Федеріго як почав руїну,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'То сповнились підлоти землі ці,
Там убезпечені лише бувають
Тремтячі перед чесністю людці.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Ще, правда, там три діди доживають,
В яких юнак воює з стариком,
Та, щоб Господь покликав, дожидають:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Коррадо да Палаццо з добряком
Герардо й Гвідо да Кастель, якого
Французи звуть ломбардським простаком.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Тож всім скажи, що римська церква вбога,
Силкуючись зліпити двоє влад,
Бруднить обидві і себе ж до того».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = '«О Марко, - мовив я, - з твоїх порад
Узнав я правду і закон той слушний,
Що спадки взяв у Левієвих чад.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Хто ж цей Герардо, мудрий, благодушний,
Уламок згаслих прастарих колін,
Лихій сучасності докір незрушний?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'І він озвався: «Обійдись без кпин
Або спокус, тосканцю, бо, здається,
Що згинув добряка Герардо й тлін.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Інакше він ніде у нас не зветься,
Хіба ще Гаїним ім''ям святим.
Ну, далі я не йду. Хай вам ведеться!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'Я бачу, мерехтить зоря крізь дим.
Це ангел блискотить там поміж духів.
Мені ще рано зустрічатись з ним».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'Він так сказав і більш мене не слухав.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 49;

UPDATE cantos SET title_uk = 'ПІСНЯ СІМНАДЦЯТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 17
    AND p.name = 'Purgatorio';

UPDATE terzinas SET text_uk = 'Згадай, як в Альпах потрапляв, читачу,
Ти в хмару й наставала сліпота,
Що всю породу відзнача кротячу;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Й коли густа, волога пара та
Нарешті рідшала і мерехтіла
Ясного сонця смуга золота, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'То уявляв уже ти лик світила,
Як я уздрів цю силу вогняну,
Коли на заході вона світила.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Я руку вчителя свого міцну
Вчував, виходячи з тієї тучі.
Вже низ гори готовий був до сну.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'О ти, уяво! Мчиш мене на кручі,
Й нічого в захваті не чую я,
Хай з сотень сурм оркестри б''ють могучі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Тебе хто зрушить, як мовчить чуття?
Та зрушить світло, небесам властиве,
А Божа воля вишле з небуття.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Обернення на пташку нечестиве,
Щонайгарнішу між пташок-співух,
Враз уявилося мені мінливе.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Та, зосередившись в думках, мій дух
Від мене все стороннє геть відкинув
І зовсім знечутив мій зір і слух.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'В уяві десь розіп''ятий пролинув,
Що клекотіли в нім зневага, гнів,
Пиха, і, нерозкаяний, він гинув.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'А поруч грізний Артаксеркс сидів
Із вірною Есфір''ю й Мардохеєм,
Славетним щирістю і діл, і слів.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Пропали цар з царицею, з євреєм
Та з Аманом, як пара пропада,
Коли потік всихає, вкритий глеєм.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Лавінія з''явилась молода
В сльозах, із зойком: «Ой яка з тобою,
Владарко-мати, скоїлась біда?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Щоб не було розлуки із дочкою,
Себе ти вбила - й розлучились ми,
І не когось - тебе нема зі мною!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Як під нежданим світлом сон німий
Ховається в кутки, мов звір до пущі,
Вмираючи із залишками тьми, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Так зникли привиди скороминущі,
Коли засяло, мов зоря якась,
Яскравіша, ніж в нас зірки найдужчі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Вдивлявсь я в даль, що вільно простяглась,
Та голос мовив: «Тут є шлях нагору», -
Й моя увага вмить перенеслась.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Він гостроти надав моєму зору
Й бажання глянути на вістуна,
І в далину я озирнувсь прозору,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Але, як зіркість слабшає ясна,
Коли виходить сонячне палання, -
Ослабла так і в мене враз вона.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = '«Божественний цей дух не жде благання,
А любо вказує, що стежка там,
Сам, як завжди, ховаючись в сіяння.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Він робить те, що слід робити й нам:
Той, хто чекає на смиренну мову,
Ладен уже відмовить прохачам.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Хай ноги коряться звертання слову!
Скоріш ходім, завидна щоб дійти,
А то світанку ждати мусим знову».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Так вчитель мовив, повен чистоти,
І тільки я на сходинку квапливо
Ступнув, щоб швидше верха досягти,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Вчув обвів крил і мову чарівливу:
«Блаженні миротворці, бо в серцях
У них нема ненависного гніву».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Останній промінь, вказуючи шлях
Для ночі, високо в зеніт піднявся,
І зорі заблищали в небесах.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = '«О доблесте, чом я без сил зостався?» -
Казав собі я сам, бо відчував,
Як поступово з сходів уступався.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Нового кола східець там сягав,
Де стали ми, мов корабель на ріні,
Коли до берега свого він став.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Я вслухався, чи може звук долине,
А то злетить іздалека луна,
І вчителеві мовив по хвилині:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = '«Яка покутується тут вина,
Мій добрий батьку? Хай ослабли ноги, -
То в мене, в тебе ж мова ще міцна».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'І він: «Карає мляву до незмоги
Любов до блага - зміцнення її,
Бо ледар ледь веслом б''є шлях вологий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'До мене приверни думки свої
І, поки стоїмо, плоди чудовні
Збереш - од слів моїх урожаї.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Творець і твір любові завжди повні, -
Почав він, - знаєш, сину, цей урок -
В одміні чи природній, чи духовній.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'У першої немає помилок,
А друга чи у виборі, чи в силі
Зробити легко може хибний крок.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Та поки в неї є високі цілі,
Низькі ж не тиснуть душу без кінця,
Тоді гріховні втіхи їй не милі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Коли ж вона до зла веде серця
Або захоплює їх понад міру,
То твір тоді іде проти творця.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Ти бачиш, отже, що любов ту щиру
Слід розглядать як вічне джерело
І блага й зла, яке ламає віру.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Любов ця відганяє завжди зло
Од любого; тому й створіння Боже
Себе зненавидіти б не могло.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'А створена істота буть не може
Не зв''язана з Творцем міцним зв''язком,
І їй ненавидіть його негоже.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Отож ця думка правильна цілком.
Крізь вашу твань в любові шлях троїстий,
Любиме ж зло - для ближнього є злом.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Той сподівається ще вище сісти,
Як шани хтось позбудеться й жезла
І втратить владу й одяг урочистий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Той, щоб од нього слава не пішла,
Бо хтось до неї буцім став моститись,
Йому найгіршого бажає зла.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'А той од кривд не знає, де подітись,
Ненавидить когось палким чуттям
І дихає жадобою помститись.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Потрійна ця любов каралась там,
Внизу. Я ж мову присвячу любові,
Яка ганьбить ті блага зіпсуттям.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Всі, блага прагнучи на кожнім слові,
Щоб душу заспокоїти в житті,
Його шукать собі хоч де готові.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Холодні, мляві, неретельні, ті,
У кого в серці забарне горіння,
Спокутують отут, по каятті.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Ще благо є - без щастя, без радіння,
Воно не є щасливим та ясним,
І не благі в нім суть, плоди й коріння.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Любов, що надто упада за ним,
Спокутується в колах трьох горішніх,
А що їм дано, трьом шляхам смутним, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Я не скажу: побачиш сам на грішних».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 47;

UPDATE cantos SET title_uk = 'ПІСНЯ ВІСІМНАДЦЯТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 18
    AND p.name = 'Purgatorio';

UPDATE terzinas SET text_uk = 'Великий вчений закінчив промову
І пильно в очі зазирнув мені,
Питаючись, чи маю сумнів знову.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Мене пекли цікавості вогні,
Та я мовчав, а у собі карався:
«Йому набридли розпити смішні».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Помітивши, що більш я не питався,
Хоч і жадав, - мій батько дорогий
Мене зохотив, бо до мене вдався.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Тоді я: «Вчителю, дає снаги
Твій пломінь, щоб ці очі розгляділи
Усе, чому ти надаси ваги.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'То, може, ще розкажеш, батьку милий,
Про ту любов, що ти до неї звів
Усі - благі і протилежні - сили».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = '«Спрямуй сюди свій ум, - він одповів, -
І помилки збагнеш тих сліпооких,
Що іншим стали за поводирів.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Бо, створена для почуттів глибоких.
Душа стремить приємному устрій,
Потрапивши в полон утіх високих.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Тоді ваш розум уявляє річ
І вимальовує її звабливо,
Аж та ввижається душі увіч.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Як пристрасть виросте, стає на диво
Любов''ю, ба природою вона
Й захоплює в утісі вас жадливо,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'І, як вогонь, спахнувши, почина
У небо прагнути, ген-ген у висі,
Бо там навкруг - його речовина,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Так квапиться душа віддатись втісі -
Не терпить цей духовний рух оков,
Аж поки мрії всі ще не збулися.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Тепер наочно бачиш ти, що знов
Неправду твердить дехто незугарний,
Мовляв, похвальна всяка в нас любов.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Усяка-бо любов, на погляд марний,
Є гарна зроду - а бува, на глум,
Негарним виливок, хоч віск і гарний».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = '«Твої слова і мій уважний ум
Поняття склали про любов чудовні,
Та не розвіяли непевних дум, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Сказав я: - Як любов приходить зовні,
То для душі заслуги в тім нема,
Чи праведні в нас вчинки, чи гріховні».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'А він: «Скажу усе щодо ума,
А з іншим всім, до віри приналежним,
То Беатріче справиться сама.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'В сутті, од речовини незалежнім,
Та з нею в непоривному зв''язку
Є здатність із могуттям необмежним.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'її не видно в жодному кутку,
А виявляється вона у чині,
Немов життя рослини у листку.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'На першого осягнення причині
Не знаєтесь - вона в запоні мли,
Як перших пристрастей ті глибочіні,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Що в вас існують, наче у бджоли
Потреба медом повнити колоди, -
Й водінням цим - ні гани, ні хвали.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Для згоджування з волею, з природи
Закладено в вас здатність міркувать,
Що помага вам на порозі згоди.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Отож у вас є змога обирать
І змога є щоразу осягнути,
Чи буде з цього зло, чи благодать.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Хто мислить і досяг самої суті,
Той вроджену свободу визнає,
На ній мораль оперта має бути.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Коли ж любов велика настає
Лише тому, що неминучість кличе, -
Ви вільні погасить чуття своє.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Цю благородну здатність Беатріче
В слова «свобода волі» убира.
Не забувай цього при вашій стрічі».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Над північ до високого шатра
З''явився місяць, розігнавши зорі,
Сліпучіший од мідного відра,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'І рушив небом по тропі прозорій,
Де сонце йде тонуть, як бачить Рим,
Між сардів з корсами в вечірнім морі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Шляхетний дух, що П''єтола із ним
Найбільш славетна в Мантуанськім краї,
Ізняв тягар у розумі моїм.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Пропали дум непевних чорні зграї.
Я був після поетових речей,
Мов той, хто пада з ніг, бо засинає.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Та раптом сон утік мені з очей,
Коли почувся ззаду крик шалений.
До наших наближаючись плечей.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Як береги Асопу та Ісмени
Колись вночі дивилися на біг
Фівян у празник Бахуса священний,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Так в цьому колі бачити я міг,
Що добра воля та любов погнали
Покутні тіні по кільцю доріг.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'І зараз же повз нас вони промчали
В нестримнім потягу до чистоти,
І дві з них перші у сльозах кричали:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = '«Марія в гори квапилася йти,
А Цезар, не затримавшись в Марсільї,
В Ілерду поспішав - перемогти».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = '«Мерщій, мерщій! Не гай часу в свавіллі
Та без любові, - так гукав ще хтось, -
Зазеленіє благодать в зусиллі».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = '«О душі, в кому полум''я знялось
Там, де раніш не жевріло нічого,
Ані чуття до іншого когось,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Цього - кажу я правду вам - живого
Піднятись на вершину порива,
То де найближчий є тут шлях для нього?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Такі були вождя мого слова,
І хтось із духів одповів: «За нами
Ідіть - там отвір сходи відкрива.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Такі ми повні світлими чуттями,
Що не спиняємось; і я б тужив,
Якби нечемним здався перед вами.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Абат в обителі Сан-Дзено, жив
В Вероні я при добрім Барбароссі,
Який в Мілані скорб та сум лишив.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'А той, кому ногою довелося
В могилу стать, оплаче монастир
І лад, який панує в ньому досі,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Бо син його, спотворений на взір
Породою, і тілом, і душею,
Найменше дбає про любов та мир».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Можливо, тінь гукала ще; за нею,
Проте, ми йшли на відстані значній,
А це зберіг я пам''яттю своєю.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'І той, хто був порада й провід мій.
Сказав: «Поглянь, як на бігу ці душі
Укусів завдають нудьзі жахній».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = '«Ті, хто пройшов по морю, як по суші, -
Гукало двоє, - в мандрах полягли,
Йордан же сприймуть юні очі й уші.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Ті, що відмовились і утекли
Од подвигів Анхізового сина,
Себе ганьбі повсюдній прирекли».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Коли од них звільнилася стежина,
Бо всіх поспішливих заніс порив,
У мене думка виникла єдина,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'А з неї кольористий рій злетів -
Таке було цікаве різновиддя,
Аж очі із утіхи я закрив,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'І думи обернулись на сновиддя.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 49;

UPDATE cantos SET title_uk = 'ПІСНЯ ДЕВ''ЯТНАДЦЯТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 19
    AND p.name = 'Purgatorio';

UPDATE terzinas SET text_uk = 'У час, коли не линуть рештки спеки
До Місяця, бо в зоряних полях
Долають їх Земля й Сатурн далекий;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Коли зі сходу йде по небесах
Фортуна геомантова велика,
А ззаду вже ясніє сонця шлях, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Мені приснилась жінка - недоріка,
Кульгава, косоока та без рук,
Обличчя ж мала, як той мрець-каліка.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Я розглядав її, і, мов той сук
Під сонцем кригу паростком ламає,
Під зором тим ліг зрозумілий звук'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'їй на язик; я вздрів, що стан спрямляє
Вона, і краска грає на лиці,
Як почуття любовне вимагає.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Вона, знайшовши звук на язиці,
Співати стала так, що полонена
Була моя увага в цім сильці.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = '«Я, - почала, - я ніжна та сирена,
Чий спів людей чарує в млі морській,
І тьмарить розум їх жага вогненна.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'З дороги звів Улісса голос мій,
І всіх принадить тих моя щедрота,
Хто в пісні закохається моїй».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Спокусниця ще не закрила рота,
Як заступила враз її сильце
В жіночу постать втілена чеснота.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = '«Віргілію, Віргілію, хто це?» -
Вона сказала. Він же приступився,
Вдивляючись у пресвяте лице.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Роздерши одяг, що на грудях збився,
Вона весь оголила їй живіт,
І я від смороду аж підхопився.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Коли я знову подививсь на світ,
Поет сказав: «Будив тебе я тричі,
Шукаймо шлях до бажаних воріт».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Я встав, і далі рушили ми швидше.
У сяйві дня сіяла висота,
З-за спин же сонце сяло на узбіччі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Я ззаду йшов, немов людина та,
В якої голова з думок похила,
Мов половина арки у моста,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Коли якась промовила нам сила:
«Ви підійдіть, тут сходи», - і в посла
Небес у мові лагідність яскріла.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Мов лебідь, розпростер він два крила,
Провів нас обережно за стіною,
Що грізну кручу колом обнесла.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Змахнув пером по лобі й наді мною,
«Блаженні плачущії, з їх-бо сліз, -
Сказав, - зросте їм радість супокою».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = '«Чому замислився, уткнувшись вниз?» -
Спитав вожай, коли пішли ми вгору,
А вісник одлетів у блиску риз.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'І я: «Такого у думках роздору
Через останню я зазнав мару,
Що під ногами загубив опору».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = '«Побачив чародійку ти стару, -
Сказав він, - пані у подальших колах?
Побачив, як її розкрити гру?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Та кинь; стопою бий по скелях голих,
Не зводь очей з примани, що кружить
Цар вічно буде в вічних видноколах».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Як сокіл поглядає, що лежить
У пазурах, і, на мисливця слово
Зірвавшись, вмить до здобичі спішить, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Так я, з тих слів наснагу мавши знову,
Нарешті подолав східцями схил
Крізь кам''яну вузьку й круту закову'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'І, опинившись в п''ятому із кіл,
Побачив душі, що лежать в риданнях,
Лицем у ґрунт, явивши небу тил.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'І шепотіли у гірких стражданнях
Вони: «Прильпне душа моя землі», -
І потопав псалом в сумних зітханнях.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = '«Обранці, в кого муки не малі
Маліють з мрій про правосуддя вище,
Порадьте шлях на дальші нам щаблі!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = '«Коли ви не лежать, а далі йти ще
З''явились, кожен з вас свій крок направ
Десницею до крутояру ближче».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Питав поет, і нам відповідав
Хтось спереду, і уловив я в очі
Того, хто співрозмовником нам став.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Я в вічі глянув вчителю, й охоче
Він рухом дозвіл дав на те мені,
Чого, як зір мій промовляв, він хоче.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Виконуючи думи потайні,
До того підійшов я запитати,
Чиї слова подобались ясні,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'І мовив: «Душе, молиш благодаті,
Без неї ж не піднімеш голови,
Та перестань хоча б на мить ридати.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Хто був ти? Ниць чом лежите всі ви?
Чим помогти тобі, коли між люди
Вернусь туди, звідкіль іду живий?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'І він мені: «Ти взнаєш суть осуди,
Та перш скажу: Петра наслідник бих
Апостола я, відомо ті буди.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'В містечках Сьєстрі й К''явері пласких
Біжить ріка, що з титулом високим
Дала наймення для моїх близьких.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Строк понад місяць був достатнім строком,
Щоб тим тягар священних шат збагнуть,
Хто дбає не вбагнить їх ненароком.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Я пізно, леле, взнав блаженства путь!
Коли я римським пастирем зробився,
Відчув, що нам життя облуди гнуть,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Що в мене в серці мир не воцарився
Й нема його у смертному житті, -
І смуток за довічним розгорівся.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Моя душа далека в сліпоті
Була від Бога, в скупості потворній, -
І тут вона за вини не пусті.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Найгірше скупості судилось чорній,
Бо не підносити в молитві лиць -
Найтяжча з кар на скелі неозорній.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'А що в нас очі до земних дрібниць
Були прип''яті, а істота скута,
То справедливість нас повергла ниць.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'І що у нас вгасила скупість люта
До блага потяг, добрі вчинки з ним,
То справедливість руки й ноги в пута'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Нам закувала присудом грізним,
Аж поки Бог не явить справедливий
Своєї ласки прощеним, ясним».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Хотів привіт сказать я шанобливий
Навколішках, і тільки став я, дух,
Зачувши, взнав про порух мій поштивий'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'І мовив: «Та навіщо цей твій рух?»
А я йому: «Така достойність сану,
Що стоячи тебе не сприйме слух».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = '«Ти, брате, встань! Всі одного ми стану, -
Одмовив він, - усе я там лишив,
Ми всі єдиному слугуєм пану.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Коли з євангельських виходиш слів:
«Не женяться», - то кривосуд знімаєш
Із tofo, що я тут проголосив.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Тепер ступай, куди ступати маєш, -
Сліз при тобі не можу лити я,
А в них засада щастя, сам ти знаєш.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'Небога добра на землі моя,
Аладжа, є, - аби чого лихого
її не вивчила моя рідня;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'А більше в мене там нема нікого».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 49;

UPDATE cantos SET title_uk = 'ПІСНЯ ДВАДЦЯТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 20
    AND p.name = 'Purgatorio';

UPDATE terzinas SET text_uk = 'Скоряється в нас воля кращій волі:
Як папа змусив - мусив я з зіниць
Взять губку, не насичену доволі,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Й піти з вождем, що між простертих ниць
Ступав до скелі ближче по стежині,
Мов на фортечнім мурі вздовж бійниць.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Бо душі, випускавши по сльозині
Все зло, яким укритий цілий світ,
Лежали покотом по широчіні.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Прокляття їй, вовчиці давніх літ,
Чия жадливість всесвіт упихає
В огидний та ненатлий свій живіт!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'О небо! Все рухоме протікає,
Ти змінюєш його в земних речах, -
Коли ж той прийде, хто її злякає?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Ми обережно обирали шлях,
І з жалем слухав я, як люд цей скніє
У стогонах, у лементі, в сльозах.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Десь перед нас: «О благосна Маріє!» -
Почув я зойк, і згадка враз прийшла,
Як породілля у переймах мліє.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'А голос вів: «Убого ти жила, -
Ми ясно бачим ясла у повітці,
Де ноша пресвята твоя лягла».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'І ще почув я: «О, колись Фабріцій
Дав перевагу бідній чистоті
Перед багатством у скверноті ницій!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Сподобались мені думки прості,
І я на тіні став дивитись доти,
Аж поки взнав, хто вів слова оті.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'А він розповідав, які щедроти
Явив невинним дівам Миколай,
Щоб не згубили юності й чесноти.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = '«О красномовний душе, не ховай,
Хто був ти, - проказав я, - і для чого
Повторюєш хвали, відповідай.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Оддячу я, коли вернусь для того,
Щоб довершить коротку путь життя,
Яке спішиться до кінця сумного».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'А він: «Хоч допомоги жду і я,
Вшаную благодаті я зусилля,
Що й тут твоє продовжують буття.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Я коренем триклятого був зілля,
Що на просторах християнських піль
Затінням губить все живе бадилля.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Молю того, хто судить все суціль:
Нехай кривавим відомстять бенкетом
За кривди Брюгге, Гент, Дує та Лілль!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Я звався за життя Гуго Капетом,
Мій рід до трону стежку вторував,
Дивуючи весь світ високим злетом, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'А дід в Парижі м''ясом торгував.
Коли згасали королі французів,
А з них останній рясу надягав,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Я так в руках вузду правління звузив
І стільки мрій плекав у голові,
А навкруги юрмилось стільки друзів,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Що став мій син короні-удові
Укоханим, а там линула злива
Посвячених у королі нові.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Аж поки кров мою звела манлива
Прованська, взята в посаг, оболонь,
Не варта кров була та й не шкідлива.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'А там грабіж скрізь понесла й вогонь,
Спочатку зжерла, на відшкодування,
Понтьє, Нормандію, взяла Гасконь.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'До вас Карл вдерся й, на відшкодування,
Вбив Куррадіно, а тоді й Фому
Вернув на небо, на відшкодування.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Ще прийде - знаю, статися тому -
Новий французький Карл на ваше поле
Уславити себе й потомків тьму.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Ще не приходив так ніхто й ніколи,
І списом юдиним в руках брудних
Він черево Флоренції проколе.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Здобуде ж він не землі - стид і гріх,
Тим важчий і тим більше непрощенний,
Що легшим він здававсь йому з усіх.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Того ж, хто буде в морі полонений,
Я бачу, як він доню продає,
Торгуючись, немов корсар злиденний.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'О скупість, тож в тобі принади є
Могутні, для мойого роду милі..
Аж тіло той занедбує своє!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Хай інші злочини всі мерхнуть в силі!
Я бачу, як Христа в заміснику
Ув''язнюють в Аланьї квіти лілій.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Я бачу їх злорадісність низьку,
Я бачу жовч із оцтом у солдата
І смерть між двох розбійників близьку.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Я бачу ще новітнього Пілата,
Якого зваблять скарби в далині,
Де здобич в храмі блискотить багата,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Коли ж чекати, Господи, мені
На мсту твою, до певної години
Приховувану з гнівом в таїні!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Звертання ж до єдиної дружини
Святого духа, що почули ви,
Як вас вона ввела на ці стежини,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Ввіходить в наші денні молитви.
Коли ж ми бачимо нічну заслону,
За приклад беремось щораз новий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'і Увагу віддаєм Пігмаліону,
Що, за багатством гнавшись, батька вбив.
Став зрадником, порушником закону;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Мідасу, охоронцеві скарбів
І скупію з обличчям прегордливим,
Що з нього всесвіт посміхи зробив;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Іще Ахану з потягом жахливим
До вражого майна, який Навін
Карає й досі гнівом справедливим.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Шлемо Сапфірі й мужеві проклін,
Хвалу коню, що збив Геліодора.
Гуде гора у криках всіх колін,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Що Поліместор - вбивця Полідора,
У вигуках: «Гей, Красе, смак який
У золота? Дай відповідь нам скору!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Той тихий в бесідах, цей - гомінкий,
Хто мовить з примусу, а хто - охоче,
На вдачу хто упертий, хто - м''який.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Пригадуємо благо, що до ночі
Про нього ми розмови всі вели,
Сказати ж голосно - ніхто не хоче».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Ми досить вже далеко відійшли
Од тіні, надолужуючи втрату,
І поспішали вгору як могли,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Коли нараз почувся грім розкату,
Гора здвигнулася під ноги нам,
І я закляк, мов той, хто йде на страту.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Так не хитався навіть Делос сам
До того, як Латона під горою
Знайшла в гнізді два ока небесам.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'І тут такий розлігся над юрбою
Могутній крик, що вчитель озирнувсь,
Промовивши: «Не бійся, я з тобою».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Та «Слава в вишніх Богу» - спів почувсь,
Наскільки шум збагнув я стоязикий,
Коли він біля мене розітнувсь.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Завмерли ми; наш подив був великий,
Як той, що вперш до пастуха прийшов;
Але ущухли землетрус і крики.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'В святу дорогу рушили ми знов,
А тіні, заспокоївшись помалу,
Вернулися до скарг і молитов.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'Як в пам''ять глянути мою несталу,
То вперше у житті відчув я вмить
Страшенної цікавості навалу,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 49;

UPDATE terzinas SET text_uk = 'Але не міг її задовольнить, -
Ні розпитатись, вгору поспішивши,
Ні сам як слід що-небудь зрозуміть.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 50;

UPDATE terzinas SET text_uk = 'І так я йшов, од незнання терпівши.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 51;

UPDATE cantos SET title_uk = 'ПІСНЯ ДВАДЦЯТЬ ПЕРША П''яте коло. - Скупі. - Стацій. - Пояснення причини землетрусу'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 21
    AND p.name = 'Purgatorio';

UPDATE terzinas SET text_uk = 'Природної тієї спраги сила,
Яку вгасить могла б вода лиш та,
Що самарянка дати їй просила,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Терзала й за вождем вела свята
Мене поміж повалених нещасних,
Котрих скарала права Божа мста.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Як у Луки воскреслий, в ризах ясних,
Христос явився по дорозі двом
У сяйві невмирущих рис прекрасних, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Так нам явився дух: ішов слідом
В юрбі скорботній, до землі похилій,
І непомітний був для нас цілком,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Аж поки мовив: «Мир вам, браття милі!»
^озирнулись ми, і привітав
Його рукою лагідно Віргілій,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Сказавши: «Суде істини, направ
Тебе у сонм блаженних душ назавше,
Якої милості мені не дав».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = '«Тож, тіні, як? - він мовив, нас догнавши, -
Бог не пуска вас до небес своїх,
Хто ж вас провів сюди, угору знявши?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'І вчений: «Придивись до знаків тих,
Що ангел в цього написав на лобі,
Побачиш - буде він поміж святих.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Та, що пряде вам нить, весь час в жалобі,
Не закінчила кужеля життя,
Що дасть Клото, і він іще не в гробі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Його ж душа, сестра твоя й моя,
Не в силі одинока крокувати,
Бо не така зірка, як ти чи я.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Тож мушу з пащі Пекла мандрувати,
Веду його і буду скрізь вести,
Аж доки стане вміння керувати.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Але скажи, напевне, знаєш ти:
Чому гора здригнулась в землетрусі
І крик зчинивсь до моря з висоти?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Мені він у голчане вушко скрусі
Цим запитанням влучив, і жага
Поменшала в надії та спокусі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'А. той почав: «Оця гора блага
Й на мить з покори небу не виходить,
Інакше б не була його слуга.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Ніщо ніяк не може їй пошкодить,
А грюк цей означає, що з землі
Своє в свою оселю Бог заводить.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Нема дощів, ні снігу в зимній млі,
Ані роси, ні інею, ні граду,
Коли минути три вузькі щаблі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Тут неба хмари не беруть в обладу,
Окремі чи густі, ні блискавки,
Ні Тавманта дочка, легка на зраду.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Сухої пари-бо не йдуть струмки
Над східці, об які спирає ноги
Осяйний брамник, до Петра близький.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Тремтять, можливо, низ гори й відроги,
Бо вітер глибочінь земну лиша,
Та поштовхи безсилі над пороги.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Гора ж тоді тремтить, коли душа
Підводиться, очищення відчувши,
Й під наші співи в небо вируша.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Коли вона, покути строк відбувши,
Спонукується волею іти
Й радіє, справжню волю осягнувши,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Бо доти прагненням до чистоти
Карала Божа правда душі кволі
За потяг до гріховної мети.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Я, лежма зносячи нестерпні болі
П''ять сотень літ і більше, враз відчув
Можливість звіритись свободній волі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Тоді-от землю поштовх і струснув,
І стали Господа молить блаженні,
Щоб ласку він свою й на них звернув».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Так мовив він. І радощі вогненні
Мене тут охопили, й не скажу,
Які приніс він втіхи нескінченні.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'І мудрий вождь: «Із слів твоїх суджу,
Які навколо вас сітки й закови,
Чом раді всі, як пройде хтось межу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Та хто ти був? Я слухати готовий.
Чом ти лежав століттями, промов,
Щоб я усе збагнув з твоєї мови».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = '«В добу, як добрий Тіт карати йшов
З помогою найвищого владики
За продану Іскаріотом кров,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Я титул ніс незмінний і великий, -
Одмовив він, - прославленим митцем
Вважався я, та був у вірі дикий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Такий я хист мав* що своїм співцем
Мене, тулузця, визнав римський форум
Та ще й оздобив миртовим вінцем.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Ще й досі Стація всі славлять хором:
Співав про Фіви й за Ахілла взявсь,
Але в дорозі впав під другим твором.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Мій запал тим жаринам розкривавсь,
З яких вогонь священний пломениться,
Що в сотнях серць раніше розгорявсь.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Кажу про «Енеїду», - годівниця
І мати це в поезії мені,
Без неї в мене все було б дрібниця.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'За те, щоб жити в ті щасливі дні,
Коли Віргілій жив, я б дав охоче
Сонцевий строк в обителі ясній».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Віргілій повернув до мене очі,
Немовби мовчки наказав: «Мовчи!»
Та воля може не усе, що хоче.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'За почуттями сміхи та плачі
Так швидко йдуть, що з воль найбільш висока
Не завжди встигне піднести бичі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'І я, мов той, хто хитро мружить око,
Всміхнувсь, а він у вічі подививсь,
Бо частка видна в них душі глибока,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'І: «Боже, дай, щоб вдало закінчивсь, -
Сказав, - твій задум, та чого несмілий
У тебе відблиск усмішки з''явивсь?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Я опинився між двома, безсилий,
Бо той забороняв, благав же цей, -
Тож я зітхнув, і мій учитель милий'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Збагнув мене і: «Ти не бійсь речей, -
Він мовив, - бо схвильований він дуже.
З''ясуй цікаве для його очей».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'І я тоді: «Ти, стародавній душе,
Дивуєшся, що посмішку зустрів,
Та я ще більш твої здивую уші:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Отой, хто вгору зір мені підвів,
Це й є Віргілій, в кого ти навчався
Оспівувати смертних і богів.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Отож, коли в чому ти сумнівався,
То сумніви свої, прошу, вздкинь -
Із збігу я кумедного сміявся».'''
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Учителю, подавшись на ступінь,
Припав до ніг він, той же мовив: «Брате,
Згадай, що тінь ти сам і бачиш тінь».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'І він, підводячись: «Таке багате
В мені чуття до тебе збереглось,
Що я забув становище закляте,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Вважаючи мару за справжнє щось».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 46;

UPDATE cantos SET title_uk = 'ПІСНЯ ДВАДЦЯТЬ ДРУГА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 22
    AND p.name = 'Purgatorio';

UPDATE terzinas SET text_uk = 'Уже лишився ангел десь за нами,
Той ангел, що вказав нам дальший шлях
І на моїм чолі торкнувся плями,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'І ті, що правду носять у думках,
Сказали ніжним голосом: «Блаженні...»
Ще й «жаждущії» - та й по цих словах.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Цей дотик ще ваги забрав у мене,
І я скоріш, як досі, вгору йшов,
Куди вели співці благословенні.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Віргілій розпочав: «Одна любов,
Запалена до цнот, запалить другу,
Як зовнішній вогонь її зборов.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Відколи розповів на всю округу
Про тебе в нас у Пеклі Ювенал,
Що ти віддав любов мені, як другу,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Я теж відчув до тебе в серці пал,
Хоча тебе ніколи я й не бачив, -
Гадаю, й тут заслужиш ти похвал.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Прошу, щоб ти по-дружньому пробачив
За неміцну вузду на язиці,
А я б тобі по-дружньому віддячив.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Розвій же хмару на моїм лиці:
То як же ти на скупості спіткнувся,
Якщо тебе навчали мудреці?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'На те звертання Стацій усміхнувся
І вожаєві мовив моєму:
«Радію, що з тобою я зіткнувся.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'А й дійсно, правди не знайти тому,
Хто прагне роздивитися у тому,
Що видно зовні, всю глибинну тьму.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Вважаєш, мабуть, що гріху тяжкому
Жадливості в житті я віддававсь,
Бо в колі здибав ти мене такому?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'То знай, що скупості я опиравсь
Усе життя, а час настав понурий -
Багато місяців за це каравсь.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Якби я проминув твій вірш похмурий,
Цей досконалий вияв чистоти,
Обуреної з нашої натури:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = '«Чом не керуєш смертним серцем ти,
Жаги до золота нелюдська сило?»
Я б мав кружляти в люті і клясти,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'А так я взнав, які широкі крила
У щедрих рук, забув про грошей дзвін,
Про всі гріхи, що їх душа носила.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'О, скільки лисих встане з домовин,
Бо через совість, незнанням закуту,
І каяття з них не зняло провин!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'І знай, що вада відбува покуту
Таку ж гірку, як протилежний гріх.
І там же всушує свою отруту.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Тож лиш того я опинивсь між тих,
Кому на плечі люта скупість тисне,
Що в мене вдача не така, як в них».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = '«Ти оспівав нам війни, люттю звісні,
І сліз Йокастиних подвійний струм, -
Сказав співець пастушачої пісні, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Тож плід натхнень Кліо не ствердить дум
Що віра, без якої добре діло -
Ніщо, ввела тебе до вірних в тлум.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Раз так, яке ж то сонце чи світило
Роздерло тьму в тобі й ти постернив
На човен рибаря своє вітрило?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'І він йому: «Це ти мене привів
На вславлену Парнаську верховину,
А потім і до Бога напутив.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Ти діяв так, як той, хто на стежину,
Якою інших поночі веде,
їм світить, беручи вогонь за спину.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Сказав ти: «Час оновлення гряде,
Вертають Правда й перший вік у мирі,
Поріддя сходить з неба молоде».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Твій син у віршах, я твій син і в вірі.
Щоб все ти осягнув, додам зусиль
І вкрию фарбою малюнки сірі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Вже сповнивсь світ до океанських хвиль
Христовим словом, ним-бо засівали
Посли святого царства все суціль.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Отим твоїм думкам відповідали
Слова, що їхні вчителі вели
І рідними за те мені ставали,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Бо в правилах таких святих жили,
Що, як Доміціан почав їх гнати,
Без мене сліз кривавих не лили.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Не припиняв я їм допомагати
Увесь земного існування строк,
Вільніших сект одкинувши багато.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Ще вів своїх я греків до річок
Фіванських, як прийняв хреста на себе,
Та з боязні приховував свій крок'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Під маскою поганства більш як треба, -
За цю байдужість четверо століть
Четвертим колом кодував до неба.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Нам довгий шлях тут для розмов лежить.
І ти, хто місце, де хвали невгавні,
Мені колись зміг приязно розкрить,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Скажи тепер: а де Теренцій давній,
Цецілій, Плавт, Варрон, - де всі вони?
В якому колі мучаться преславні?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'І вождь мій: «Персій, я, ще гурт ясний
Із нами, й грек, що музи краснолиці
Йому лиш харч давали чарівний, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Всі в першім колі хмурої темниці
Вчащаємо у думці до гори,
Де пробувають наші годівниці.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Там з Антіфоном Евріпід старий
І з Сімонідом поруч Агатона
Ще сила греків славної пори.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'А з тих, що оспівав ти, - Антігона,
Аргія, Деїфіла, дотепер
Засмучена Ісмена безборонна;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Ще й няньку, хлопчик у якої вмер,
Стрічав, дочку Тіресія, Фетіду,
Деїдамію між її сестер».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'І мова їм урвалася без сліду,
Бо в мурі ми пройшли останній крок
І нам краса відкрилась краєвиду.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Служницям першим дня вже вийшов строк,
І п''ята, взявши дишель колісниці,
Підводила розжеврений ріжок,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Коли вожай: «Немає тут різниці,
Спішім, як перш, щоб південь не потух,
До прірви обертаючи правиці».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'За звичкою ми й почали свій рух
Упевнено, а надто як до ладу
З тим згодивсь другий чеснотливий дух.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Вони вперед ішли, а я позаду
З їх бесід вчився, як тлумачить слід
Високої поезії відраду.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Та, перервавши їм розмови хід,
Враз перед нами дерево постало,
Яке вкривав пахучий ніжний плід.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Чим більше в височінь воно сягало,
Тим, як в ялин, коротшало гілля, -
Мабуть, це лізти вгору заважало.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'А з кам''яного муру, побіля,
Струмок спадав, блискучий та краплистий,
І ним скроплялись зелень і земля.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'І підійшли під велет ряснолистий
Поети, і почули голос там
Погрозний, владний: «Вам цього не їсти!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'І ще: «На святі не своїм устам
Марія, що до всіх любов''ю дише,
Хотіла догодити всім гостям;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'Колись-то римлянки в воді лиш свіжій
Утіху мали; Даниїл-звіздар
Здобув собі знання, як зрікся їжі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 49;

UPDATE terzinas SET text_uk = 'Для голоду був жолудь - неба дар
У перший вік, що золотим був віком,
Для спраги ж не вода текла - нектар.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 50;

UPDATE terzinas SET text_uk = 'Хреститель сарану їв з медом диким,
В пустелі живши, віддалік од міст,
І став таким славетним та великим,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 51;

UPDATE terzinas SET text_uk = 'Як свідчить нам святий євангеліст».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 52;

UPDATE cantos SET title_uk = 'ПІСНЯ ДВАДЦЯТЬ ТРЕТЯ Шосте коло. - Обжерливі. - Форезе Донаті'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 23
    AND p.name = 'Purgatorio';

UPDATE terzinas SET text_uk = 'Тоді, як в зелень зором я впивався,
Мов той, хто вік пустив намарно свій,
Бо на пташок безглуздо любувався,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'За батька більший мовив: «Сину мій,
Ми маєм скористатись зараз саме
Нам даним часом, - тож ходім хутчій».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'І зір я й крок повів за мудрецями,
Й не довелося докладать зусиль, -
Так захопивсь я їхніми речами.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Але з плачем співання, звідусіль
«О господи, устні мої!» почуте,
Вливало в серце радощі та біль.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = '«Мій ніжний батьку, що це може бути?» -
Спитав я, й він: «Це тіні у сльозах,
Мабуть, розв''язують вузли покути».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Немов юрба прочан в святих думках,
Не зупиняючись, лиш погляд кине,
Коли хто-небудь перетне їй шлях,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Так натовп мовчазних побожних тіней,
Догнавши нас, випереджав, легкий,
Занурений у почуття єдине.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Запали темні очі, вид різкий
У всіх здавався, висохлий, здрібнілий,
І шкіра обтягала їм кістки.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Навряд, щоб отакий худий та білий
Став Ерісіхтон, як, на кістяка
Змарнівши, падав з голоду без сили.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Подумав я: «Єрусалим така
Сповняла, мабуть, людність тої ночі,
Коли Марія з''їла хлопчака».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Були мов персні без каміння - очі.
Хто ж «ОМО» бачить на людськім лиці,
Той скрізь би «М» розпізнавав охоче.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Не відаючи, в чому корінці,
Хто б думав, що плоди й вода пахучі
Виснажують жаданням душі ці?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Я дивувавсь, чого вони худючі,
Чому покров їх шкіри лусковий, -
Пояснення ховалось ніби в тучі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Та із глибин своєї голови
Цікава тінь на мене поглядала
Й гукнула враз: «О радість, ти живий?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Нікого жодна з рис не нагадала,
А з голосу її я все згадав,
Що в себе жадна худина забрала.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'З тієї іскри в мене спомин встав
Про губи, висхлі тут з тяжкого посту,
І я тоді Форезе упізнав.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = '«О, не зважай на люту цю коросту, -
Благав він, - що знебарвлює мене,
На тіло, нині без ваги та зросту.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Скажи, щоб все було мені ясне,
Про себе й тіні ці, що йдеш із ними,
Промов мені слівце хоча б одне».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = '«Твоє обличчя, що я змив гіркими,
Коли помер ти, варте знов цього, -
Я відповів, - із змінами тяжкими.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Та, бога ради, схудли ви чого?
І не питай причин мого приходу, -
В думках про це не вимовиш того».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'І він: «Спадаючи на листя й воду,
Тут сила потаємна та блага
Гріховну нам знесилює природу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Юрбу, що в плачі й співах не ляга,
Бо встигнув рот багато зла накоїть,
Тут очищають голод і жага.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Бажання їсти й пити непокоїть
їм дух, коли зачують, як пахтять
Плоди та рідина, що зілля поїть.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Під дерево ідуть себе терзать,
Щораз вертають на нові страждання...
Кажу: «страждання», «втіха» б мав сказать.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Ця ж воля, що сюди веде з блукання,
Звела Христа до зойку: «Боже мій!», -
Коли Він кров''ю відкупляв сконання».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'І я: «Форезе, нас в земній пітьмі
Лишив, на кращий світ її змінявши,
Ти літ із п''ять - так згадую в умі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Якщо ти навіть доживав, не мавши
Гріхів нових, аж поки став на иуть,
Себе стражданням з Богом поєднавши, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'То як ти встиг цю вишину здобуть?
Гадав зустрінутися я з тобою
Там, де покуту рік за рік здають».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'А він мені: «Це плачем та журбою
Моя подбала Нелла влити сил
В полин солодкий тужного напою.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Й відколи я зійшов з землі у діл,
А тіло сповила смертельна тиша,
Звільнити з місць, де ждуть, і з інших кіл.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Тим Богові приємніша й рідніша
Вона, хто сльози безутішно ллє,
Чим у своїй чесноті самітніша.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'В Сардинії в Барбаджі - й там своє
Пристойніший жіноцтво вигляд має,
Як в цій Барбаджі, де мій дім ще є.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Знай, любий брате, - скоро час минає:
Коли цей день, що в небесах стоїть,
Утечі з пам''яті ще не зазнає,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'З амвонів скрізь під тягарем страхіть
Осудять безсоромних флорентинок
І їхню звичку персами світить.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Чи треба варварок та сарацинок,
Щоб не ходили з голими грудьми,
Лякати карами за цей їх вчинок?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Коли ті соромітниці самі
Дізнаються, що ждало їх за гулі,
Завиють, наполохані, зі тьми.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Бо посмутяться у посмертнім гулі
Раніше, як змужніє те маля,
Що нині мирно спить під «люлі-люлі».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Та, брате, бачиш, що не тільки я,
А й всі цікавляться, щоб ти відкрився,
Бо в тебе тіло сонце затуля».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'А я на це: «Коли б ти в пам''ять вбився,
Згадав би дружбу давньої пори,
То тут од прикрощів би й не дивився.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Оцей, що стежку вказує, старий,
З життя мене поніс на край дороги,
Коли був повен лик цього сестри, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Й на сонце показав: - 3 його помоги
Помандрував до справжніх я мерців
Зі справжнім тілом, що несуть ці ноги.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Підтримав він, до сходів цих привів
По стежці на верхів''я таємниче,
Яке спрямляє в вас, що світ скривив.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Він мовив, що мене до Беатріче
Охоче доведе й на вишині
Лишусь без нього після тої стрічі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Віргілій - той, хто мовив так мені, -
І я сказав: на честь цієї ж тіні
Був трус гори і співи голосні,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Бо з вашим царством розстається нині».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 45;

UPDATE cantos SET title_uk = 'ПІСНЯ ДВАДЦЯТЬ ЧЕТВЕРТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 24
    AND p.name = 'Purgatorio';

UPDATE terzinas SET text_uk = 'Ні мові нашій рух не був на шкоду,
Ні руху мова, - ми тепер неслись,
Немов судно в сприятливу погоду.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Мерці, що двічі трупами здались,
В дірки очей світили подив знову,
Що я живий, як і вони колись.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'І, далі ведучи свою розмову,
Я проказав: «Ця тінь не поспіша,
Либонь, через нову якусь умову.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'А де Піккарди чарівна душа?
І ще скажи, коли це тільки можна,
Хто з славних тут увагу полиша?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = '«Сестра, не менш прекрасна, як побожна,
Святкує на Олімпі між святих
В своїм вінку, щаслива і вельможна».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Так він сказав, а потім: «Тут усіх
Назвати вільно, бо не зчинять бунту,
Такі спотворені обличчя в них.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Пізнай-но в цім, - вказав він, - Бонаджунту.
Це Бонаджунта з Лукки, а в лиці,
Сухішому від кам''яного ґрунту,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Того, хто взяв із церквою вінці, -
Тепер цей турець згадує голодним
Больсенську рибку, зварену в винці».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Він одного показував за одним,
І прикрості не взнав ані один
Із згадуваних духом благородним.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Тут марно зуби шкірив Убальдін
Із замку Піла, був там Боніфацій,
Що юрми пас жезлом серед рівнин.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'То був месер Маркезе, що горляці,
Ще не сухій, заняття дав хмільне
Й ніяк не міг скінчить цієї праці.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Мов той, хто з різних обира одне,
Я врешті зупинивсь на тому, з Лукки,
Що начебто найбільше знав мене.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Почув я, як шептав ім''я Джентукки
Він ротом, що без їжі та води
Терпів тяжкі безперестанні муки.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = '«О душе, - я сказав, - а ти не жди
Моїх питань, а сам, як хочеш, далі
Зі мною втішну мову поведи».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = '«Іще та жінка не вдягла вуалі, -
Почав він, - що тебе розважить в нас,
На спільний осуд у міськім загалі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Бодай пророцтва зміст в тобі не згас!
Коли ж в думки заводить помилкові
Тебе мій шепіт, - правді буде час.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Чи не того я бачу, хто чудові
Нові рядки створив і так почав:
«Ви, донни, знаєтеся на любові...»?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'А я: «Що від любові я чував,
Все списував у зошит на роздачу
І сказане мені всім повідав».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = '«О брате, - мовив він, - тепер я бачу,
Чому Гвіттоне, нотарю й мені
Новий солодкий стиль явив задачу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Бо ваші пера, бачу, запальні
І вірно пишуть, що любов диктує,
А наші в цьому надто забарні.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'І саме цим, хай всякий занотує,
Новий різниться від старого стиль».
І, мов скінчивши, вдав, що більш не чує.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Як птаство, що летить до нільських хвиль
На зиму, по весні, зібравшись в зграї,
Ключами повертається звідтіль,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Так душі, схудлі у сумному краї,
Сухі, легкі, без гомону й пісень,
Звернули на стежки страждань безкраї.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'І наче той, хто, втомлений за день,
Пускає інших наперед юрбою,
Аж поки стишить віддихи легень,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Форезе так пускав перед собою
Весь натовп, тихо йшовши до мети,
Питаючись: «Чи стрінемось з тобою?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = '«Не знаю, - я промовив, - скільки йти
Ще мушу, та хоч як цей час пролине,
Хотів би швидше в гавань приплисти,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Бо місто, де життя у мене гине,
Збавляється щодня нових чеснот
І котиться по схилу до руїни».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'І він: «То йди, бо мерзощів оплот
Звірюці, бачу, до хвоста прип''ятий,
В низину тягнеться, де край підлот,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'І звір прискорює свій біг затятий,
Хвицаючи копитами щомить,
Щоб скинуть труп спотворений, розтятий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Уже недовго сферам цим кружить, -
І очі зняв до неба, - і в усьому
Розглянешся, чого не пояснить.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Тут я тебе лишу, бо в царстві цьому
Час дорогий, я ж гаюсь, далебі,
В ходінні із тобою нешвидкому».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Як уперед виноситься в гоньбі
Кіннотник перед кінними бійцями,
Щоб першому почати лютий бій,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Так він помчав за іншими мерцями,
А я зостався знову із двома,
Що в світі славними були митцями.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Коли ж він загубивсь між усіма
І став не більш приступний нам для зору,
Ніж зміст його розмови для ума,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Побачив я, поглянувши під гору,
Ще яблуню в спокусливих плодах,
Розложисту, високу і простору.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'І сила тіней заступила шлях,
Благально руки простягла до листу,
Як діти біля того, хто в руках'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Показує їм звабу пломенисту,
І, поки казяться вередуни,
Він мовчки слуха просьбу голосисту.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Немов отямившись, пішли вони,
Й тоді ми підступили до глухого
На зойки дерева, як до стіни.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = '«Проходьте - не добудете нічого,
Згори мій предок віття нахиля, -
Колись-то Єва куштувала з нього», -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Так хтось проголосив тут із гілля,
І ми, притиснувшись до скель лускатих,
Пройшли вперед - Віргілій, Стацій, я.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = '«Згадайте, - мовив той, - п''яниць проклятих
Із кодла Хмари, що Тезей гатив
По грудях їх, подвійних та кошлатих;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'І тих євреїв, хто в вигоді пив
І не придавсь у військо Гедеону, ''
Як сходив той на Мадіан з горбів».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Ми слухали про неба заборону
І про ненащності гріх тяжкий,
Про справедливість кари та закону.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Коли ж на вільні вийшли ми стежки,
То далі сунули в мовчущім строї
І кожен з нас заглибивсь у думки.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = '«Куди йдете, замислені, всі троє?» -
Раптово хтось сказав, і я здригнув,
Мов звір, що чує раптом брязкіт зброї.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'І зір на того, хто питав, звернув, -
Як в горні, склом розжареним надміру
Й розжевреним металом, враз сяйнув'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Той хтось, що мовив: «Ясного ефіру,
Сюди пішовши, певно сягнете.
Іде сюди, хто прагне йти до миру».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'Він засліпив мене, і, мов на те,
Щоб сказаному підкоритись, очі
Одвів назад на двійко я святе.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'І, наче вдосвіта вітрець лоскоче
Траву і ніжні квіти на землі
І ледве в гарних пахощах шепоче,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 49;

UPDATE terzinas SET text_uk = 'Такий відчув я повів на чолі
І вчув, як од легкого колихання
Тонку амброзію, чутно в крилі,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 50;

UPDATE terzinas SET text_uk = 'Й почув: «Блажен, у кому пожадання
Солодких страв не може затулить
Високого до неба поривання,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 51;

UPDATE terzinas SET text_uk = 'Хто їсть, аби лиш сили поновить».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 52;

UPDATE cantos SET title_uk = 'ПІСНЯ ДВАДЦЯТЬ П''ЯТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 25
    AND p.name = 'Purgatorio';

UPDATE terzinas SET text_uk = 'Додержуючи вічного закону,
На небесах меридіан здали
Тельцеві сонце, ніч же - Скорпіону.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Отож, мов той, хто вдень чи серед мли
Іде, не спинений припоном жодним,
Бо пильні справи в мандри потягли, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Крутими сходами один за одним
Так рушили ми швидше, без розмов
Проходом тільки одному свободним.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'І як малий лелека, що готов
Злетіти, крила розправля й, лишати
Гніздо страхаючись, склада їх знов, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Жадавши знать, як тільки міг жадати,
Я врешті рух зробив після вагань,
Як той, хто мову хоче розпочати.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'І хоч спішили ми на вищу грань,
Мій добрий батько вимовив: «Стріляй-но,
Бо вже натяг ти лука запитань».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Я, осмілівши, рот розкрив негайно
Й почав: «Як схуднуть так могли вони,
Коли усі тут не їдять звичайно?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = '«Ти пригадай, як Мелеагр смутний
Згорав, аж поки головня згорала,
І знайдеш, - мовив він, - одвіт ясний.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Ще помізкуй, як рухами дзеркала
Рух віддають ваш, і уздриш гнучким
Все те, що мисль твоя твердим вважала.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Щоб край покласти сумнівам тяжким,
Он Стацій тут, - до нього я звернуся
І ліків ранам попрошу твоїм».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = '«Коли йому я при тобі візьмуся, -
Той мовив, - говорить свої слова,
То лиш слухняністю з вини звільнюся. -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'І він почав: - Як в тебе голова
Це слово, сину, сприйме й заховає,
Тоді її осяє мисль нова.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Кров досконала, що не прибуває
До спраглих вен, неначе повний стіл
Усяких страв, а з серця випливає,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Творить нові тіла, в нім взявши сил,
Які частками тіло знову творять
Із крові, що беруть вони із жил,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Пливе туди, про що в нас не говорять,
А звідти в кров чужу іде вона,
В природний келих, де вони не спорять,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'А змішуються: з них слабка одна
Й терпляча, друга ж - дійова і сміла,
Бо з місця досконалого зрина.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Вона й береться до складання тіла:
Згустить ту кров, яка рідка була,
І оживить усе те, що згустила.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Душею ставши, сила чимала,
Підхожа до рослини всім, крім того,
Що йде іще, а та уже дійшла,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Цілком подібна до гриба морського,
Теж має рух і почуття пізніш
Зростає й інше з зародків усього.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Так, синку, з серця батька йде повніш
І ширше розвиток дочки чи сина;
Про це природа дбає найпильніш.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Не знаєш ти ще, як стає дитина
З тварини, та схибнула в тайні цій
Мудріша й вченіша, ніж ти, людина,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Навчавши, буцімто в душі людській
Можливий розум не перебуває,
Бо там не місце здібності такій.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Відкрий же груди правді, що все знає,
І відай: мозок тільки і живе,
Як певну частку в зародку займає.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Радіючи на чудо це нове,
Рушій найперший їй вдихає духа,
Це вмістище для цноти життьове,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Який діяльне все вбирає, й руха,
І складує у душу - в те одно,
Що і живе, і дивиться, і слуха.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Поглянь, щоб дивним не здалось воно,
Як сонячне тепло, віддавшись грону,
Із соками його дає вино.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Коли ж у Лахезіс забракне льону,
Дух звільнить здібності із тіла вмить,
Людські й божественні, немов з полону.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Частина більша з них уже мовчить,
А пам''ять, розум, воля - від порогу
Враз починають в діянні гостріть.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Душа, мов чудом чуючи знемогу,
На берег падає, на той чи цей,
Уперше дізнається про дорогу'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'І йде між душ без м''яса та костей
У сяйві сили творчої живої, ,
Як і колись, серед живих людей.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'І як вологи повне дощової
Повітря проти сонця розгорта
Розкішні різноколірні сувої, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Повітря те, яке навкруг літа,
Бере той образ, що душа дарує,
Коли стоїть незрушна та густа.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Як полум''я за вогником слідкує,
Хоч де б він рухатися не хотів,
Так образ за душею скрізь прямує'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'І зветься «тінь», бо йде до всіх кутів
За нею; творяться таким звичаєм
Знаряддя зору й інших почуттів,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Так сміємось ми, так ми розмовляєм,
Так плачемо й зітхаємо в журбі, -
Та сам ти чув це, йшовши нашим краєм.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Тінь обриси свої міня собі
Як до бажань і порухів натури.
Це все й збудило подив у тобі».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Ми вийшли до останньої тортури,
Праворуч рушивши в прохід вузький,
І подивлялися вже не на мури,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Бо з кручі пломінь вилітав яркий,
З провалля ж дужий вихор виривався,
Гнав до стіни вогненні язики.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'І кожен з нас по краю пробирався
Один по одному; і тут - в огні,
Там - в прірві опинитись я боявся.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Вожай мій: «Стережись! - казав мені, -
Вузду очей тримай, бо оступання
Тут небезпечне, похибки страшні».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'І враз «Бог вящей милості» - співання
Почув я крізь розжарену глибінь,
І виникло поглянути бажання.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Уздрів я в полум''ї за тінню тінь
І, голову звертаючи на боки,
Вбачав то їх, то дальший свій ступінь.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Скінчився гімн, і голос чийсь високий
«Не знаю мужа» крикнув на краю,
І тихо відновився спів широкий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = '«Діана, - знов гукнули всі, - в гаю
Геліки не лишила, бо дівчині
Дала Венера трутину свою».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'І заспівали знов рухливі тіні
Хвалу жіноцтву і чоловікам,
Чесноті вірним і своїй родині.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Мабуть, кричать вони й співають там,
Аж поки палить пломінь, вітром гнаний,
І засіб цей нещадний, цей бальзам'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Загоює нарешті їхні рани.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 47;

UPDATE cantos SET title_uk = 'ПІСНЯ ДВАДЦЯТЬ ШОСТА Сьоме коло. - Любострасні і содоміти. - Приклади любострастя'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 26
    AND p.name = 'Purgatorio';

UPDATE terzinas SET text_uk = 'Ми низкою отак ішли по краю,
І вчитель часто говорив мені:
«Побережись, тебе остерігаю».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Аж от засяли промені ясні
У нас на правих плечах: розчинило
Західне сонце синь у білині.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Де впала тінь моя, зачервоніло
Яскравіш полум''я; з усіх сторін''
Дивились тіні на таке несміло,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Й вони про мене, ідучи вздовж стін,
Заговорили в палі чималому,
Почавши: «Не з примарним тілом він».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'І пересвідчувалися у тому,
Та не переступаючи межі,
Щоб залишатись в вирі вогняному.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'І хтось: «Свій слух до слова прив''яжи,
Ти, що, либонь, з пошани йдеш позаду,
Й нам, хто в огні й жазі горить, скажи.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Ця відповідь нам принесе розраду,
Потрібніше тут душам всім вона,
Ніж мешканцям пустелі свіжість саду.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Чого ти перед сонцем, як стіна,
Стоїш собі, немов тебе ще й досі
В тенета не вловила смерть страшна?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Та слово з уст моїх ще не знялося.
Як раптом трапилося щось нове,
Й моє єство до нього потяглося.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Знов душі йшли крізь полум''я живе
Назустріч першим, мов дарма тинялись, -
І в видиво я втупивсь миттьове.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Я бачив, що квапливо обіймались
Вони, вітальні кажучи слова,
Та навіть на хвилинку не спинялись.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Отак на стежці сіра мурашва
Збирається питання вирішати,
Мабуть, про шлях чи про якісь дива.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'І тіні перед тим, як вирушати,
Прощалися по-дружньому цілком,
Та й ну одна до одної кричати.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Нові: «Оце Гоморра і Содом!»
А ті: «В телицю лізе Пасіфая,
Щоб хіть угамувати із биком!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'І як ключами журавлина зграя
Від спеки чи льодів летить кудись,
Чи буде це Ріфей, чи суш безкрая,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Так тіні в різні боки розійшлись
Із тими ж вигуками та піснями,
Які найкращими для них здались.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Ті ж душі, що уже рівнялись з нами,
Прийшли, уважливі й поштиві, знов,
Моїми зацікавившись словами.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'І я відчув їх потяг до розмов,
Почав: «О духи, вірно ви вчинили,
Що кожен правильну тропу знайшов!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Себе мої там члени не лишили:
Старі чи юні, тут усі вони,
Зі мною кров моя, суглоби, жили.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Угору йду, щоб зір мій став ясний:
Таке жони з небес веління важне,
Щоб смертне тіло вніс я в світ страшний.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Хай сяйво зглянеться на вас звитяжне
І вас у лоно прийме на віки
Любові повне небо всеосяжне!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Але скажіть, хто ви, щоб сторінки
Заповнить міг би записом, для чого
Іде за вами натовп гомінкий».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Горянин, як до міста голосного
Уперше потрапляє з диких гір,
Так оком водить з подиву німого,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Як тіні ці втупляли в мене зір,
Аж поки заспокоїлися знову -
Високе серце скоро знайде мир.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = '«Блажен, хто усього життя основу
Шукає з досвіду в краю гіркім, -
Так дух той мовив, що почав розмову. -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Зустрічні душі согрішали тим,
За що в тріумфі з Цезаря глумились,
Ім''ям «цариці» кидались бридким.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Із вигуком «Содом!» вони пустились,
І зашарілі зразу щоки їх
В почервонілому вогні відбились.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Зате у нас був двостатевим гріх,
Такий, проте, що личить не людині,
А диким пристрастям тварюк ярких.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Тому, як зустрічаєм інші тіні,
Плямим себе тією, що була
Твариною у дощаній тварині.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Ти наші взнав тепер гріхи й діла,
А хто тут є - розповісти не можу
Й не маю часу - нас тут без числа.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Своїм лише ім''ям твій слух стривожу:
Я - Гвідо Гвініцеллі - тут іду,
Бо вдавсь, вмираючи, по ласку Божу».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Раділи, на Лікургову біду,
Сини, принісши порятунок нені, -
І я відчув ту ж краску на виду,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Коли назвався батько мій - знаменне
Є в нього ще поріддя молоде,
Значніше у поезії за мене.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Не кажучи, не чуючи, хто й де,
В думках я йшов край вогняної смуги,
Та не пускало полум''я ніде.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Нарешті, зір наситивши, у слуги
До нього щиро зажадав піти, -
Цій щирості не міг не вірить другий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'І він мені: «Усе, що мовив ти,
Лишило слід в мені такий яскравий,
Що Леті ані змити, ні звести.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Якому ж вияву якої слави
Я вдячний за любов таку, радий,
Що знак її, як бачу, нелукавий?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'І я: «В рядках такий ви молодий,
Що поки буде вірш нової мірки.
їх атрамент сіятиме завжди».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = '«О брате, - мовив він, - поглянь-но зірко, -
І він перед собою показав, -
Ото ковач був рідної говірки!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Як вірші й прозу нею він писав!
Хай йолопи верзуть, що той, з Ліможа,
Був кращий ніби для усіх тих справ, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'їм важить галас, а не правда гожа,
Вони й виходять з нього до пори,
Ума й мистецтва думка їм ворожа.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Колись Гвіттоне славився старий
Найпершим із поетів, їх вожатим,
Аж поки правда не взяла гори!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Раз жеребом ти значений багатим,
То як потрапиш у чудесний гай,
У ту обитель, де Христос абатом,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'За мене оченаша прочитай,
Крім слів, що нам були в потребі зроду,
Але давно покладено їм край».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'І, наче іншим даючи свободу,
Туди ступнув, де душ брела сім''я,
Пірнувши в полум''я, як риба в воду.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'До вказаного ним наблизивсь я
І мовив, що хотів би, повен миру
Й поваги, привітать його ім''я.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'І відповідь почав він ґречну й щиру:
«Віншує пан мене в тонких словах.
І я одвіт не маю за офіру.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'Арнаут я, йду з піснею в сльозах
По ватрі учорашніх злих зусиль,
По ватрі сподівань на ліпший шлях.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'А що ласкавий пан іде на шпиль
У втішливі і файні височіні,
То прошу пана пам''ятать мій біль».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 49;

UPDATE terzinas SET text_uk = 'І зник в очисного вогню лавині.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 50;

UPDATE cantos SET title_uk = 'ПІСНЯ ДВАДЦЯТЬ СЬОМА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 27
    AND p.name = 'Purgatorio';

UPDATE terzinas SET text_uk = 'Там, звідки перший промінь пада саме
На гору, вкриту кров''ю бога слав,
І Ебро блискотить під Терезами,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'А Ганг вогнем опівдні запалав, -
Там стало сонце, й день уже спустився,
Як ангел Божий раптом нам засяв.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Він на краю, не в полум''ї з''явився
Й «Блаженні серцем чистії» завів,
І голос благовісника полився:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = '«До того, поки пломінь не вкусив
Вас, душі, - йти святим невільно вище:
Пройдіть багаттям, слухаючи спів».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Він так сказав, як підійшли ми ближче,
І, чувши те, подібним я зробивсь
До трупа, що несуть на кладовище.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Підвівши руки, в жар очима впивсь
І згадував те видиво страшенне,
Коли на спалюваних я дививсь.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Мої вожді поглянули на мене,
І вимовив Віргілій: «Сину мій,
Не смерть - лиш муку дасть кільце вогненне.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Згадай, згадай... Коли вже в ямі злій
Я зніс тебе на плечах Геріона, -
Чого б не зміг я на горі ясній?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Надійна в тебе, певна охорона:
Нехай би сотні літ в огні ти був,
Не стане в тебе й цяточка червона.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'А хочеш знать, чи я не обманув,
То сміливо зайди в огонь невтомний,
Щоб полумінь твоє вбрання лизнув.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Зламай же ти, зламай свій страх незломний
І сміло йди, чого б то я боявсь!»
Та я не рухавсь, хоч і був притомний.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Побачив він, що я упертим вдавсь,
Збентежився й промовив: «Бачиш, сину,
До Беатріче мур лиш цей зоставсь».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Зачув колись-то про свою єдину
І очі звів, конаючи, Пірам,
Коли пофарбувала кров рослину, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Так подививсь я на вождя, ім''ям
Тим пресвятим повернутий до тями,
Що дороге весь вік моїм ушам.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Кивнув він і сказав: «Та що це з нами?
Так і не підем?» Ніжно посміхнувсь,
Немов дитині, звабленій плодами.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'І перше, ніж зайти в огонь, звернувсь
До Стація, прохавши йти позаду,
Бо з місця той між нами не схитнувсь.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Коли за ним ступив я, то розраду
Знайшов би навіть у киплячім склі, -
Такий-бо жар узяв мене в обладу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Мій батько, проганявши страхи злі
Й весь час про Беатріче яснооку
Казавши, мовив: «Он вона, в імлі!..»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'А голос кличним співом з того боку
Нас вів і вивів просто на місця,
Де знов був хід на крутизну високу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Тут од такого сяйного лиця,
Що відвернувся вбік я: «Приїдіте, -
Почув, - благословеннії отця/..»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = '«Сідає сонце, присмерком сповите,
Вам не спинятись, поспішати слід,
Бо скоро небо тьмою буде вкрите».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Угору в скелі сходи йшли на схід,
І тіло в мене, промені собою
Спинявши, слало перед себе слід.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Ми встигли трохи лиш пройти ступою,
Як з того, що моя пропала тінь,
Відчули вечір мудреці зі мною.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'І перед тим, як безліччю сплетінь
Одноманітний морок опустився
І вийшла ніч із безлічі склепінь,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'На східцях кожен з нас лягти вмостився,
Бо, сходячи так стрімко догори,
Не так зрадів з дороги, як стомився.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Мов кози, що скакали до пори,
Стрибавши зі шпиля на шпиль далекий,
Аж поки, ситі, не скінчили гри'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'І не притихли у години спеки,
А біля них з ґирлиґою хлопчак
Уважно доглядає їх безпеки;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Чи, мов козар, що, здершись на стрімчак,
Чатує стадо у нічній долині,
Щоб не нагнав його якийсь хижак, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Такі утрьох були ми в тій хвилині -
Я за козу, вони за пастухів -
І звідти й звідси стиснені в щілині.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Там тільки клапоть неба нам світив,
На ньому ж більші сяяли зірниці,
Яскравіші, ніж досі я зорив.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'На них я став замріяно дивиться
Й запав у сон, той сон, що знає все
Ще перед тим, коли воно здійсниться.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Мабуть, коли Цітера, що несе
В чаду кохання сяйво без спочинку,
На сході перший промінь свій пасе,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Побачив уві сні я юну жінку, -
Вона, вродлива, поставна, струнка,
Співала, рвавши квіти у корзинку:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = '«Коли питаєшся, хто я така
Й чого квітки збираю, знай, - я Лія,
І гарні руки ці плетуть вінка,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Бо дзеркало оздобить - в мене мрія.
Не чинить так сестра моя Рахіль:
Вдивлятись в нього - це для неї дія.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Для неї зір - мета дбання й зусиль,
А я цікавлюсь рук своїх діянням,
їй споглядать, для мене ж діять - ціль».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'А ближче вже до дня, перед світанням,
Приємним для прочан, що в путь знялись,
Побачивши кінець своїм блуканням,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Додолу тіні в темряву сповзлись,
І я повіки звів, од сну свобод ні,
Уздрів учителів, що теж звелись.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = '«Солодкий плід, якого всі голодні
Шукають всюди по гілках рясних,
Жагу тобі вгамує вже сьогодні».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Віргілій саме в цих словах ясних
Сказав, і новорічного подання
Ніхто б не дав любішого за них.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Таке жадання до мого жадання
Тут додалось, що кручі вперекір
Щокрок зростали крила на злітання.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Коли ми вийшли із східчастих гір,
Закінчивши свій довгий шлях величний,
Віргілій обернув до мене зір'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'І мовив: «Пломінь часовий і вічний
Ти бачив, сину, та мені вже строк
Не кидать оком за щабель граничний.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Я вміло скерував сюди твій крок,
А далі - волі підкоряйся власній,
Бо вийшов ти з крутих, вузьких стежок.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Глянь, щік твоїх торкнувся промінь ясний,
Глянь, квіти й зелень в пишній гущині
Самі зростають на землі прекрасній.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'І поки очі прийдуть чарівні,
Що втерти їхні сльози був я радий,
Сиди, гуляй по любій глушині.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Не жди од мене й слова чи поради, -
Мені б тебе послухати було:
Ти мудрий, вільний, і як знаки влади'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'Прийми корону й митру на чоло».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 48;

UPDATE cantos SET title_uk = 'ПІСНЯ ДВАДЦЯТЬ ВОСЬМА Земний Рай. - Мательда. - Божественний ліс'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 28
    AND p.name = 'Purgatorio';

UPDATE terzinas SET text_uk = 'Оглянути зсередини та зовні
Старезний ліс, могутній і святий,
Де юний день ховавсь у млі чудовній,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Часу не гаючи, крізь діл пустий
Від прірви я відходив стиха-стиха,
Навколо ж лився аромат густий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Тонкий вітрець, що повсякчас тут диха,
Все гладив лагідно чоло моє,
Немов зефір, з яким приходить втіха.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Готові листя ворухнуть своє,
Вершки дерев назад всі напрямлялись,
Де першу тінь священний шпиль дає.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Але вони не дуже відхилялись,
Тож щебетухи в вітті чарівнім
В мистецтві дивовижному вправлялись'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'І радісним цвіріньканням своїм
Виспівували величання сходу,
А лист одлунював повтором рим.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Так гілка з гілкою шумить в негоду
Над К''яссі в соснику, коли з заков
Еол пуска Сірокко на свободу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Хода нечутна тихих підошов
Мене помалу в давній ліс пустила,
Аж я незчувся, як туди зайшов.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Та зліва річка враз мене спинила,
І хвилі пробігали в ній дрібні,
Й трава обабіч неї зеленіла.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'На всьому світі води скрізь брудні,
В них домішки усякі неприємні,
А в цих, прозорих, видно все на дні,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Хоча вони здавались темні-темні,
Бо й промінь не проходив крізь той гай
У непроникні сутінки таємні.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Я став і поглядом через ручай
Пройшов туди, де хаща несходима
Стояла в щебеті пташиних зграй,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Коли з''явилася (перед очима
Так іноді з''являється нам річ,
Спочатку з подиву нерозрізнима),'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Одніська жінка йшла мені устріч,
Зі співом бравши скарби квітникові,
Що без числа цвіли вподовж узбіч.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = '«О гарна дамо в сяєві любові,
Коли правдиво вказують сліди,
Що певно свідчать про серця чудові,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Зласкався, я благаю, підійди, -
До неї мовив, - до струмка, на розцвіт,
Щоб любий голос долинав сюди.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Ти наче Прозерпіни юний одсвіт,
Що в матері відірвана була,
Вона сама і весь її первоцвіт».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Як з одною одну ступні звела,
Кружлявши, танцюристка і на полі
За ногу ставить ногу спроквола, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Прекрасна в різноколірнім околі -
Червоне з жовтим - так звернула вбік,
Мов дівчина, спустивши зір поволі,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'І підійшла туди, де біг потік,
Моє прохання любо вдовольнивши,
Бо чув я, що сказав її язик.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Тоді вона, мене перепинивши,
Де хвилі обмивали стебла врун,
Осипала дарами, зір підвівши.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Така, напевне, іскра, мов перун,
Під віями в Венери не займалась,
Коли влучав у матір син-пустун.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Вона до мене лагідно всміхалась,
В руках тримавши цілий жмут квіток,
Що сила тут, несіяних, здіймалась.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Була завширшки річка чи не крок,
Та Геллеспонт, для Ксеркса - шлях свобідний,
Для інших славолюбів же - замок,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Такий же був Леандрові огидний,
Коли той протягом стількох ночей
Перепливав його, коханець бідний.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = '«Ви новаки, і, може, усміх цей, -
Розпочала вона, - в такій місцині,
Призначеній колись-то для людей,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'В вас будить подив і непевність нині,
Але псалом «Возвеселил єсиь
Вам розжене туман у розумінні.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Ти ж, хто спитавсь у мене, попроси
На гідне подиву щось відповісти,
Бо я на те й зійшла у ці ліси».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = '«Вода, - сказав я, - й гамір густолистий
Зневірюють у тому, що я чув,
Чому перечить вигляд очевистий».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Тоді вона: «Скажу, щоб ти збагнув,
Як все з причини родиться, й розвію
Пітьму, що нею ти пойнятий був.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Найвище благо, що для себе дію
Всю творить, добрим людям тут дало
Оселю, як на вічний мир надію.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'За гріх свій людство вигнане було,
За гріх свій од покори та спокою
До зла, печалі й жалів перейшло.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Аби з тих змін, що їх несуть з собою
Ізнизу випари води й землі,
Йдучи по змозі вгору з теплотою,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Ніколи б людям не прийшли жалі,
Оця гора ніде вітрів не знає
Од брами аж до саду на шпилі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Але в повітрі кола піднімає
Рушій той перший, що й собі кружля,
Коли ж їм перешкод ніде немає,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'То вир находить звідти, іздаля
Сюди на вільний шпиль в живім повітрі
І тут розхитує рясне гілля.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'І дерево свої прикмети хитрі,
Гойдавшись, віддає, й вони притьма
Летять із гаю в далину на вітрі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'І там, де небо та й земля сама -
Все інше, родить сад вона багатий,
Внизу дерев зростає тьмуща тьма.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Отож не доведеться дивувати,
Як щось, неначе без насіння, там
Враз прийметься та стане квітувати.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'І про святий цей лан дізнайся сам,
Що сповнений він сім''ям та плодами,
Просякнутими завтрашнім життям.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Потік же цей не живиться парами,
Морозом зрідженими, як ріка,
Що то всиха, то повниться часами, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Тече він з невичерпного струмка,
Що з волі й слова Бога всеблагого
Двома річками далі протіка:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Коли він випливає з боку цього,
То забирає пам''ять про вини;
Про добрі вчинки - повертає з того.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Тут з Лети, там - з Євної, струмини
З обох покуштувать повинні люди,
Бо діють тільки разом вдвох вони.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'В них кращий смак за той, що в водах всюди,
І хоч вгамуєш ти жагу собі,
Так що про неї й мови вже не буде, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Та з ласки особливої тобі
Ще думку висловлю - надію маю,
Що ти її не втопиш у ганьбі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Пливла колись Парнасом серед гаю
Про золоті часи пісень луна -
Так то був одгомін із цього краю:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'Невинні люди тут, цвіте весна
Одвічно, й солодко в річках дзюркоче
Нектар - співцям приємна рідина».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'І, на своїх поетів звівши очі,
Побачив я, що кожен усміхнувсь,
Останні чуючи слова жіночі;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 49;

UPDATE terzinas SET text_uk = 'І знов я на прекрасну озирнувсь.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 50;

UPDATE cantos SET title_uk = 'ПІСНЯ ДВАДЦЯТЬ ДЕВ''ЯТА Земний Рай. - Алегорична процесія, або Тріумф церкви'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 29
    AND p.name = 'Purgatorio';

UPDATE terzinas SET text_uk = 'Вона своє скінчила говорити
І стала, мов закохана, співать:
«Блаженні ті, чий гріх уже покритий»,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Як німфи, що ополудні спішать
По затінку діброви самітними
Зирнуть на сонце й далі простувать,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Пішла вона лугами запашними
Тим берегом, а цим - проти води,
Дрібним я крокам слідував дрібними.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'По сотні кроків нашої ходи
Враз береги кудись убік звилися,
І я на схід звернув свої сліди.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Коли ми трохи далі подалися,
То жінка та мені, як я почув,
Сказала: «Брате, слухай і дивися».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'І раптом висвіт з гущини блиснув, -
Він для очей таким сліпучим здався,
Що я на блискавку помислив був.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Та полиск блискавки б умить промчався,
А цей нестримно далі все зростав,
Аж я: «Та що ж воно таке?» - спитався.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'В осяйному повітрі спів почав
Неждано ширитись, принадно й гойно,
І знову, гнівний, Єву я згадав.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Все Господу корилося достойно,
Вона ж сама зневажила Творця,
Який життя вдихнув у неї щойно.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Якби не скинула вона з лиця
Покрову, то мені б в садах прегарних
Була б найперша й довга втіха ця.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'І поки йшов я в спогадах примарних
Про вічні радощі в раю земнім,
З бажанням свят, ще більших та безхмарних,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Повітря осяйнуло вогняним
Серпанком зеленіючу дорогу
І ніжний звук став співом чарівним.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Святі дівчата, голоднечу вбогу,
Безсоння мусив я за вас нести, -
Подайте ж зараз світлу допомогу!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Збере хай думи Гелікон святий,
Та й ще підсобить хором Уранія
У вірш важке для розуму ввести!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Сім золотих дерев уздріла мрія,
Бо відстанню обманена була:
Обман цей - віддалі звичайна дія.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'А от як стала відстань ця мала
І річ, іздалеку ніби туманна,
Всіма своїми рисами зросла, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'То над думками влада безустанна,
Що світники це, - довела увіч,
І влад виспівували всі: «Осанна!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Проміння розливала кожна з свіч
Розкішніше за місяць серед ночі,
Коли уповні він і повна ніч.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Захоплений, свої звернув я очі
На доброго Віргілія, який
Вернув у здивуванні зір пророчий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Я на високі глянув світники -
Ті посувались далі так повільно,
Що їх догнали й молоді б жінки.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Та провідниця мовила: «Як сильно
Оцим живлющим світлом захопивсь,
Що дальшим не цікавишся ти пильно!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'І погляд мій за вогники повивсь,
І там людей уздрів я в білих шатах, -
Світ на таке ніколи не дививсь.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Та зліва річка в берегах покатих
Одбила, як упав на неї зір,
Мій лівий бік, мов із дзеркал багатих.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Не зупинявся аж до тих я пір,
Спішивши йти назустріч невидимим,
Поки не ліг між нами водний шир.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'А світники все шляхом невгасимим
Лишали слід, накреслений без рук,
Мов пензлем, вимальовуваний димом.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Лягли в повітрі, як стрічок тих пук,
Сім стяжок різноколірних, що б склали
Перев''язь - Делії, а Сонцю - лук.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Вогні все далі й далі відбігали,
Аж поки не зробилися малі,
Й весь час між себе десять кроків мали.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Під пишним небом, по ясній землі
Двадцять чотири діди йшли ступою
З лілейними вінками на чолі,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'І всі співали: «Благодать з тобою
Між дочок всіх Адамових, вовік
Будь благодать з твоєю красотою!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Коли останній проминув старик
І розрівнявся трав і квітів килим,
Що під його стопами був поник,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Як в небесах світило за світилом,
Ступило четверо тварин тепер, -
Оздоблених листом зазеленілим.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'У кожної шість крил з барвистих пер,
І кожне з них було таке окате,
Як Аргус, поки той іще не вмер.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Але, читачу, рими витрачати
Не можу тут, бо далі місце є,
Ще й не одне, цікаве та багате.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Читай Єзекіїля: він дає
їх опис, рух із півночі крізь вири,
Де вітер, сніг і полум''я снує.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Які на сторінках у нього звірі,
Такі ж і тут ішли, - без всяких змін,
Лиш крил було по шість - не по чотири.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Святковий повіз між святих тварин
Повільно рухала грифона сила -
Вагу велику віз невтомно він.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Він простягнув одне за одним крила
З середньої по трьох і трьох стяжках,
І кожна їх без шкоди пропустила,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Й вони кінцями зникли в небесах,
А тіло золотим було пташаче
Й червоним з білим, де вже був не птах.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Убогішим візком втішав гаряче
Завзяття Риму сам Октавіан,
І повіз Сонця б не сіяв багатше;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Той Сонця повіз, що на зойк землян
Згорів аж до останньої дощинки,
Коли творив свій суд Юпітер-пан.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'При правім колесі ішло три жінки
Весь час у танці; першої не зміг
Помітить я у виблисках жаринки,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'У другої від голови до ніг
Все тіло й кість були як з ізумруду,
А третя сяла, наче свіжий сніг.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'То біла брала інших під оруду,
А то червона, і мінявсь танок,
Скоряючись її пісням, як чуду.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Ліворуч гралось четверо жінок
У пурпурі, піддаючись єдиній
З трьома очима, кращій від зірок.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Йшло двоє за описаними нині
В одежі неоднаковій старих,
Однакових в суворій благостині.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Бо перший, мабуть, вчивсь у школах тих,
Де Гіппократ в природи сам навчався
На користь любих їй істот людських,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'А другий зовсім іншим видавався
З мечем, який так страшно блискотів,
Що я й на цьому березі злякався.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'Ще бачив скромних чотирьох дідів
І одного, який, повитий снами,
Самотній в даль проникливо глядів.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'Ці семеро одягнені так само
Були, як перші, тільки не з лілей
їх чола прикрашалися вінками, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 49;

UPDATE terzinas SET text_uk = 'З багряних рож: для неблизьких очей
Здавалось, що вогонь горить стіною
Понад бровами у святих людей.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 50;

UPDATE terzinas SET text_uk = 'Вже порівнявсь блаженний віз зі мною,
Коли по небу раптом грім пройшов.
І перед забороною грізною'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 51;

UPDATE terzinas SET text_uk = 'Похід спинився біля корогов.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 52;

UPDATE cantos SET title_uk = 'ПІСНЯ ТРИДЦЯТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 30
    AND p.name = 'Purgatorio';

UPDATE terzinas SET text_uk = 'Коли це семизір''я, в вищім небі
Ні сходу, ані схилу, ані хмар,
Окрім гріха, не беручи на себе,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Всім вказуючи їх моральний дар, -
Як наше, нижче, вказує дорогу,
Що нею йде до берега весляр, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Спинилося, то старці, вірні Богу,
Що поперед грифона йшли за ним,
До воза стали, що втишав тривогу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'І хтось, мов небом посланий ясним,
Гукнув: «Гряди, невісто, от Ліванак -
Підтримуваний хором голосним.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Немов святі, коли сурма неждана
Покличе, встануть з домовин співать
Воскреслими устами всі: «Осанна!», -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Так сотні тих, хто ширить благодать,
Єгда прорік премудрий, в колісниці
Святково стали угорі літать,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'На спів: «Благословен грядий!» клониться
І квіти кидати, додаючи:
«Наповнюйте лілеями кошниці!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Бувало, бачиш, з місця не йдучи,
Початок дня і схід порум''янілий,
А решту неба - в ясній ще ночі,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'І устає вид сонця потьмянілий,
І вранці за серпанками хмарок
Дивитись легше диск потуманілий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Отак у хмарі запашних квіток,
Що кидали їх ангельські загони
Й метали у візок і повз візок,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'В вінку з олив з-над білої запони
Явилась жінка, й згортками спадав
Зелений плащ їй на убір червоний.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Моєму духу, що не трепетав
Уже давно у неї на прикові,
Бо вже давно її не зустрічав,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Не очі - сили потайні, чудові,
Йдучи од неї, й почуття міцне -
Дали впізнать колишній чар любові.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'І тільки бачення моє сумне
Висока сила вдарила в хвилину,
Що ранила, як змалку ще, мене,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Звернувсь я вліво, схожий на дитину,
Жалем чи страхом змушувану вмить
За мамину приховуватись спину,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Хотів сказать Віргілію: «Тремтить
Усе в мені з нестримного екстазу,
І стала кров, як в юності, горіть», -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Але Віргілій десь від нас одразу
Пропав, Віргілій, добрий батько мій,
Віргілій, мій вожай з її наказу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'І сад, зчужілий матері старій,
Не став розрадою сльозам чималим
На вмитій росами щоці моїй.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = '«Ти, Данте, за Віргілієм пропалим
Не плач іще, за ним іще не плач,
Ще маєш плакати під гострим жалом».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Мов адмірал, який в ім''я удач
З корми та з носа в морі прикликає
Підлеглі судна, пильний оглядач,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Такою у коші на лівім краї,
Як озирнувся на своє ім''я,
Що мимоволі тут в рядок лягає,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Побачив жінку на тім боці я, -
За мною стежила крізь покривало,
Навколо ж гралась ангелів сім''я.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Хоча розглянути її спиняло
Густіючою тінню на лиці
В Мінервиному листі запинало, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Вона промовила слова оці,
По-царськи випроставшись мальовниче,
Мов той, хто каже головне в кінці:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = '«Вдивляйсь отак - так, так, я Беатріче.
Як стати на цю гору зваживсь ти?
Не знаєш, що вона щасливих кличе?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'У воду глянувши, перевести
Я поспішив свій зір в траву, додолу,
Бо лоб мій сорому не міг знести.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Дошкульність материнського уколу
Я взнав, бо в нім чуття мої знайшли
З гіркою ніжністю суворість голу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Замовкла; ангели розпочали
Усі: «На Тя, Всевишній, уповаю»,
Та за «стопи моя» не перейшли.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Як сніг, по скелях та по вітах гаю
Замерзлий на Італії хребтах
З вітрів того, що родить славів, краю,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Знов тане і тече в жарких ґрунтах
Безтінних, аж ти згадуєш палання
Вогню, що віск розтоплює в свічках, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Такий я був, без сліз і без зітхання
До того, як крилатих спів почув
Після святого вічних сфер співання.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Коли ж я з. їхніх голосів збагнув
їх співчування більш, аніж сказали
Вони б: «Владарко, чим він винен був?» -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Крижини, що на серці намерзали,
Сльозами й зойками з грудей моїх
Виходити крізь очі й рота стали.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Благим істотам на благання їх,
Не ворухнувшись у коші священнім,
Вона відповіла в словах таких:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = '«Чатуєте в кружінні цілоденнім, -
Ні тьма, ні сон не скриють найпильніш,
Що робить вік у русі нескінченнім.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'І через те я відповім гучніш,
Щоб той почув, хто плаче на тім боці, -
Що кари міряють гріхами лиш.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Не тільки сфери маю я на оці,
Що сім''я перетворюють на плід
У спільному зористому потоці,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'А й весь той благодатний неба хід,
Який так може пару піднімати,
Що в вишині важкий зникає слід, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Бо цей в новім житті мав дар багатий
Із риски вдачі, хоч яка дрібна, -
Найвищу славу Богу добувати.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Але земля тим менш дає зерна,
Як не скропляти потом, мов росою,
Чим краща та родючіша вона.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Якийсь-то час впливала я красою
Свого лиця, і зір дівочий мій
Його проводив стежкою прямою.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'А тільки я поріг лишила свій
До віку другого і відлетіла,
Як цей піддався суєті земній.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Коли я духом підвелась із тіла
І виросла в чесноті і красі,
Для нього стала менше люба й мила.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Неправим шляхом погляди усі
Він скерував і лиш мари питався,
Що скрізь облуди сіє ті і сі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'І в яв, і в снах, яким він віддавався,
Нагадувала я про Вишній суд -
Але він цим не дуже клопотався'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Й до того впав, що був би марним труд
Великий мій, якби по всій дорозі
Не провела його між грішний люд.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Отож я стала в мертвих на порозі
І в того, хто привів його сюди,
Я випросила бути в допомозі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'Зазнали б кривди Божі всі суди,
Якби він став тут, Лету перепливши,
Та й ще покуштував її води,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'Борг покаяння слізьми не сплативши».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 49;

UPDATE cantos SET title_uk = 'ПІСНЯ ТРИДЦЯТЬ ПЕРША Земний Рай. - Лета'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 31
    AND p.name = 'Purgatorio';

UPDATE terzinas SET text_uk = '«Чом ти мовчиш, на тому боці ставши? -
Знов слів жало націлила грізне,
Уже і так їх лезом ран завдавши,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Й нещадно вдарила вона мене: -
Скажи, скажи, визнаннями доповни
Моє обвинувачення страшне».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Я був такий бентежний, що гріховний
Не міг мій голос із грудей пройти
До рота, й зоставався я безмовний.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Пождала й мовила: «То як же ти?
Відповідай-но, поки Лети хвилі
Не змили болісної тяготи».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'В збентеженні й страху був ледь я в силі
«Так, правда» видавити з уст смутних,
Не вуху, тільки оку зрозумілі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Як лук, із сил натягнутий усіх,
Рве тятиву, ламається, й важкою
Стає стріла у пошуках своїх, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Так я знемігсь під ношею тяжкою,
Бо ніс у зойках та сльозах одвіт,
І голос зник від смутку й неспокою.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Тоді вона: «Коли мій заповіт
Тобі «Любити благо», здавна даний,
Повинен був заповнити твій світ, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Які ж провалля та які кайдани
Перед собою бачив ці роки,
Що забував подальший шлях жаданий?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Які приваби та зазив який
Читав ти, на чоло красунь зирнувши,
Що переслідував їх залюбки?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'І довго, тяжко в каятті зітхнувши,
Насилу весь свій голос я зібрав,
Заледве тільки рота розімкнувши,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'І з плачем вимовив: «Щоденних справ
Брехливі радощі звели з дороги,
Як тільки вид ваш із очей пропав».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Вона ж:« Хоч ти б весь час мовчав, убогий,
Або вигадував за річчю річ,
Але суддя всю правду знає строгий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Коли ж зізнатись у провинах ввіч,
З обмитим щирими сльозами зором,
То тут точило кружить вістрю встріч.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Проте, щоб взяв тебе ще більший сором
З твоїх помилок і на інший раз,
Сирен зачувши, ти лишавсь суворим, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Насіння плачу кинуть - мій наказ,
І слухати: не так чинити мали
Кістки мої, заховані од вас.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Такої радості ще не давали
Колись тобі природа й твір митця
Як риси ті, що прахом нині стали.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Тоді ж, коли найвища радість ця
З моєю смертю зникла, то навіщо
Було вертать до смертного лиця?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'І тільки стрельнула брехня найнижча,
Тобі звести слід очі ввись було,
Слідом за мною - я ж бо правда віща.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Тягар було не брати на крило
Й не піддаватися ані дівчатку,
Ні іншому чомусь, що б там не йшло.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Мисливця вбачить досить пташенятку
Лиш двічі-тричі, і тікає птах
Тенет чи стріл, в яких нема нестатку».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Як дітлахи із соромом в очах
Понуряться, коли ти їх картаєш,
І мовчки каються в своїх гріхах,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Так я стояв. Вона ж: «Коли страждаєш,
Лиш чуючи, то бороду зведи,
Бо дивлячись - ще більш страждати маєш».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Мерщій дуби із ґрунту, мов з води,
Геть вивертає наський вітер зразу
Чи той, що з краю Ярби мчить сюди,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Ніж підборіддя зводив я з наказу,
Де в слові «борода» замість «лице»
Гірку отруту вчув я і образу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Нарешті я уздрів, мов крізь сильце,
Що перестали первістки творіння
Змикать круг воза квіткове кільце.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'І ще уздрів я, мов серед проміння,
Що Беатріче зір тримала свій
На звірі двоєдиного коріння.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'На тому березі, в габі ясній,
Була ще краща, ніж коли бувала
Найкращою з красунь на кулі всій.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Відчув я каяття кропивні жала,
Й чим більше щось любив, було, колись,
Тим більш ненависть нині повивала.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'І так жалі у серце уп''ялись,
Що впав я. Знає владарка стеменне,
Які події далі відбулись.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Коли ж з душі знялось ярмо тяженне, -
Схилилась жінка, давній мій водій,
І мовила: «Тримайсь, тримайсь за мене».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Й занурила у річку, а тоді
Вмить потягла, заглибивши до рота,
Мов човника по лагідній воді.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Блаженства берег, де була чеснота
Й співали: «Окропи мя», - близько був,
Та це списать - не до снаги робота.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'І мимоволі я нараз пірнув,
Бо жінка, склавши пальці, тім''я ними
Моє натисла, й я води ковтнув.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Між чотирма жінками чарівними
Поставила мене, й вони сами
Руками стали обіймать своїми.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = '«Ми - німфи тут, зірки ми - в прірвах тьми.
Ще Беатріче не було на світі,
їй слугувати готувались ми.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Тебе на очі, для добра відкриті,
Зведем, хай тільки погляд погострять
Тобі ці троє, зором знамениті».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Співаючи, мені звеліли стать
Проти грудей грифона, і плечима
До нас була кохана благодать.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'І ще сказали: «Тут слідкуй очима,
Бо ти стаєш перед смарагда грань,
Й до нього спрага в тебе невтолима».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'І тисячі роз''ятрених жадань
З моїм скували зором зір невинний,
В грифона втуплюваний без вагань.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'В її зіницях звір двополовинний,
Як в дзеркалі світило, відбивавсь,
Являвши вид то орлій, то левиний.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Зміркуй, читачу, як я здивувавсь,
Побачивши, що звір, без змін на очі,
На іншого в очах перекидавсь.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Я, дивлячись на чудо це пророче,
Тієї їжі споживав шматок,
Яку хто більше їсть, то більше хоче.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'А троє гарних молодих жінок,
Наділених, мабуть, званням високим,
По-ангельськи співали під танок.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = '«Глянь, Беатріче, глянь пресвітлим оком, -
Я чув слова, - на вірного свого:
Прийшов до тебе шляхом він жорстоким.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Зласкавсь, будь ласка, над слізьми його,
Відкрий свої уста, хай він спізнає
Ще другу красоту єства твого».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Живого світла сяєво безкрає!
Чи на Парнасі є завзятий хтось,
Хто з джерела жагу задовольняє,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'Хто б зважився і щоб йому вдалось
Тебе таким списать, яке розкрилось
І в тінь гармонії небес влилось,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'Коли перед очима появилось?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 49;

UPDATE cantos SET title_uk = 'ПІСНЯ ТРИДЦЯТЬ ДРУГА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 32
    AND p.name = 'Purgatorio';

UPDATE terzinas SET text_uk = 'В очах моїх міцна така напруга
Була з десятирічної жаги,
Що проти неї никла всяка друга.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Ховавсь уважний зір за мур благий -
Його в мережі так тримав пестливо
Божественний той усміх дорогий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Та мусив погляд я звернути вліво,
Бо вигуки почув неголосні
Тих трьох богинь: «Занадто вже сміливо!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Осліплення, яке дають вогні
Побаченого сонячного диску,
На хвилю одібрало зір мені.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Коли ж я звикнув до малого блиску
(Кажу «малого», бо не тим було
Те сяйво, що з чужого збувсь я тиску),'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Помітив я, що вправо враз пішло
Славетне військо, і перед очима
У нього сонце й сім вогнів пливло.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Як полк заходить лівими плечима,
А потім всі під прапором стоять,
Щоб шикувалась лава незлічима,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Так ця небесної держави рать,
Це воїнство круг повоза зімкнулось,
Який не починав ще завертать.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Нарешті все жіноцтво озирнулось,
Грифон же зрушив, обернувши вид,
І ні пірце на нім не ворухнулось.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Прекрасна, що скеровувала хід
За колесом зі Стацієм і мною,
Крутішої дуги лишала слід.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Під спів з небес розмірною ходою
Ми рухалися лісом самітним,
Що Євиною позначивсь виною.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Як тричі луком стрельнути тугим, -
Ми стільки йшли до дерева сухого,
І Беатріче стала перед ним.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = '«Адам!» - з докором всі шептали строго,
Оточуючи яблуню сумну,
Що зовсім не росло на ній нічого.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Чим вище, більшало в широчину
її гілля; схилявшись смаглим лобом,
Індійці б славили в ній вишину.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = '«Хвала, грифоне, що не вдарив дзьобом
Ти дерева, бо гарний має смак
Та браму різним відмика хворобам!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Навколо товплячись, гукав усяк;
І мовив звір подвійної природи:
«Скрізь правди сім''я бережеться так!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Він дишля за ріжок без перешкоди
Вузлом прип''яв до яблуні-вдови -
Й єдине ціле склали дві породи.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Як тужать в нас дерева без листви,
Коли ж велике світло йде в промінні,
Що ллє позад небесної плотви,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Брунькують враз та барви всі первинні
Собі вертають, поки сонцю віз
Готується не в іншому зорінні, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Так раптом одягнувсь у розкіш риз,
Що тон троянд, з фіалковим зливали,
Той стовбур, де гілля було як хмиз.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Ніколи я не чув, щоб так співали,
Бо на землі такий не лине спів,
І я знести не міг чуттів навали.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Коли б я мав снагу та відтворив,
Як повість про Сірінгу очі пильні
Склепила, й пильний зір за це сплатив, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Мов той, хто дав з моделей безпомильні
Малюнки, свій би сон я описав:
Та краще зроблять це умілі й сильні!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Я ж перейду на мить, коли устав,
Бо в одіж сну проникнув блиск рожевий
І голос вигукнув: «Устань і вслав!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Мов квіт уздрівши ніжний яблуневий,
Що втіху ангелам дає плодом
І празник в небі прикраша вогневий,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Іаков з Іоанном і Петром.
Підняті голосом, що мчить в просторі
І має владу і над кріпшим сном,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Побачили - немає на Фаворі
Ураз обох - Мойсея та Іллі,
А сам Господь явивсь в новім уборі, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Я теж схопивсь і добрість на чолі
Побожниці уздрів, що таємниче
Вела мене по річці й по землі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Спитав схвильовано: «Де Беатріче?»
Й вона: «Поглянь, під деревом сидить
В новому листі і тебе ось кличе.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Поглянь, громада ця навкруг стоїть,
Та ж за небесним звіром шлях прослала,
І співи ніжні линуть у блакить».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Не знаю я, чи ще вона мовляла:
Бо перед поглядом була ота,
Що розумові уші затуляла.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Сиділа прямо на землі, проста,
Мов силою двоїстого грифона
Прип''ятий повіз стерегла, свята.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Була круг неї німф сімох заслона
І факели тримала, мур немов,
Що не боявся Австра й Аквілона.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = '«Походиш трохи серед цих дібров,
А там зі мною будеш вічно в Римі,
Куди Христос як римлянин ввійшов.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Для світу ж, де провини незчислимі,
На повіз цей поглянь, а там спиши
Події, що очам постануть зримі», -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Так Беатріче. З щирої душі
Я, підкоряючись її наказу,
Спинив свій зір і розум на коші.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Небесне полум''я, яке одразу
На землю падає із гущі хмар,
Так не злітало з вишини ні разу,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Як птах Юпітерів, що вмить удар
Од верху скрізь завдав по листю й вітах,
Які з''явились, мов нежданий дар,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'По возу врешті, що стояв на квітах, -
І той хитнувсь, мов буря потягла
Його по хвилях пінявих, сердитих.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Я ще побачив, як лиса повзла
До пишної в тріумфі колісниці,
Бридка, худюща, зголодніла й зла.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'І стала дорікать за вчинки ниці
Владарка їй моя, й якнайскоріш
Пропала ця кощава тінь лисиці.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Я ще орла побачив: як, давніш
Злетівши, знову сів на віз жаданий,
Насипав пір''я з себе повний кіш.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'І наче з серця, що болить од рани,
Із неба голос жалібний розливсь:
«Мій човнику, який вантаж поганий!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'А там здалось мені, мов ґрунт розсівсь
Між двох коліс, і я побачив змія,
Який хвостом у повіз знизу в''ївсь,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Мов жало з ранки, витяг лиходія
Свого із подення та й зник назад,
Бо вже доволі вдовольнила дія.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Недоломки ж, як той живучий сад
Вкривається весь листом, пір''ям вкрились,
Залишеним із добрих, знать, засад.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Усі колеса й дишель оперились
За мить таку недовгу, що в устах
За неї віддихи б не повторились.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'Із дишля троє і по всіх кутах
Повипиналиєь голови з будови
Нечуваної, що спорудив птах.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'Три мали по два роги, як корови,
А кутові - лише по одному, -
Чи був іще де звір семиголовий?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 49;

UPDATE terzinas SET text_uk = 'Неначе башта на круту строму,
Повія до повозки пресвятої
Зійшла, бридка у стиді своєму,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 50;

UPDATE terzinas SET text_uk = 'А поруч дикий велет став у зброї,
Либонь, щоб не хапнули, крадії,
Й щомиті цілувалися обоє.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 51;

UPDATE terzinas SET text_uk = 'Як раптом на мені вона свої
Нахабні очі жадібно спинила,
Лихий коханець враз шмагнув її,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 52;

UPDATE terzinas SET text_uk = 'В злобі, яка від ревнощів кипіла,
Страшидло відіпнув і втяг у ліс,
Де гущина з моїх очей вхопила'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 53;

UPDATE terzinas SET text_uk = 'Повію й звіра, що із воза зріс.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 54;

UPDATE cantos SET title_uk = 'ПІСНЯ ТРИДЦЯТЬ ТРЕТЯ'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 33
    AND p.name = 'Purgatorio';

UPDATE terzinas SET text_uk = '«Язиці приїдоша, Боже», - звівся
На три й чотири голоси псалом,
І спів з жіночими сльозами злився.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'А Беатріче із смутним чолом
Усю пойняв глибокий біль затятий,
Ще більше, ніж Марію під хрестом.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Коли ж дівчата скінчили співати,
Вона до них обличчя вогняне
Звернула й почала їм промовляти:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = '«5м емалі і не видите мене,
І се глаголю вам я, сестри милі,
/ паки емалі узрите мене».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Сімох вперед послала, нам же (в силі
Був я, й мудрець, і жінка, щоб її
Й без слів були накази зрозумілі)'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Вказала мовчки на сліди свої,
Та кроків з десять лиш пройшла стежину,
Як очі раптом втупила в мої'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'І з виглядом спокійним: «Підійди-но, -
Сказала, - щоб не проминуть промов,
Призначених лише тобі єдино».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Коли ж я, як належить, підійшов,
Вона сказала: «Брате, чом сміливо
Мене ти не питаєшся ізнов?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Мов ті, що так занадто шанобливо
Звертаються до старшого, аж їм
Не йде назовні й слово полохливо,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Почав я звуком, майже не чутним:
«Відомі, пані, вам мої турботи
І як їх заспокоїти і чим».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Вона: «Ти б збувся ляку й соромоти
І так би говорити перестав,
Як той, хто щось белькоче із дрімоти.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Дізнайсь: те подення, що змій зламав,
Було й нема. Людці хай знають ниці,
Що Божа мста до їх байдужа страв.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Що безліч внуків буде завжди в птиці,
В орла, що, пір''я скинувши в візок,
Зробив страшидло й здобич з колісниці.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Бо твердо знаю й добре бачу крок,
Яким іде у небі кожна зірка,
Аби наблизить без завади строк,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Коли п''ятсот, і десять, і п''ятірка,
Число від Бога, кралю ту заб''є
Із велетом, що з нею винен гірко.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Можливо, що пророцтво це моє,
Як і Феміда, й Сфінкс, навряд чи раду
Подасть, бо теж розгадки не дає,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Та дійсність перетвориться в наяду,
Яка розв''яже загадок вузли
Й не заподіє шкоди хлібу й стаду.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Завваж слова, що з вуст моїх зійшли,
І всім тим, хто живе життям, що кличе
До смерті, передай і перешли.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Та занотуй, записуючи швидче,
Як вразило це дерево тебе,
Що при тобі зогиджене аж двічі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Бо хто його рубає чи скубе -
Своїм блюзнірством ображає Бога,
Який творив, щоб вдовольнить себе.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Понад п''ять тисяч літ, вкусивши з нього,
Чекала перша мучена душа
Того, хто зніме гріх із світу всього.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Твій розум спить, коли не виріша,
Від чого саме стовбур той високий
Така широка крона виверша.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Коли б не вгруз, як в Ельсу, до мороки
І, нею тішачись, ти б не плямив ''
Свій розум, мов Пірам шовковиць соки,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Належну Думку скласти б ти зумів
Про справедливість Божу з заборони
Круг дерева цього для всіх умів.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Та кам''яніє, бачу, і холоне
Твій розум у гріхах - із сліпоти
У сяйві слів моїх безсилий тоне,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Тож, як не в записах винось їх ти,
Бодай в малюнках хоч, на землю плоску,
Як пілігрим несе ціпок святий».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'І я: «Як вдавлена печатка в воску
Без зміни сотні літ пережива,
Так ви відбилися у мене в мозку.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Та чом жадані ваші мчать слова
Так високо, що зір, хоч як би знявся,
За ними все-таки не поспіва?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = '«А це, - промовила, - щоб ти дізнавсі
Яку пройшов тут школу, й подививсь,
Чи вдало розуміть мене навчався.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Щоб знав: од Бога шлях ваш віддаливсь
Далеко так, як від земного краю
Небесний круг, що перший закрутивсь».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'І я їй відповів: «Не пам''ятаю,
Коли себе од вас я відштовхнув,
Тож мучитись сумлінням я не маю».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = '«Не маєш тільки тим, що все забув, -
Всміхаючись відповіла, - згадай-но,
Що ти із Лети щойно вод ковтнув.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Немає диму без вогню, звичайно,
Й забутливість ця - доказ, що твоя
Грішила воля ще, відверто й тайно.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Тож неприховано надалі я
Казатиму, щоб слово долетіло
Й закарбувалося на все життя».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Яскравіш полудневе те світило
Нам з точки, що весь час повільно йде -
Як до положення землі, - блистіло,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Коли спинилися (той, хто веде
Загін вперед, прикмети, повні змісту,
Примітивши, так опізнілих жде)'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Ці сім жінок, у тінь зайшовши чисту,
Яка ляга на води Альп од ґрат,
Що творить чорна гілка й зелень листу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Мені здалось, що Тігр, а з ним Євфрат,
З одного витоку набравши ходу,
В розлуці тужать, як за братом брат.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = '«О світло, о хвало людського роду!
Що за річки з одного джерела
У далину несуть окремо воду?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Й на запитання відповідь була:
«Питай Мательду, скаже хай». І наче
Та, що провину на собі несла,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Прекрасна: «Я про все, про це ж, - найпаче
Йому розповіла, і пам''ята
Це, певна я, й по Леті око зряче».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'І Беатріче: «Мабуть, пам''ять та
Занурена не в ті турботи й жалі
І розумові очі відміта.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Біжить Євноя тут у звивах далі, -
Як завше, вирушай з ним до води,
Верни йому там сили підупаді».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Немов душа шляхетна, що завжди,
Бажання інших роблячи своїми,
Уловлює охоче їх сліди, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Мене торкнувши пальцями тонкими,
Пішла прекрасна, встигнувши сказать,
Як чемна дама, Стацієві: «Йдімо».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Коли було б, читачу, де писать,
Я б оспівав хоча б напій єдиний,
Що хочеться ще раз до уст узять.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Та сторінки для другої частини
Уже я всі заповнив - до рядка,
Й вузда мистецтва - проти писанини.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'Я вийшов з прохолодного струмка,
Освіжений у цій святій купелі,
Оновлений від першого ж ковтка,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'Готовий зводитись на зорні стелі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Purgatorio'
    AND terzinas.terzina_number = 49;


-- ── Paradiso ─────────────────────────────────────

UPDATE cantos SET title_uk = 'ПІСНЯ ПЕРША'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 1
    AND p.name = 'Paradiso';

UPDATE terzinas SET text_uk = 'Одвічне сяєво того, хто водить
Світи по колах, славу підійма
Угору більше і додолу сходить.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'У небі, що найбільш його сприйма,
Я був і бачив те, чого віддати
По воротті ні в кого слів нема.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Бо, летячи на те, що смів жадати,
Наш розум досяга таких глибів,
Звідкіль несила пам''яті вертати.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'З красот святого царства я зробив
В умі своїм коштовностей зібрання,
Які нестимуть до вершин мій спів.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'О добрий Аполлоне, увостаннє
Ти душу оберни в сосуд мені
І лавром увінчай її старання!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Задовольняв мене у давні дні
Один Парнасу верх, тепер же сміло
Обох благаю на діла трудні.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Ввійди мені у груди, щоб світило
Натхнення, як було, коли, благий,
Ти витяг з піхов Марсієве тіло.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'О Божа доблесте, як подих твій
Примножить сили цим писанням бідним
З відбитків, знятих в пам''яті моїй,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Мене ти під своїм галуззям рідним
Побачиш і даси мені вінок,
Мене зробивши цього змісту гідним.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Так рідко, батьку, листя рвуть з гілок
На шану цезаря або поета
(Одна з людських ганебних помилок!),'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Що радісна була б для Дельф прикмета,
Якби людина в затінок зайшла
Пенейського гіллястого намета.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Великий пломінь іскра дасть мала;
Хтось після мене ліпшими піснями
Вблагає Кірру, щоб відповіла.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'До смертних сходить через різні брами
Лампада світу; в тій, де заплелись
Чотири обводи трьома хрестами,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Гарнішає на всю небесну вись
Вона сама, й зоря її гарніша,
Щоб втиски в воску світовім вдались.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'І майже звідти день устав, темніша
Ніч стала в нас, збіліла вся кругом
Півкуля та, а ця була чорніша,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Коли я Беатріче вздрів: з чолом,
Ліворуч звернутим, вона зорила
На сонця лик, змагаючись з орлом.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'І так, як другий промінь родить сила
Проміння першого, щоб той вертавсь,
Немов блукач, кому оселя мила, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Той вчин її крізь погляд мій діставсь
До почуття мого й відбивсь у вчині, -
І в сонце довше я, ніж хто, вглядавсь.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Багато з неприступного людині
Стає цілком приступним в місці тім,
Колись призначенім людській родині.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Недовго промінь я терпів, а втім,
Устиг помітити, що розсипався
Навколо жар, як в горні вогнянім.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Враз видалось, що день до дня додався,
Мов другим сонцем в небі на весь шир
Одразу Всемогутній розсіявся.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'То Беатріче свій втопила зір
У віковічний повіз, я ж дивився
На неї лиш, забувши про ефір.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'І, дивлячись, я тим в душі зробився,
Ким Главк зробивсь, коли його трава
Зробила богом, як її наївся.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Цього онадлюдинення в слова
Не вкласти. Приклад цей доступний зорам,
А сутність явить благодать жива.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Якби лишавсь я тим, який був твором
Твоїм, любове, що весь світ ведеш,
Ти піднесла б мене ясним простором!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Коли той рух, що колесу даєш,
Мою увагу привернув до нього,
Бо в нім гармонію і лад ти ллєш,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Такі простори з сонця огняного
Спахнули, що ні дощ, ні всі річки
Не налили б водоймища такого.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Нові ці звуки, цей огонь близький
Мені жаги до знань встромили жала,
Що досі пал не був такий різкий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Мене, як сам я, знавши, побажала
Вона мій ум звільнить од дум хитких,
Уста розкрила й запитань не ждала,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'А почала: «Під тягарем важких
Ти помилок того не споглядаєш,
Що споглядав би, якби збувся їх,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Бо вже не на землі ти, як гадаєш,
І полиск блискавок, що вниз майнув,
Не так летить, як вгору ти злітаєш».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'І тільки знищений мій сумнів був
Коротким словом ласки та щедроти,
Коли нову непевність я відчув'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'І мовив: «З мене ти зняла турботи,
Та ще нова турбота виника:
Як я лечу над ці легкі істоти?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Вона ж, сердечна й розумом тонка,
На мене глянула з зітханням гожим,
Як мати на цікавого синка,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'І почала: «Тобі ми допоможем,
Все має лад, і формою він є,
Яка весь світ на Бога робить схожим.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Створінням вищим видний тут стає
Слід сили вічної, закон якої
Нагадувало слово вже моє.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'У цьому ладі - різновидні строї
В природі, нахили і почуття,
Й далекі, й ближчі від мети ясної,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Великим морем вашого буття
Пливуть кудись, а їх стежки спрямляє
Той порив, наданий на все життя.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Він полум''я на місяць посилає,
Він в серці смертному - двигун основ,
Він в ціле землю з''єднує й скріпляє.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'І лук цей всіх вражає знов і знов -
Не тільки безрозсудливі створіння,
А й ті, в яких є розум і любов.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Своїм тримає словом провидіння
Незрушну твердь, яка вбирає ту,
Що зазнає найшвидшого кружіння.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'А нині нас помчала в вись святу
Потужна тятива, яка керує
Всім тим, що кида в радісну мету.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Це ж правда, що, як форма не пасує
До заповітних намірів митця,
Яких глуха матерія не чує, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'То й утвір збочує тоді з правця,
Бо, хоч прямує він до блага, мари
Зведуть його й до іншого кінця'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = '(Отак ти можеш бачить, як із хмари
Йде вниз вогонь) і просто на загин,
Коли його облудні зваблять чари.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'То з того, що ти сходиш до вершин,
Не більш дивуй, ніж бачивши, як води
Біжать із високості до низин.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Було б у дивину - без перешкоди
Тобі спинитися побіля дна,
Як полум''ю згасати без свободи».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'Й звела у небо погляд свій вона.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 1
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 48;

UPDATE cantos SET title_uk = 'ПІСНЯ ДРУГА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 2
    AND p.name = 'Paradiso';

UPDATE terzinas SET text_uk = 'О ви, хто прагне вутлими човнами
Здогнать моє співаюче судно
І ніжними утішитись піснями,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Назад вертайте краще, бо одно
Судилось вам - у безбережнім морі
Себе згубити і піти на дно.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Я перший мчу в незвіданім просторі;
Мінерва дме, кермує бог співців,
І дев''ять муз постерігають зорі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Ви ж, нечисленні, хто споконвіків
До ангельського хліба тягне шию,
Хоч тут усмак його ніхто не їв,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Оддайтеся хоробро вітровію
І, поки слід лиша в воді мій рух,
Стерніть свій корабель в морську стихію!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Як ваш, не дивувався смілих дух,
Коли в колхідське поле, тестем дане,
Погнав Ясон биків, немов пастух.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Бажання вроджене, безперестанне
В богоподібне царство мчало нас.
Випереджали небо ми зірчане.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Вверх владарка дивилась, я ж весь час
На неї, й протягом тієї миті,
В яку із лука стрельнуть встигнеш раз,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Там опинились ми, де розмаїті
Мене дивниці вразили, а та,
Якій були чуття мої відкриті,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'В якій краса сіяла й чистота:
«Хто зніс на першу зірку нас, - сказала, -
Того уславлять хай твої уста».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Мені здалось, що хмара нас вкривала
Велика, щільна, сяюча, пласка,
Мов адамант, де сонця міць вдаряла.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Перлина вічна, з одного куска,
Втягла нас, і ніщо не затремтіло,
Як промінь втягує вода в''язка.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Був тілом я, й було незрозуміло,
Як в інший умістився мій об''єм,
Бо неможливо ж тілу вкластись в тіло,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Й бажанням спалахнув я, як вогнем,
Пізнати Сутність ту, в якій єднання
Людини з Богом вічним пізнаєм.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Спізнається в ній наше сповідання, -
Бездоказова, звісно, віра ця, -
Як перших вірних кращі сподівання.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Я відповів: «До вічного Отця
Підношу скільки маю шани й дяки,
Що взяв мене від смертних в ці місця.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Але скажіть мені, що то за знаки
На цьому тілі, з приводу яких
Про Каїна пригадує всілякий?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Всміхнулась злегка: «В сітях мов густих
Так б''ється мисль, коли чуття не в силах
Відкрити світ одним з ключів своїх,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Тож, - мовила, - йди далі не по стрілах
Здивовання: це тягне почуття
З собою розум на коротких крилах.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Скажи мені, яка тут мисль твоя?»
А я: «Складають всесвіту багатство -
Тіла щілинні й щільні, мислю я».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Й вона: «Покинеш цих думок жебрацтво
І взнаєш, що впадуть вони без сил,
Лиш зрушу доказів своїх вояцтво.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'У восьмім небі повно тих світил,
Що кожне з них від інших всіх різниться
У силі світла й величинах тіл.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Якби тут полягала вся різниця,
У ступені щілинності однім,
Одне з усіх могло б хоч як втісниться.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Прикмет же різність вдячна основним
Засадам, що їх всі, крім однієї,
Ти відкидаєш висловом своїм.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'І до плямистості якби тієї
Щілинність спричинялася, тоді
Нецільною б речовина всієї'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Була планети; і як ті худі
Чергують з ситими місцями в тілі,
В цій книзі білі аркуші й руді.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'У першім разі видний на світилі
Під час затьмарень став би диск ясний,
Просвічений крізь місяцеві щілі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Цього ж немає. Отже, ми хутчій
Іще одне припущення відкинем
І в помилці упевнимось твоїй.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'У разі ж з тілом, в масі неєдиним,
Натрапить світло на путі кінець,
Ішовши встріч суціль твердим глибинам,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'І не єдиний верне промінець,
Мов колір, що відбивсь об стекла верхні,
Коли під них підкладено свинець.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Та, може, скажеш ти, що промінь мерхне,
Бо йде назад не з самої землі,
А з глибшої і дальшої поверхні.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Ці доводи, на силу немалі,
Такий спростує дослід знаменитий,
Бо досвід - ґрунт науки взагалі:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Візьми три дзеркала, щоб встановити
Два поруч зблизька, третє вглиб відстав,
Щоб із-за них могло тобі ясніти,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'А за собою свічника пристав,
Щоб відбивався світ у тих дзеркалах
І від усіх до тебе повертав, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'То, дивлячись у них на різних далях,
Враз троє пломенів побачиш ти,
На розмір різних, а на силу сталих.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Отож, як з сонячної теплоти
Оголюється снігу підоснова
Від холоду свого та білоти,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Роздерла так моя правдива мова
Запону, що тобі вкривала зір,
І сяє нині істина чудова.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Під небом, де панує Божий мир,
Велике тіло з перших днів кружляє
Й дає буття всьому на весь свій шир.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'А ближче небо, що від зір палає,
Всі різні сутності, які в нім є
Й різняться з ним, буттям тим обділяє.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'І в кожній іншій сфері є своє,
Яке вона безперестанно плодить,
Йому причин і цілей надає.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Ці члени світу поступово сходять,
Як бачив сам ти навіч, слід у слід
І взяте угорі донизу зводять.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Ти продивись моїх правдивий хід
Для тебе міркувань неоціненних,
Бо через них лежить прямий твій брід.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Одвічний рух і сила кіл священних,
Як спритність молота від коваля,
Залежать всі од рушіїв блаженних.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'І небо, що зірок юрба встеля,
Ту зобразити мисль високу прагне
Й відбить, навкруг якої все кружля.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'І як душа, що тлін на себе вдягне, -
Себе по різних членах несучи,
Так зробить, що з них кожен дій забагне,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Так розум, доброту скрізь ведучи,
її по зоряних розносить чудах,
Навкруг своєї єдності йдучи.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'В зв''язок заходячи по всіх усюдах
З коштовним тілом, всяка сила й міць
Єднається із ним в житті у людях,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'І, з радісних природи таємниць,
Крізь тіло блискотить яскраво й світло,
Мов радість з глибини живих зіниць.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'Ось через що різниться з світлом світло,
І аж ніяк не через щільність ту;
Це основне, що на весь світ розквітло'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 49;

UPDATE terzinas SET text_uk = 'І творить все - темноту й ясноту».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 2
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 50;

UPDATE cantos SET title_uk = 'ПІСНЯ ТРЕТЯ'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 3
    AND p.name = 'Paradiso';

UPDATE terzinas SET text_uk = 'Ясної правди риси пречудові
Списало сонце ніжним язиком,
Мені спаливши серце у любові,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'І я хотів з піднесеним чолом
Заговорити і подать відомість,
Що здоланий і вмовлений цілком,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Але примара виникла натомість
І всю мою увагу притягла, -
І зовсім я забув свою свідомість.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Бо як крізь чистоту й прозорість скла
Або на водах ясних по мілинах,
Де не ховає дна глибинна мла,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Розмиваними бачиш лиця в тінях,
Перлини ж, лігши на бліде чоло,
Мов розчиняються в тонких площинах, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Таке обличчя видно тут було,
І я запав у заблуд, протилежний
Закоханості хлопця в джерело:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Гадаючи, що образ цей залежний
Од віддзеркалення, я озирнувсь
Поглянути, кому-то він належний,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Та не знайшов нікого і звернувсь
До ніжної своєї провідниці,
В її ж очах святий вогонь всміхнувсь.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = '«Сміюсь, дитинко, на твої марниці, -
Сказала, - не дивуй, твої сліди
Ще не сягнули в істини границі,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'І спотикаєшся ти, як завжди.
Це - справжні сутності, зломили міру
Вони обіту й вміщені сюди.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Кажи їм, слухай їх і дай їм віру,
Бо сяйво, що знесло їх до святинь,
їм не дає лишати правду щиру».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'І видалось мені, що ближча тінь
Бажає говорить, і я озвався,
Мов той, хто сохне з надміру хотінь:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = '«О душе, що утіхами пройнявся
Солодкими, не знаними для тих,
Хто їх смаком ще й досі не впивався,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Подякую тобі в словах благих, -
Назви своє ім''я й талан ваш гожий».
І він із радістю в очах святих:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = '«Для праведних жадань наш, як і Божий,
Дух не замкне ніяк до ласки брам, -
Бо волить Бог, щоб з ним був почет схожий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Була я дівчина й черниця там,
А зосередиш розум весь, що маєш,
Бо нині я приємніша очам,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'То у мені Піккарду розпізнаєш.
У сфері найповільнішій мене
Між інших ти блаженних зустрічаєш.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Запалює нам почуття одне
Лиш Дух святий; як нагороду гідну
Це місце ми сприймаємо ясне.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Бо долю нашу, із землі завидну,
Нам дано за обітниці, як слід
Не здійснені, й за легкодухість стидну».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'І я до неї: «Ваш прегарний вид
Божественністю так тут став сіяти,
Що від колишнього запав і слід.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'І я тому не міг тебе назвати,
Та знане щось в твоїх словах лежить,
Що помогло мені тебе впізнати.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Але скажи, чи хочете кружить
Десь вище всі ви, тут щасливі бувши,
Щоб бачить більше і ще більш дружить?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'І, враз найближчі тіні озирнувши,
Із усмішкою мовила палка,
Мов з юного кохання спалахнувши:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = '«Мій брате, ласки сила тут така,
Що волі нашій не дає простору
Бажати далі від свого кутка.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Якби ми звідси поривались вгору,
Тоді в незгоді був би наш порив
Із волею, що бачить лиш покору,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'І став би ладові насупротив.
У неба спосіб є непоборимий:
Це ласка - ти ж її природу зрів.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Нас радує блаженство між святими,
Які в усьому з волею Того
Цілком тут злиті волями своїми.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'В усіх є свій щабель, з щабля свого
Всі раді в царстві, й царству для догоди,
Й царю: вволяєм волю ми його.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Його воління - мир наш, моря води,
Куди зусюди всяк несе ручай
Його всі твори й вироби природи».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'І втямив я, що скрізь у небі Рай,
Хоч ласки блага Вишнього спадає
На кожного йому належний пай.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Якщо кому пожива набридає,
Він прагне скуштувати інших страв
І просить їх, а першу відкладає, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Так я у слові й русі показав,
Що хочу знати, на якій тканині
У неї човник краю не дістав.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = '«Великого діяння й благостині, -
Вона сказала, - жінка монастир
Звела для нас, де в покривалах нині'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Вночі і вдень ми відчуваєм мир
В подружжі з тим, хто наші всі обіти
Приймає, добрий, лагідний без мір.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Я теж, юниця, святістю сповитий
Клобук вдягла, обітницю стару
Про Божі повторивши заповіти...'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Та люди, ближчі злу, аніж добру,
Мене з затишку піддали недолі,
І знає Бог, як я жила в миру.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'От ясність ця, що виникла у колі
З моєї правої руки, бліда,
І в нашім розгорілася околі,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Про мене річ до себе приклада:
Хоч в неї теж черниче покривало
Розідрано без сорому й стида.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'її в миру до світла поривало,
А звички стріла перешкод стіна, -
Воно їй серце завжди сповивало.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Те сяєво - Констанца видатна,
Що, з другим швабським вихром шлюб узявши,
Родила вихра третього вона».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Так мовила Піккарда й, заспівавши
«Маріє-приснодіво», зникла вмиг,
Як зник тягар би, в темну воду впавши.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Мій зір її проводив, скільки міг,
А вже коли згубив, то похопився,
До любої мети бажань побіг'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'І був на Беатріче зупинився,
Але так блиснула краса її,
Що погляд мій одразу потемнився,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'І перервав я розпити свої.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 3
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 44;

UPDATE cantos SET title_uk = 'ПІСНЯ ЧЕТВЕРТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 4
    AND p.name = 'Paradiso';

UPDATE terzinas SET text_uk = 'Людина вільна б доти обирала
Між двох однаково звабливих страв,
Аж поки б, зголоднівши, не сконала.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Отак би й зляканий баран стояв
Між двох вовків, незрушним залишавшись,
Отак би й хорт поміж двох ланей став.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Тож змовкнув я, із цього не стидавшись
(Непевне-бо чуття мені прийшло
Лиш з неминучості) і не пишавшись.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Замовкнув я, але моє чоло
Горіло запитанням, спломенілим
Яркіше, ніж би на язик лягло.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'А Беатріче, схожа з Даниїлом,
Що Навуходоносорів злий гнів
Погамував єдиним словом смілим,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Сказала: «Бачу, зовсім полонив
Тебе і той предмет бажання й другий,
Турботи повернувши з давніх днів.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Ти думаєш: «Якщо завдасть наруги
Благим чуттям насильства шал яркий,
Хіба змаліють з того їх заслуги?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Зростає й тим ще сумнів твій гіркий,
Що бачив ти у мудрому Платоні,
Мов повертають душі на зірки.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Тебе дві гадки держать у полоні,
І я на ту спочатку відповім,
Де мисль твоя у глибшій жовчі тоне.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Вбожествлений найбільше серафим,
З Мойсеєм Самуїл (щодо Марії
Вже не кажу), з Йоанном, тим чи тим, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'На цьому небі всі у спільній дії
Із духами, яких вже чув твій слух
І око бачило, прикривши вії.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Окраса кола першого - їх рух,
Але вони щасливі не порівну,
А в міру, скільки вчують вічний дух.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Не тим тобі тут стрілись, що поживну
Свою тут мають сферу, - лиш тому,
Щоб показать найменш високу й дивну.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Так слід казати вашому уму,
Що все крізь зовнішні чуття сприймає
І лиш вони дають покорм йому.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Святе письмо ваш ум на гадці має
І руки й ноги Богу надає,
Хоч і не те собі в думках тримає.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'І церква плоть на всіх вдяга, як є, -
Й на Гавриїла, й Михаїла, й того,
Що Товію грязиво дав своє.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Старий Тімей про душі мислив много
Й не так, як упевняє все тут нас,
Бо слово, мабуть, згодне з мислю в нього,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Що на зірки вертають душі з нас,
Бо із світил, за волею природи,
Злетіли нам в тіла на певний час,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'А може, не дійшовши в нього згоди,
Слова думкам пішли наперекір,
І збиткуватись тут нема нагоди.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Сказав би він, що знову мчать до зір
Честь і ганебність впливу, - й лук втулився
У нього б в частку правди, всім на взір.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Невірно втямивши це, помилився
Весь майже світ, - Юпітеру тоді,
Меркурію і Марсу він вклонився.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'А другий сумнів у твоїй біді
Отруйний менш - він зла не заподіє.
Ти не помилишся в своїй ході.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Те, що неправда правду од оліє
В очах у смертного, правдиву путь
До віри, не до єресей, відкриє.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Але до дна в цій істині сягнуть
Для розуміння вашого можливо,
Тож я тобі все можу розгорнуть.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Нехай насилуваний би тремтливо
Й не помагав насильству до дрібниць, -
Ці душі винуватить справедливо,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Бо волю не загасиш силоміць.
Вона, мов пломінь, рветься із безодні,
Хоча її насильство й валить ниць.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Коли ж вони стають більш-менш свободні,
То йдуть за силою; і душі ті
Отак і не вернули в дім Господній,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'А, мавши волю цілісну в житті,
Як мав Лаврентій у печі Ґратчастій
Чи Муцій, руку спікши до кості,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Знов стежкою, з якої у нещасті
їх зірвано, вели б свій дальший хід.
Але, на жаль, ці приклади не часті.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Як сприймеш ти мої слова як слід,
Юрба вагань, до цього нерушима,
Втече, подальших не завдавши бід.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Але стає нараз перед очима
Нова завада й згубою грозить,
Бо для самого тебе незборима.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Я вже дала тобі урозуміть,
Що лжа в уста святій душі не ляже,
Бо та у первоістині лежить.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Піккарда правду й про Констанцу каже,
Що та плека любов до покривал, -
І що ту мову із моєю в''яже?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Нерідко, брате, гасне чистий пал
У тому, хто чогось перелякався,
І до гріха його примусив шал,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Як Алкмеон: до батька прислухався
Побожно він, щоб матір покарать,
Хотів безгрішності - і в гріх удався.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Повинен ось що ти обміркувать:
Коли з насильством воля примирилась,
Не можна вчиненого дарувать.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Ги часто бачиш волю, що схилилась
З своєю досконалістю до зла
І в страху перед злішим помилилась.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Про досконалу волю цю й вела
Піккарда, я ж - про іншу, теж глибоку,
І істина одна в обох була».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Так збігли хвилі тихого потоку,
Що в правді джерело святе знайшов,
І втишили жагу мою двобоку.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = '«О люблячого першого любов
Небесна, все, що з ваших уст виходить, -
Сказав я, - сили живить знову й знов.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Мій дух глибинам почуттів не шкодить,
За ласку ласку вдячну не веде, -
Хто зрить і може, хай одвіт знаходить.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Я бачу, що наш розум упаде
Без правди в осіянному чертозі,
Без неї ж правди не знайти ніде.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Він зручно в ній лежить, мов звір в барлозі,
Підноситься із нею до зірок, -
Інакше все справдитися не в змозі,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'І сумнів випускає свій росток
В ногах у правди, вгору до безкраю
З горба на горб веде природа крок.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Тож, пані, я посмію й попитаю
Про істину, що спокій мій лама,
Бо сенсу в ній я ще не добираю.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Я хочу знати, чи в людей нема,
Замість обітниці, такого діла,
Щоб шалька з ним у вас тягла сама?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Тут Беатріче в мене утопила
Зір, сповнений такого почуття,
Що здолана очей поникла сила,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'І зір одвів, немов стерявшись, я.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 4
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 48;

UPDATE cantos SET title_uk = 'ПІСНЯ П''ЯТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 5
    AND p.name = 'Paradiso';

UPDATE terzinas SET text_uk = '«Коли моя у полум''ї любові
Не по-земному сяє красота,
Аж очі в тебе знемогти готові,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'То не дивуйся: бачення зроста
На досконалості і, як відкриє,
То на відкрите благо шлях верста.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Я бачу вже, як світло зазоріє,
Що в розумі твоєму зайнялось,
Як, бачивши його, любов замріє.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Коли ж її привабить інше щось,
Це лиш сліди, що ледве розрізняють,
Сліди од світла, що в віках знялось.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Запитуєш, чи добре заміняють
Нездійснений обіт святі діла
Й тоді гризоти душу обминають?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Так Беатріче пісню почала
І, наче той, хто каже без зупинки,
Благе повчання далі повела:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = '«Дарунок найдорожчої оцінки,
Що добрий Бог в щедроті дав нам всім,
Оцінювати й визначати вчинки, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Свобода волі та, що лиш самим
Усім розумним надана створінням
І надаватиметься тільки їм.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Тепер своїм ти дійдеш розумінням,
Що важить більш обіт од всяких мір,
Бо згоден Бог, як згоден ти сумлінням.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Але, уклавши з Богом договір,
Здаєш ти скарб понад усяку ціну, -
Моїм словам про нього ти повір!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Що може стати на його заміну?
Ти вже віддав від себе основне,
А з не свого ти як даси й частину?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Таке тут міркування головне.
Та церква зміни дозволя робити,
І це немов спростовує мене.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Тож не відходь од столу, хоч і ситий,
Бо страви нелегкої, що я дам,
Тобі інакше не перетравити.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Розкрий же розум свій моїм словам
І їх замкни: те не стає в науку, ¦
Що ти, почувши, не сприймаєш сам.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Дві речі вкрай потрібні на розлуку
Із жертвуваним: це - саме воно
І між двома угода на спонуку.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Ця друга річ існує все одно,
Аж поки здійснюється; це про неї
Тобі казала я не так давно.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Тому-то править мусили євреї
Цю жертву завжди, хоч не раз вона
Була, як знаєш, не в вині й єлеї.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Суть іншої не дуже-то й складна,
І, певно, гріх ви б не такий зробили,
Коли б змінилась в ній речовина.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Та хоч би як тягар змінить хотіли,
А, взявши, мусите його нести,
Поки ключі не зрушні - з жовтим білий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'І всякий обмін, ти повір, пустий,
Якщо обміненого у новому
Не вмістиш, як чотири у шести.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Коли ж воно у значенні свойому
Аж перетягує ваги, тоді
Його не можна обмінять нікому.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'В обітах, смертні, будьте ви тверді,
Але не обіцяйте необачно,
Як сталось Ієвфаєві-судді,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Що не сказав: «Вчинив я непробачно», -
А зле вчинив, і вряд стоять вони
Із грецьким тим вождем, що в війську лячно'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Усі ридали, що з його вини
Як жертва Іфігенія вмирає, -
Й ридма ридали мудрий і дурний.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Хай кожен з християн себе смиряє,
Пером під вітром не летить у літ,
Не вірить, ніби все вода змиває.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'У вас є Ветхий і Новий завіт,
Ще й пастирі церковні - вам єдиний
Показувати шлях на правди світ.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Не забувайте ж гідності людини,
Як пориватиме вас хіть на зле,
Щоб вас єврей не брав на сміх і кпини.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Не будьте, наче те ягня мале,
Що кила материне вим''я ссати,
Стрибає й бавиться, як Бог пошле».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Так Беатріче - маю те списати -
І погляди, палких жадань гінці,
Звелись у світ, яскравим сяйвом взятий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'її мовчання й зміна на лиці
В мого розсудку одібрали мову,
Що запитом лягла на язиці.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'І як стріла влучає в здобич лову
В той час, коли ще тятива дзвенить,
У друге царство ми летіли знову.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Так владарка спахнула радо вмить,
Коли на світ цієї сфери стала,
Що не могло й світило так ясніть.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Якщо ж сама зоря торжествувала,
То що з собою я б робити став, -
Моя природа-бо така нестала!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Щось кинувши в прозорий рибний став,
Ти бачиш, як всі риби збились в кучі,
Гадають, що принаду ти їм дав, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Так іскор тисячі - яркі, блискучі -
До нас збігалися й гукали всі:
«Ось хто зростить нам почуття найлуччі!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'По сяйній наближалися косі
За духом дух, на радощі багаті,
Осяяні в усій своїй красі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Читачу, здумай: як слова початі
Тут увірвались би, то з дальших дій
Ніщо б не втиснуло в твій ум печаті.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'І зрозумів би ти тоді хутчій,
Як прагнув я розмови з душ юрбою,
Лиш увійшла вона у погляд мій.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = '«О значений високою судьбою,
Уздриш ти вічного тріумфу трон
Ще до закінчення земного бою!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Ми в сяйві ясному небесних лон
Теж сяєм; як в собі ти хіть роздмухав
Спитать, хто ми, - ця хіть тобі закон», -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Сказав так хтось із благочесних духів,
А Беатріче: «Ти кажи, кажи
І вір їм, начебто богів ти слухав».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = '«Ти вбраний, бачу, в промінь нечужий,
Бо ллється він твоїм же чистим зором,
Всміхнешся - заяскріє до межі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'З''ясуй, благаю, хто ти й на просторім
Цім місці, світлий душе, став чому,
Від смертних вкритий світлом непрозорим?» -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Так проказав я сяєву тому,
Що мовило, й воно спахнуло лиском,
Немов зачувши ангельську сурму.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Як сонце, сховане надмірним блиском,
Вгорнулося у клуби світляні,
А спека випромінювалась диском, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Свята ця постать радістю в ясні
Запнулась промені, прямі й навскісні,
Й, вкривалом вкрита, мовила мені...'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'А що - йде спів про це в наступній пісні.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 5
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 47;

UPDATE cantos SET title_uk = 'ПІСНЯ ШОСТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 6
    AND p.name = 'Paradiso';

UPDATE terzinas SET text_uk = '«Відколи Константин орла у небі
Пустив навпроти, а не по слідах
Того, хто взяв Лавінію за себе,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Сто літ, і сто і більше божий птах
Жив на кінці Європи, край Троади,
Звідкіль злетів колись він по світах,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'І попід тінню крил своїх без вади
Передавав з рук в руки берло й сан,
Коли й мені тягар дістався влади.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Там був я цезар, тут - Юстініан.
Займавсь огнем я першої любові,
Коли закони очищав з оман.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Ізмалку я в одну, не в дві Христові
Природи твердо вірив, мов граніт,
І щиро віддавався цій обмові,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Але благословенний Агапіт,
Найвищий пастир, в казаннях церковних
Відкрив мені святої правди світ.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Повірив я у суть речей ґрунтовних
І добре бачу, змивши смертний бруд,
Як святість одрізнять од діл гріховних.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Я прилучивсь до церкви без облуд.
І Бог мене вкрив ласкою такою,
Що вклав я все життя в величний труд.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Вручив я Велізарієві зброю,
І небеса сприяли в війнах їй,
І міг я скуштувати супокою.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Ця відповідь на запит перший твій
Іще кількох пояснень вимагає,
Щоб ти звільнився від обманних мрій.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Щоб ти збагнув, хто з них всю правду знає, -
Чи той, хто знак святий собі на спис
Прикріплює, чи хто його знімає, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Глянь на чесноту, із якою зніс
Себе він в небо». І почав з години,
Як вмер Паллант, щоб він звитяжно зріс.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = '«Ти знаєш, як три віки ждав хвилини
Він в Альбі, поки стався перехід,
І три з трьома зійшлись серед рівнини.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'І знаєш, як од злих сабінкам бід
До бід Лукреції він, за свавільних
Сімох царів, звойовував сусід.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'І знаєш, як він в римських лавах сильних
Встав проти Бренна, проти Пірра встав
Та інших ватажків, із ними спільних,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Як вславилися Квінтій, що дістав
Ім''я Кошлатий, Фабії з Торкватом
І Деції, що світ їх вихваляв!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Він гордощі арабам збив пихатим,
Що з Ганнібалом Альп взяли кордон,
Де протікає По в краю багатім.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'З ним юнаки долали - Сціпіон,
Пізніш Помпей, - твою він рідну гору
Віддав печалям і журбі в полон.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Коли ж у небі здумали в ту пору
Дать тишу всій землі на свій зразок,
Над ним взяв Цезар з волі Риму гору.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Ізара, Ера, Сена, тих річок
Долини, що у Рону йдуть, уздріли
До Рейну й Вару діл могутній крок.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'А далі дії так замиготіли
З Равенни й рубіконського стрибка,
Що вгнатися перо не має сили.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Він переніс в Іспанію війська,
В Дураццо, у Фарсалу тим походом,
Що скрута й Ніл одвідала гірка.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Минув Антандр, Сімоент, звідки родом,
Могилу ту, де Гектор спить німий,
Губити Птолемея ринув згодом,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'На Юбу кинув раптом він громи,
А там до вас, на захід, повернувся
І рев Помпеєвої вчув сурми.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'За те, що той, хто ніс його, спіткнувся,
Вік з Кассієм скавчить у Пеклі Брут,
Модени ж і Перуджі край здригнувся.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'А Клеопатрі й досі горе тут,
Бо, марно утікаючи від нього,
Вона з гадючих згинула отрут.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Досяг він моря Чермного страшного,
Досяг твердого миру для людей,''
І храм замкнувся Януса ясного.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Але все те, що знак сподіяв цей
І що він мав сподіять дальшим кроком
У смертнім царстві, данім, як трофей,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Ніщо, коли поглянуть світлим оком,
Як третій цезар в руки взяв його,
І почуттям віддатися глибоким.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Жива-бо Правда із руки того
Дала йому у славі неугавній
Помститись палом гнівання свого.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Почуєш з подивом про речі славні:
Із Тітом він пізніше відомстив
Тяжке відомщення за гріх днедавній.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Як лютість лангобардових зубів
Свята спізнала церква, Карл Великий
її під крилами його укрив.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Я звинуватив - засуди ж навіки
Тих, хто своїми вчинками в житті
Одводить вас од Вишнього владики.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Одні за стяг лілеї золоті
Вважають, ті ж - собі його грабують,
І хто тут винний більше - ці чи ті?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Хай краще гібеліни всім гендлюють
Під іншим знаком, в нього ж стежка є,
Яку вони із правдою торують.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'І хай його новий той Карл не вб''є
Із гвельфами, а то ще з кігтів згинуть,
Якими й левам ран він завдає.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Син часто-густо сліз ніяк не спинить
За батькові гріхи. І марно ждать,
Що Бог свій герб на їх лілею змінить.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'На цій маленькій зірці - благодать
Для добрих духів, що були діяльні,
І вслід пошана й слава їм спішать.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Коли ж на манівці ступає дальні
Бажання вславитися чимскоріш,
Любові никнуть промені печальні.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'У кожного тут щастя частка лиш,
Хто скільки заслужив життям в чесноті,
І меншого чи більшого не зриш.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Живої Правди міць в своїй пишноті
Торкається сердечних наших сил,
Які не піддаються злу й скверноті.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Співають ніжні голоси окіл, -
Так східці нашого життя багату
Гармонію дають поміж цих кіл.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'На всю перлину, сяєвом залляту,
Ромео сяє, що йому дало
Його пресвітле діло темну плату.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Та провансальцям зиску не було,
Що замах їх на нього був удалий:
Тим зле, кому чужа чеснота - зло.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'В Раймонда четверо дочок зростало,
І так зробив для графа пілігрим,
Що королевами вони всі стали.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Та на вимогу скласти звіт у всім
Якій причина - наговір огидний,
Здав праведник за десять п''ять і сім,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'А сам пішов собі, старий та бідний, -
Й якби у жебраку впізнав загал,
Хто просить хліба, шани справді ж гідний,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'Ще похвали б додав він до похвал».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 6
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 48;

UPDATE cantos SET title_uk = 'ПІСНЯ СЬОМА Друге, Меркурієве небо. - Спасіння'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 7
    AND p.name = 'Paradiso';

UPDATE terzinas SET text_uk = '«Владико воїнства, предвічно сущий,
Возславим тя, счастливії огні
Всегда во царствіє сіє несущий!» -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Так заспівавши, в вири огняні
Ця сутність одлетіла по кружінню,
З подвійним сяєвом у вишині,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'І в танцях легко віддалась тяжінню,
Та затягла її юрма в свій край,
Раптовою помчавши далечінню.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Вагавсь я й мовив: «Ну, спитай, спитай, -
Собі: спитай, - я мовив двічі й тричі:
Роси напитись спраглому подай».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Але під шаною до БЕ й до ІЧЕ,
Що пойняла всього, чоло схилив,
Мов той, що сон йому заходить в вічі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Сказала Беатріче кілька слів
І стала так чарівно посміхатись,
Що й той зрадів би, хто в огні горів:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = '«Я знаю, з чого розпитам початись, -
Хіба за люту справедливу мсту
Теж справедливо люто відомщатись?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Лишень послухай - помилку пусту
І весь твій сумнів скоро заспокою
І подарую істину святу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Той, що не народився, із пихою
Вузду Господню мав собі за зло
Й згубив себе й нащадків із собою.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'І людство кволе у гріхах жило,
Віками підпадало безголов''ю,
Аж поки Слово Боже не зійшло'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'На вбогу землю й не злучило кров''ю
Природу, гнану за вину стару,
Із власною безсмертною любов''ю.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'А зараз погляд на таке скеруй:
Природу цю, приєднану до Бога,
Сотворено, щоб віддалась добру,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Але прослалась врешті їй дорога
Із Раю, бо вона пішла убік
Від стежки істини й життя святого.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'І кара на хресті, що Бог прирік,
Як міряти на сприйняту природу,
З усіх найсправедливіша повік.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Але й несправедливості ізроду
Безсмертної такої не знайшлось, -
Бо страдник мав не ту натуру й вроду.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'На всьому різно це взнаки далось:
Господь зрадів тій смерті і євреї,
Стряслась земля, і небо розійшлось.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Тепер із думки не дивуй моєї,
Що справедлива мста прийшла-таки
До помсти справедливої своєї.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Та бачу я, таким вузлом думки
З думками розум у тобі скрутило,
Що визволився з них ти б залюбки.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Ти скажеш: «Все, що чую, зрозуміло,
Та Божого не тямлю рішенця, ''-
Спасавши нас, таке обрати діло».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Та, брате, неприступна тайна ця
Для тих, що розум їх недосконалий
Не зріс в огні любові до кінця.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'І чим її упертіш спізнавали,
Тим таїна була темніша та...
Скажу тобі, що інші б не сказали.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Іскриться сяйвом Божа доброта.
Лють женучи зусюди, й так же само
Скрізь вічно променіє красота.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Те, що до вас іде від неї прямо, -
Безмежне, бо вона як покладе
Печать, не буде зміни або плями.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Те, що до вас од неї прямо йде, -
Цілком свободне, бо сторонніх впливів
Не зазнає ніколи і ніде.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Миліший той, хто із найтонших звивів,
Святий-бо запал блискотить ясніш
У тому, хто себе із неї вивів.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Людина з благом схожа найповніш,
Та благородності їй убавляє
Нестача риси хоч одної лиш.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Від неї гріх єдиний затуляє
Свободу й схожість з благом неземним,
її не досить сяйво убіляє,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Чуже воно достойностям своїм
І знає лиш веселощі без краю,
Каранням ще не сплачені страшним.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Природа ваша, грішна до відчаю
Ще з зародку, втеряла сповна суть
Достойностей, і, вигнаній із Раю,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Не можна їй було їх повернуть
(Сягнеш цих мислей в їх протиборінні,
Як тільки станеш на єдину путь),'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Або щоб Бог в своїм благоволінні
Простив, або людина щоб сама
Розкаялася у гріхопадінні.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Тепер заглибся силою ума
В безодню мислей, щоб могла святитись
Твоя увага, чуйна і німа.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Людина не змогла з вини омитись, -
Природні межі не давали їй
До послуху принижено хилитись,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'А в вись тяглась через непослух свій, -
Тому-то їй роками і віками
Не випадало змить вину самій.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'І мусив Бог покінчити з гріхами
Й вернуть людині повноту буття
Чи то одним, чи то двома шляхами.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Та виріб тим любіший за життя
Виробникові, чим повніш відбиті
Закладені в нім добрі почуття.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Тож Божа доброта, відбита в світі,
Була щаслива помогти тому,
Щоб піднялась людина до блакиті.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'З початку світла по останню тьму
Ні разу не прийшло ще, засіявши,
Таке й не прийде рівного йому.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Бог щедрість вищу виявив, оддавши
За порятунок ваш себе всього,
Ніж просто б вам гріхи всі оставлявши,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Не досить справедливості того
Було б, як не принизився б смиренно
Син Божий до влюдинення свого.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'А зараз до дрібниці достеменно
Вагання кожне роз''ясню твоє,
Щоб все ти розумів не гірш за мене.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Ти кажеш: «Бачу, все, що в нас не є -
Вогонь, земля, вода, повітря, - з тління
Окремо й вкупі гине і гниє,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'А це, звичайно, все-таки створіння».
Але щоб суть була тут таїни,
Ніщо б не нищилося до коріння.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Самі лиш ангели, й цей край ясний,
Де, брате, зараз ти, і ці світила -
Всі первісно сотворені вони.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Стихії ж, що згадав ти не до діла,
Й все, складене з часток їх складових, -
Всі речі створена формує сила.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Сотворено й речовину всіх їх,
Сотворено і силу формування
У зоряних кружіннях колових.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Із тіл святих небесних рух і сяння
Низходять в душі звірів і рослин
На їх минуще кволе існування.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'А вам життя приносить лиш один
Дух доброти, найвищої в природі,
Й запалює бажання вічні він.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'Це з вашим воскресінням стане в згоді,
Коли до тебе думка вже дійшла,
Як ваше тіло твориться відтоді,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 49;

UPDATE terzinas SET text_uk = 'Як створено прабатьківські тіла».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 7
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 50;

UPDATE cantos SET title_uk = 'ПІСНЯ ВОСЬМА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 8
    AND p.name = 'Paradiso';

UPDATE terzinas SET text_uk = 'В те вірили народи, нині зниклі,
Що шле навкруг любовний шал вгорі
Ясна Кіпріда в третім епіциклі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'В старих цих заблудах вони, старі,
Не тільки їй у пристрастей полоні
Споруджували пишні вівтарі,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'А й матері - вродливиці Діоні,
І сину Купідонові, що сів
На руки, переказують, Дідоні.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Ім''я, з якого я почав цей спів,
Тій зірці дано, що з жаги своєї
На сонце дивиться з усіх боків.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Я, не відчувши, що злетів до неї,
Це зрозумів із того, як зросла
Ще більш краса володарки моєї.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Як видна іскра в полум''ї мала
Чи голос вирізняється рухливий
З незрушного голосового тла,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Помітні стали світлі переливи
Світильників у вихорах швидких,
Куди, гадаю, вів їх зір щасливий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Холодний вітер, що летить з низьких
Зимових хмар чи зримий, чи незримий,
Той залічив би до найменш прудких,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Хто б глянув, як гірляндами стрімкими
Летючі світла кидали танки,
Що почались, де линуть серафими.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Між духами, яких неслись полки,
Бриніла так «Осанна!», що я досі
Бажаю знов почути звук палкий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Один наблизивсь чемно, як велося,
Промовив: «Радо зробить наш загал
Усе для тебе, що б не довелося.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Ми кружимося стежками Начал,
У тому ж крузі, крутені, потребі,
Що ти про них казав під гул похвал:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = '«Ви, хто думками водить в третім небі...»
Зупинимось, любові повні, ми,
Якщо приємний спочив наш для тебе».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Звів погляд я поштивий і німий
На владарку і з поглядом зіткнувся,
Що влив би певність у людські уми,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Й до світла я привітного звернувся,
І на моїх словах: «Скажіть, хто ви?» -
Од хвилювання голос мій здригнувся.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Який же спалах радості новий
Я вздрів, коли ще сяйво приєдналось
До сяйва круг святої голови!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Спахнувши, він сказав: «Мені дісталось
Недовго жить, а не взяла б земля,
То зла, що сталося, тоді б не сталось.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Мене відрада світла затуля
Від тебе, наче кокон величавий,
В шовку якого спить черв''як-маля.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Мене любив ти і не без підстави;
Якби не вмер я, міг тобі зложить
Не листя б - інше щось, гідніше слави.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Мене ждав лівий берег, де біжить,
У себе Соргу увібравши, Рона, -
Коли ж він зможе підо мною жить!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Так само й ріг Авзонський, де Катона,
Гаета й Барі повняться снаги,
А Тронто й Верде обійма корона.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Вже на мені вінець був дорогий
Земель, де ллє Дунай, з тієї грані,
Де поїть він германські береги.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'А чарівна Трінакрія, у тьмяній
З Пакіно до Пелоро течії,
Жорстоко Евром мученій, в тумані'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Не від Тіфея - з сірки надр її,
І досі б звикла, що на трон восходять
З Рудольфа й Карла в ній сини мої,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Якби не кепські власті, що призводять
Народ до бунту й вигук: «Бий їх, бий!», -
Як у тому Палермо, завжди родять.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Коли б дививсь мій брат вперед, юрби
Харциз би каталонських одцурався
І через них би не зазнав ганьби.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'З думками, справді, добре б він зібрався,
Судна, що й так обтяжить водну синь,
Вантажити над міру б не старався.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Скупар, хоч батьку люба широчінь,
Хай брав людей на всяку б він посаду,
Уважних не лише до власних скринь».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = '«Тут, де з кінцем початок блага зряду,
Гадаю, бачиш добре, як я сам,
Велику, нескінченну ту відраду,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Яку ти, пане, дав моїм очам,
І цінне тим мені твоє прозріння,
Що погляд твій належить небесам.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Приніс мені ти втіху розуміння,
То ще мій сумнів розтлумач мудріш:
Чом плід гіркий в солодкого насіння?» -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Так я йому, а він: «Ти правду вздриш,
Звернувши очі на мої повчання,
А ти до неї спиною стоїш.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Благий, що цим місцям несе втішання
І рух, в тілах великих тих святе
На порух обертає призначання.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Натури, що призначені на те,
Не лиш притулок в мислі досконалій
Знаходять, - в ній спасіння їм росте.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Що кидається луком в дальні далі,
Все опиняється в своїй меті,
Немов стріла в призначенім кружалі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Бо небо, де твої лежать путі,
Творитиме інакше не тривалість,
А нетривкі лиш безлади пусті, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Цього ж не може бути, якщо сталість,
Що водить ці зірки, не має вад
І Перший не забув про досконалість.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Та, мабуть, досить з тебе цих засад?»
Я ж: «Ні, не вірю, начебто безсиле
Те, що встановлює в природі лад».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Тоді він знов: «Скажи, хіба не миле
Життя в громаді для людських сердець?»
«Еге ж, - відмовив я, - це зрозуміле».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = '«А чи здійсниш його, коли Творець
Різниць не зробить в різних званні й вмінні?
Ні, якщо пише правду ваш мудрець».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Поглибив ще він докази незмінні
І закінчив: «Так ось який закон
Про різний плід на різному корінні.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Народиться тут Ксеркс, а тут Солон,
А тут Мельхіседек, а там - той самий,
Чий син з-під хмар упав у вічний сон.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Круговорот природи, хоч віками
На смертний віск печаток тьму поклав,
Не робить все ж відміни між домами.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'І через це від Якова Ісав
Різнився сім''ям, хоч з того ж був ложа,
Квірин же вбогий Марса батьком звав.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Народжена природа всім би схожа
Ставала на родительку свою,
Коли б управа не втручалась Божа.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Ось втеклу тайну ти зловив твою,
Та вчу тебе для власної догоди
І думку ще одну скажу мою.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'В незгодної із долею природи,
Мов у насіння в ґрунті несвоїм,
Бувають завжди слабосилі сходи.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'Як світ би, рухавшись, у русі тім
Спирався тільки на природу праву,
Росло б далеко ліпше людство в нім.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'Призначеного на воєнну славу
Ви тягнете до олтарів і ряс,
Молитвенику ж даєте державу, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 49;

UPDATE terzinas SET text_uk = 'Тому й неправильні стежки у вас».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 8
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 50;

UPDATE cantos SET title_uk = 'ПІСНЯ ДЕВ''ЯТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 9
    AND p.name = 'Paradiso';

UPDATE terzinas SET text_uk = 'По цих словах твій Карл, Клеменцо гарна,
Повідав, скільки зла його сім''ї
Наробить люта ворожнеча марна,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Й сказав: «Мовчи, хай літ спливуть рої».
Тож мовить мушу лиш, що сплатять в плачі
За ваші муки миру крадії.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Святого сяєва життя гаряче
Вернуло знов до сонця, до мети
Всього, що в світі є, буттям кипляче.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Ой леле душам тих, хто й сам іти
Звик понизу й думки свої принизив
До ницої мирської суєти!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Аж от ще блиск себе до нас наблизив,
І спалах сяяння його я мав
За лагідний мені до втіхи призив.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'І погляд Беатріче, що сприймав
Його в тремтливості я невимовній,
Ласкаво знову дозвіл мені дав.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = '«О мир подай душі, бажання повній,
Блаженний душе, - я сказав, - промов,
Що втямив думку ти без слів іззовні».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'І світ мені новий, що вів з основ
Глибоких надр, похвальний спів у славі,
Сказав, мов той, хто на добро готов:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = '«В Італії, зіпсутій і кривавій,
На землях від Ріальто до хребта,
Який дарує води Бренті й П''яві,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Є не така й велика висота,
Де блиснув факел в замку старовиннім
І попалив навкруг поля й міста.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Із ним були одні ми за корінням.
Куніцца звалась я і тут свічу,
Цієї зірки скорена промінням.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Я безтурботно й радісно лечу
І розгрішаю бурний шлях гріховний,
Хоч втямить це юрбі не по плечу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'А цей, до нас найближчий, скарб коштовний
Мав славу голосну, ще поки жив,
І поки край їй прийде безумовний,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Цей сотий рік зросте у п''ять разів.
Поглянь лишень, які той мав заслуги,
Хто друге по собі життя лишив.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Не так міркує натовп, що без туги
Між Тальяменто й Адідже живе
Й, хоч битий, а не визнає наруги.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Та скоро бунт знамено бойове
Підніме в Падуї, й Віченца в твані
Інакшою водою підпливе.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Де збіглись води в Сілі та Каньяні,
Владар підносить в гордості чоло,
Хоч вже плететься сіть, в яку він встряне.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'У Фельтро скорбному велике зло
Таке учинить пастир нечестивий,
Що й менше в Мальті варт карать було.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Під кров феррарців в світі неможливий
Потрібен чан; на унції ж вагар
Ту кров не зважив би й найбільш терпливий,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Якою, партії любимій в дар,
Поллє люб''язний цей священик поле,
Та не здивує тамошніх почвар.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Згори, з дзеркал, що звуть у вас Престоли,
Яскраво сяє вишній Судія,
Що не марнує слів своїх ніколи».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Вона замовкла, й сяйного буття
У вічній ясності могутня сила
Знов узяла її, як бачив я.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = '1 інша радість, знана вже, ступила
Під пломінь у моїх жадних очах,
Немов рубін у променях світила.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Радіють сяєвом у небесах,
Як на землі усмішкою; хмурніє
Тінь унизу, коли думки в сльозах.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = '«Бог бачить все й в твоєму зорі мріє,
Блаженний, - я промовив, - голова
Від тебе жодна дум своїх не скриє.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Чи голос твій, що в небесах співа, -
Тут кожне полум''я благословенне
Шістьма крильми обличчя закрива -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Моє жадання обмине смиренне?
Йшло б запитання з мене без зусиль,
Коли б я в тебе вливсь, як ти у мене».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = '«Найбільший діл, де хвилі мчать суціль, -
В таких словах почав свою він мову, -
Із вод, що сушу тиснуть звідусіль,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Між берегів розтяг свою основу
Так проти сонця, що меридіан
Стає на місці, де крайнебо, знову.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'На цьому долі жив я, бережан,
Між Ебро й Магрою, що омиває
Кордонний Генуї й Тоскани лан.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Схід сонця й захід в той же час буває
В Буджеї й в рідному краю моїм,
Де кров ще й досі хвилі зогріває.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Я Фолько звався між людей, яким
Був знаний на ім''я; тепер душею
Владає небо, як колись я ним.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Ні Белова дочка в ганьбу Сіхею
Й Креусі не була така палка,
Як я із невтолимістю своєю,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Ні зведена дівчина боязка
Зі скель Родопських, ні Алкід могутній,
Якого вбила жінчина рука.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Не згадують тут голоси покутні
Гріха старого, й кожен промовля
Про мудрість, що приводить час майбутній.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Зорим тут на мистецтво не здаля,
Захоплено віддаємося благу,
Що в вишній дольній світ переробля.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Але щоб ти відчув свою звитягу
Й здолав останні сумнівів сліди,
Я ще затримаю твою увагу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Ти хочеш знати, хто пливе сюди
В осяйності сліпучій та глибокій,
Мов сонце в шарі чистої води?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'То знай, що тут вкушає вічний спокій
Раава і, вінчаючи нас всіх,
Підводиться на сходинки високі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Найперша із тутешніх душ святих,
Де видно ще ваш світ у тіні млистій,
Вінців сподобилася золотих.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Це правильно було, що в сфери чисті
Він зніс її, як тріумфальну віть
Звитяги, що здобув, прип''явши кисті,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Сприяла ж славі до кінця століть
Вона Ісусовій в святій країні,
Якої пам''ять папі не болить.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'В твоєму місті рідній тій дитині
Того, хто перший встав проти Творця
І лихо заздрістю приніс людині,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'З''явилася проклята квітка ця,
Яка зі шляху вівці гонить люто
Й на вовка обертає чабанця.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Святе письмо, святих отців забуто,
Звід Декреталій всю науку зжер,
І це на їхніх берегах почуто.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Ось папі й кардиналам труд тепер,
Байдужий їм той Назарет з хатками,
Де крила Гавриїл колись простер.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Та Ватикан, святі прадавні храми
І кладовища, де поліг той люд,
Який пішов Петровими слідами,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'У себе скоро винищать весь блуд».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 9
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 48;

UPDATE cantos SET title_uk = 'ПІСНЯ ДЕСЯТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 10
    AND p.name = 'Paradiso';

UPDATE terzinas SET text_uk = 'На сина дивлячись, любові повний,
Що вічно з них обох потоком ллє,
Найперший, у могутті невимовний'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Усе, що в думці чи в просторі є,
Створив так до ладу, що всі істоти
Вбачають в ньому торжество своє.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Зведи, читачу, зір свій на висоти,
Зі мною перехрестя досягни,
Де певний рух стрічає рух навпроти,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'І ту майстерність споглядать почни,
Яку митець так гаряче плекає,
Що втуплює у неї зір ясний.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Поглянь, як звідти дуги випускає
Для осяйних планет похилий круг,
Що їх на допомогу світ гукає.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Якби планети йшли не в площі дуг, -
То сил у небі зникло б вщент немало,
А на землі загибло б все навкруг.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Якби кружіння їх не приставало
До сторчака, на волосинку хай, -
То ладу б в світі, вниз чи вверх, не стало.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Отож, читачу, з лави не вставай,
Посидь, помрій, на що я надивився,
І без утоми щастя зазнавай.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Я дав покорм, щоб ним ти наситився,
Мене ж поглинув той предмет цілком,
Письменником якого я зробився.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Природи величавий майордом,
Що сили неба в світ низводить нижчий
І доби лічить світляним перстом,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Із перехрестям, що списав я вище,
Кружляв по небу закрутом крутим,
Щораз, то все яскравіший та ближчий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'І я з ним був; як опинивсь на нім,
Я не помітив, як і не помітить
Хтось думки, поки не спахне в самім.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'І в Беатріче - у тієї світить
Не благо, щось значніше в ясну мить.
Якої часові і не одмітить.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Як мають сяянням усі рясніть
У надрах сонця, - це я встиг відзначить, -
Коли не колір - світло їх різнить!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Ні хисту, ні знання, ні слів не стачить
Мені, щоб все належно повісти,
То просто вір і прагни сам побачить.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Уява ж нас не може занести
До тих висот, і є на це причина,
Бо їлиб за сонцем для очей пустий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Отак четверта блискотить родина
Високого Отця, що звіку слав
І шле із себе Духа й родить Сина.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'І Беатріче почала: «Прослав,
Прослав же Сонце ангелів, що з його
Ти ласки шлях сюди живим прослав».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Не знало жодне серце ще такого
Святого захвату, й ніхто не був
У пориванні ще такім до Бога,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Як, слухаючи, зразу ж я відчув, -
Любов мене взяла всього без лишку,
І я про Беатріче позабув.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Вона ж, безгнівна, кинула усмішку,
І сміхотливий блиск її очей
Мою суцільну мисль дрібнив на кришку.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Уздрів я безліч сяйв, і натовп цей
Робив з нас центр, а сам - на взір корони,
Вів пісню ще ніжнішу за лице.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Так пояс із сріблястої запони,
Коли густіє пара в небесах,
Вдягає чарівна дочка Латони.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'В палаці вишньому, де йшов мій шлях,
Без ліку самоцвітів є коштовних,
Яких із царства не знести в руках.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Таким було й співання сяйв чудовних,
Кому ж даровано без крил серця,
Речей ждуть од німого велемовних.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Співаючи, яріючі сонця
Промчали тричі вкруг, подібно зорям
Круг осі, ближчим до її кінця,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Й спинились, як, віддавшись танцям скорим,
Жінки безмовно мить якусь стоять,
Аж поки пісня знов поллється хором, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Одне з них почало: «Як благодать,
Котрої промінь полум''ям одводить
Любов правдиву, щоб улад зростать'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Із нею люблячи, в тобі так сходить,
Що на висоти сходами веде,
Якими йде наверх, хто вниз низходить, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'То хто б вина свого не дав ніде
Тобі, той од натури був би вільний,
Як річка та, що не до моря йде.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Які складають квіти цей начільний
Вінок - спитаєш зараз ти мене -
Тій, що звела тебе в палац весільний?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'От я - в отарі був ягня дрібне,
Що Домінік вів шляхом, де невинно
Живитимуться всі, хто не схибне.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Цей, справа, брат і вчитель воєдино
Для мене був; Альберт з Колоньї він
Ім''я носив, а я - Фома з Аквіно.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'А хочеш упізнати весь загін,
За розповіддю стеж очима стишка,
Йдучи разком блаженних намистин.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Ось світить Граціанова усмішка;
Він присвятив життя обом правам,
І просто в Рай звела його доріжка.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'А цей, що сяє в нашім хорі там,
Був тим Петром, який, мов удовиця,
Свій скарб увесь пожертвував на храм.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'З нас найгарніше п''ятий промениться
В любові, і юрба людських сердець
Вгорі на нього мріє подивиться.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'В високий ум таку глибінь Творець
Вклав знань, що в разі правду правда каже,
Не бачено таких, як цей мудрець.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'А з ним своє палання світоч в''яже,
Що досконально за життя дізнавсь
Природу й службу Богової стражі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Блаженний вогник ще один снувавсь:
Поборник християнських тих історій,
Яких сам Августин пізніш навчавсь.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'А зараз думкою проглянь в просторі,
Від сяйва в сяєво, хвалам услід,
І в восьмому уздриш великі зорі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Радіючи на благ найменший слід,
Душа свята облуду в світі злому
Всім розкрива, хто терпить тьму обид.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Бо тіло, що її немає в ньому,
Лежить в Чельдавро, мученицька ж тінь
Блаженствує в спокої неземному.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Очима стрінься ще в вінку світінь
Із Ізідором, Бедою, Рішаром,
Який над людством став після видінь.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'А цей, мені сусіда ясним жаром,
Той сяйний дух, який в думках тяжких
Вважав був смерть занадто пізнім даром,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Сігером звавсь - на лекціях своїх
В Кутку Солом''янім він без упину
Доводив істини в словах їдких».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Коли годинник будить у хвилину,
Коли дружина Божа йде хвалить
Щоранку любого свого дружину,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'Й зубець, штовхнувши інші, їм велить
Свій виливати звук в «тінь-тінь» співливі,
Що може дух, мов соком плід, налить, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'Так видатне у славі справедливій
Це коло рушило, і з ним потік
За співом спів у зграйності, можливій'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 49;

UPDATE terzinas SET text_uk = 'Лиш там, де радість не скінчиться ввік.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 10
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 50;

UPDATE cantos SET title_uk = 'ПІСНЯ ОДИНАДЦЯТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 11
    AND p.name = 'Paradiso';

UPDATE terzinas SET text_uk = 'О смертних нерозважне метушіння!
Який нікчемний кожен силогізм,
Що відбирає в крил снагу кружіння!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Хто в право зануривсь, хто в «Афоризм»,
Хто - в вигоди церковної посади,
Хто в панство крізь насильство чи софізм,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Хто - у торгівлю, хто - в діла громади,
Хто ж - у розпусні втіхи виснажні,
А хто - у ледарстві шука розради,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Коли, чужий усій цій метушні,
В ті висі я піднявся з Беатріче,
Де шана готувалася мені.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Пропливши в небі коло таємниче
І повернувшись на свої місця,
Незрушні встали душі, ніби свічі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'І я почув, як мовить ясність ця,
І, мовлячи, ще більше заяскріла
Усмішкою і голосу, й лиця:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = '«Яснію я у променях світила
І, дивлячись в одвічний світ святий,
Ту бачу річ, що мисль твою збудила.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Ти сумніваєшся й бажаєш ти,
Щоб виклав я докладніше основу,
Якою міг би розум твій піти'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Од слів: «Живитимуться всі», - і знову
Од дальших слів: «Не бачено таких», -
Тож сенсу слід цьому надати слову.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Небесний промисл, що в путях своїх
Керує світом з мудрістю, якої
Дно недоступне для створінь людських,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Послав обвінчаній, щоб у спокої
До вінчаного тернами чола
І щедрим струмом крові пресвятої'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Вірніше і упевненіше йшла,
Двох вожаїв, які б шляхом незвичним
Вели її на визначні діла.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Один горів паланням серафичним,
А другий, невичерпний скарб наук,
Сіяв відбитком херувима вічним.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Скажу про одного, і правди звук
Обох торкне, бо йшли і той, і другий
На спільне кожен із своїх спонук.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Поміж Тупіно й річки, що з округи,
Де схил, Убальду любий, води ллє,
Зверта гора квітуча до яруги'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'І спеку, й холод на Перуджу шле
Крізь браму Сонця, ззаду ж слізьми сходять
Ночера й Гвальдо, нісши іго зле, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Де шлях в долину подорожніх зводить,
Колись там сонце світові зійшло,
Як наше з Гангу нам щоранку сходить;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Щоб на ім''я назвати це село,
«Ашезі» - назва не була б в пригоді,
Сказати «Схід» до речі б тут було.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Не так ще довго сонце йшло на сході,
А силою незмірною землі
Багато в чому стало при нагоді.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Почав цей світоч ще в літа малі
Із батьком суд за жінку, що в печалі
її в доми впускають крізь жалі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Перед судом в єпископальнім залі
Й перед Отцем обітниці слова ''
їй мовив, і любов зростала в палі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'В журбі за першим мужем удова
Жила понад тисячоліття з віком,
Аж поки з ним любов прийшла нова.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Байдуже, що безстрашно перед ликом
Того вона, як і Амікл, звелась,
Хто жах промчав над всесвітом великим.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Байдуже й те, що смілива вдалась
І, кинувши Марію у риданні,
Сама з Христом аж на хреста знялась.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Щоб не блукав ти з слів моїх в тумані,
Дізнайсь, що то з убогістю Франціск,
Та, певно, сам ти взнав, хто ці кохані.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'їх згоди й щастя їх осяйний блиск
Так на порив здивовання любовний
Збудив святими помислами тиск,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Що першим рушив сам Бернард шановний
Роззутий і чимдуж в життя нове
Спішився, бо, мовляв, забари повний.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'О тайний скарбе, благо вік живе!
Роззувсь Егідій, і Сільвестр роззувся
За тим дружиною - дружина ж зве.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'А батько й вчитель їх не похитнувся,
З владаркою, з сім''єю тих іде,
Хто мотузом смиренним перепнувся.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Він з того не спускає зір ніде,
Що він - дитина П''єтро Бернардоне,
Зневажувана за лице худе.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Кладе велично, мов король із трону,
Він перед Інокентієм статут,
І перший той дає закон загону.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Коли ж вбогеньких зріс чималий кут
У пастуха, чия бучна звитяга
У небі славиться - не тільки тут,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Прихильна духа вічного увага
Гонорієві ще один вінець
Дала оздобити чоло ватага.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Ждучи на мученицький рішенець,
Оголосив перед султаном пишним
Він про прихід Христа й його овець.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Але казання не було успішним,
І він вернувсь, робучий, в рідний дім,
Де мався урожай зрости розкішним.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Між Арно й Тібром на шпилі страшнім
Він у Христа останні взяв печаті,
Й вони два роки ятрились на нім.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Коли ж прикликав Бог в сади крислаті
Обранця, що в смиренності святій
На милості заслужував багаті,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Кохану в спадок братії своїй
Довірив він, щоб, наче неню діти,
її гляділи та служили їй.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Лише із неї прагнула злетіти
У небеса його душа свята
І інших мар для тіла не творити.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Яка ж душа була, помисли, та
Вести з ним гідна морем величенним
Петрову барку з символом хреста.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Отцем у нас він був благословенним,
І всі, хто чинить так, як він велить,
Опікуються ділом преблаженним.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Його ж отара стала так воліть
Нового харчу, що порозбрідалась,
Урожаїв шукаючи й політь.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'І чим вона охочіш відривалась
Від свого дому, тим частіш вона
Без молока у вимені верталась.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Лиш деякі, що пастка їм страшна,
Пригорнуться до пастуха; їх мало,
І обмаль їм на ряси йде сукна.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Тепер, якщо все говорив я вдало,
Якщо ти все у пам''яті зберіг,
Якщо до того ж і засвоїв дбало, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Ти вдоволив бажання, скільки міг:
Побачив, де рослина розчахнеться,
І зрозумів, чому я застеріг:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Живитимуться всі, хто не схибнеться».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 11
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 47;

UPDATE cantos SET title_uk = 'ПІСНЯ ДВАНАДЦЯТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 12
    AND p.name = 'Paradiso';

UPDATE terzinas SET text_uk = 'По мудрій мові полум''я блаженне
Замовкло, й знову порух між світів
Послав кружляти жорно те священне,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Та й першого ще кола не довів,
Коли намисто в зовнішньому крузі
Замкнуло з рухом рух, зі співом спів.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Суремний спів той в кожній нашій музі,
В сиренах наших зараз же чутно,
Як видно денний блиск у водній смузі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Як на дугу дуга стримить водно,
Така ж і кольорами, й кривиною,
Мов слід Іріди крізь небес вікно,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Але породжувана основною,
Тієї голос, начебто, яка,
Мов пара сонцем, всушена жагою,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Дуга ж звисає, як печать тривка,
Засвідчивши слова до Ноя Божі:
Не взна потопу більш сім''я людська, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Так віковічні ці сплелися рожі,
І, згоджені із одною одна,
Круг нас вились вже дві гірлянди гожі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Та враз врочиста пісня голосна,
Тріумфу гомін, радісне палання,
Із сяйвом сяйва мова затишна'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Спинились в спільнім трепеті чекання
(Буває спільним так на світлі й в тьмі
Повік і вій змикання й розмикання), -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'І з серця пломеня в новій юрмі
Злетіла річ, що зразу ж притягнула,
Мов зірка голку, зір уважний мій'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'І почала: «Любов, що огорнула
Мене, того вождя вславлять велить,
Бо про мого хвала тут спалахнула.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Обом достойно ту хвалу ділить, -
Як на землі рівнялися війною,
То й в славі цей із тим уряд стоїть.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Христова рать, великою ціною
Добувши зброю знов, брела до хмар,
Мала числом, несмілою ступою,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Коли в віках пануючий владар
На ці полки, запалі у тривогу,
Проливши не в заслугу щедрий дар,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Прислав своїй дружині на підмогу
Двох витязів, що їх діла й слова
Розгублених вернули на дорогу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'У тій землі, з якої повіва
Зефір солодкий, що теплом стікає
В Європу й зеленню її вкрива,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Та не у тому хвиль бурхливих краї,
Ізвідки вечорами суне мла,
А сонце від людських очей тікає,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Щаслива Каларога розцвіла,
Захищена великими щитами,
Де лев то здоланий, а то дола.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Тут народивсь закоханий без тями
В Христову віру богатир святий,
До друзів добрий, грізний з ворогами.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Зачатий, він такої висоти
Досяг одразу у своїх чеснотах,
Що неньці дав майбутнє проректи.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Коли в хрещальні малось при кіотах
Його і віру шлюбом об''єднать,
Обом те благо творячи в щедротах, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Тій, що за нього згоду мала дать,
Наснилось, що його, з братами спільно,
За труд вмиває Божа благодать.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'І щоб у слові суть відбилась пильно,
На рідних знявшись, дух його нарік
Того найменням, чий він був суцільно.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Отож з ім''ям Господній - Домінік -
Він між усіх обранців став Христових
У вертограді щирий помічник,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Посланець ще й слуга в садах Христових,
І першою спахнула в нім любов
До першої поради з вуст Христових.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Вночі ще змалку, повний молитов,
Він крижем падав долі, мовчазливий,
Мов кажучи: «Я в світ на те й прийшов».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Феліче-батьку, справді ти щасливий!
Джованно-мати, мила небесам!
Бо зміст в іменнях ваших справедливий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Не слідуючи суєтним трудам
Остійця чи Таддео недоспалим,
Він добував лиш манну справжню сам.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Невдовзі став знавцем він досконалим
[ взявся у саду глядіти грон,
Що гинуть з виноградарем недбалим.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'В престолу, що болів за всіх, в полон
Убозтвом взятих, а не про найближчих
(Бо виродок іще не сів на трон),'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Він не посад тепліших або вищих,
Не виплати по два чи три за шість,
Не «десятини іже Божьїх нищих», -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'А дозволу просив на добру вість
Про сім''я двадцяти чотирьох квітів,
Яку він сам заблудним розповість.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Знанням і волею шляхи намітив
Та й ринув на апостольські путі,
Немов потік із верхових гранітів.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Рубати єретичний сухостій,
І тим була палкіша в нього сила, -
Чим впертіший траплявся опір їй.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Пішла від нього вод силенна-сила,
Що католицьким садом протіка
Й багато вже деревець в нім зросила.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Коли таке одне з коліс візка,
В якому Божа церква подолала
Ворожі в міжусобицях війська,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'То уявляєш славу, що засяла
Круг другого, якому з вуст Фоми
Хвала переді мною тут лунала?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Проте забулись колії самі
Од верху кола, й з винного остатку
Сама лиш цвіль зосталась серед тьми.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Шляхом вождя родина йшла спочатку,
Але багато хто з його сім''ян
Вже ставить пальці там, де ставив п''ятку.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Й невдовзі доведе пожнивний лан
Суцільну ґандж; до житниць не попавши,
Почне являть обурення бур''ян.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Звичайно, в томі нашому гортавши
Одну по одній славні сторінки,
Читаєш: «Я такий, яким був завше».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'В Касале ж, в Акваспарті, навпаки.
Статут чернецький, як до їх натури,
Тим - засуворий, іншим - залегкий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Поглянь, я дух живий Бонавентури
Із Баньйореджо; службу ніс у лад,
Не важачи на лівий зиск понурий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'От Августин з Іллюмінатом вряд,
З мотуззям первістки із стада того,
Що їм, вбогеньким, Бог надав розрад.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Тут і Гуго од Віктора святого
З Петром їдцем, з Іспанським теж Петром,
Що дав дванадцять книг ума земного.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Натан-пророк тут, тут і Хризостом
(Що значить Златоуст), Ансельм з Донатом,
Який відомий видатним трудом.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'З Рабаном, що у Фульді був абатом,
Тут калабрійський пастир Джоакін,
Пророчим даром вславлений багатим.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'Що тут великий Божий паладин
Підніс на заздрість вчинки незабутні,
Це брат Фома причиною, - це він'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'На те підніс мене й вогні супутні».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 12
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 49;

UPDATE cantos SET title_uk = 'ПІСНЯ ТРИНАДЦЯТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 13
    AND p.name = 'Paradiso';

UPDATE terzinas SET text_uk = 'Нехай уявить, хто охоту має
Дізнатись, що я зрів (і хай він те
Як в камені карбоване, тримає),'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'П''ятнадцять зір, що сяйво золоте
Із неба нам на землю ллють у блиску,
Повітря пересиливши густе;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Нехай уявить Віз, оту колиску,
Яка черкає небеса щедрот,
І дишель в ній не меншає й на риску;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Нехай уявить також рога рот,
Туди розтулений, де, мов притертий,
Не рушить кола першого оплот,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'На ті два знаки в висях обіпертий,
Що, начебто Міноєва дочка,
Коли близький почула холод смерті,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Сплела проміння на взірець вінка;
І кожен знак летить один за одним,
Немов один від одного тіка, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'І вздрить тоді за колом хороводним
Мов тінь сузір''я в віддалі ясній,
Із рухом тим подвійним і свободним,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Який з усім, що в звичці є земній,
Не порівняти, як із рухом К''яни
Небесний рух, могутній і гінкий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Спів не про Вакха лився, не пеани -
Про того, хто в особах трьох один,
Про Божеський його і людський стани.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Та закінчивсь пісень і танців плин,
До нас вернулись, мов почувши втому,
Святі огні, неначе на спочин.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Зламав божеств мовчанку незнайому
Той пломінь, що душею я прилип
До слів його про божого сірому,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Й сказав: «Раз впорано вже перший сніп,
Раз впору з ниви урожаї знято,
То вже любов готує другу з кіп.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Ти думаєш, що в груди, звідки взято
Ребро на створення тих щічок-краль,
Де глотка людству обійшлась багато,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'І в ті, які, пробиті списом, жаль
І скорб лише за всесвіт почували,
Аж з місця зрушилась одна із шаль,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Влила все світло, скільки б не вміщали
Всі люди всіх часів і всіх держав,
Та міць, що їй обидва дітьми стали, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'І здивувався ти, як я сказав,
Що рівного не має тут в околі
Захований у п''яте сяйво слав.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Тож зір відкрий - і втямиш, як поволі
Твоя ця думка й слово це моє
У правді ляжуть так, як центр у колі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Все, що вмира чи мертвим не стає, -
Лиш відблиск мислі, що на світ появу
Господь в своїй любові їй дає.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Бо світло те живе, що йде по праву
З світильником й одноістотне з ним
Та ще з любов''ю, третьою во славу,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Осяює, за зволенням ясним,
На дев''ять сфер, мов дзеркало чудове,
І вічно залишається одним,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'А там донизу сходить по основі
Із кола в коло аж до кіл малих,
Де твориться минуще й випадкове.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'За випадкове я в розмовах цих
Вважаю утвори, що небо пружне
І з сім''ям і без сім''я плодить їх.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'їх віск і все оточення накружне
Не сталі, а тому й відбитки ці
Несуть значіння більш чи менш потужне.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Тому на першім-ліпшім деревці
Плоди ростуть солодші чи гіркіші,
І власна мисль на кожнім язиці.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Якби-то віск лишав сліди масніші,
Якби-то небо тиснуло сяйне,
Були б в печаті блиски найясніші.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Природа ж все, бува, в туман замкне,
Мов хтось-то появив мистецьке вміння,
Й, здригнувшись враз, рука в митця схибне.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Коли ж палка любов й ясне прозріння
Вливають першу силу у діла,
Тоді виходить звершене створіння.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Так сталось, що вшанована була
Земля над всею сутністю живою;
Так сталося, що діва понесла.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Погоджуюсь охоче я з тобою,
Що в вас, людей, такої не було
Й не буде вже натури, як ці двоє.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Коли б у мене мову одняло,
То: «Чим же мудрість в нього незрівнянна?» -
Твою б це слово мову почало.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Щоб таїна розкрилась осіянна,
Згадай, хто він, як рушила у путь
На клич «Проси!» молитва безустанна.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Не так кажу, щоб ти не міг збагнуть,
Що цар той мав за головне й важливе
Премудрості царевої сягнуть,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Не взнати все число зірок правдиве;
Або чи вийде неминучість та,
Як з неминучим в засновку можливе;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Й невже той поштовх - перших сил мета;
І як трикутник збудувать в півколі,
Щоб не було прямого в нім кута.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Отож, коли я промовляв доволі
Тобі про мудрість, то стрілою слів
Я націлявсь у мудрість на престолі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Як зір би на «не бачено» ти звів,
Побачив там би про державців мову:
їх безліч, гарних обмаль все ж царів.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Становить це речей моїх основу
Таку ж, як і в своїх ясних хвалах
І Праотцеві, й любому нам Слову.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Хай буде це свинцем в твоїх ногах,
Щоб вчув ти, мов утому від ступання,
Й до «ні», й до «так» щоб тягся довгий шлях.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Бо той - тупиця між дурних остання,
Хто чи підтверджує, чи відкида -
Й все навмання - усяке запитання.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Було, хапання часто без труда
На хибний шлях без роздуму водило,
Бо розум топить пристрастей вода.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Хто істину розшукує невміло
Й не тим, що був, вертає в свій куток,
Той гірш, ніж марно підніма вітрило.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Відкритий всьому світові зразок:
Брісс, Парменід, Мелісс і всі, хто в хмурній
Блукав пітьмі, шукаючи стежок;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Савелій, Арій і подібні дурні,
Що як мечі були для Божих книг,
Псували риси їм святі, безжурні.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Нехай би зважитись ніхто не міг
Чи суд, чи лік вершити з зиску й збитку,
Аж поки ниви впорати не встиг.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Узимку бачив я задублу вітку,
Колючий терен, гострий блиск шабель, -
І враз троянда розгорнула квітку.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Я бачив, як розкішний корабель,
Моря пропливши й океани, гине,
Уже діставшись бажаних земель.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Не мисліть, донно Берто й сер Мартіне,
Що, дивлячись - цей щедрий, інший - тать,
Ви з Богом дивитеся на єдине, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'Той може впасти, другий може встать».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 13
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 48;

UPDATE cantos SET title_uk = 'ПІСНЯ ЧОТИРНАДЦЯТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 14
    AND p.name = 'Paradiso';

UPDATE terzinas SET text_uk = 'Од краю в центр і з центру знов над краєм
Колишем воду в круглій вазі ми,
Коли у ній боки чи дно торкаєм.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Згадалися ті образи й самі
В ту мить мені постали просто в вічі,
Коли замовк преславний дух Фоми'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Й полився любий голос Беатріче,
Яка відповісти його словам
Так зволила для благосної стрічі:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = '«Цьому потрібно, хоч не каже вам
Ні голосом він, ні у мислі навіть,
Щоб корінь істини побачив сам.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Скажіть, вогонь, що в нього вас оправить
Вам дано ласку, чи на всі віки
Залишиться, щоб вас, як досі, славить?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Якщо ж це буде так, то знов-таки,
Коли в нове одягнетеся тіло,
Чи буде одяг цей очам легкий?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'У ціль те запитання долетіло
І радощами кола осяйні
В живих піснях і танцях закрутило.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Так у танках, в веселій метушні
Захоплення раптове вмить здіймає
Ще вище скоки й співи голосні.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Хто ремствує на те, що врешті має
Розлуки із життям прийти пора,
Про свіжість вічного дощу не знає:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Один, два, три - хто вічно не вмира,
Віки царює в трьох, у двох, в одному
І, не увібраний, усе вбира,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Оспіваний був тричі в колі цьому
На той мотив, що кожен би обрав
За нагороду подвигу значному.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'І найчистішу я почув зі слав
У меншім колі, й голос той ласкавий,
Яким Марії ангел проказав,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Так одповів: «Як райське свято слави,
Любитиме весь наш святий загал
Цей одяг променистий і яскравий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Бо перед сяєвом його йде пал,
А перед палом - бачення щедроти
З хвали, чистішої з усіх похвал.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Коли одягнемо покрови плоті,
Святі й преславні, в душі нам злетить
Ще більша чистота, ніж сяла доти.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Тому й зросте без того, щоб сплатить,
Те сяйво, дане з блага неземного,
Те сяйво, що дає себе уздріть.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Звідсіль зросте вже бачення усього,
Зросте вже пал, який із того йде,
Зросте вже й промінь, що із палу того.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Як вугіль з себе полум''я зведе
І скрізь його жароту й поза нею
Своє обличчя виявить бліде, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Так блиск, що вкрив нас ризою своєю,
Не зменшиться в видимості за плоть,
Донині ще приховану землею.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Не буде світло це очей колоть,
І силу матимуть частини тіла,
Щоб не вдалося радощам збороть».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Така була єдина зграйна сила,
З якою хори мовили «Амінь»,
Мов їх любов до мертвих охопила,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Не так до себе, як до поколінь
Батьків, і матерів, і всіх, хто з ними
Пройшов у вічну пломінну глибінь.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'І от вогнями блискавок рясними
Замріло сяйво, сходячи до зір,
Із обріями схоже осяйними.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Як в надвечір''я згаснуть схили гір
І небом попливуть оманні хмари,
Яким і вірить і не вірить зір, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Так тут пливли, з''являючись, примари,
Щоб ще один серпанок піднести,
Обидва вкривши попередні шари.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'О духа огняного блиск святий,
Сліпучий! Він, як заграва стожарна.
Мою увагу змусив одвести.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'А Беатріче радісна і гарна
Така здалась, що описать її
Була б перу моєму спроба марна.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Коли ж я очі знов розкрив свої,
То впевнився, що раптом нас із пані
У вищі перенесено краї.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Впізнав я про ту зміну в нашім стані
З палаючого усміху зорі,
Що червоніла, як троянди ранні.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Як наші праотці в часи старі,
Я справив Богові усеспаління
За те, що опинився угорі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Іще у грудях не прочахло тління
Тієї жертви, я уже збагнув,
Що сприйнято зичливо ці моління:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Такий в дві стежки виблиск спалахнув
Таких ясних огнів, що я, дивившись,
Сказав: «О Боже, я про це й не чув!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Як, з менших аж до більших роз''яскрівшись,
Пала між двох кінцевих полюсів
Молочний Шлях, од мудрих затулившись,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Так із глибоких Марсових низів
Угору превелебний знак знімався,
Що в колі між квадрантами осів.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Мій розум перед пам''яттю зламався,
Бо хрест ясний виблискував Христом,
І з ним ніхто б красою не зрівнявся.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Хто ж взяв свій хрест і рушив за Христом,
Пробачить хиби, - їх я припустився,
Уздрівши древо з сяючим Христом.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Поміж вершком і низом так іскрився
І між плечима спалах вогняний,
Який то зблизька, то здалека лився.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Так в''ється порох по землі дрібний -
Частинки всякі, сторчові й навскісні,
Коротші й довгі, миготять вони'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'По променю, який, буває, блисне
У затінку, що з наших він турбот
І вмілості у нас в кімнаті висне.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Як в арфі злагодженістю красот
Бринять численні струни щось приємне
Й для того навіть, хто не знає нот, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Так пломені співання понадземне
Лили навкруг Христового чола,
Для мене чарівливе, хоч і темне.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Я зрозумів, що це звучить хвала,
Із слів: «Воскресни, щоб звитяжцем бути!», -
А суть всього до мене не дійшла.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Так полюбився гімн, тоді почутий,
Що в серце глибоко мені проник, -
Такого вперш далось мені сягнути!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Засмілим здатись може мій язик,
Бо очі він принижує багаті.
Що в них мету життя вбачать я звик.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Але хто знає, як живі печаті
Краси ростуть угору день по дню, -
Я ж звів на них шляхи очей початі, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Звинить мене, в чім я себе виню,
Щоб збутися вини, бо правду бачить:
Не підляга святий екстаз огню'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Тим більш, чим ближче верх себе означить.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 14
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 47;

UPDATE cantos SET title_uk = 'ПІСНЯ П''ЯТНАДЦЯТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 15
    AND p.name = 'Paradiso';

UPDATE terzinas SET text_uk = 'Предобра воля благосна, якою
Завжди любов до праведних спонук
Являється, як жадібність, - лихою,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Притишила у ніжній лірі звук
І струн святих спинила рокотання,
Настроєне дбанням небесних рук.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Чи можуть буть глухими до благання
Ті сутності, що співи перервать
Погодились і вислухать прохання?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'О, без кінця той має горювать,
Хто так минуще любить, що не хоче
Свою любов на вічне прямувать!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Як в тихій, ясній висі замигоче
Раптовий вогник і, вразивши нас,
Приверне наші неуважні очі,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Видаючись тремтливою весь час
Зорею, хоч насправді всім відомо,
Що жоден пломінь там іще не згас, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Так з правого в хресті плеча до злому
Ковзнуло вниз світило вогняне
З-поміж зірок, що світять в небі тому.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Наблизилося видиво ясне,
Спускаючись по променевій смузі,
Мов блиск, який крізь алебастр сяйне.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Радів, як вірити найбільшій музі,
Так дух Анхізів, мов з великих свят,
Зустрівши сина в Єлісейськім лузі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = '«О кровь моя! О лучшая стократ
Господня благодать! Никто доселі
Не зріл отверстих паки в небо epamU -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Так світло це; і погляди веселі
Я зніс до нього й до владарки звів, -
І став подібний тут і там до скелі:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'В очах її сіяла, з ясних див,
Така усмішка, що я зрів на власні,
Як для блаженства в свій я Рай злетів.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Хоч дух цей, що його були прекрасні
І вид, і голос, щось казав, здались
Слова глибокі, та на зміст неясні.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Не мали наміру вони кудись
Піти від мене, - сповнені радіння,
Над смертний розум вгору піднеслись.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Коли ж той лук високого летіння
Ослабнув так, що стріли слів могли
Влучать в мету людського розуміння,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Почув я знов: «Подяки й похвали
Прийми од мене, триєдиний Боже,
Бо внуки не обминуті були!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'І далі: «Прагнення тривале й гоже,
В великій вичитане книзі тій,
Де біле й чорне змін зазнать не може,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Ти зняв, мій сину, в сфері світляній,
Де мовлю; хай же та благословиться,
Що крил дала на зліт високий твій!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Ти віриш - мисль у тебе промениться
До мене з першої, як п''ять і шість
Із знаної походять одиниці,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Тому й не хочеш вислухати вість,
Хто я і чом у радісному тиску
Для мене ти - найрадісніший гість.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Ти в правду віриш! Тут, в дзеркальнім лиску.
Малі й великі без пустих розмов
Прийдешніх мислей бачать кожну риску.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Та щоб святу я вдоволив любов,
З якою вартував, безсонний, пильний,
І до мети жаданої дійшов,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Хай голос твій, веселий, смілий, вільний,
Дзвенить в питанні, хай в жазі дзвенить,
Тобі готов мій.відголос незмильний».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Я зваживсь в Беатріче зір втопить,
Вона ж моїм думкам так усміхнулась,
Що мій порив розправив крила вмить.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'І я почав: «Відколи розімкнулась
Вам перша рівність, почуття й ума
Вага порівно на всіх вас відчулась,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Як з сонця - ясність і жарінь сама -
Тепло і світло нарівно зринають, -
Тут порівняння іншого нема.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Але з причин, які усі з вас знають,
Знання і воля протягом життя
Відмінних крил у смертних не зрівняють.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Тож серцем дяку вам складаю я, -
Бо, смертний, за нерівність ту в уразі, -
За батьківське гостинне прийняття.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Благаю я тебе, живий топазе,
Щоб і в найбільших скарбах помічавсь,
Мене своїм ім''ям вгамуй у спразі».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = '«О віть моя! Тобою я пишавсь,
Чекаючи невтомно! Я ж твій корінь, -
З тих слів його одвіт мені почавсь,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'І далі: - Той, хто для своїх утворень
Дав назву й сам понад сто літ в журбі
Йде по горі уступом упокорень, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Мені був син і прадід був тобі.
Тож треба, щоб діяннями своїми
Йому ти втому зменшив у ходьбі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Флоренція між мурами старими,
Де лік видзвонюється терц і нон,
Жила в чесноті й мирі незборима.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Не мала ні намист, ані корон,
Ні дженджерух, ні поясів розкішних,
Пишніших за найкращих ваших жон,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'І не було у нас батьків невтішних,
Якщо дочка знаходилась нова,
Бо віку й він було у міру пишних.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Дітей мав дому кожного глава,
Й пора ще не прийшла Сарданапалу
З палат робить небачені дива.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Не перевершив гору Монтемало
Учеллатойо ваш, що був вінцем
З піднесення і буде ним з провалу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Я Беллінчоне Берті з ремінцем
І кісткою здибав, його ж дружину
Завсіди з нефарбованим лицем.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'А Веккйо й Нерлі просту шкуратину
Носили, з веретена та руна
Жінки їх одягали всю родину.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Щасливиці! Своя була труна
Для кожної, і зраду в ліжку взнати
З-за Франції не мусила й одна.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Та, звикши сон вночі від себе гнати,
Співала над колискою з малим
Пісень, яким радіють батько й мати.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'А та сиділа з прядивом своїм,
Весь вечір повідаючи родині
Про Трою, чи про Ф''єзоле, чи Рим.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Були б їм дивні Лапо ваш в гордині
Або Чангелла, вся з пороку й зла,
Як Цінцінат з Корнелією нині.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Громадськими чеснотами жила
Громада без облуди, без обиди, -
Такий мені чудесний дім дала'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Та, що в роділь гамує болі й біди,
І я, принесений в ваш древній храм,
З хрестом дістав імення Каччагвіди.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Моронто й Елізео - двом братам
Було ім''я, а жінку взяв з-над Падо,
Й вона лишила прізвище всім вам.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Служив я в імператора Куррадо,
І він мені меча подарував
За бій, який йому я виграв радо.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'З ним я пішов на захист ваших прав,
Які народ невірний, знахабнілий -
Вина в тім пастирів - у вас забрав.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'І ці поганські племена звільнили
Мене із світу, повного брехні,
Що всіх принижує, кому він милий,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 49;

UPDATE terzinas SET text_uk = 'І мучеництво мир дало мені».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 15
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 50;

UPDATE cantos SET title_uk = 'ПІСНЯ ШІСТНАДЦЯТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 16
    AND p.name = 'Paradiso';

UPDATE terzinas SET text_uk = 'О вбога благородносте, в нас кревна!
Що ти живеш між вихвалянь і слав
Тут, де любов у нас не дуже ревна, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'То зовсім я б тому не дивував;
Бо навіть там, де шлях нам сяє в очі,
У небі тобто, славу сам я слав.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Ти, як той плащ, що все стає коротший,
І, як щодня не піклуватись ним,
То ножиць час втина його охоче.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'На «ви», як перший звик звертатись Рим,
Хоч згодом чемність ця не раз ламалась,
Поклав початок я словам своїм;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'А Беатріче осторонь всміхалась,
Мов та, що, пишуть, кашель стався їй,
Коли Джіневра вперше завагалась.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Отож почав я так: «Ви - батько мій,
Ви піднімаєте мене над мене,
Ви розрішаєте язик німий!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Тече струмками стількома шалене
Радіння в розум, що воно б могло
Ще трохи - і розхлюпатись, вогненне.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Скажіть, моє кохане джерело,
В якій сім''ї й коли вам повне чару
Народження відзначене було?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Скажіть і про Йоаннову кошару:
Яка була вона і хто в ній був
Шанований найбільш на всю отару?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Я бачив, як той світоч спалахнув,
Зрадівши, навстріч запитанням ясним, -
Так жар шугнув би, щоб вітрець дмухнув, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'І, ставши для очей ще більш прекрасним,
Почав ще краще мову дорогу,
Але наріччям не цілком сучасним,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Із слів: «Відколи вість приніс благу
Архангел, поки я не народився
В тієї, що на райському лугу,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Яркий планети пломінь розгорівся
П''ятсот, і п''ятдесят разів, і три,
Бо лапам Лева пломінь цей корився.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'І там, де роду нашого двори,
Оселя кам''яна стояла рідна,
Звитяжці гонів там беруть дари.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Та й годі з тим, хоч відповідь ця бідна:
Бо хто й звідкіль діди мої були,
Про те мовчати - річ пристойна й гідна.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Ті, що тоді носить мечі могли,
Від Марса до Хрестителя п''ятині
Дорівнювали тим, що в вас жили.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'І чиста кров, в яку од зайд з Фіггіне
Й Чертальдо нині вмішано чужу,
Струміла в кожному городянині.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'О, якби той, про кого я кажу,
І далі б оселяв свій дім бруднючий,
Ви б у Галуццо провели межу,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Щоб не устряг між вас селюк смердючий
Із Агульйоне з Сіньєю, ділок,
До всього, що не так лежить, жаднючий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Коли б народ, що робить хибний крок,
На кесаря уважно озирнувся,
Як мати на улюблених діток,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Додому б, в Сіміфонте, повернувся
Котрийсь із флорентійських торгашів, -
Там в нього батько, жебраючи, гнувся,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Рід Конті б Монтемурло не лишив,
Як Черкі рід, - Аконської округи,
І Бондельмонте б в Вальдігр''єве жив.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Тяжкі від люду прийшлого наруги
На місто завжди будуть зле впливать,
Як надмір страв на шлунок недолугий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Та й бик сліпий не може так стоять,
Немов сліпе ягня; твердою сталлю
Єдина шпага б''є певніш за п''ять.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Коли ти звернеш зір на Урбісалью,
На Луні, на падіння їхнє (та
Судьба чига на К''юзі й Сінігалью),'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'То вздриш, що вихор той, який зміта
З землі роди прадавні, - не дивниця,
Коли зникають і значні міста.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Як ви, колись і ваше все скінчиться,
А здасться вам щось вічним, то хіба
Недовгістю життя все роз''ясниться.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Як небо Місяця то погреба,
То оголяє береги без впину,
З Флоренцією чинить так судьба.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Тож не дивуй, коли згадаю, сину,
Я давніх флорентійських городян,
Що й слава їх лягла вже в домовину.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Я бачив Кателліні славний стан,
Філіппі, Угі, Гречі, Альберікі,
Орманні - ще поважних громадян.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Я бачив ще роди старі й великі
Делла Санелла і дель Арка теж,
Ардінгі, Сольданьєрі та Бостікі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Край брами, де тепер тягар без меж
Нової зради, що під ним потоне
Ваш корабель, хоч як за ним не стеж,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Жили там Равіньяні - в їхнім лоні
Зароджені були й граф Гвідо, й рід
Високого старого Беллінчоне.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Рід делла Пресса знав, як править слід,
А Галігайі вже свій меч жорстокий
Вкривали золотом після побід.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'В гербах же білячий був стовп високий;
Ще славилось сімейство не одне,
Що згодом з мірок в них палали щоки.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Стебло Кальфуччі вже було міцне,
А місце в уряді вже намічали
Для Сіці й Аррігуччі визначне.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Скількох я бачив, що в ганьбі кінчали -
З пихи, а куль кошниці золотих
Кошару міста рідного вінчали.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Такі були й батьки старезні тих,
Хто, поки церква в вас без пастуха є,
Жере й жиріє на стадах людських.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Стоклятий рід, що, мов дракон, карає
Тих, хто тіка, а хто покаже зуб
Чи гаманець, до тих ягням стихає,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Уже з таких підносився халуп,
Аж заперечив Убертін Донато,
Щоб тестя поріднив із ними шлюб.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Вже Капонсакко вивів на Меркато
Рідню із Ф''єзоле й уславивсь там.-
Жили статечно й Джуда, й Інфангато.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Вір правди неймовірної словам:
Заходили тоді ще в місто з брами,
Що делла Пера звалася ім''ям.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Всі ті, хто ходить з пишними гербами
Великого барона (у юрби
Став звичай відзначать Фому згадками),'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Від нього мали рицарство й скарби,
А йдуть з юрбою, що безтямно суне,
Хоча він їм і дав свої герби.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Були вже Гвальтеротті й Імпортуні, -
Якби ще не нові сусіди ті,
То Борго міг би дякувать фортуні.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Ще дім, де вам вчинилось зло в житті,
Бо вас понищив гнів той справедливий
І зникли давні звичаї святі,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Був повен домочадцями, щасливий.
О Бондельмонте! Зле повівся ти,
Що, на чужу пораду, став зрадливий!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'Хто нині тужить, щастя б міг знайти,
Втопи тебе Всевишній в Еми вирі,
Коли ти в місто вперше мав зайти.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'А то на кам''яній плиті в офірі
Флоренція здала твоє життя
На згадку про літа, прожиті в мирі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 49;

UPDATE terzinas SET text_uk = 'При людях цих і схожих бачив я
Флоренції таку спокійну долю,
Що прикре не з''являлось почуття.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 50;

UPDATE terzinas SET text_uk = 'При людях цих я бачив славу й волю,
Лілея ж гордо маяла до хмар,
А не тяглась повержена по полю'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 51;

UPDATE terzinas SET text_uk = 'Й не стала ще червоною від чвар».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 16
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 52;

UPDATE cantos SET title_uk = 'ПІСНЯ СІМНАДЦЯТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 17
    AND p.name = 'Paradiso';

UPDATE terzinas SET text_uk = 'Як той, хто з видом тужним і сердитим
Спитав Клімену й безумом тяжким
Навчив батьків не потурати дітям,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Таким я був, і бачили таким
Мене й володарка, й світець священний,
Що місцем поступивсь мені летким.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'І Беатріче: «Смолоскип вогненний
Бажання вийми, - мовила, - й звільни
Душі своєї зліпок сокровенний,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Та, звісно, не на те, щоб ти хвальний
Постав у нас в очах, але щоб сміти
Жаль на жагу висловлювать гучний».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = '«О любий стовбуре мій знаменитий,
Ти так здійнявсь, що, як всі бачать в нас,
Що двох тупих в трикутник не вмістити,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Так бачиш ти можливе людських мас,
Дивуючись на першу цятку в перлах,
Де вічно є теперішній лиш час.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Коли з Віргілієм по темних жерлах
Підводивсь я горою каяття
І сходив у глибини світу вмерлих,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Про те, що принесе мені життя,
Чимало чув я прикрого, й невільно
Підготувавсь до цих ударів я.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Тому бажав би взнати непомильно,
Який тягар мені на долю спав - -
Стріла очікувана б''є не сильно», -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Так в одповідь до світла я сказав
І тим, на побажання Беатріче,
Признався сам у тім, чого бажав.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Не манівцями і не таємниче -
Було це в звичках вчителів основ,
Супроти чого Божий син їх кличе, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'А, лагідно всміхаючися знов,
Латинським словом мовила глибоким,
У сяйво вбрана, батьківська любов:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = '«Можливе не виходить ненароком
За межі вашої речовини:
Усе лежить перед правічним оком,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Не роблячи із того новини,
Як рух човна, котрий униз спливає, -
Уважні очі стежать з вишини.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'А звідти, як до слуху долинає
Орган, так час, що жити маєш ти,
До погляду мойого долітає.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Примушений був Іполит втекти,
Побачивши, як мачуха лютує,
Ти ж мусиш із Флоренції піти.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Так схоче, зажадає і вторує
Цю згубну стежку зграя навісна
Там, де щодня Христом усяк торгує.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'І на розбиту партію вина,
Як завжди, ляже вся; лиш мить остання
Освідчить щиру істину до дна.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Ти кинеш все, чому віддав кохання,
До решти все, бо й решту розтягли б, -
Найперший це удар меча вигнання.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Ти звідаєш, який солоний хліб
Не свій, як важко сходить вниз чи вгору
По сходах не своїх без ліку діб.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Але найтяжче під жорстоку пору -
Це буде товариство дурнів злих,
В яке потрапиш, втративши опору.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Невдячність, тупість, нечестивість їх
Відчуєш скоро ти, але не в тебе
Зачервоніють скроні, а у них.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Підлота скотська їх в ділах, як треба,
Себе покаже, - слава й честь тобі,
Що партію свою складеш ти - з себе.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Свій перший знайдеш захисток собі
В великого Ломбардця із тим птахом
Священним, що під сходами, в гербі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'І під його привітним пишним дахом
Ітимуть між обох вас просьба й дар
Не в тім порядку, не звичайним шляхом.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Уздриш того з ним, хто родимий чар
Дістав і міць таку з цієї зірки,
Що слава діл його злетить до хмар.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Про нього поки що ні слів, ні спірки,
Бо молодий іще і - небесний рух
Десятої навкруг не лічив мірки.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Гасконець ще не зманить зір і слух
Високого Арріго, бо зневажить
Срібло й знегоди чеснотливий дух.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Його щедроти скрізь усім розкажуть
Про нього, так що навіть вороги
Йому во славу язики розв''яжуть.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Йому під щит укрийся дорогий,
Бо тим допомагає він без міри,
Кого обсіли злигодні й борги.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Зроби ж в умі про нього запис щирий,
Не повідай лиш...» - і повів таке,
Що хто й почув би, не пойняв би віри.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'І: «Сину, ось пояснення тривке
Тому, що чув ти; пастки всю брехливість
Світил кружіння виявить близьке.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'А ти виказуй до сусід терпливість,
Бо ще подовжиться життя твоє,
Й побачиш їхню скарану зрадливість».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Я, зрозумівши, що перестає
Свята душа, замовкнувши, з основи
Моєї ткати полотно своє,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Почав, як той, хто прагне із розмови
Позичити науки в мудреця
Із бачення, зичливості й любові:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = '«Я втямив, батьку, що доба от ця
Уразить несподіванкою злою
Мене, як необачного бійця.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Тож маю вигострить уваги зброю,
Щоб піснею не рідне лиш одне,
А й інших міст не посварить з собою.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Там, де провалля темне та сумне,
І на гори чудесній верховині,
З якої зір владарки взяв мене,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'І тут, світило за світилом, нині, -
Я стільки взнав, що в глотку смак гіркий
У декого від слів моїх приплине,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'І якщо я - друг правди боязкий,
Боюсь не жити в людстві молодому,
Що наші древніми назве віки».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'І світло усміхом у скарбі тому,
Що я знайшов тут, спалахнуло вмить,
Мов сонце у свічаді золотому,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'І мовило: «Сумління, що тремтить
З гріхів своїх або чужих, сприймає
В твоїх словах, звичайно, тьму страхіть.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Зневаж брехання тих людців безкрає,
Все бачене хай пісня розповість, -
І хай свербить тому, хто чирку має!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Твій голос буде, як коли хто їсть
Спочатку неприємне, а пізніше,
Засвоєне, воно дає користь.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Твій буде крик, як вітер, найсильніше
Верхи вдаряти, щоб між них гуло,
І це тобі ще вищу шану впише.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Тому тобі й показано було
В цих сферах, на горі, у прірвах згаги
Лиш.духів, що у лаврах їх чоло.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Слухач своєї не спиня уваги
На прикладах, узятих з неясних
Джерел, що без довіри й без поваги,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'І на ділах, не дуже голосних».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 17
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 48;

UPDATE cantos SET title_uk = 'ПІСНЯ ВІСІМНАДЦЯТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 18
    AND p.name = 'Paradiso';

UPDATE terzinas SET text_uk = 'Блаженне змовкло дзеркало, кінчавши
На цім, я ж пробував на смак своє,
У солодощі гіркоту мішавши,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'І та, що ввись вела чуття моє:
«Зміни гадки, згадай, що я, - сказала, -
При тім, від кого легшим все стає».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Я погляд звів на ту, що так втішала,
І вздрів любов таку в ясних очах,
Що враз німою мова в мене стала'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Не тим, що нетвердий я у словах, -
А тим, що розум мій понад межею
Без вищих вожаїв загубить шлях.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Сказать лиш можу, що, втішавшись нею,
Не зв''язувалось почуття ніяк
Із пристрастей юрбою усією.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Одвічна радість полум''ям, однак,
Сіяла в Беатріче і, відбита,
Щасливила мене, як свята знак.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Мене скорила усмішка розлита,
Коли сказала: «Озирнись і чуй,
Бо втіха не в моїх очах лиш скрита».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Як інколи в обличчях всім в очу
Буває сила почуття такого,
Що душі коряться його мечу,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Так із палання сяєва святого
Збагнув я, зір на нім спинивши свій,
Що має він додати щось до цього.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'І він сказав: «На гілці п''ятій цій
У дереві, що живиться в вершині,
Плодами вкриване в листві густій,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Блаженствують ті духи, що в тіснині
Якби жили між горя та біди,
Багатшали з їх діл би музи й нині.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Тож на хрестові плечі погляди:
На голос мій посуне їх лавина,
Мов миготливих блискавок ряди».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Й побачив я, як на ім''я Навіна
Майнув хрестом високий пломінь цей,
І мову, й рух ввібрала мить єдина.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Був названий великий Маккавей,
І сяєво вслід вогняним гірляндам
Кружляло, наче дзиґа у дітей.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Перед Великим Карлом та Орландом
В душі захоплень спалахнув мільярд:
От соколи, зразки шляхетним грандам!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Майнули ще Гульємо, Реноард
І герцог Готтіфред переді мною,
Хрестом ще перебіг Руберт Гвіскард.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Вмішавшись між юрбою вогняною,
Дух предка дав мені урозуміть,
Що й тут він славний піснею дзвінкою.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'І я праворуч повернувсь на мить
Щоб з мови або рухів Беатріче
Збагнути, що повинен я чинить.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'І в неї зір так сяяв мальовниче,
Так променисто, навіть перейшов
Він досі бачене в її обличчі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'І як із того, що вогонь основ
Тому, хто творить благо, все ясніша,
Він рух в чесноту осягнуть готов,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Так осягнув я, що дуга рівніша
Мене укупі з небом в вись знесла,
Бо я дививсь, як диво яскравіша.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'І як збігає краска із чола
Та щік, і лиця знов стають сліпучі,
Коли красуня сором свій збула,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Так я зирнув, і очі невсипучі
Сказали, що мене прийняв терен
На шостій зірці, не такій блискучій.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Той смолоскип Юпітерів блажен
Іскривсь любов''ю, пломенів частками,
До наших дуже схожими письмен.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'І як птахи летять над берегами,
Зрадівши кормові, і вниз і ввись,
Шикуючись і колами, й рядами,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Так і святі створіння піднялись,
І, ринучи у небі, мов обвали,
То в «Л», то в «Ю», то в «2>» вони плелись.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Вони спочатку з піснею кружляли;
А, склавши букву, з палом мовчазним
Хвилину-другу з місця не рушали.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'О Пегасеє, людям видатним
Ти довгий вік даєш, у славі милий,
Вони ж-і царствам, і містам значним, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Так освіти мене, щоб міг я, смілий,
До них колишній образ повернуть!
Надай моїм рядкам колишні сили!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'У сімках п''ять разів пробігли путь
І приголосні, й голосні, й з частини
Шукав я сили цілість осягнуть.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = '«Любіте правосудіе», - з картини
За дієсловом там іменник став,
«Кто суд вершиш над всім», - й ущухли плини.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Скінчивши «М», собою не писав
їх сонм нічого більше, і Юпітер
Сріблом в розводах золотих засяв.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'І на шпилях останньої із літер
Побачив я, як славили вогні
Те благо, що несе їх, наче вітер.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Як із удареної головні
Злітають іскри та й летять, мигтівши,
Й на них ворожать неуки дурні,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Так тисячі мигтінь звились, злетівши,
Ці - дуже високо, а нижче - ті,
Як присудило сонце, їх створивши.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'І вздрів я, - з душ, зупинених як стій,
Орлину шию й голову малює
Хтось в огненно-прекрасній чистоті.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Митець той вчителя не потребує:
Він вчитель сам у блиску сяйних риз,
Він формами й пташиних гнізд керує.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'А решта душ блаженних збилась вниз
На букву «М», вінцем з лілей укриту,
Й в коротку мить закінчила ескіз.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'О ніжна зоре! Скільки самоцвіту!
І все це свідчить: правий суд гряде
Нам з неба, повного твойого світу!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Тож я благаю Вищий Розум, де
Береш свій рух і міць, знайти між люду,
Звідкіль на промінь твій той дим іде.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'І знов на тих звести свій гнів, осуду,
Котрі на ринок обертають храм,
Який завдячує і муці, й чуду.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'О військо, що мені зустрілось там!
За тих молись, хто взяв зразок поганий
І на брехню піддався ворогам.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Колись ішли на війни громадяни,
Мечі гострили на ворожу рать, -
Тепер грабують хліб, Отцем всім даний.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Згадай-но ти, хто пишеш, щоб стирать:
Петру і Павлу, вбитим за саджання
Того, що нищиш, - вік не умирать.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Ти, певно, скажеш: «Скупчивши жадання
На тім, хто радо ніс пустель ярем
І з танців смертного зажив страждання, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Забувся я про Павла з Рибарем».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 18
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 46;

UPDATE cantos SET title_uk = 'ПІСНЯ ДЕВ''ЯТНАДЦЯТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 19
    AND p.name = 'Paradiso';

UPDATE terzinas SET text_uk = 'Мені здалось, що гарний образ, дужі
Піднявши крила на високий літ,
Потішив сплетені у нього душі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Мені здалось: з них кожна - самоцвіт,
І промінь так осяяв самоцвіти,
Що зник у мене із очей весь світ.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Того, що маю тут я відтворити,
Письмом чи усно не повів ніхто б,
Ніхто не зміг би навіть уявити:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Я ж бачив і я чув орлиний дзьоб,
Що мовить став, і «я» та «мій» злітало,
Де «ми» та «наш» доречнішим було б.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Почав: «Я жив побожно й незухвало,
Й мене ввібрала слава огняна,
Яку б саме бажання не здолало.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Лишилась пам''ять по мені ясна, -
її зіпсуте людство вихваляє,
Історія ж наслідувань не зна».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Тепло із багатьох вуглин палає
Одне, а для любовей багатьох
Звучання птаха злинуло безкрає.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Я одказав: «О квіти днів стількох
З одвічних радощів, що аромати
Зливаєте свої з усіх епох!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Допомагайте піст мені зламати,
Що, поки я його не поборов,
Мене воліє в голоді тримати.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Хай в небі інше царство має знов,
Всю Божу справедливість оддзеркалить,
На ній і в вашім не лежить покров.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Ви знаєте, як можу я усталить
Свою увагу; знаєте, який
Той сумнів, що мене віддавна палить».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Як сокіл, знов без ковпачка зіркий,
В жадібній оглядається надії
І крильми б''є, красивий та стрімкий, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Отак повівсь із хвал Господній дії
Та правосуддю складений цей стяг,
Співавши чутне тим, хто тут радіє.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Він мовив: «Той, хто циркулем досяг
До краю світу і в просторі цьому
Усе відверто й потайки простяг,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Не міг ніде покласти ні на чому
Відбиток так, щоб він не повершав
Того, хто меж не має геть у всьому.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'І перший той гордливець з вишніх слав,
Найвищий із сотвореного роду,
Не виждав світла і незрілий впав.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Усе ж, в чім нижчу бачимо породу,
Занадто вже дрібненьке для добра
Безкрайнього і з власним ритмом ходу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Так погляд наш, що розуму вбира
Не більше в себе за єдиний промінь,
Який себе на всесвіт простира, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Не в силі дать такої сили пломінь,
Щоб сяло джерело ясних струмінь
Каррарських блисканням каменоломень.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Бо справедливість, що іде з стремлінь
Правічних, зір скінченний ваш скородить
Лиш як поверхню - не морську глибінь:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Хоч він при березі зо дна доходить,
А відпливти - і товща водяна
Його крізь себе зовсім не проводить.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Лише те - світло, що його одна
Дає предвічна ясність, решта ж - з тьмою.
Це тінь лиш плоті а чи трутина.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'От схов із справедливістю прямою
Я відімкнув - і все ясним здалось,
Що не давало так тобі спокою,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Аж ти казав: «От жив над Індом хтось,
Кому ніколи про Христа ні слова
Ні чути, ні читать не довелось.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Та воля до добра була чудова,
Й не знайде в ньому розум наш провин, -
Були безгрішні в нім діла і мова.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'І ось він вмер без віри, без хрестин.
Чи праведно за те його карати?
Чи з власної вини не вірив він?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Та хто ж ти, щоб вдягти суддівські шати
Й судити за десятки тисяч миль,
Як зір не може твій на крок дістати?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Хто мисль зі мною вигострить на шпиль,
Якби в нас не було Письма святого,
На сумніви той клав би тьму зусиль.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'О грубі розуми гурта земного!
Боління перше - у собі благе,
Ще й блага не цурається самого.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Все згідне з ним - як істина, наге
Й своїм не скорюване жодним твором,
Веде його у щастя дороге.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Як над гніздом лелека мчить простором,
Принісши корму виводку всьому,
Годованці ж за нею стежать зором, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Святий піднявся образ в вись німу,
Коли я очі звів, і крила - зграя
Єдиних воль підводила йому.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Співав він обертаючись: «Пуста є
Тобі ця пісня з розумом твоїм;
Ця правда, смертні, в вас зразка не має».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Коли все стихло в образі яснім
Святого духа, не забувши знака,
Що ним земля ушанувала Рим,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'То він почав: «Душа не йде ніяка
Сюди, якщо не вірила в Христа,
Бо це найперша нам усім відзнака.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Та згадує багато хто Христа,
А на суді стоятимуть не ближе -
За тих, що і не чули про Христа.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Тих християн засудить око свіже
Арапів, як ділити розпочнуть, -
Хто розкошує, хто жаровні лиже.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Що перси нашим владарям дадуть,
Коли почнеться книги розгортання,
Де списано їх бруд і каламуть?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Затямлять там Альбертове діяння,
Як він скерує крила у ганьбі
І празькі землі дасть на плюндрування.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Затямлять Сену в горі та журбі,
Що принесе, фальшуючи й донині,
Той, хто на ловах знайде смерть собі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Затямлять там, що в заздрісній гордині
Шотландцю і англійцю тісно жить
Здалось на власній тільки половині.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Лишать в очах пишноту й сласну хіть
Іспанця та богемця, що границю
Забув своїй неславі спорудить.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Лишать в очах, як цінять в одиницю
Кульгу (єрусалимець був скупій),
А вади будуть в тисячу ціниться.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Лишать і пана в скнарості черствій
Із острова вулкана й спеки зразу,
Де шлях Анхіз колись покінчив свій;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'От вид його, щоб дати до показу,
Усього написали кілька слів,
Уклавши щедрий зміст в убогу фразу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'От хай на його дядька й брата гнів
Обрушить всяк, бо піддали ті гані
Честь гідного народу й двох вінців.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'От з португальцем тут норвежець знані
На цілий Божий світ, як той далмат,
Який топив венецьке злото в твані.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'Тут пощастить Угорщині, як ґрат
Всіх допильнує, й пощастить Наваррі,
Як гір не подолає хижий кат!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'Хай стануть їй як засторога в сварі
Зойк Нікозії, Фамагости крик,
Бо там шаліє звір у дикій ярі'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 49;

UPDATE terzinas SET text_uk = 'І не цурається лихих владик».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 19
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 50;

UPDATE cantos SET title_uk = 'ПІСНЯ ДВАДЦЯТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 20
    AND p.name = 'Paradiso';

UPDATE terzinas SET text_uk = 'Коли вже той, хто ризу ніс червону,
Пішов на другу із півкуль земних
І день сховавсь під ночі охорону,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'То зразу ж безліччю зірок ясних
Все небо у промінні засіяло,
А той же сам світив ясніш за них.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Мені це явище на думку спало,
Коли знак світу і його вождів
Свій дзьоб стулив, промовивши немало.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Й незмірна безліч тих живих світів
Співати почала, ще більш огняна,
Та саме що - я в гадці не лишив.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'О чарівна любове, в усміх вбрана,
Поміж найблагочесніших думок
Яка здалась мені ти полум''яна!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Коли в цих самоцвітах, що в вінок
Оправлена з них сяйна шоста свічка,
Затих останній ангельський дзвінок,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Мені зачулось, мов гуркоче річка,
Далеко дзюркотить між каменюк,
Неначебто струмків джерельних стрічка.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'І нібито при гирлі цитри звук
Знаходить форму, і як подув, лине
Мелодією з флейти із-під рук, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'І тут, не переждавши ні хвилини,
Із образу так грім прогуркотав
Орлиним горлом, як із порожнини.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'На голос обернувся він і став
У дзьобі словом, що я ждав од нього
І r cenui v своєму записав.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = '«Той орган мій, що бачить, а в земного
Орла ще й зносить сонце, - мовив він, -
Уваги потребує хоч не много.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'З огнів, що видно з різних тут сторін,
Ті, з кого око тут моє іскриться,
Всі пильно дібрано один в один.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Цей, внутрішній, що створює зіницю,
Святого духа оспівав колись,
Возивши із ковчегом колісницю,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Тепер він знає, що перелились
Побожні співи на відплату рівну
І в пломеніючий вінець сплелись.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'З п''ятьох, що створюють дугу надбрівну,
Той, що від дзьоба перший, втишив ту
Журбу за сином у вдови незмивну.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Тепер він знає, що хоч доброту
Він виявляв, та вічного спокою
Позбувсь, бо душу не віддав хресту.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'А другий, як угору йти дугою,
Відстрочуючи неминучу мить,
Покаявся з молитвою палкою.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Тепер він знає: присуд не щастить
Усунуть геть, з молитви ж можна в слові
«Сьогоднішнє» на «завтрашнє» змінить.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'А дальший, поступившись пастухові,
Хай добрий намір дав гіркі плоди,
Мене й закони в грецькій вклав обнові.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Тепер він знає, що хто зло сюди
З добром заніс, той приєднавсь до лику,
Хоч світ од нього й зазнавав біди.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'А цей, на згині вниз брови, на стику,
Гульєльмо був, що плаче край за ним,
Бо смерть прийшла не Карлу й Федеріку.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Тепер він знає, що царем благим
Захоплюється небо, й в пишній свиті
Доводить це він одягом ясним.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Чи думав хто в несталім дольнім світі,
Щоб той Ріфей-троянець п''ятим був,
Де четверо - особи знамениті?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Тепер він знає краще, ніж хто чув,
Про Божу благодать в небеснім краї,
Але до дна її не досягнув».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Як жайворон зі співами ширяє
По висі й раптом мовчазним стає,
А насолода у ньому ще грає,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Таким здалось уявлення моє
Тієї волі, що з її веління
Усе стає одвічно тим, чим є.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Хоч перед сумнівом мого сумління
Я був, мов скло над барвами пусте,
Йому забракло довгого терпіння.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Та з уст моїх: «То що ж воно все те?» -
З великим він виштовхувавсь напором,
І я уздрів, що свято скрізь росте.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'І відповів із спалахнулим зором
Моїм думкам благословенний знак,
І розум втішив розв''язанням скорим:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = '«Ти, бачу, віриш, але просто так,
Не розібравшись, що те слово значить;
Ти віриш, а не знаєш, чом та як.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Ти наче той, хто сутності не бачить,
Хоч назву речі й відає умом,
Аж поки хтось йому не розтлумачить.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = '/ царствіє небесноє силком
Покориться любові та надії,
Щоб волю Божу подолать цілком, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Не як людьми людина володіє -
її долають, бо дає долать,
А, здолана, добром долать воліє.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'В брові тій перша й п''ята дивувать
Тебе повинні душі, бо ж не в''яне
Ця ангельського краю благодать.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'їх прах покинули вже християни,
Які повірили в каліцтво ніг,
Одна - що сталось, друга - що настане.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Ця, з Пекла, звідки ще ніхто не міг
Із добрим вийти наміром, - вдяглася
В свої кістки, -живих надій поріг.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'З живих надій цих до небес знялася
Така молитва про благі краї,
Що просто аж до Бога підвелася.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Душа ця, про яку слова мої,
Вернувшись до живих на строки певні,
Повірила в того, хто спас її,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Й пірнула так в огні любові ревні,
Що, вмерлу знов, занесено було
її у ці святі чертоги древні.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Та ж з ласкою, що лляло джерело
Таке на глиб, що жодне сподівання
На дні уздріть нічого не могло,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Дала чуттям до правди спрямування,
І з ласки в ласку Бог її очам
Відкрив грядуще наше врятування.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Повіривши у нього, з почуттям
Більш не вклонялась ідольській колоді
І докоряла грішним землякам.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Хрестилась в трьох жінок, яким в поході
При правім колесі веліли йти,
Настав же хрест в десятий вік відтоді.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'О доле, в джерелі далека ти
Від тих, кому причини не знайомі
І хто не має сили їх знайти!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Ви ж не хапайтесь, смертні несвідомі,
З своїм судом: хай бачим Бога, все ж
Усі обранці нам ще не відомі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Та незнання це втішне нам без меж,
Найвище благо з наших благ навіки, -
Бо те, що хоче Бог, ми хочем теж».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Так образ цей божественно великий,
Подовжуючи зір короткий мій,
Подав ці ніжні, чудодійні ліки.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'І як цитрист вторує визначний
Значному співаку, торкавши струни,
Щоб спів його був гарний, голосний,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'Так відгукались зграйно, наче луни,
Мигали згідно, як повіки, вряд
Два сяйва й блискали, немов перуни,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 49;

UPDATE terzinas SET text_uk = 'Орлиній мові громовій улад.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 20
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 50;

UPDATE cantos SET title_uk = 'ПІСНЯ ДВАДЦЯТЬ ПЕРША'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 21
    AND p.name = 'Paradiso';

UPDATE terzinas SET text_uk = 'Віддав своєї владарки обличчю
Я очі, з ними й почуття були, -
З усякою простивсь чужою річчю,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Вона ж, не посміхнувшись: «Ти б коли, -
Сказала, - вздрів мій сміх, зазнав би шкоди,
Став, як Семела б, жменею золи.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Бо, як ти бачиш, міць моєї вроди
Чимдалі все яскравіше сія,
Поки долаєм в цих чертогах сходи.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Якби себе не тамувала я,
То сяла б так, що впала б в тебе сила,
Неначе лист, коли гроза буя.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Вже досягли ми сьомого світила,
Що Лев на нього свій справляє тиск,
І спільно виграють обидва тіла.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Тож ум зведи, де очі ллють свій блиск,
Зроби дзеркала тій зображень зливі,
Яку тобі дає дзеркальний диск».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Хто знав би, що знайшли мої щасливі
Враз погляди в блаженному лиці,
Напрямлені на враження мінливі,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Той втямив би, чом в радостей вінці
Скорився я небесній провідниці,
Як ту відраду протиставив цій.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'В цьому кристалі, що скріпив світниці
І славний іменем вождя зробивсь,
Який понищив геть пороки ниці,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'У золоті, де промінь весь відбивсь,
Побачив сходи я, такі високі,
Що угорі мій погляд загубивсь.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Побачив я іще, як зносять спокій
Додолу безліч сяйв, і здумав: он
Зійшлись з усього неба ясноокі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'І як природні звичаї ворон
У купу всіх збирають, поки дніє,
Щоб з задубілих крил зігнати сон,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'І вже летять птахи: той даленіє,
Той зараз же додому поверта,
А хто й двох кроків одлетіть не сміє, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Так юрмилася сходиною та,
Похожа на гучну пташину зграю,
Сяйв низхідних процесія густа.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'І той, хто із мого наблизивсь краю,
Так спалахнув, що я аж погадав:
«Це тим любов свою він розкриває».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'А та, від кого я веління ждав,
Чи мовить, чи мовчать, була в чеканні,
Й не зле, що не питав я, хоч жадав.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Вона, побачивши мене в мовчанні,
Бо бачила в тому, хто бачить все,
Сказала: «Заспокойся у жаданні».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'І я почав: «Мої заслуги - се,
Що не дає надій, але ж я - з тою,
Хто дозвіл запитать тебе несе,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Блаженний душе, радості габою
Укритий! Чом, скажи, між усіма
Ти, зблизившись, спиняєшся зі мною?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Скажи іще, чом сфера ця німа
І дзвін благочестивий не рокоче,
Як в нижчих колах, чом пісень нема?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = '«У тебе вуші смертні, як і очі, -
Він одповів, - тож спів для тебе стих,
І владарка всміхнутися не хоче.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Зійшов я вниз по сходинах святих,
Лише щоб свята справив ти чудові
Для слів моїх і шат моїх світних.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Шлях збільшив я не з більшої любові,
Хоч більший жар любові тут не згас, -
Це бачиш ти в веселці пелюстковій.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Висока ж ласка, слуг зробивши з нас
Тій волі, що пасе зірчате стадо,
Нам приділила місце на весь час».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = '«Дивлюся, - я озвавсь, - свята лампадо,
Що вільної любові вистача,
Щоб вічній волі слугувати радо.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Та знову сумнів, мов удар меча:
Коли тут вас без ліку сяєв мчиться,
Чом хтось тебе лиш мовить признача?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Мої слова не встигли закінчиться,
Як, маючи середину за вісь,
Вогонь, мов бистре жорно, став крутиться,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Й слова любові з нього полились:
«Господнє світло має налітати
На мене, усього здіймати ввись.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Цей пломінь, з баченням моїм зіллятий,
Підносить так мене, що бачу в''яв
Найвищу сутність, звідки він узятий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'А звідси й захват, що я ним засяв,
Бо з поглядом моїм, прозорим з себе,
Прозор у сяєві себе зрівняв.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Тож дух, який найбільш палає з неба,
Той серафим, що бачить Бога сам,
Не відповість, у чім твоя потреба.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'У глиб такий одвіт твоїм словам
Захований, в такий провал запертий,
Що непомітний твореним очам.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Коли повернешся до світу смерті,
Усім скажи, щоб шляхом тим пустим
Не поспішали на загин одвертий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Уми, вогненні тут, там - тільки дим;
Зміркуй же, як вони б щось там робили,
Коли не можуть тут, у небі цім».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'До того ці слова мене вразили,
Що тишу я не зважився зломить,
Ледь: «Хто ти був?» - спитати стало сили.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = '«Між італійських берегів стримить,
А біля місць твоїх угору пнеться^
Такий хребет, що грім внизу гримить;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Під пагорбом, що Катрією зветься,
Стояв затишний і самотній скит,
Відлюдникам і захист, і фортеця, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Утретє він почав мені одвіт
І далі вів: - Я був такий горливий
В служінні Господові кілька літ,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Що, в їжу додававши сік оливи,
Я не боявся спеки й холодів,
Думками споглядальними щасливий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Колись цей монастир плодами цвів,
Але тепер в занепаді пустому, -
І треба, щоб я всім про це повів, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Я П''єром був Дам''яно в місці тому.
Петром же Грішником прийшов під дах
Приморського пречистенського дому.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Дали мені в похилих вже літах
Почесну шапку ту попівські кліки,
Що нині кидають їх по церквах.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Був Кіфа босий, а сосуд великий
Святого духа - той ходив худий,
І жебрали вони ім''ям владики.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'А пастирів теперішніх - веди
Під руки, ще й підтримуючи пишно, -
Вагу-бо мають! - ще й в сідло сади.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Вони плащем коня встеляють смішно,
І двох тварюк у шкурі взриш одній, -
О, як, терпцю, страждаєш безутішно!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'По цих словах уздрів я, як вогні
Зі сходини на сходину стрибали
Й що не стрибок, яскрішали, ясні.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Зусюди збіглися і поставали,
Зчинивши крик такий, вгорі й внизу,
Що в нас такого зроду не чували.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'І не добрав я слів крізь цю грозу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 21
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 48;

UPDATE cantos SET title_uk = 'ПІСНЯ ДВАДЦЯТЬ ДРУГА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 22
    AND p.name = 'Paradiso';

UPDATE terzinas SET text_uk = 'Звернувсь я вражено до провідниці,
Як те маля, що помочі з біди
В порадниці шукає й рятівниці.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Мов синові, який тремтить, блідий,
Вона, підвищуючи віру в себе,
Тим тоном, що од сліз втира сліди,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Сказала: «Чи не знав ти, що ми в небі?
І чи не знав, що небо той святив,
Хто діє тільки по благій потребі?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Як вплинув би на тебе їхній спів
І посміх мій, - ти можеш зрозуміти
Із того, як тебе їх крик вразив.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Якби ж ти знав, про що він мав молити,
Тобі відома стала б люта мста,
Яку побачиш сам ще на землі ти.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Небесний меч ні рано не зліта,
Ні пізно, як, бува, тому здається,
Кого чи страх, чи радість огорта.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'А зараз глянь туди і вздриш, як в''ється
Багато різних духів видатних,
Як їх тобі розглянуть доведеться».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'І я побачив там сто куль дрібних;
Вони усі, і перша, і остання, ''
Палали сяйвом променів світних.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Я був, мов той, хто вгамував жадання,
Не зважившись розпитувать, бо він
Побоюється зайвого питання.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Найбільша й найяскравіша з перлин
Наблизилася, щоб я їй завдячив,
Коли думок моїх втамує плин.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'І з неї я почув: «Коли б ти бачив,
Як я, всю добрість, що у ній горим, -
То гарних висловів би не настачив.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Та щоб з вичікуванням ти своїм
Не опізнивсь на ждані височини,
Вперед на мисль твою я відповім.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'На тій горі, що висить над Кассіно,
Колись мав звичку темний люд простий
Ходити всім народом до вершини.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'І перший я посмів їм повісти
Ім''я того, хто зніс із неба долу
Ту правду, що несе до висоти,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'І зміг з усього вигнати околу,
Бо так в мені сіяла благодать,
Гріховний культ безбожного престолу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Тут душі споглядальників мигтять,
Які, палаючи в могутнім жарі,
Готові цвіт і плід святий давать.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Тут Ромуальдо є, тут є Макарій,
Багато із братів моїх тут є,
Що нас, тверді серця, замкнув келарій».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'І я йому: «Це ставлення твоє,
Цей звернутий до мене голос щирий
І приязнь всіх, що знать себе дає,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Так надають мені до вас довіри,
Як світло сонця розу розкрива
Настільки, скільки вистача в ній міри.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Прошу тебе я, отче, не ховай, -
Чи благочесний вид твій споглядати
Я матиму можливість і права?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'І він: «Твоє палке бажання, брате,
В останім небі знайде рішенець,
Як знайдуть всі чуття й моє завзяте.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Там повний і довершений кінець
У кожного жадання; як в колисці,
Незрушно свій несуть частки вінець.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Ні на осі вони, ні в певнім місці;
І сходи наші йдуть до них міцні,
Тобі не видимі у жодній рисці.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'їх бачив Яків-праотець у сні
До самого вершка найвищих сходин,
І ангели по них ішли ясні.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Але тепер, щоб сходить ними, жоден
Ноги не підніма, і мій устав
Пергамент лиш бруднити нині годен.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'З моїх монастирів сьогодні став
Кублом вже не один, а люди в рясах -
Як в лантухах мука, що черв псував.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Але й у лихварів, найбільше ласих,
Не так бунтує проти Бога хіть,
Як у ченців, закоханих в припасах.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Над чим в нас церква жадібно дрижить, -
Не для рідні та й гірших, аніж рідні,
А для примушених на жебри жить.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Та смертні на рішучість досить бідні,
Щоб добра вість достатня їм була, -
Дуби ростуть повільно многоплідні.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Петро почав без золота й срібла,
Мені став любий піст, моління миле,
Франціскові ж - змалілість все дала.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Тепер же глянь, куди росте незріле
І як остання блискітка скреса,
Й побачиш сам, що чорним стало біле.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Проте Йордан роздавсь, як небеса
Того схотіли, й розступилось море, -
А то, звичайно, більші чудеса».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Він закінчив і линув у просторе
Те сонмище, й те сонмище співна
Знесла завія в небо неозоре.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Єдиним рухом пані чарівна
Звела й мене по сходах - керувала
Моєю так природою вона.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Ніколи в світі стільки не тривала
Дорога до нових, ще вищих втрат,
Як миттьова ця наша небувала.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Хай не вернусь до цих побожних свят,
Що я за ними покаянно плачу
І в груди б''ю себе багатократ,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Коли хутчій, ніж пучку ти гарячу
Смикнеш з вогню, я поміж зірних тіл
На знаку за Тельцем не був, читачу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'О славні зорі, о світильник сил
Високих, від яких мені був даний
Мій геній для значних і знатних діл!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Заходив пізно з вами, сходив рано
Отець усього смертного буття,
Коли вітрець я вперш відчув Тоскани.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Пізніш, коли, діставши милість, я
Зійшов у вище коло, що вас кружить,
Ваш край розкрив мені своє життя.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Тепер душа моя смиренно тужить,
Щоб ви дали їй сили перехід
Угору, хоч тяжкий, ураз подужать.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = '«Тобі так близько до кінця всіх бід, -
Сказала Беатріче, - ще всевладний
І гострий пильний погляд мати слід.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Рушаючи в подальший літ відрадний,
Ти озирнись на світ, що я до ніг
Тобі кладу, - який він неоглядний.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Щоб серцем радісним, наскільки б зміг,
Ти з сонмом тріумфуючим зіткнувся,
Який ефіром ще примчать не встиг».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'І поглядом своїм я повернувся
Крізь сім небес - і вгледів кулю цю
Такою, що презирливо всміхнувся.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Здавалося, вона гидка й Творцю,
І, хто думки веде у вище лоно.
Той чинить, як належить мудрецю.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Там бачив я твою дочку, Латоно,
Палаючу й без тінявих тих плям,
Що я вважав рідинним їхнє гроно,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'Й того, чий батько Гіперіон сам,
Я бачив, і навкруг, і поруч дану
Путь дітям Майї та Діони там.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'Відтам Юпітер став з меридіану
Між батька й сина; там я міг збагнуть
В усіх їх безперервні зміни стану.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 49;

UPDATE terzinas SET text_uk = 'Переді мною сім верстали путь,
Таких стрімливих і таких багатих,
І мріяли притулок осягнуть.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 50;

UPDATE terzinas SET text_uk = 'А тут уздрів я, звівшись на Близнятах,
Нікчемну крапку із морів та гір,
Геть сповнену всю дикощів пихатих, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 51;

UPDATE terzinas SET text_uk = 'І зір звернув я на прекрасний зір.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 22
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 52;

UPDATE cantos SET title_uk = 'ПІСНЯ ДВАДЦЯТЬ ТРЕТЯ'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 23
    AND p.name = 'Paradiso';

UPDATE terzinas SET text_uk = 'Як під коханою листвою птиця
Біля гнізда, де сплять її пташки,
Коли в нічній пітьмі усе таїться,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Побачить прагне любі голівки
Й летіти добувати їм сніданок -
Обов''язок приємний, хоч тяжкий, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'І нетерпляче жде на світлий ранок,
Коли, прокинувшись, її сім''я
Зустріне щебетом ясний світанок, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Так, випроставшись, владарка моя
Туди дивилась у задумі й мрії,
Де йшло повільніш сонце іздаля.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Я вздрів її в непевності й недії
І став, неначе той, хто жде чогось
І втишується у твердій надії.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Мені недовго ждати довелось:
Минуло часу зовсім небагато,
А полум''я у небі зайнялось.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'І Беатріче мовила: «Йде свято
Звеличення Христа, й побачиш плід
Кружіння сфер, що вертяться завзято».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'І так, здалось, палав у неї вид,
І світлі очі так її раділи,
Що мови я згубив останній слід.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Як Трівія свій усміх заяснілий
Під повню вічним німфам посила,
Які по небу сфери всі скрасили,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Так сонце над зірками без числа,
Світило всім од пломеня святого,
Як наше сонце - факелам з срібла.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'І річищами сяєва живого
Пливла осяйна сутність у мій зір,
Аж нестерпучою була для нього.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'О Беатріче, любий проводир!
Вона сказала: «Владна й над тобою
Чеснота, владарка світів і зір.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Тут - Всемогуття з Мудрістю святою,
Що поміж небом і землею шлях
Відкрили всім, омріяний журбою».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Як полум''я, рвучись у хмар жмутах,
Не вверх іде, а, всупереч природі,
Спадає раптом у наземний прах,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Так розум мій у любій насолоді,
Що переріс свою звичайну грань,
Не зна, що стало з ним при цій нагоді.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = '«Розплющ-но очі і на мене глянь!
Бо витримаєш ти мою усмішку,
Коли побачив стільки святкувань».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Я був, як той, хто геть забув ще в ліжку,
Що снилось уві сні, й тепер дарма
Силкується згадати сну хоч кришку.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Жадану щедрість я відчув - сама
Така була, що не зітреться з книги,
Де забуття минулому нема.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Хай славних язиків зберуться здвиги,
Хай їх, годованих на молоці
Полімнії й сестер, звезуть квадриги,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Хай прийдуть всі допомагать митці, -
На частку й тисячну не оспіваю
Святу усмішку на святім лиці.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Отож в години змалювання Раю
Стрибком веде свята поема нить,
Долавши на шляху завад без краю.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Хто смертний той хребет згада на мить
І ту вагу, яка лежить на ньому, -
Не дорікатиме, що він тремтить.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Біда у хвилях човнику малому,
Коли під кілем плин на піну збивсь,
Біда й людині в випадку страшному.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = '«Чи так ти вже у вид мій залюбивсь,
Що й не помітив чарівного саду,
Який під променем Христа розвивсь?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Там роза, що дала всім на відраду
Святому Слову плоть, лілеї там,
Чий аромат несе благу всім раду», -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Так Беатріче; я ж її словам
Йдучи услід, до бою сил надати
Хотів своїм кволіючим очам.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Як промінь сонця в окрай хмар розтятий
Колись-то дозволяв квітчастий луг
Затіненому оку показати,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Вогнів побачив я великий круг,
Освітлений яскравим сяйвом дужним,
Не бачачи джерел осяйних дуг.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'О благосна чесното, над навкружним
Ти піднеслась, щоб місце дать мені
Й моїм очам, вже не таким потужним.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Красива квітка - їй я ночі й дні
Моливсь - своїм іменням спрямувала
Мій дух на найвеличніші вогні.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'І пара моїх світел змалювала
Усю красу і радісність зорі,
Яка владає й тут, як там владала,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Коли, покинувши глибин краї,
Вінцевий пломінь, рухом опоясним
Обнявши миттю, закружляв її.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Мотив, що здався б на землі прекрасним,
Тут гуркотав би як оглушний грім,
Хоч там би видався для душ незгасним, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Як порівняти з співом голосним
Кіфари ніжної з вінця в сапфірі,
Що небо ним сапфіріє святим.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = '«Я - ангельська любов і в''юсь в ефірі
Круг радості, яка прийшла до нас
Із чрева, що за сховок стало вірі,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'І витимуся, владарко, весь час,
Аж поки здійснюється неба мрія,
Й до нього йдеш за сином, що всіх спас».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Так голос колового іскровія
Виводив, хором духів огняних
Оспівувалась пресвята Марія.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'А царська мантія на світових
Плечах, під Божих подихів потоком
Пекучіша й живіша за живих,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Над нами простиралась у глибокім
Просторі, що звідтіль, де я тримавсь,
Кінець зникав за обрієм широким.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Мій зір летіти на сназі не мавсь
Увінчаного пломеня слідами,
Бо той до сина любого здіймавсь.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'І мов маля, що до своєї мами,
Наївшись, рученята простяга,
Бо це природний вияв між чуттями, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'В огнях з вершка звелась якась дуга,
Й пошана діві, що вони являли,
Була для мене вельми дорога.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'І зараз же вони всі заспівали
Небесную царицю ніжно так,
Що в пам''ять звуки ці навік запали.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'О, скільки в зерні видатних ознак
Ховають щедрі скрині, звідки вийшов
На землю не один розкішний злак!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Тут вічним скарбом той себе потішив,
Хто в Вавилонському вигнанні лив
Горючі за майном, яке залишив,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Тут тріумфує, бо його завів
Син Бога та Марії до держави
Й до давніх і нових учителів,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Той, хто трима ключі такої слави.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 23
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 47;

UPDATE cantos SET title_uk = 'ПІСНЯ ДВАДЦЯТЬ ЧЕТВЕРТА Восьме, Зірне небо. - Відповіді Данте на запитання про віру'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 24
    AND p.name = 'Paradiso';

UPDATE terzinas SET text_uk = '«О ви, на учту обрані велику
Святого агнця, що достатком страв
Бажання ваші вдовольня без ліку,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Коли вже з ласки Бога цей збирав
Крихти, що кидаєте, ясночолі,
Ще перед тим, як час йому настав,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'І спрагу, й голод він вчува доволі.
Вгамуйте їх! Своїх дійшли ви мет,
І чиста вам вода струмує долі», -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Так Беатріче. Душі в бистрий лет
Пішли круг осі, мов прудкі дівчата,
Сіяючи вогнем летких комет.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'І, як годинникові коліщата:
Поглянь на те - сповільнене воно,
А інше - наче дзиґа заповзята,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Немов у хороводі неодно-
манітно йдуть - те звільна, те жвавіше,
Бо певний рух їм завдано давно, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Я в тій, яка розквітла найясніше,
Побачив рух найвищого з вогнів,
Що сяяв із усіх найяскравіше.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Круг владарки він тричі обкружив
І став чудесним співом рокотати, -
Фантазія не чула схожих див.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Перо стрибає... Як мені писати?
Уяви тло у згортках неясне,
Не те що мова, навіть фон строкатий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = '«О сестро люба і свята! Мене
Від товариства Божих славословів
Твоє позвало слово чарівне».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Огонь благословенний так свій повів
До владарки направив, і язик
Його до неї ті слова промовив.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Вона ж: «О світло, що ввібрало лик
Того, кому Господь на зберігання
Ключі небесних благ віддав навік, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Хай він на всі відкаже запитання
Про віру, що в воді тебе вела, -
Трудні й легкі, як на твоє жадання.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Тобі відкриті всі його діла,
Як любить, як надіється, як вірить, -
І для очей твоїх безсила мла.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Тут громадян своїх держава мірить
За вірою; нехай же скаже й він,
Як міру він і прославляє, й ширить».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Мов бакалавр, на запит не один
Відповідати вчителю готовий
Не висновком - переліком причин,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Так зброю зготував я для відмови
Огню, в якому язики вились,
Щоб сповідати вірувань основи.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = '«Християнине добрий, зголосись:
У чому віра?» Я звернув обличчя
До сяйва, звідкіля слова лились,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'А потім озирнувсь на Беатріче,
Яка зробила миттю знак мені,
Що джерело мене відкрити кличе.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = '«Коли дозволить ласка таїні, -
Почав я, - перший в раті цій хоробрій
Хай чує сповіді слова ясні!-'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'І далі:- Як писав громаді добрій
Твій славний брат, що ви з ним Риму шлях
Прямий накреслили на світлий обрій,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Це сутність у сподіваних речах
І певний доказ у речах незримих, -
У цьому зміст її в моїх очах».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'І я почув: «До істин незборимих
Піднісся ти, коли підніс її
До сутностей, з усіх найбільше чтимих».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'І знову я: «Глибин тих, що мої
їх бачать очі, йдуть з вершини миру,
Навік позбавлені земні краї,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Буття яких спирається на віру,
Надії теж на ній самій лежать,
Тому вона й являє сутність щиру.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'На вірі висновки побудувать
Ми мусим, як звання убоге змістом, -
Тож треба доказом її вважать».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Тоді я вчув: «Коли б то тайнам чистим
Навчав би зрозуміло богослов,
То не було б чого робить софістам».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Дихнувши ще, докинула любов:
«В монеті цій посвідчили учені
Вагу та вартість складових основ.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Скажи, чи є вона в твоїй кишені?»
І я: «Атож, блискучим кругляком,
В карбівці ж сумніву немає в мене».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'І вчув я, як сяйнула язиком
Глибінь вогню: «Де камінь самоцвітний,
З якого добрі йдуть діла цілком,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Знайшов ти?» І тоді я: «Дощ привітний
Святого Духа, що так рясно ливсь
Пізніш по шкірі ветхій і новітній, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Це силогізм, який мені явивсь
Таким вже гострим, супроти якого
Всяк інший нам тупим би уявивсь».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'І я почув: «Із давнього й нового
Учень ти склав уявлення своє,
Та чи ти певен, що вони від Бога?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'І я: «На те ґрунтовний доказ є -
Діла чудесні дальші, бо не плавить
Заліза в них природа й не кує».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Відказано: «Хто ж певності добавить,
Що тим були діла ці? Тут же те,
Що треба довести, за доказ править».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = '«Весь світ прийняв учення пресвяте, -
Сказав я, - без чудес, і це доводить,
Що чудеса всі - марнота й пусте.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Ти став, голодний та худий, виходить
На поле й готувати гарний збір,
Що нині терен, не колосся родить».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Замовкнув я, й святий високий двір
Тут розпочав у сферах «Бога хвалим»
На голос, узвичаєний для зір.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'І славний вождь, вивчавши цаль за цалем
Гілля моє, яка в нім чистота,
Закінчуючи листом не опалим,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Почав ізнову: «Ласка пресвята,
Любивши розум в тебе, розтуляла,
Як розтуляти слід, твої уста.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Це добре, що у тебе віра стала,
Але коли ж у вірі ти достиг
І як хвала її в тобі постала?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = '«Ти, любий отче й душе, бачить зміг
Те, в що так вірив, аж у гроб спустився
Куди прудкіше од юнацьких ніг, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Почав я, - хочеш ти, щоб я відкрився,
У чому віра ця тверда моя,
І ще, чому у ній я утвердився?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Відповідаю: вірю в Бога я, -
Любов''ю й волею дає, незрушний,
Єдиний, вічний небу він буття.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Хоча у фізиці є довід слушний
І в метафізиці те ж маєм ми,
Ллють докази, як Богу дощ послушний,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Мойсей, усі пророки та псалми,
Євангеліє й ви, що вийшли з кущі
Вогню богонатхненними людьми.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Я вірю в три особи вічно сущі
І в сутність їх троїсту і одну,
Де з «єсть» пов''язуються «суть» найдужче.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'Всю Божої природи таїну,
Яку моє тут слово розливає,
В євангельську сокрито глибину.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'У ній початок, іскра в ній тепла є,
Що миттю пломеніє по стезі
Й зорею неба у мені палає».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 49;

UPDATE terzinas SET text_uk = 'Як володар, що дякує слузі
Та обійма на знак благовоління,
Що вість приніс він швидше, ніж возій,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 50;

UPDATE terzinas SET text_uk = 'Мені утішне дав благословіння
І тричі облетів, коли я стих,
Апостольський вогонь - з його ж веління'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 51;

UPDATE terzinas SET text_uk = 'Я й мовив, бо зрадів зі слів моїх.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 24
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 52;

UPDATE cantos SET title_uk = 'ПІСНЯ ДВАДЦЯТЬ П''ЯТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 25
    AND p.name = 'Paradiso';

UPDATE terzinas SET text_uk = 'Якщо колись в поемі цій священній,
Де рук доклали небо і земля,
А я в роботі гнувся цілоденній,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Нарешті втишу лють, яка збавля
Мене кошари, де я спав ягнятком,
Не знав, що вовча зграя виробля, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'То з іншим голосу і вовни статком
Вернусь, поет, і вкриюся вінком
В хрещальні, де я світло взнав малятком,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Бо в віру увійшов, яка цілком
Єднає душі з Богом; ради неї
Петро витав у мене над чолом.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Тут хтось наблизився в сяйній киреї
З юрби, де був і перший серед тих,
Що стали по Христі архієреї.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'І Беатріче в почуттях святих
Сказала: «Глянь-но, глянь! Ідуть в Галісью
Вождя цього вславляти з місць усіх».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Як любий голубок літає виссю,
А вгледить любку - пада з вишини,
І, вдвох туркочучи, кружляють віссю, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Так - я побачив - князь той видатний
Зустрівся радісно з своїм співбратом,
І страву вславили удвох вони.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Врочисті, світлі, як великим святом,
Обидва мовчки встали пред мене,
Засліплюючи сяєвом багатим.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'І владарка лице звела ясне
Й сказала: «Душе в огняному диску,
Ти місто наше описав сяйне, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Повідай про надії кожну риску -
її ж тобі побачить довелось,
Коли вам трьом Ісус являвсь у блиску».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = '«Ти не тремти, сміліш чоло піднось,
Бо вже дійшов сюди зі смертних спадів,
Вже й луки наші бачити вдалось», -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Так другий пломінь цей мені порадив,
І погляд свій я звів до тих вершин,
Що вигляд їх мене безмежно надив.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = '«Дозволив наш Властитель верховин
Тобі, живому, в потайнім покої
Уздріти воєвод його дружин'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'І, досягнувши правди нелюдської,
Надію, що веде всіх у любов,
Зміцнити і в собі, і в інших втроє.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Та що вона і як цвіте, промов,
І як вона твій розум покорила», -
Озвався словом другий пломінь знов.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Побожниця, яка перисті крила
Мені скеровувала в вишній літ,
Так відповідь мою упередила:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = '«У войовничій церкві в сотні літ
Він перший із надією такою,
Що сонце дасть, як писано, нам світ.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Тож дано із Єгипту до спокою
В святий Єрусалим пройти йому,
Хоч він іще воює із судьбою.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Два інші запитання не тому
Ти ставив, щоб дізнатись, - хай він ширить
Вість, як чесноту любиш ти пряму.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Я їх йому лишу: він легко змірить
І знайде відповідь кінець кінцем,
Нехай себе на Божу ласку звірить».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Як учень, що відповіла бігцем,
Аби мерщій явить старання ревне,
Бо він себе вважає мудрецем,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = '«Надія, - я сказав, - ждання то певне
В прийдешнім слави; благосний вінець -
їй ґрунт, як і життя безгрішне кревне.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'З численних зір я сяйво взяв сердець,
І почуття у мене вилив щирі
Найвищий пана вишнього співець:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = '«На тебе хай надіються, - в Псалтирі
Писав, - знайомі з іменем твоїм!»
А хто не зна, як у моїй він вірі?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Зросив мене росою у своїм
Посланні ти, і, повний вод сторічних,
Проллюсь на інших у дощі ряснім».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Коли я говорив, то в грудях вічних
Святого пломеня тремтів огонь,
Спалахуючи в іскрах блискавичних.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'І він дихнув: «З моїх ще видна скронь
Любов до цнот, яка мене в завії
До пальм звела, до гір із оболонь,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Велить мені дихнути знов про дії
Коханої, і річ твоя пливе
Нехай про всі обітниці надії».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'І я: «Святе письмо, старе й нове,
На здруження вказало непреложне
Душ з Богом, і в мені цей дух живе.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Ісайя мовив, що набуде кожне
В своїй землі колись подвійних шат,
Земля ж своя їм - то життя тут можне.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'А зрозуміліше у многократ,
Розповідаючи про одяг білий,
Твій відкриває в одкровенні брат».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Слова мої в простори ще летіли,
Як спів «На тя да уповают» - вчувсь,
І зграйним колом хори підхопили.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Один з тих пломенів так розгорнувсь,
Що якби схожим став кристал у Раку,
То взимку б цілий місяць день тягнувсь.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Як дівчина, не з примусу, не з ляку,
Іде у танці молодих вітать
І виявляє шану їм всіляку,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Так полум''ям пойняту благодать
Побачив я з двома, що йшли у колі,
Як їм високі почуття велять.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Вона влилась у співи в ореолі,
А владарка, мов наречена та,
Незрушна, мовчазна, вдивлялась долі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = '«Його до Пелікана чистота
На груди клала, і велике діло
Довірено йому було з хреста», -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Так владарка; і це їй зір одкрило,
Й вона в красу зоріння все своє
Рішуче втупила, невступно й сміло,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Мов той, хто дивиться, а в думці є,
Що зрить, як сонце тьма перемагає,
Бо зрить, як вкруг незримим все стає,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Так я дививсь на полум''я безкрає,
Коли почув: «Навіщо зір в очах
Сліпить, шукавши те, чого немає?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Як всі тіла, й моє - у праху прах,
Поки не будуть наші числа злиті
З тим, що судилось ввік у небесах.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Лиш двоє в два убори тут повиті,
Ті, що оце знеслись до полюсів,
Про що й розповіси в своєму світі».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'І тут танок палаючих огнів
Змішався разом з мелодійним блиском
Троїстих найніжніших голосів,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Як перед труднощами або риском
Рух весел, що у вирі хвилі рвав,
На свист переривається встріч бризкам.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'О страх який нараз мене обстав,
Коли я озирнувсь на Беатріче
І не уздрів її, хоча й стояв'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Із нею поруч в світі, щаснім тричі!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 25
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 47;

UPDATE cantos SET title_uk = 'ПІСНЯ ДВАДЦЯТЬ ШОСТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 26
    AND p.name = 'Paradiso';

UPDATE terzinas SET text_uk = 'Коли я знітився із зором згаслим,
То з пломеня, який його згасив,
Почув я голос, що звернувся з гаслом'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'До мене так: «Як зір твій осклянів,
Уражений із вигляду мойого,
То втішся хоч самим лиш звуком слів.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Тож починай: скажи мені, до чого
Летить душа твоя, й забудь свій страх,
Бо змерхнув зір твій, а не вмер од того.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'У владарки ж, яка по всіх містах
Небесної держави йде з тобою,
Є вплив Ананіїних рук в очах».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Я мовив: «Ліки волею благою
Вже йдуть, коли у зір, як в отвір брам,
Вона ввійшла яскравістю яркою.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Найвищого святого блага храм -
То альфа і омега книг, що втішив
Себе я ними, бо любов зрю там».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Той самий голос, що оце потишив
Мій лютий біль в раптовій сліпоті,
Мене без запитань ще не залишив'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'І мовив: «Ще раз на сита густі
Я перевірю. Тож які підстави
Твоїй стрілі знайшлись в такій меті?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'І я: «Філософічні всі розправи
] впливи, що з небес до нас летять,
Карби дали мені любові й слави;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Бо благо, як його за благо взять,
Вогні любові в''є, тим більш розквітлі,
Чим добрістю багатша благодать.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'До сутності, яка палає в світлі
Сліпучому, а все те, що не в ній, -
Лиш промені від неї напівсвітлі,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Хай той свої зусилля основні
З великою любов''ю направляє,
Хто правду зрить, бо доказ в ній одній.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Цю правду розумову розстеляє
Той, хто мені довів, що ту любов
Найперше сутність вічна виявляє,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Це розстеля Творець світобудов:
«Я благо покажу тобі, як просиш», -
Мойсею мовлячи, щоб був готов.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Ти розстеляєш теж, коли підносиш
Про зміст найвищих таїн річ свою
За всіх глашатаїв гучноголосіш».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Почув: «Розсудок, звичний в вас в краю,
І тонша влада, згодна з ним, із грубим,
Для Бога бережуть любов твою,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'А може, й інші струни в''яжуть з любим?
Скажи, щоб відповідь ясна була, -
Яким тебе любов кусає зубом?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Святі думки Христового орла
Господнє показали спрямування,
Щоб і моя ним сповідь поплила.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'І мовив я: «Усі ті мордування
До Бога серце благосне ведуть
І зміцнюють любові поривання.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Бо путь всесвітня, і моя вся путь,
І смерть його, мого життя заради,
Чого, як я, всі віруючі ждуть,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Що й сказані слова, й живі поради -
Все з хвиль любові ложної взяло
Мене на берег справжньої відради.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Зелене листя, що у ріст пішло
Навік в саду, вславляю я уроче, -
Мене з садівником воно звело».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Скінчив я, й задзвеніли найсолодше
З усіх усюдів хори: «Свят, свят, свят!»
І владарка їм вторила охоче.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Як сонце, зазирнувши до кімнат,
Розбудить сонних на приємнім ложі,
Все зливши морем променистих шат,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'І враз пробудженим страшне й вороже
Все видається, й все не до пуття,
Аж поки їм свідомість не поможе, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Так із сліпих очей моїх сміття
Під чистим зором Беатріче спало
І зникло в дальніх далях забуття.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Гострішим ще прозріння в мене стало,
І, остовпівши, я спитав, чого
Чотири раптом сяєва засяло.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'І владарка: «Із пломеня цього
Найперша з душ, твір першої чесноти,
Зорить в екстазі на творця свого».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Як стовбур хилиться, коли навпроти
Дме вітер, та гнучкі свої гілки
Випростує і ставить, як і доти, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Так я вчинив на шани знак палкий,
І, раптом опинившись у полоні
Жадоби мовити, я, говіркий,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Почав: «О яблуко єдине, в лоні
Не зроджене, о праотче старий,
Кому жіноцтво - невістки і доні!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'На мене зглянься з вишньої гори,
Молю тебе. Мою ти знаєш віру,
Тож я змовкаю, ти ж заговори».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Коли серпанки вкриють спину звіру,
То, ревно вивільняючись із них,
Він виявляє неспокійність щиру.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Цілком так само перша з душ земних
Явила вогняними язиками
Сліпучу радість після слів моїх,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'І далі: «Хоч не виразив словами
Бажання ти свого, все знаю в нім,
Як ти - в найкраще знаній між речами.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Його я бачу в дзеркалі яснім,
Що відбива все чисто без підлогу,
Саме ж не відбивається ні в чім.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Ти хочеш знать, як, дякуючи Богу,
Я трапив у найвищий сад, звідкіль
Ця жінка повела тебе в дорогу,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Ще - скільки я втішався там суціль,
І ще про гніву Божого природу
Й про мову - наслідок моїх зусиль.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'То, любий сину, сталось не від плоду
Моє вигнання, що в синах трива, -
То поламав я Божу загороду.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Чотири тисячі і триста два
Ждав роки я в тім місці, де Віргілій
Твоєї владарки почув слова,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'А поки жив я ще в земному тілі,
То сонце дев''ятсот і тридцять раз
На кожному засяяло світилі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Та мова, що гранив я, як алмаз,
До незавершеної зникла вежі,
Коли напав людей Немврода сказ.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Залежать дум людських складні мережі
Від вдач, а ті - від зір, що красять ніч,
Тому у них є визначені межі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Людині розмовлять - природна річ,
Тож кожен має дозвіл од природи
Обрать собі бажану мову й річ.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Ще не ступав я на пекельні сходи,
А всеблагий звавсь «І» серед земель,
Кого шаную я й усі народи.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Пізніше він дістав наймення «Ель»,
Бо звичаї зникають у людини,
Як всохлий лист зника серед пустель.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'А на верху, що на землі єдиний,
Гріхом жив я й не відав, що є смерть,
Од першої до другої години'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'За шостою, де сонце мінить чверть».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 26
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 48;

UPDATE cantos SET title_uk = 'ПІСНЯ ДВАДЦЯТЬ СЬОМА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 27
    AND p.name = 'Paradiso';

UPDATE terzinas SET text_uk = '«Отцю, і Сину, і Святому Духу», -
Почав гучну співати славу Рай,
І спів солодким став напоєм слуху.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Лилося в очі й вуха з вишніх зграй
Захоплення, в сп''янілому паланні
Я зрів усміхнений небесний край.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'О радощів розкоші несказанні!
О це життя, де все - любов і мир!
О скарби не в журбі і не в жаданні!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Чотири світочі ввійшли в мій зір,
І з них найдужчим світлом розсіявся
Той шпиль, що появився першим з гір'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'І став такий, яким очам здавався
Юпітер би, коли б із Марсом він,
Зробившись птахом, пір''ям помінявся.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Те провидіння, що чергу і чин
Розподіляє всюди, хор зімкнути
Уста примусило, й затихнув дзвін,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Коли я вчув: «Ти не дивуй, що з люті
Мінюсь я, - змінять вид цих мирних грон
Слова, що доведеться їм почути.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Той, хто загарбать зважився мій трон,
Мій трон, мій трон, що перед Божим Сином
Стояв порожній, і зламав закон,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Ще й цвинтар мій залляв смердючим плином
Та кров''ю, і радіє лиходій,
Який вигнанцем звідси був єдиним».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'І колір той, яким під захід свій
І схід, світило тьму небес малює,
Забарвив обрій в вишині ясній.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Мов чесну пані, як вона почує,
Що неподобством хтось ганьбить міста
Чи села, вельми звістка ця хвилює, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Мінилась так і владарка свята, -
Так само небо, думаю, хмурніло,
Коли волала Сила із хреста.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'І далі грізне слово це гриміло,
І гнівна зміна в голосі була,
Й великий гнів обличчя появило:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = '«Дружина Божа не на те зросла
Моєю кров''ю, кров''ю Ліна, Клета,
Щоб золото стягалось без числа.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'І щоб блаженства блиснула прикмета,
Кров Сікст пролив, ще й Пій, Калікст, Урбан,
І ваша ними вславилась планета.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Не ми хотіли, ні щоб християн
Наступник наш нечесною рукою
Ділив на правий і на лівий стан,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Ні щоб ключі, що я ношу з собою,
Могли на корогві тій знаком стать,
Котра проти хрещених зве до бою,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Ні щоб лицем я скріплював печать
На грамотах продажних та брехливих,
Щоб мусив потім з сорому палать!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'На паші бачимо вовків кусливих
В пастушім одязі поміж овець, -
О суде Божий, грянь на нечестивих!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'З Каорсою Гасконь сіда, мов ґедзь,
На нашу кров. О праведний початку,
Який поганий ждав тебе кінець!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Та промисел, що славу Риму в статку
Із Сціпіоном збройно врятував,
Поможе й нам, гадаю, до остатку.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Коли повернеш до земних держав,
Тоді, мій сину, ти розкрий там рота
Й слів не ховай, як я їх не ховав!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Як випари верта згори мерзлота
Й скидає снігом вниз, коли ріжком
Коза черкає сонців диск із злота,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Помчали раді випари сніжком,
Що коло нас були і щойно спаді
З ефіру спломенілого цілком.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Простежував я їх стежки несталі
І стежив, як всередину знялись
І віддаль не дала летіти далі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Уздрівши зір, не втоплений у вись,
Сказала владарка: «Як опинився
Ти саме тут, уважніш роздивись».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Побачив, що відколи я дивився
Звідсіль уперш, по кліматних стрічках
На перший край з середини скотився.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'За дальнім Гадесом я бачив шлях
Рискований Улісса й берег вище,
Де всілася Європа на рогах.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Я той куток би обдивився ближче,
Та сонце вже випереджало нас
Понад весь знак, в безодні бігши нижче.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Закоханий мій дух впада всякчас
Біля владарки й навіть на вершині
Жадав, щоб зір її мене потряс.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Все, чим природа чи мистецтво й нині
Чарують зір, вловляючи серця,
Чи в людськім тілі, а чи на картині,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Мізерним видалось би до кінця
Проти відради, що мені засяла,
Як глянув я на блиск її лиця.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'І сила, що в її очах блищала,
Лишивши в Лединім гнізді зірки,
Мене в найшвидше небо перемчала.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Найвищі та найскорші в нім частки
Однакові усі, і я не зчувся,
Як з Беатріче став на ґрунт легкий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Вона сказала, щоб я схаменувся,
І посміх був її такий ясний,
Мов Бог у неї на лиці всміхнувся:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = '«Дає природа світу рух міцний,
Недвижна у середній огорожі,
Відштовхується тут, як од стіни.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'І небо це вмістилось в мислі Божій,
Яка запалює ізнову й знов
Любов рушійну і чесноти гожі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Іде круг нього сяйво і любов,
Воно ж іде круг інших кіл зіллятих,
І з ним в усі Творець його прийшов.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'І рух його - не в мірах десь узятих,
А інші в ньому вимір свій беруть,
Як десять - з других складені та з п''ятих.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Неважко буде вже тобі збагнуть,
Чом корені у ньому час тримає,
Гілки ж він може деінде тягнуть.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'О ненажерливість, що поглинає
Людей, а з них хай хтось би очі звів
З глибин її, - на те снаги немає!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Коли буває літом надмір злив, -
Хоч скільки добра воля в смертних квітне, -
Кислиці виростають замість слив.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'У вірі й цноті немовля привітне,
А підросте, вже уника цих справ,
Хоч на щоках волосся й ледь помітне.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Той постував, коли ще белькотав,
А як підріс язик, вжива охоче
При всякім місяці усяких страв.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'А інший поважа, коли белькоче,
І любить неню, стане ж розмовлять,
То зажада закрити любій очі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Так білу шкіру деякі чорнять
Від чар дочки того, з чиєї волі
То схід, то захід пломенем горять.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Ти, щоб не дивуватися доволі,
Помисли, що весь рід ваш неборак
Без вожая непевно йде в юдолі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'Та перш, як в весну прийде січня знак, -
Щорік-бо людство забуває соту-, -
Найвищі кола закружляють так,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'Що ждана буря виявить турботу,
Корму поставить в давній носа слід,
Належний напрям указавши флоту,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 49;

UPDATE terzinas SET text_uk = 'І з квітки визріє прекрасний плід».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 27
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 50;

UPDATE cantos SET title_uk = 'ПІСНЯ ДВАДЦЯТЬ ВОСЬМА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 28
    AND p.name = 'Paradiso';

UPDATE terzinas SET text_uk = 'Коли відкрила істину до краю
Про вбогих смертних в нинішніх віках
Та, що проводила мене по Раю,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'То, як спахнулі ззаду в свічниках
Вогні, уздрівши в дзеркалі раніше,
Аніж на очі власні чи в думках,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Ми, озирнувшись зріть, чи правду пише
А чи неправду скло, зримо злиття
Таке ж, як співу з ладом, не вільніше, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Так пам''ять зберегла від забуття,
Що я зробив, дивившись в гарні очі,
Де пута заплело мені чуття.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Коли ж я озирнувся - так щоночі
Ми в небі бачимо нові тіла,
А в них щось тайне, радісне, уроче, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Я цятку вздрів, яка такий лила
Вогонь, прегострий силою своєю,
Аж гостротою очі обпекла.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Та найдрібніша зірка поруч з нею
Здалась би місяцем в достатку сил,
Коли б зрівнять їх, як зорю з зорею.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Мабуть, так само близько круг світил,
Коли повітря мокре охололо,
Корона виплива на небосхил,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Як цятку обвило вогненне коло
І рух його став швидший від основ
Кружіння, що собою світ збороло.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'І з першим другий обвід обійшов,
А з другим - третій, з третім же - четвертий,
З четвертим - п''ятий, з п''ятим - шостий знов.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'І сьомий увижавсь такий простертий,
Що вісниці б Юнониній було
Обняти неможливо в круговерті.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'А восьмий у дев''ятім був; плило
В них сил для обертання в меншу міру,
Чим далі сяло первісне число.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'В тім пломінь грав з чистішого ефіру,
Хто ближче до святої іскри був,
Бо вглиблювався глибше в неї щиру.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Уздріла владарка, що я відчув
Вагання, й мовила: «Вплив цятка має
На кожний в небі чи в природі зсув.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Поглянь, що коло ближче обіймає,
І знай: у нім швидкий цей біг явивсь
Тому, що всіх любов тут поглинає».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'І я на те: «Коли весь світ би вівсь
Таким порядком, як ти освітила,
То б відповідаю я задовольнивсь.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Але в чуттєвім світі, чим світила
Сміліше над землею піднялись,
Тим більша є божественна їх сила.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Якщо тепер не менше, ніж колись,
Відзначений я ангелів собором,
Що вкруг любов''ю й сяйвом обвились, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'То прагну відповіді, чом із твором
Відтворення не йде одним шляхом,
Бо я причин не бачу вутлим зором».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = '«Що справитися пальцям з тим вузлом
Тобі незмога - в тім немає дива:
Не торкнутий, він затягнувсь цілком, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Так владарка. І далі:- Незрадлива
Наповнить істина думки близькі,
Як визріє в тобі ця мисль правдива.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Тілесні кола ширші чи вузькі
Од сил, що їх приймають без остатку
Всі частки їх, високі і низькі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Чим добрість більшає, тим більше статку,
Тим статку більш, чим більшає об''єм,
Де частки досконалі ще з зачатку.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'І, всесвіт женучи, немов бичем,
Узгоджується вихором незмірним
З любові й знання вогняним кільцем.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Отож як не за розміром позірним,
За сутністю давать оцінку їм,
Істотам, що тут кружать колом зірним,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Уздриш ти цей увесь зв''язок чудним
У кожнім небі в стані неспокою -
Значного з більшим, меншого з малим».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Як сяючою стане і тонкою
Повітряна півкуля, бо дихне
Борей своєю м''якшою щокою, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Склепіння враз яснішає хмурне,
Туманів смуга розтає нестала,
Й сміється радо небо чарівне, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Такий був я, коли мені казала
Привітна владарка слова свої,
І правда, мов нічна зоря, сіяла.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'І тільки мова скінчилась її,
То враз, як із розжареної криці
Йдуть іскри, з кіл сипнули їх рої.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Здавалося, що кожна з них іскриться,
І їх палало більше, ніж коли
Подвоювать на клітках шахівниці.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Я чув, як здійнялись хвали й хвали
До цятки непорушної, що ними
Лишаться завжди, як завжди були.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'І та, що бачила мій незборимий
Порив, сказала: «В першім колі цім
Витають херувими й серафими.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Захоплювані наміром одним
Вподібнитись до цятки, їх водійки,
Ведуть всі стежку колом осяйним.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Любові йдуть ще, крім цієї двійки,
Святі Престоли Божого лиця, -
Які до першої належать трійки.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'То знай: вся радість кожного кільця
У баченні, що в істину ввіходить,
Утишуючи розум до кінця.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Як можна бачити, це думку родить,
Що лиш у баченні - блаженства суть,
Воно ж любов пізніше вже приводить.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Заслуги силу баченню дають,
їх - ласка й добра воля навіває, -
На східець так зі східця вгору йдуть.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Знов інша трійка листя розвиває,
Бо споконвік цвіте весна жива,
Яку Баран вночі не осяває, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = '«Осанну» безперестану співа
На троє голосів, і в них єдині
В трьох родах радощів бринять слова.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'В цій ієрархії є три богині:
Це - Панств, це - Сил могутня благодать,
І третій рід - Властей у благостині.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Передостанні кола два мигтять,
З Архангелами там Начала мають,
В останньому ж лиш Ангелам літать.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Всі ті роди угору зір спрямляють
І, долу проливаючи свій вплив,
Всі, Богом підняті, всіх піднімають.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'І Діонісія так запалив
Цих родів вигляд, що він лад багатий,
Як я роблю, назвав і поділив.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Григорій не хотів на це пристати,
А як на власні очі глянув сам,
То став тоді із себе кепкувати.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Не диво, що в земних долинах, там,
Всі знає смертний тайни верховинні:
Хто ж їх тут бачив, той повідав вам'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Між тайн, не знаних в людському корінні».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 28
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 47;

UPDATE cantos SET title_uk = 'ПІСНЯ ДВАДЦЯТЬ ДЕВ''ЯТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 29
    AND p.name = 'Paradiso';

UPDATE terzinas SET text_uk = 'Коли обоє родженців Латони
При знаках Терезів та Барана
Стоять на точках обрійної зони,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'То, поки їх вагу зеніт єдна
Й, міняючи півкулю мальовниче,
І він цей пояс кидає, й вона, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'Так глянула, всміхнувшись, Беатріче,
Звернувши блиск нетлінної краси
На цятку й відсвіт на моїм обличчі,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'І почала: «Непевні голоси
З твого бринять єства, що взнать схотіло,
Де сходяться простори всі й часи,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Не щоб покращать - цього, зрозуміло,
Не може буть, - а щоб в красі ясній
Усюди слово «Єсмь» заблискотіло,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Любов одвічна в вічності своїй
Поза часів і просторів імлою
Створила дев''яти любовей рій,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'І перш вона була сама собою,
Ні «перш», ні «після» не було, коли
Дух Божий промовляв понад водою.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Він суть і речовину, що були,
В політ у бездоганний блиск усталив,
Як тритятивний лук на три стріли.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'І як у скла, бурштинів чи кристалів,
Що промінь проникає в них і вмить
Наповнює без всяких інтервалів. -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Так став триформний твір Господній лить
Єдине неподілене сіяння,
І ладу в нім було не розрізнить.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'А далі йшли ладнання та світання
Тих сутностей, що встали на верхах
У всесвіті, які значить діяння.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Можливість же - внизу, де тьма і страх;
Всередині - діяння і можливість
У нерозв''язних заплелись зв''язках.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Довів Ієронім вам справедливість
Думок про те, що ангельські війська
Старіші за стрімку світів рухливість.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Та істина написана ярка
В усіх письменників Святого Духа,
Побачиш це з їх кожного рядка.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'І розуму свого лишень послухай:
Чи довго рушії знесли б усі,
Що справжня досконалість їх не руха?'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Так взнав ти, де й коли любові ці
Сотворено і як; в бажаннях в тебе
Отож загашено три пломінці.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Ще не налічив двадцяти як треба,
А частка ангелів геть потрясла
Стихії ваші від основ до неба.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'А інші закружляли без числа,
Й тебе захоплює та невгавуща
Жага, що в коло танців їх ввела.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Примусила упасти проклятуща
Пиха того, якого - зрів ти сам -
Стиска вага, з усіх земних найдужча.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'А ті, кого ти бачиш тут і там,
Смиренно визнали, що розумінням
Завдячують лише святим словам.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Наповнилися очі їх зорінням,
Засяяли заслуги й благодать
їх цілковитим і твердим болінням.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Покинь свій сумнів, ти повинен знать:
Заслуга тягне благодать, і знову
Любов готується її сприйнять.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Тепер собор цей і стезю чудову
Ти самотужки розглядати линь,
Коли мою сприйняв як треба мову.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'А що твердить усяка шкільна тлінь,
Говорячи про ангельську породу,
Про здатність мислі, пам''яті, волінь,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'То я скажу, щоб відвернути шкоду,
Якої щирій правді завдає
Закрутистий читець такого роду:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Ці духи, щастя бачивши своє
У Божому лиці, очей не зводять
Від Нього, бо Йому все явним є.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Отож ніколи зору їх не шкодять
Новини, тож нема потреби їм
Пригадувать думки, що геть проходять.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Ми ж унизу, хоч не спимо, а сним,
І вірячи й не зірячи казанням,
На осуд і ганьбу синам земним.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Не ростемо там філософуванням,
Бо світ усіх занадто полонив
І марнотою, й самовихвалянням.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'А тут не менший викликає гнів,
Ніж перекручування в Божім слові
Й додатки, роблені до наших днів.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Не маєте ви й гадки, скільки крові
Взяла його сівба, тому й вінця
Був гідний той, хто йшов з ним до любові.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'А марна слава знаджує ченця
На вигадки, щоб їхній блиск торкнувся
Усіх, з Євангелія ж - ні слівця.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'От ці твердять, що місяць повернувся
Під час страстей Христа, не даючи,
Щоб сонця промінь крізь пітьму проткнувся;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'А ті - що день пропав десь уночі,
Тікаючи із неба Палестини,
Від індів та іспанців біжачи'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Імення Лапо й Бінді хто не стріне
В Флоренції на вулицях витких?
А з кафедри дурниць ще більше рине.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'З казань же гурт овець бреде тупих,
Пустопорожню ремиґає фразу,
Й темнота їхня не рятує їх.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Христос апостолам не дав наказу:
«Ідіть і проповідуйте брехню», -
До неї в них він виховав відразу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Це їх запалювало на борню
За перемогу вічного блаженства;
Євангельє за спис було й броню.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'А нині храми сповнені блазенства,
Як сміхом зайдеться в мирян душа,
Клобук аж дметься з шалу верховенства,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'А в шлик таке вгніздилося пташа,
Що люд би, бачивши його, побачив,
Хто саме їх щосвята розгріша.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'І дур такий усіх людей позначив,
Що вірять всяким брехням навмання,
Хоч доказів ніхто їм не постачив.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Смакує так в Антонія свиня,
Смакують інші, за свиней поганші,
Яким підробка гроші підміня.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Та ми таки зблудилися, - поглянь же,
Зверни свій погляд на правдиву путь,
Щоб час і шлях у нас були без ґанджі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Роди ці ангельські далеко йдуть
В чисельності, і ані смертна мова,
Ні розум їх не можуть осягнуть.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Уважно придивися ти до слова
Із тьмою тем, що мовив Даниїл,
І в нього скрита числова основа.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Найперше світло, сяючи навкіл,
По-всякому сприймається повсюди,
Бо стільки з ним злучається світил.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Вчин од чуття не від ступа нікуди,
Й вогонь любові в кожнім язику
По-різному горіть чи жевріть буде.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'Поглянь, велику творить річ яку
Одвічна сила, бо себе всю крає
В стількох дзеркалах, в кожному шматку, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'І неподільність завжди зберігає».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 29
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 49;

UPDATE cantos SET title_uk = 'ПІСНЯ ТРИДЦЯТА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 30
    AND p.name = 'Paradiso';

UPDATE terzinas SET text_uk = 'Мабуть, що за шість тисяч миль із лишком
Горить година шоста, і малі
Світи схиляють тінь над всім проміжком,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Коли небес глибінь очам землі
Стає така, що зірка найсвітліша
Немовби губиться на цьому тлі,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'То йде служниця сонця найясніша,
І в небі погаса зірок сім''я,
Зоря з зорею, навіть найгарніша.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Година свят, яка в огнях сія,
Обнявши цятку, що мене скосила,
Уміщуваним вміщувана вся,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Помалу-малу сяєво гасила;
Коли ж все згасло, то любов мій зір
До Беатріче знову опустила.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Як ту хвалу, що ніс до цих я зір,
Зібрати всю в єдиній мовній лаві,
То нині замалий би вийшов збір.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Красу її збагнуть моїй уяві
Несила, й думаю, що осягнуть
її творець би тільки міг у славі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = '(Цей уступ, визнаю, мене вжахнуть
Спроможен глибше, ніж думки урочі
Поетів театральних в страх женуть.)'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Як сонце стомлює кволіші очі,
Так з гадки про її усмішки слід
Усі гадки мої стають коротші.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Відколи вперш її побачив вид
В цьому житті, аж до цього стрівання,
Я завжди пісню їй носив услід.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'А тут забракло слів для віршування
Про вроду, як у кожного митця,
Що вже досяг верхів обдарування.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Така, яку я вищій, аніж ця
Моя сурма, лишаю (ясно й світло
Я досуремлю труд свій до кінця),'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Та, на лиці якої сяйво квітло,
Немов меткий вожай, сказала знов:
«З найбільшого звелись ми тіла в світло,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'В безтіле світло, що саме - любов,
Любов до блага, що сама - відрада,
Відрада, всіх блаженств найвищих схов.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Зри, райська рать одна і друга пада
Сюди згори, й одна така, яку
Душа в день суду зріти буде рада».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Як, блискавку побачивши близьку,
Наш зір ураженим стає й уздріти
Не здатен навіть річ і громіздку,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Так я таким був сяєвом окритий,
Що світ навкруг увесь мені погас
І я не міг нічого розрізнити.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = '«Любов, що в небі мир пильнує в нас,
Гостей вітає зустріччю бучною
І запалить свічки ладна всякчас».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'І ледь мені до слуху далиною
Долинули короткі ці слова,
Я вчув, як підіймаюсь над собою.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'І сила зору припливла нова,
Так що не стало світляного вічка,
Увага щоб зневажила жива.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'І я побачив світло, що, мов річка,
Блищало лиском в берегах святих,
Де весняних лісів тяглася стрічка.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Спадали зграї вогників живих
У квіти, пурхаючи над потоком
Рубінами в оправах золотих,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'І, сп''янені тим запахом високим,
В глибини поринали аж на дно,
І ті йшли вниз, а ті - угору скоком.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = '«Бажання, що горить в тобі одно -
Все взнати із навкружного простору, -
Тим втішніше, чим більш стає воно.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Та маєш воду випити прозору,
Щоб спраги жар в тобі нестримний стух», -
Так вимовило сонце мого зору.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'А там: «Ця річка, цей топазів рух
Угору й вниз, цей сміх трави священний -
В усім провісний правди сяє дух.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Не сам собою він є незбагненний,
А через власну похибку твою,
Бо зір твій зовсім ще не глибоченний».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Так не зверта дитина силу всю
На молоко, коли вона проспала
Годину звичну годувань свою,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Як, щоб удосконалити дзеркала
Своїх очей, я до води приник,
Яка повз мене тихо дзюркотала.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'І ледь почув я, що дашок повік
Зволожився, як начебто зробився
З протяглого округлим весь потік,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Мов той, хто машкарою був прикрився,
А як облудний вигляд враз упав,
З лицем справдешнім раптом появився,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Так ще ясніше забенкетував
Квіток та іскор світ, і я побачив
Обидві раті перед себе в''яв.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'О Божий блиску, у якім побачив,
Де свято істинного царства є,
Дай сил сказати, що я там побачив!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Є світло нагорі, що в нім стає
Творець наш зримим кожному створінню,
Яке там в мирі щастя зрить своє.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'І він складає коло величінню
Таке, що випрямлене коло те
Лягло б круг сонця здовженою тінню.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Йде з променя лице його святе,
Відбите на вершку перворушійнім,
Що в нім його життя і міць росте.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Як, оддзеркалившись в струмку спокійнім,
Глядить пригорок на свій власний луг
В оздобленні зеленім, легковійнім,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Так світло, висячись округ і вкруг, -
Я бачив, - тисячами граней грало
В тих, хто вернувся до небесних дуг.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Коли вже дно себе так представляло,
Яке ж тоді розкішне, пишне тло
У розі коло пелюсток являло!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Ніщо моїм очам не завдало
Тут шкоди, і вони вхопили, смілі,
Яких і скільки радощів було.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Там близь і даль узяти й дать не в силі,
Бо де сам Бог свій присуд виріка,
Природні там закони не при ділі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'У жовтизну правічного цвітка,
Що в пахощах для сонця весняного
Розкрився пелюстками до листка,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Ввела мене, у захваті німого,
Тут Беатріче й мовила: «Почну
Із натовпу сліпучо-снігового.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Зри ж міста нашого величину!
Зри лави довгі і народом повні,
Що чи вмістять ще душу хоч одну!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Ось трон стоїть, і очі невгамовні
Ти втупиш, бо корону залиша
І перш, як ти, - на учти повнокровні,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Сюди велична з''явиться душа
Високого Арріго, - вгамувавши
Італію, він дуже поспіша.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Сліпа неситість, розум відібравши,
З вас робить немовлят. Як малюки,
Мрете голодні, мамку відігнавши.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'Префект на божім форумі такий:
З ним зовні буде приятель, а тайно
Штовхатиме його на шлях тяжкий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'Та Бог недовго витерпить, звичайно,
Того в святому сані й прожене
Туди, де стогне Сімон-маг одчайно,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 49;

UPDATE terzinas SET text_uk = 'Й цього, з Аланьї, глибше проштовхне».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 30
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 50;

UPDATE cantos SET title_uk = 'ПІСНЯ ТРИДЦЯТЬ ПЕРША'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 31
    AND p.name = 'Paradiso';

UPDATE terzinas SET text_uk = 'Мов біла роза, пишний цвіт яскравий,
Переді мною стала рать свята,
Що з нею взяв Христос свій шлюб кривавий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'А та, що в льоті зір і спів зверта
На блиск того, кого вона кохає
Й кого велична робить доброта,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'І, як крильми родина бджіл махає
На квітку ще і ще й летить назад,
Де їх труди солодкість просякає, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Злітала в наймахровішу з засад,
Із льоту повертаючи швидкого
В її любові віковічний сад.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Всі лиця кольору були жаркого,
А крила - золоті, й убір такий,
Що снігу не знайти ніде такого.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Вони від пелюсток на пелюстки
Лили і мир, і пал вгорі та долу,
їх беручи із Божої руки.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Ширяючи між східцями престолу
І квіткою, полки святих могуть
Не заважали зору й ореолу:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Господні сяйні сили в світ ідуть
В тій мірі, щоб йому відповідала,
Й завад ніколи тут не може буть.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Держава ця, радіюча і стала,
Рясна на стовпища нові й старі,
Свою любов і зір до цятки слала.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'Троїсте сяйво, що в одній зорі
Блискочеш в очі, - наче мирні віти,
До наших бур схили свій зір вгорі!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Якщо вже варвари, діставшись звідти,
Де кружить свій щоніч Геліка стан,
А перед нею - син, в любов сповитий,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Запали в Римі в непритомний стан,
Коли, мов чудо, з смертними не схоже,
їм встав перед очима Латеран, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'То я, коли зміняв людське на Боже,
На вічність - час короткий та плохий,
Флоренцію - на місто праве й гоже,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Який удар я раптом вчув лихий!
Потрапивши між нього та відради,
Волів, щоб став сліпий я та глухий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'І як прочанин оглядає радий
Освітлений обітницею храм
І в думці вже описує облади, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Надав я волі жадібним очам
І зором перебіг по сяйних лавах
Вгорі, внизу, навкруг, і тут, і там.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Сувій облич сіяючих, яскравих
У світлі й усмішках я розгорнув
І лиць, похвал достойних, нелукавих.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Будову Раю я вже озирнув,
Але, спинившись перед розгляданням
Частин його, їх форми не збагнув'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'І озирнувсь, озорений жаданням
Про те, що для ума було трудним,
До владарки звернутися з питанням.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Та ждав одне, а здибався не з ним:
Не Беатріче вздрів, але старого
В убранні, притаманному святим.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Зичливістю весь образ діда цього
У душу глибоко мені запав
І виглядав по-рідному, не строго.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'І: «Де ж вона?» - я зараз же спитав,
А він: «Щоб не лишавсь ти сам у тузі,
Від Беатріче щойно тут я став.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'На третю лаву у найвищім крузі
Поглянь - вона вже відчуває мир
На троні, даному їй по заслузі».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Не відповів я й, знявши вгору зір,
Побачив, як вона сидить уроче
В вінку з яскравих, променистих зір.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Із високостей, звідки грім гуркоче,
До глибу, де придонний плин тече,
Не більша віддаль одбирає очі,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Як в Беатріче від моїх очей;
Але ця даль обличчя не згасила -
Воно й крізь відстань сяло гаряче.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = '«О владарко, моїх надій ти сила,
З якою, щоб мене порятувать,
Свої сліди у Пеклі ти лишила!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'В усім, що дозволяла споглядать
Ти з добрості й могутності своєї,
Я впізнаю потугу й благодать.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'До волі з рабства провели моєї
По всіх стежках, по тропах всіх вони,
Де тільки влади міць була твоєї.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Щедротами мені ти сохрани
Здорову душу з тілом не опрічно
І потім вгодною тобі звільни!»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Так я благав. Вона, здаля незвично,
Всміхнулась, глянула на мене й знов
Вдивилась в джерело, що ллється вічно.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'І дід святий: «Щоб ти мети дійшов, -
Сказав, - я слушну дам тобі пораду,
Як просьба вказує й свята любов.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Обвівши зором обвід цього саду,
Божественного променя цей дар
Ти сприймеш легше на свою відраду,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'Й цариця неба, що увесь їй жар
Любовний я несу, поможе в цьому,
Бо я - навіки вірний їй Бернар».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Мов той, хто йде з Кроації, із дому,
Поклавши, залишаючи сільце,
Вероніку побачити відому,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'І думає, як поглядить на це:
«О Господи святий, Христе Ісусе,
То справді в тебе ось яке лице!», -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'Таким був я, в душі вчувавши струси
З краси того, хто жив у світі сліз
І не піддався впливові спокуси.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = '«О сину ласки, бачить сяйво риз, -
Почав він, - зір у тебе неспроможний,
Бо ти весь час вдивляєшся униз.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Ти ж роздивись круги окремо кожний,
І трону досягнеш цариці скл,
Якій весь край скоряється побожний».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Я очі звів: як вранці небосхил
Яскравіший на сході, ніж у жодній
Частині, де зникає знак світил,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Я, зводячи свій зір, мов із безодні,
Побачив, що середина кайми
Пруги лишила темні та холодні'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Як дужче пломеніє там, де ми
Ждем дишля, згубного для Фаетона,
Обабіч же - дедалі більше тьми,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'Так мирна орифлама та червона
Посеред смуг темніших, неярких
Мінилася, мов огняна корона.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Я бачив юрми ангелів святих
Співали посередині й світились,
І блиск і вміння розрізняли їх.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Я бачив, що, коли вони крутились,
їм слала''усміх, як м''який єдваб,
Краса, й на неї радо всі дивились.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Зі скарбом слів, як і уяви, я б,
Скромнішим бувши із людей, смиренний,
Не описав найменшої з приваб.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Бернар, побачивши, як очі в мене
Принадив пал, що і його палив,
У нього затопив свій зір вогненний,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'І зір мій теж сильніш запломенів.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 31
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 48;

UPDATE cantos SET title_uk = 'ПІСНЯ ТРИДЦЯТЬ ДРУГА'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 32
    AND p.name = 'Paradiso';

UPDATE terzinas SET text_uk = 'Повитий в радість мудрий споглядальник
Почав так мову у святих словах,
Мов добрий та уважний стернувальник:'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = '«Ту рану, що Марія у віках
Загоїла, - завдати ще й ятрити
Тій дано, що сидить в її ногах.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'А трохи нижче - третій ряд відкритий
Рахіллю, що ласкавий зір зверта
До Беатріче, як ти мав уздріти,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Ревекка з Сарою, Юдіф і та,
Яка прабабкою була співцеві,
Що для «Помилуй мя» розкрив уста, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Здадуться всі тобі кільцем в кільцеві,
Я ж оком кожний теж пройду карниз,
Аж поки стане низ кінцем кінцеві.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Од лави сьомої угору й вниз
Єврейки посідали на сидіннях
В яскравім сяйві пелюсткових риз.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'Помітно змінність в різних поколіннях
У вірі у Христа між різних лав,
Як вал, що височить на половинах.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'Де квіт весь розпустився й розплатав
Всі пелюстки - собор там розмістився
Тих, хто Христового пришестя ждав.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Де ж простір поміж дуг ще не закрився,
Над чолами сіяє ореол
В тих, хто повірив, як Христос явився.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'В усіх віках уславлений престол
Цариці неба й нижчі ще престоли
Собою створюють великий мол.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Навпроти ж - Іоанн, високочолий
Святий пустельник, що, зазнавши мук,
Два роки ще топтав у Пеклі доли.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'А нижче лави у відрубний пук
Франціска, Бенедикта, Августина
Та інших в''яжуть, як у зграйний звук.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Дивуйся ж на дбайливість властелина:
Два зори віри в цьому є саду,
І кожному в нім- рівно половина.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Униз за поділяючу гряду,
Яка проходить точно та грунтовно, -
Не по своїх заслугах всі в ряду,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'А по чужих, проте й не безумовно,
Бо виправдані душі ці були,
Як ще їм правди шлях не сяв любовно.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Ти в цім переконаєшся, коли
Побачиш зір невинний та чудовний,
Почуєш хор дитячий немалий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Не певний ти й в непевності безмовний,
Але я визволю від пут, що ум
Тебе оплутав, сам облуди повний.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Ніяка випадковість дій і дум
По всіх просторах вишньої держави
Не знана, як і голод, спрага, сум.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Одвічний-бо закон порядок правий
Установив, і звичаї святі,
Немов на пальці самоцвіт яскравий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Тому й дочасний мир у тім житті
Не без причин малеча торжествує,
На різній пое-ідавши висоті.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Той цар, в якого царство розкошує
В такій любові, в радості такій,
Що їх ніколи і ніхто не вчує,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Уми в одраді творячи палкій,
Дарує ласку з вибором свободним, -
З вас досить висновків у мові тій.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'Це явлено у мудрістю безоднім
Святім письмі, де двоє близнюків
В утробі ще сварились один з одним.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'Тож відзнача роздачею вінків
Найвища благодать, з ясним сіянням
Вслід ідучи забарвленню висків.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Тому-то не за життьовим діянням
Щабель розміщення різниться в них,
Але різнить за першим спонуканням.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'На самому початку літ земних
Була достатня, щоб спастись, невинність
У злуці з вірою батьків старих.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'У міру, як минала часу плинність,
В хлоп''ят невинних біль будив сльозу,
Обрізання ж давало силам цінність.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'Коли вже час зростив нову лозу,
То без хрещення іменем Христовим
Зосталась та невинність унизу.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Поглянь на ту, чиє лице з Христовим
Найбільше схоже, і дістанеш сил
Іти назустріч святощам Христовим».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Над нею, несеною махом крил
Істот, сотворених у верховині,
Я бачив дощ з таких сяйних світил,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Що все, побачене в світах донині,
Немов стопила непрозора мла
Перед лицем святої благостині.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Й любов, яка нам перша повіла
Спів «Радуйся, Маріє-приснодіво»,
Простерла перед нею два крила.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Святим цим звукам одповів співливо
З усіх усюд благословенний двір,
Обличчями ясніючи на диво.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = '«Святий мій Отче, що приніс свій зір
Вниз ради мене і підвівся з лави,
Де радісно вкушав довічний мир, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'Який це ангел зору в сяйві слави
Не зводить од Царициних очей,
З любові, наче з полум''я, яскравий?»'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Так мовив я й того чекав речей,
Якому озорила вид Марія,
Мов ранком сонце зірку гаряче.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'І він мені: «Краси й відваги дія
У ньому виявляється без змін -
У нас про це можлива тільки мрія, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'Дав гілку пальмову Марії він
В ту мить, як тягарем вини всієї
Себе обтяжить зволив Божий Син.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'Дивись же й мови дослухайсь моєї:
Ось тут сидять патриції значні
Побожної імперії цієї.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'З них двоє - щастям значені, ясні,
Посаджені найближче до Августи,
Мов корені у розі неземні.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Отцеві, що ліворуч, суд стоустий
Плода солодкий закидав укус,
Бо людству гірко від його розпусти.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'Отець, що справа, - вільний від спокус
Страж церкви Божої, йому-бо саме
Ключі від рози передав Ісус.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'А той, хто перед смертними часами
Із днем зіткнувся, для жони тяжким,
Звойованої списом та цвяхами,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Сидить з ним поруч; вліво ж, поруч з ним, -
Той вождь, який приніс колись-то манну
Невдячним людям, зрадним і пустим.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Насупроти Петра ти бачиш Анну,
Що з доччиного ніжного лиця
Очей не зводить і співа «Осанну».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Навпроти ж Превеликого Отця
Сидить Лючія, що в тяжкі години
Була в лісу тобі за посланця.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Але збігають сну твого хвилини,
Й скінчу на тім. Щоб вийшов добрий шов,
Швець кроїть так, щоб стало шкуратини.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'Спрямуймо зір очей на Пралюбов,
Щоб, мавши змогу ближче придивитись,
Ти скільки змоги в блиск її зайшов.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'Та щоб тобі не ззаду опинитись
І щоб не марно крилами махать,
Повинні ми про ласку помолитись.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 49;

UPDATE terzinas SET text_uk = 'Молитись тій, хто дасть нам благодать.
За мною йди з любов''ю, без вагання,
Щоб од молитви серцем не відстать».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 50;

UPDATE terzinas SET text_uk = 'І він почав таке святе благання.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 32
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 51;

UPDATE cantos SET title_uk = 'ПІСНЯ ТРИДЦЯТЬ ТРЕТЯ'
  FROM parts p WHERE cantos.part_id = p.id
    AND cantos.canto_number = 33
    AND p.name = 'Paradiso';

UPDATE terzinas SET text_uk = '«О Приснодіво, доню свого Сина,
Сумирне й найвеличніше з сердець,
Надіє вічного добра єдина!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 1;

UPDATE terzinas SET text_uk = 'Подарувала людству ти вінець
Облагородження, і стати твором
Сам навіть не погребував Творець.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 2;

UPDATE terzinas SET text_uk = 'В тобі спахнула світовим простором
Любов, і на чолі її горить
Правічна квітка перед мирним зором.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 3;

UPDATE terzinas SET text_uk = 'Вгорі тут - ласки полуденна мить,
Внизу ж, хоч де б ти смертних не поїла,
Із тебе сподівання струменить.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 4;

UPDATE terzinas SET text_uk = 'Така, владарко, в тебе міць і сила,
Що спроба полетіти, летячи
Без тебе, буде, певна річ, безкрила.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 5;

UPDATE terzinas SET text_uk = 'Твоїм щедротам вдячні прохачі,
Та не вони самі, бо досконалість
Всім благодіє, просьби не ждучи.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 6;

UPDATE terzinas SET text_uk = 'В тобі - вся добрість, у тобі - вся жалість,
В тобі - вся лагідність, в тобі - для душ
Людських злилось все милосердя в сталість.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 7;

UPDATE terzinas SET text_uk = 'З невтоленою спрагою цей муж,
Який дорогою зо дна земного
У душах бачив лють, щедроту, суш,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 8;

UPDATE terzinas SET text_uk = 'Тебе благає зглянутись на нього
Й дозволити на верх піти йому,
До джерела палання осяйного.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 9;

UPDATE terzinas SET text_uk = 'І я, щоб знять з очей своїх пітьму,
Не піднімав молитви ще такої,
Але тепер за нього підніму.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 10;

UPDATE terzinas SET text_uk = 'Розвій же хмари смертності важкої
З його путі, нехай він із перлин
Бере блаженство в щасті й супокої!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 11;

UPDATE terzinas SET text_uk = 'Іще прошу, царице верховин,
Хай помислами чистими палає
Й по тому, як усе побачить він!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 12;

UPDATE terzinas SET text_uk = 'Твій пал пориви хай людські здолає!
Глянь, Беатріче з сонмом Душ святих,
Піднісши руки, теж про це благає».'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 13;

UPDATE terzinas SET text_uk = 'Тут зір очей, для Бога дорогих,
Звернувся на промовця, й їх горіння
Явило радість від прохань таких.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 14;

UPDATE terzinas SET text_uk = 'Вони звелись у вічне пломеніння,
Що, проти недоречних сподівань,
Його ніяке не сягне створіння.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 15;

UPDATE terzinas SET text_uk = 'Я, до кінця усіх своїх бажань
Усю дорогу ревно проходивши,
Покінчив у собі з вогнем жадань.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 16;

UPDATE terzinas SET text_uk = 'Бернар мені всміхнувся, знак зробивши,
Щоб я угору глянув; я ж підняв
Уже лице, його упередивши.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 17;

UPDATE terzinas SET text_uk = 'Вістря очей одвертих устромляв
Все більше й більше я у промінь самий,
Який у правді свій початок мав.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 18;

UPDATE terzinas SET text_uk = 'Мій зір бере тут гору над словами,
Бо не відтворять бачене вони,
Воно ж на пам''ять тисне тягарями.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 19;

UPDATE terzinas SET text_uk = 'Неначе той, хто часто бачить сни,
І довго з них один його хвилює,
І тільки він один йому ясний, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 20;

UPDATE terzinas SET text_uk = 'Такий і я: хоч обмаль вже вогню є
В моїй примарі й жевріє вона,
А в серці насолода аж вирує.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 21;

UPDATE terzinas SET text_uk = 'Так точить сніг яскравість весняна,
Так листя в вихорі легке знялося,
І сплутались Сівілли письмена.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 22;

UPDATE terzinas SET text_uk = 'О вишнє світло, що у вись звелося
Над смертну думку, розумові кинь
Моєму трохи з баченого досі'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 23;

UPDATE terzinas SET text_uk = 'І дай моїм словам таку глибінь,
Щоб слави присок, ледве нині видний,
Знесла аж до найдальших поколінь!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 24;

UPDATE terzinas SET text_uk = 'Оживши в пам''яті, як відсвіт бідний,
І продзвенівши в цих моїх рядках,
До них долине пломінь твій побідний!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 25;

UPDATE terzinas SET text_uk = 'Згадавши рани на своїх очах
Від сяєва, вважав я, що, осліпши,
Не бачив би нічого по боках.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 26;

UPDATE terzinas SET text_uk = 'Пригадую, що я, немов прилипши,
Дививсь туди, аж поки Вічна Міць
Не піднесла мене у світ ще ліпший.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 27;

UPDATE terzinas SET text_uk = 'О щедрий даре вишніх таємниць,
Дай утопити зір в яскравім світі,
Який не зна ні меж, ані границь!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 28;

UPDATE terzinas SET text_uk = 'Я бачив, що у цій глибіні скритій
Любов, як в палітурці, добира
Розкидане, мов сторінки розбиті.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 29;

UPDATE terzinas SET text_uk = 'Суть, випадковість, суміш зла й добра
Роїлись на межі мого вмлівання...
І мову ніби сутінок стира.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 30;

UPDATE terzinas SET text_uk = 'Я, мабуть, вузол бачив їх зливання,
Бо, не скінчивши слова ще свого,
Відчув я величезне раювання.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 31;

UPDATE terzinas SET text_uk = 'Забулася ця мить життя мого,
Мов двадцять п''ять віків, як замір смілий
Нептуна здивував веслом Арго.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 32;

UPDATE terzinas SET text_uk = 'Тож розум мій глядів заціпенілий,
Піднесений, уважливий, меткий,
Здивований і з дива спломенілий.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 33;

UPDATE terzinas SET text_uk = 'За ясним"сяйвом пломінь цей такий,
Що в нього йде все на землі постале,
І іншого не вміщують думки.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 34;

UPDATE terzinas SET text_uk = 'До нього пожадання волі стале, -
Все - в ньому благо, поза ним стає
Потворним все, що в ньому досконале.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 35;

UPDATE terzinas SET text_uk = 'Хоч вбоге усвідомлення моє,
Проти моєї мови здався б пишним
Дитинки крик, яка із груді п''є.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 36;

UPDATE terzinas SET text_uk = 'І не тому, що він із чимось лишнім
В живому світлі цьому не вміщавсь, -
Увесь однаковий він із колишнім;'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 37;

UPDATE terzinas SET text_uk = 'І несказанно зір в мені зміцнявсь,
І мерхнув образ зовнішній ясною
Глибінню, бо я сам в собі мінявсь.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 38;

UPDATE terzinas SET text_uk = 'В глибокій ясноті переді мною
Явилися із світла троє кіл
Трьох кольорів з об''ємністю одною.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 39;

UPDATE terzinas SET text_uk = 'Одне - відбиток другого всіх сил,
Немов Іріда близ Іріди стала,
А третє йде вогнем з обох світил.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 40;

UPDATE terzinas SET text_uk = 'Який ти куций одяг надівала,
Безсила мисле, проти ж тебе річ
Іще куцішою себе являла.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 41;

UPDATE terzinas SET text_uk = 'О вічний блиску, що шляхом сторіч,
Самоосяжний, самоосягаєш
Й, осягнутий, собі зориш устріч!'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 42;

UPDATE terzinas SET text_uk = 'На колі, що відбитий в ньому сяєш, -
Коли його я зором перебіг, -
Бо ти навколо сяйвом осяваєш,'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 43;

UPDATE terzinas SET text_uk = 'Де завертав унутрішній поріг,
Мені немовби з нас малюнок здався,
І наче барви власні він зберіг.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 44;

UPDATE terzinas SET text_uk = 'Мов геометр, який старанно брався
За вимір площ і ліній колових,
Але, засад не маючи, стерявся, -'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 45;

UPDATE terzinas SET text_uk = 'Такий став я при дивинах нових:
Хотів уздріть, як образ той у колі
Розміщено, як скріплюється їх.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 46;

UPDATE terzinas SET text_uk = 'Були ж у мене крила надто кволі;
Але яскравість сяйва тут прийшла,
І міць зростала розуму і волі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 47;

UPDATE terzinas SET text_uk = 'Уяву сила зрадила була,
Та, мов колеса, ясні і веселі,
Жадобу й волю долі повела'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 48;

UPDATE terzinas SET text_uk = 'Любов, що водить сонце й зорні стелі.'
  FROM cantos c JOIN parts p ON c.part_id = p.id
  WHERE terzinas.canto_id = c.id
    AND c.canto_number = 33
    AND p.name = 'Paradiso'
    AND terzinas.terzina_number = 49;


COMMIT;
